const TRADUCTEURS_CORAN={"fr": "Muhammad Hamidullah", "en": "Saheeh International", "id": "Kementerian Agama RI", "tr": "Diyanet İşleri Başkanlığı", "de": "A. S. F. Bubenheim & N. Elyas", "nl": "Sofian S. Siregar", "es": "Julio Cortés", "it": "Hamza Roberto Piccardo", "ar": "التفسير الميسر"};
const QURAN={"1:1": {"s": 1, "v": 1, "nom": {"ar": "سُورَةُ ٱلْفَاتِحَةِ", "lat": "Al-Faatiha"}, "ar": "﻿بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ", "tl": {"en": "Bismillaahir Rahmaanir Raheem", "tr": "bismi-llâhi-rraḥmâni-rraḥîm."}, "tr": {"fr": "Au nom d'Allah, le Tout Miséricordieux, le Très Miséricordieux.", "en": "In the name of Allah, the Entirely Merciful, the Especially Merciful.", "id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "tr": "Rahman ve Rahim olan Allah'ın adıyla:", "de": "Im Namen Allahs, des Allerbarmers, des Barmherzigen.", "nl": "In de naam van Allah, de Erbarmer, de Meest Barmhartige.", "es": "¡En el nombre de Alá, el Compasivo, el Misericordioso!", "it": "In nome di Allah, il Compassionevole, il Misericordioso", "ar": "سورة الفاتحة سميت هذه السورة بالفاتحة؛ لأنه يفتتح بها القرآن العظيم، وتسمى المثاني؛ لأنها تقرأ في كل ركعة، ولها أسماء أخر. أبتدئ قراءة القرآن باسم الله مستعينا به، (اللهِ) علم على الرب -تبارك وتعالى- المعبود بحق دون سواه، وهو أخص أسماء الله تعالى، ولا يسمى به غيره سبحانه. (الرَّحْمَنِ) ذي الرحمة العامة الذي وسعت رحمته جميع الخلق، (الرَّحِيمِ) بالمؤمنين، وهما اسمان من أسمائه تعالى، يتضمنان إثبات صفة الرحمة لله تعالى كما يليق بجلاله."}}, "1:2": {"s": 1, "v": 2, "nom": {"ar": "سُورَةُ ٱلْفَاتِحَةِ", "lat": "Al-Faatiha"}, "ar": "ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", "tl": {"en": "Alhamdu lillaahi Rabbil 'aalameen", "tr": "elḥamdü lillâhi rabbi-l`âlemîn."}, "tr": {"fr": "Louange à Allah, Seigneur de l'univers.", "en": "[All] praise is [due] to Allah, Lord of the worlds -", "id": "Segala puji bagi Allah, Tuhan semesta alam.", "tr": "Hamd, Alemlerin Rabbi Allah'a mahsustur.", "de": "(Alles) Lob gehört Allah, dem Herrn der Welten,", "nl": "Alle lof zij Allah, de Heer der Werelden.", "es": "Alabado sea Alá, Señor del universo,", "it": "La lode [appartiene] ad Allah, Signore dei mondi", "ar": "(الحَمْدُ للهِ رَبِّ العَالَمِينَ) الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، وفي ضمنه أَمْرٌ لعباده أن يحمدوه، فهو المستحق له وحده، وهو سبحانه المنشئ للخلق، القائم بأمورهم، المربي لجميع خلقه بنعمه، ولأوليائه بالإيمان والعمل الصالح."}}, "1:4": {"s": 1, "v": 4, "nom": {"ar": "سُورَةُ ٱلْفَاتِحَةِ", "lat": "Al-Faatiha"}, "ar": "مَٰلِكِ يَوْمِ ٱلدِّينِ", "tl": {"en": "Maaliki Yawmid-Deen", "tr": "mâliki yevmi-ddîn."}, "tr": {"fr": "Maître du Jour de la rétribution.", "en": "Sovereign of the Day of Recompense.", "id": "Yang menguasai di Hari Pembalasan.", "tr": "Din Gününün sahibidir.", "de": "dem Herrscher am Tag des Gerichts.", "nl": "De Heerser op de Dag des Oordeels.", "es": "Dueño del día del Juicio,", "it": "Re del Giorno del Giudizio.", "ar": "وهو سبحانه وحده مالك يوم القيامة، وهو يوم الجزاء على الأعمال. وفي قراءة المسلم لهذه الآية في كل ركعة من صلواته تذكير له باليوم الآخر، وحثٌّ له على الاستعداد بالعمل الصالح، والكف عن المعاصي والسيئات."}}, "2:2": {"s": 2, "v": 2, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ", "tl": {"en": "Zaalikal Kitaabu laa raiba feeh; udal lilmuttaqeen", "tr": "ẕâlike-lkitâbü lâ raybe fîh. hüdel lilmütteḳîn."}, "tr": {"fr": "C'est le Livre au sujet duquel il n'y a aucun doute, c'est un guide pour les pieux,", "en": "This is the Book about which there is no doubt, a guidance for those conscious of Allah -", "id": "Kitab (Al Quran) ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa,", "tr": "Bu, doğruluğu şüphe götürmeyen ve Allah'a karşı gelmekten sakınanlara yol gösteren Kitap'dır.", "de": "Dieses Buch, an dem es keinen Zweifel gibt, ist eine Rechtleitung für die Gottesfürchtigen,", "nl": "Dit is het Boek (de Koran) waaraan geen twijfel is, een leidraad voor de Moettaqôen.", "es": "Ésta es la Escritura, exenta de dudas, como dirección para los temerosos de Alá,", "it": "Questo è il Libro su cui non ci sono dubbi, una guida per i timorati,", "ar": "ذلك القرآن هو الكتاب العظيم الذي لا شَكَّ أنه من عند الله، فلا يصح أن يرتاب فيه أحد لوضوحه، ينتفع به المتقون بالعلم النافع والعمل الصالح وهم الذين يخافون الله، ويتبعون أحكامه."}}, "2:31": {"s": 2, "v": 31, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ", "tl": {"en": "Wa 'allama Aadamal asmaaa'a kullahaa summa 'aradahum 'alal malaaa'ikati faqaala ambi'oonee bias maaa'i haaa'ulaaa'i in kuntum saadiqeen", "tr": "ve`alleme âdeme-l'esmâe küllehâ ŝümme `araḍahüm `ale-lmelâiketi feḳâle embiûnî biesmâi hâülâi in küntüm ṣâdiḳîn."}, "tr": {"fr": "Et Il apprit à Adam tous les noms (de toutes choses), puis Il les présenta aux Anges et dit: «Informez-Moi des noms de ceux-là, si vous êtes véridiques!» (dans votre prétention que vous êtes plus méritants qu'Adam).", "en": "And He taught Adam the names - all of them. Then He showed them to the angels and said, \"Inform Me of the names of these, if you are truthful.\"", "id": "Dan Dia mengajarkan kepada Adam nama-nama (benda-benda) seluruhnya, kemudian mengemukakannya kepada para Malaikat lalu berfirman: \"Sebutkanlah kepada-Ku nama benda-benda itu jika kamu mamang benar orang-orang yang benar!\"", "tr": "Ve Adem'e bütün isimleri öğretti, sonra eşyayı meleklere gösterdi. \"Eğer sözünüzde samimi iseniz bunların isimlerini bana söyleyin\" dedi.", "de": "Und Er lehrte Adam die Namen alle. Hierauf legte Er sie den Engeln vor und sagte: \"Teilt Mir deren Namen mit, wenn ihr wahrhaftig seid!\"", "nl": "En Hij onderwees Adam de namen van alle dingen en vervolgens toonde Hij deze aan de Engelen en zei: \"Noem Mij de namen van deze (dingen), als jullie waarachtig zijn.\"", "es": "Enseñó a Adán los nombres de todos los seres y presentó éstos a los ángeles diciendo: «Informadme de los nombres de éstos, si es verdad lo que decís».", "it": "Ed insegnò ad Adamo i nomi di tutte le cose, quindi le presentò agli Angeli e disse: “Ditemi i loro nomi, se siete veritieri”.", "ar": "وبيانًا لفضل آدم عليه السلام علَّمه الله أسماء الأشياء كلها، ثم عرض مسمياتها على الملائكة قائلا لهم: أخبروني بأسماء هؤلاء الموجودات، إن كنتم صادقين في أنكم أَوْلى بالاستخلاف في الأرض منهم."}}, "2:34": {"s": 2, "v": 34, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", "tl": {"en": "Wa iz qulnaa lilmalaaa'i katis judoo liAadama fasajadooo illaaa Ibleesa abaa wastakbara wa kaana minal kaafireen", "tr": "veiẕ ḳulnâ lilmelâiketi-scüdû liâdeme fesecedû illâ iblîs. ebâ vestekbera vekâne mine-lkâfirîn."}, "tr": {"fr": "Et lorsque Nous demandâmes aux Anges de se prosterner devant Adam, ils se prosternèrent à l'exception d'Iblis qui refusa, s'enfla d'orgueil et fut parmi les infidèles.", "en": "And [mention] when We said to the angels, \"Prostrate before Adam\"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers.", "id": "Dan (ingatlah) ketika Kami berfirman kepada para malaikat: \"Sujudlah kamu kepada Adam,\" maka sujudlah mereka kecuali Iblis; ia enggan dan takabur dan adalah ia termasuk golongan orang-orang yang kafir.", "tr": "Meleklere, \"Adem'e secde edin\" demiştik, İblis müstesna hepsi secde ettiler, o ise kaçındı, büyüklük tasladı ve inkar edenlerden oldu.", "de": "Und als Wir zu den Engeln sagten: \"Werft euch vor Adam nieder!\" Da warfen sie sich nieder, außer Iblis. Er weigerte sich und verhielt sich hochmütig und gehörte zu den Ungläubigen.", "nl": "En toen Wij tot de Engelen zeiden: \"Buigt jullie voor Adam,\" toen bogen zij, bhalve Iblis (de Satan). Hij weigerde en was hooghartig en hij werd één van de ongelogigen.", "es": "Y cuando dijimos a los ángeles: «¡Prosternaos ante Adán!». Se prosternaron, excepto Iblis. Se negó y fue altivo: era de los infieles.", "it": "E quando dicemmo agli Angeli: “Prosternatevi ad Adamo”, tutti si prosternarono, eccetto Iblîs, che rifiutò per orgoglio e fu tra i miscredenti.", "ar": "واذكر -أيها الرسول- للناس تكريم الله لآدم حين قال سبحانه للملائكة: اسجدوا لآدم إكرامًا له وإظهارًا لفضله، فأطاعوا جميعًا إلا إبليس امتنع عن السجود تكبرًا وحسدًا، فصار من الجاحدين بالله، العاصين لأمره."}}, "2:35": {"s": 2, "v": 35, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ", "tl": {"en": "Wa qulnaa yaaa Aadamus kun anta wa zawjukal jannata wa kulaa minhaa raghadan haisu shi'tumaa wa laa taqabaa haazihish shajarata fatakoonaa minaz zaalimeen", "tr": "veḳulnâ yâ âdemü-skün ente vezevcüke-lcennete vekülâ minhâ ragaden ḥayŝü şi'tümâ. velâ taḳrabâ hâẕihi-şşecerate fetekûnâ mine-żżâlimîn."}, "tr": {"fr": "Et Nous dîmes: «O Adam, habite le Paradis toi et ton épouse, et nourrissez-vous-en de partout à votre guise; mais n'approchez pas de l'arbre que voici: sinon vous seriez du nombre des injustes».", "en": "And We said, \"O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers.\"", "id": "Dan Kami berfirman: \"Hai Adam, diamilah oleh kamu dan isterimu surga ini, dan makanlah makanan-makanannya yang banyak lagi baik dimana saja yang kamu sukai, dan janganlah kamu dekati pohon ini, yang menyebabkan kamu termasuk orang-orang yang zalim.", "tr": "\"Ey Adem! Eşin ve sen cennette kal, orada olandan istediğiniz yerde bol bol yiyin, yalnız şu ağaca yaklaşmayın; yoksa zalimlerden olursunuz\" dedik.", "de": "Und Wir sagten: \"O Adam, bewohne du und deine Gattin den (Paradies)garten, und eßt von ihm reichlich, wo immer ihr wollt! Aber naht euch nicht diesem Baum, sonst gehört ihr zu den Ungerechten!\"", "nl": "En Wij zeiden: \"O Adam, verblijft in het Paradijs, jij en je vrouw, en eet daaruit overloedig, zoals jullie willen, maar nadert deze boom niet, anders zullen jullie tot de onrechtplegers behoren.\"", "es": "Dijimos: «¡Adán! ¡Habita con tu esposa en el Jardín y comed de él cuanto y donde queráis. pero no os acerquéis a este árbol! Si no, seréis de los impíos».", "it": "E dicemmo: “O Adamo, abita il Paradiso, tu e la tua sposa. Saziatevene ovunque a vostro piacere, ma non avvicinatevi a quest'albero, ché in tal caso sareste tra gli empi”.", "ar": "وقال الله: يا آدم اسكن أنت وزوجك حواء الجنة، وتمتعا بثمارها تمتعًا هنيئًا واسعًا في أي مكان تشاءان فيها، ولا تقربا هذه الشجرة حتى لا تقعا في المعصية، فتصيرا من المتجاوزين أمر الله."}}, "2:43": {"s": 2, "v": 43, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ", "tl": {"en": "Wa aqeemus salaata wa aatuz zakaata warka'oo ma'ar raaki'een", "tr": "veeḳîmu-ṣṣalâte veâtü-zzekâte verke`û me`a-rrâki`în."}, "tr": {"fr": "Et accomplissez la Salât, et acquittez la Zakât, et inclinez-vous avec ceux qui s'inclinent.", "en": "And establish prayer and give zakah and bow with those who bow [in worship and obedience].", "id": "Dan dirikanlah shalat, tunaikanlah zakat dan ruku'lah beserta orang-orang yang ruku'.", "tr": "Namazı kılın, zekatı verin, rüku edenlerle birlikte rüku edin.", "de": "Und verrichtet das Gebet, entrichtet die Abgabe und verbeugt euch (im Gebet) mit den sich Verbeugenden!", "nl": "En onderhoudt de shalât en geeft de zakât en buigt tezamen met hen die buigen.", "es": "¡Haced la azalá, dad el azaque e inclinaos con los que se inclinan!", "it": "E assolvete all'orazione, pagate la decima e inchinatevi con coloro che si inchinano.", "ar": "وادخلوا في دين الإسلام: بأن تقيموا الصلاة على الوجه الصحيح، كما جاء بها نبي الله ورسوله محمد صلى الله عليه وسلم، وتؤدوا الزكاة المفروضة على الوجه المشروع، وتكونوا مع الراكعين من أمته صلى الله عليه وسلم."}}, "2:83": {"s": 2, "v": 83, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًۭا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًۭا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًۭا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ", "tl": {"en": "Wa iz akhaznaa meesaaqa Baneee Israaa'eela laa ta'budoona illal laaha wa bil waalidaini ihsaananw wa zil qurbaa walyataamaa walmasaakeeni wa qooloo linnaasi husnanw wa aqeemus salaata wa aatuzZakaata summa tawallitum illaa qaleelam minkum wa antum mu'ridoon", "tr": "veiẕ eḫaẕnâ mîŝâḳa benî isrâîle lâ ta`büdûne ille-llâhe vebilvâlideyni iḥsânev veẕi-lḳurbâ velyetâmâ velmesâkîni veḳûlû linnâsi ḥusnev veeḳîmu-ṣṣalâte veâtü-zzekâh. ŝümme tevelleytüm illâ ḳalîlem minküm veentüm mü`riḍûn."}, "tr": {"fr": "Et [rappelle-toi], lorsque Nous avons pris l'engagement des enfants d'Israël de n'adorer qu'Allah, de faire le bien envers les pères, les mères, les proches parents, les orphelins et les nécessiteux, d'avoir de bonnes paroles avec les gens; d'accomplir régulièrement la Salât et d'acquitter la Zakât! - Mais à l'exception d'un petit nombre de vous, vous manquiez à vos engagements en vous détournant de Nos commandements.", "en": "And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], \"Do not worship except Allah; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakah.\" Then you turned away, except a few of you, and you were refusing.", "id": "Dan (ingatlah), ketika Kami mengambil janji dari Bani Israil (yaitu): Janganlah kamu menyembah selain Allah, dan berbuat kebaikanlah kepada ibu bapa, kaum kerabat, anak-anak yatim, dan orang-orang miskin, serta ucapkanlah kata-kata yang baik kepada manusia, dirikanlah shalat dan tunaikanlah zakat. Kemudian kamu tidak memenuhi janji itu, kecuali sebahagian kecil daripada kamu, dan kamu selalu berpaling.", "tr": "İsrailoğullarından, \"Allah'tan başkasına kulluk etmeyin, anne babaya, yakınlara, yetimlere, düşkünlere iyilik edin, insanlarla güzel güzel konuşun, namazı kılın, zekatı verin\" diye söz almıştık. Sonra siz pek azınız müstesna, döndünüz; hala da yüz çevirip duruyorsunuz.", "de": "Und als Wir mit den Kindern Isra'ils ein Abkommen trafen: Dient keinem außer Allah! Und zu den Eltern sollt ihr gütig sein und zu den Verwandten, den Waisen und den Armen! Und sagt Gutes zu den Menschen, verrichtet das Gebet und entrichtet die Abgabe. Danach kehrtet ihr euch - bis auf wenige von euch - ab; ihr seid ja Widerstrebende.", "nl": "En (gedenkt) toen Wij het verbond van de Kinderen van Israël aanvardden (zeggent): \"Aanbidt niets dan Allah, en betracht goedheid jegens de ouders, en de verwand, en de wees, en de behoeftige, en spreekt het goede tot de mensen en onderhoudt de shalât en geeft de zakât.\" Vervolgens ontrokken jullie je er aan, behalve een klein aantal van jullie, terwijl jullie je afwendden.", "es": "Y cuando concertamos un pacto con los hijos de Israel: «¡No sirváis sino a Alá! ¡Sed buenos con vuestros padres y parientes, con los huérfanos y pobres, hablad bien a todos, haced la azalá dad el azaque!» Luego, os desviasteis, exceptuados unos pocos, y os alejasteis.", "it": "E quando stringemmo il patto con i Figli di Israele [dicemmo]: “Non adorerete altri che Allah, vi comporterete bene con i genitori, i parenti, gli orfani e i poveri; userete buone parole con la gente, assolverete all'orazione e pagherete la decima!”. Ma dopo di ciò avete voltato le spalle, a parte qualcuno tra voi, e vi siete sottratti.", "ar": "واذكروا يا بني إسرائيل حين أخَذْنا عليكم عهدًا مؤكدًا: بأن تعبدوا الله وحده لا شريك له، وأن تحسنوا للوالدين، وللأقربين، وللأولاد الذين مات آباؤهم وهم دون بلوغ الحلم، وللمساكين، وأن تقولوا للناس أطيب الكلام، مع أداء الصلاة وإيتاء الزكاة، ثم أَعْرَضْتم ونقضتم العهد -إلا قليلا منكم ثبت عليه- وأنتم مستمرون في إعراضكم."}}, "2:97": {"s": 2, "v": 97, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "قُلْ مَن كَانَ عَدُوًّۭا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَهُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ", "tl": {"en": "Qul man kaana 'aduwwal li Jibreela fainnahoo nazzalahoo 'alaa qalbika bi iznil laahi musaddiqal limaa baina yadihi wa hudanw wa bushraa lilmu'mineen", "tr": "ḳul men kâne `adüvvel licibrîle feinnehû nezzelehû `alâ ḳalbike biiẕni-llâhi müṣaddiḳal limâ beyne yedeyhi vehüdev vebüşrâ lilmü'minîn."}, "tr": {"fr": "Dis: «Quiconque est ennemi de Gabriel doit connaître que c'est lui qui, avec la permission d'Allah, a fait descendre sur ton cœur cette révélation qui déclare véridiques les messages antérieurs et qui sert aux croyants de guide et d'heureuse annonce»", "en": "Say, \"Whoever is an enemy to Gabriel - it is [none but] he who has brought the Qur'an down upon your heart, [O Muhammad], by permission of Allah, confirming that which was before it and as guidance and good tidings for the believers.\"", "id": "Katakanlah: \"Barang siapa yang menjadi musuh Jibril, maka Jibril itu telah menurunkannya (Al Quran) ke dalam hatimu dengan seizin Allah; membenarkan apa (kitab-kitab) yang sebelumnya dan menjadi petunjuk serta berita gembira bagi orang-orang yang beriman.", "tr": "De ki, \"Cebrail'e düşman olan kimse Allah'a düşmandır\", çünkü O, Kuran'ı Allah'ın izniyle kendinden öncekini tasdik ederek, yol gösterici ve inananlara müjdeci olarak senin kalbine indirmiştir.", "de": "Sag: Wer (auch immer) Gibril feind ist, so hat er ihn doch (den Qur'an) mit Allahs Erlaubnis in dein Herz offenbart, das zu bestätigen, was vor ihm (offenbart) war, und als Rechtleitung und frohe Botschaft für die Gläubigen.", "nl": "Zeg (O Moehammad): \"Wie een vijand van Djibrîl is: voorwar, hij heeft hem (de Koran) in jouw hart neergezonden, met toestemming van Allah, als een bevestiging can wat er vóór (geopenbaard) was, en als Leiding en als een verheugende tijding voor de gelovigen.\"", "es": "Di: «Si hay alguien enemigo de Gabriel -él es quien. autorizado por Alá. lo reveló a tu corazón, en confirmación de los mensajes anteriores, como dirección y buena nueva para los creyentes-,", "it": "Di': “Chi è nemico di Gabriele, che con il permesso di Allah lo ha fatto scendere nel tuo cuore, a conferma di quello che era venuto in precedenza, come Guida e Buona novella per i credenti;", "ar": "قل-أيها الرسول- لليهود حين قالوا: إن جبريل هو عدونا من الملائكة: من كان عدوًا لجبريل فإنه نزَّل القرآن على قلبك بإذن الله تعالى مصدِّقًا لما سبقه من كتب الله، وهاديًا إلى الحق، ومبشرًا للمصدِّقين به بكل خير في الدنيا والآخرة."}}, "2:98": {"s": 2, "v": 98, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "مَن كَانَ عَدُوًّۭا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّۭ لِّلْكَٰفِرِينَ", "tl": {"en": "Man kaana 'aduwwal lillaahi wa malaaa'ikatihee wa Rusulihee wa Jibreela wa Meekaala fa innal laaha 'aduwwul lilkaafireen", "tr": "men kâne `adüvvel lillâhi vemelâiketihî verusülihî vecibrîle vemîkâle feinne-llâhe `adüvvül lilkâfirîn."}, "tr": {"fr": "[Dis:] «Quiconque est ennemi d'Allah, de Ses anges, de Ses messagers, de Gabriel et de Michaël... [Allah sera son ennemi] car Allah est l'ennemi des infidèles».", "en": "Whoever is an enemy to Allah and His angels and His messengers and Gabriel and Michael - then indeed, Allah is an enemy to the disbelievers.", "id": "Barang siapa yang menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya, Jibril dan Mikail, maka sesungguhnya Allah adalah musuh orang-orang kafir.", "tr": "Allah'a, meleklerine, peygamberlerine, Cebrail'e ve Mikail'e düşman olan kimse inkar etmiş olur. Allah şüphesiz, inkar edenlerin düşmanıdır.", "de": "Wer Allah und Seinen Engeln und Seinen Gesandten und Gibril und Mikal feind ist, so ist Allah den Ungläubigen feind.", "nl": "En wie een vijand van allah is en van zijn Engelen en vam zijn boodschappers en van djibril en van MIKA IL: voorwaar, Allah is een vijand van de ongelovigen.", "es": "si hay alguien enemigo de Alá, de Sus ángeles, de Sus enviados, de Gabriel y de Miguel, Alá, a Su vez, es enemigo de los infieles».", "it": "chi è nemico di Allah e dei Suoi Angeli e dei Suoi messaggeri e di Gabriele e di Michele, ebbene [sappia che] Allah è il nemico dei miscredenti.", "ar": "من عادى الله وملائكته، ورسله من الملائكة أو البشر، وبخاصة المَلَكان جبريلُ وميكالُ؛ لأن اليهود زعموا أن جبريل عدوهم، وميكال وليُّهم، فأعلمهم الله أنه من عادى واحدًا منهما فقد عادى الآخر، وعادى الله أيضًا، فإن الله عدو للجاحدين ما أنزل على رسوله محمد صلى الله عليه وسلم."}}, "2:127": {"s": 2, "v": 127, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ", "tl": {"en": "Wa iz yarfa'u Ibraaheemul qawaa'ida minal Baitiwa Ismaa'eelu Rabbanaa taqabbal minnaa innaka Antas Samee'ul Aleem", "tr": "veiẕ yerfe`u ibrâhîmü-lḳavâ`ide mine-lbeyti veismâ`îl. rabbenâ teḳabbel minnâ. inneke ente-ssemî`u-l`alîm."}, "tr": {"fr": "Et quand Abraham et Ismaël élevaient les assises de la Maison: «O notre Seigneur, accepte ceci de notre part! Car c'est Toi l'Audient, l'Omniscient.", "en": "And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], \"Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing.", "id": "Dan (ingatlah), ketika Ibrahim meninggikan (membina) dasar-dasar Baitullah bersama Ismail (seraya berdoa): \"Ya Tuhan kami terimalah daripada kami (amalan kami), sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui\".", "tr": "İbrahim ve İsmail, Kabenin temellerini yükseltiyordu: \"Rabbimiz! Yaptığımızı kabul buyur. Şüphesiz ki, Sen hem işitir hem bilirsin\"", "de": "Und (gedenkt,) als Ibrahim die Grundmauern des Hauses errichtete, zusammen mit Isma'il, (da beteten sie): \"Unser Herr, nimm (es) von uns an. Du bist ja der Allhörende und Allwissende.", "nl": "En (gedenkt) toen Ibrâhîm de grondvesten van het Huis legde, samen met Isma'îl (biddend): \"Onze Heer, aanvaard het van ons: voorwar, U bent de Alhorende, de Alwetende.", "es": "Y cuando Abraham e Ismael levantaban los cimientos de la Casa: «¡Señor, acéptanoslo! ¡Tú eres Quien todo lo oye, Quien todo lo sabe!", "it": "E quando Abramo e Ismaele posero le fondamenta della Casa, dissero: “O Signor nostro, accettala da noi! Tu sei Colui Che tutto ascolta e conosce!", "ar": "واذكر -أيها النبي- حين رفع إبراهيم وإسماعيل أسس الكعبة، وهما يدعوان الله في خشوع: ربنا تقبل منَّا صالح أعمالنا ودعاءنا، إنك أنت السميع لأقوال عبادك، العليم بأحوالهم."}}, "2:144": {"s": 2, "v": 144, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةًۭ تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ", "tl": {"en": "Qad naraa taqalluba wajhika fis samaaa'i fala nuwalliyannaka qiblatan tardaahaa; fawalli wajhaka shatral Masjidil haaraam; wa haisu maa kuntum fawalloo wujoohakum shatrah; wa innal lazeena ootul Kitaaba laya'lamoona annahul haqqu mir Rabbihim; wa mal laahu bighaafilin 'ammaa ya'maloon", "tr": "ḳad nerâ teḳallübe vechike fi-ssemâ'. felenüvelliyenneke ḳibleten terḍâhâ. fevelli vecheke şaṭra-lmescidi-lḥarâm. veḥayŝü mâ küntüm fevellû vucûheküm şaṭrah. veinne-lleẕîne ûtü-lkitâbe leya`lemûne ennehü-lḥaḳḳu mir rabbihim. veme-llâhü bigâfilin `ammâ ya`melûn."}, "tr": {"fr": "Certes nous te voyons tourner le visage en tous sens dans le ciel. Nous te faisons donc orienter vers une direction qui te plaît. Tourne donc ton visage vers la Mosquée sacrée. Où que vous soyez, tournez-y vos visages. Certes, ceux à qui le Livre a été donné savent bien que c'est la vérité venue de leur Seigneur. Et Allah n'est pas inattentif à ce qu'ils font.", "en": "We have certainly seen the turning of your face, [O Muhammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face toward al-Masjid al-Haram. And wherever you [believers] are, turn your faces toward it [in prayer]. Indeed, those who have been given the Scripture well know that it is the truth from their Lord. And Allah is not unaware of what they do.", "id": "Sungguh Kami (sering) melihat mukamu menengadah ke langit, maka sungguh Kami akan memalingkan kamu ke kiblat yang kamu sukai. Palingkanlah mukamu ke arah Masjidil Haram. Dan dimana saja kamu berada, palingkanlah mukamu ke arahnya. Dan sesungguhnya orang-orang (Yahudi dan Nasrani) yang diberi Al Kitab (Taurat dan Injil) memang mengetahui, bahwa berpaling ke Masjidil Haram itu adalah benar dari Tuhannya; dan Allah sekali-kali tidak lengah dari apa yang mereka kerjakan.", "tr": "Yüzünü göğe çevirip durduğunu görüyoruz. Hoşnud olacağın kıbleye seni elbette çevireceğiz. Artık yüzünü Mescid-i Haram semtine çevir; bulunduğunuz yerde yüzlerinizi o yöne çevirin. Doğrusu Kitap verilenler, bunun Rab'lerinden bir gerçek olduğunu bilirler. Allah onların yaptıklarından gafil değildir.", "de": "Wir sehen ja dein Gesicht sich (suchend) zum Himmel wenden. Nun wollen Wir dir ganz gewiß eine Gebetsrichtung zuweisen, mit der du zufrieden bist. So wende dein Gesicht in Richtung der geschützten Gebetsstätte! Und wo immer ihr seid, wendet eure Gesichter in ihrer Richtung! Diejenigen, denen die Schrift gegeben wurde, wissen sehr wohl, daß dies die Wahrheit von ihrem Herrn ist. Und Allah ist nicht unachtsam dessen, was sie tun.", "nl": "Waarlijk, Wij hebben gezien hoe jouw gezicht voortdurend tot de hemel wendde, daarom wenden Wij jou (nu) naar een Oiblah die jou welgevallig is. Wend jouw gezicht in de richting van de Masdjid al Harâm (de Gewijde Moskee te Mekkah). En waar jullie je ook bevinden (en de shalât gaan verrichten), wendt jullie gezichten in die richting. En voorwaar, degenen aan wie de Schrift is gegeven, weten zeker dat het de Waarheid van jullie heer is. En Allah is niet onachtzaam omtrent wat zij doen.", "es": "Vemos cómo vuelves tu rostro al cielo. Haremos, pues, que te vuelvas hacia una dirección que te satisfaga. Vuelve tu rostro hacia la Mezquita Sagrada. Dondequiera que estéis, volved vuestro rostro hacia ella. Aquéllos que han recibido la Escritura saben bien que es la Verdad que viene de su Señor. Alá está atento a lo que hacen.", "it": "Ti abbiamo visto volgere il viso, al cielo. Ebbene, ti daremo un orientamento che ti piacerà. Volgiti dunque verso la Sacra Moschea. Ovunque siate, rivolgete il volto nella sua direzione. Certo, coloro a cui è stato dato il Libro, sanno che questa è la verità che viene dal loro Signore. Allah non è incurante di quello che fate.", "ar": "قد نرى تحوُّل وجهك -أيها الرسول- في جهة السماء، مرة بعد مرة؛ انتظارًا لنزول الوحي إليك في شأن القبلة، فلنصرفنك عن \"بيت المقدس\" إلى قبلة تحبها وترضاها، وهي وجهة المسجد الحرام بـ \"مكة\"، فولِّ وجهك إليها. وفي أي مكان كنتم -أيها المسلمون- وأردتم الصلاة فتوجهوا نحو المسجد الحرام. وإن الذين أعطاهم الله علم الكتاب من اليهود والنصارى لَيعلمون أن تحويلك إلى الكعبة هو الحق الثابت في كتبهم. وما الله بغافل عما يعمل هؤلاء المعترضون المشككون، وسيجازيهم على ذلك."}}, "2:153": {"s": 2, "v": 153, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ", "tl": {"en": "Yaaa ayyuhal laazeena aamanus ta'eenoo bissabri was Salaah; innal laaha ma'as-saabireen", "tr": "yâ eyyühe-lleẕîne âmenü-ste`înû biṣṣabri veṣṣalâh. inne-llâhe me`a-ṣṣâbirîn."}, "tr": {"fr": "O les croyants! Cherchez secours dans l'endurance et la Salât. Car Allah est avec ceux qui sont endurants.", "en": "O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient.", "id": "Hai orang-orang yang beriman, jadikanlah sabar dan shalat sebagai penolongmu, sesungguhnya Allah beserta orang-orang yang sabar.", "tr": "Ey İnananlar! Sabır ve namazla yardım dileyin. Allah, muhakkak ki sabredenlerle beraberdir.", "de": "O die ihr glaubt, sucht Hilfe in der Standhaftigkeit und im Gebet! Allah ist mit den Standhaften.", "nl": "O jullie die geloven, zoekt hulp door middel van geduld en de shalât. Voorwaar, Allah is met de geduldigen.", "es": "¡Vosotros, los que creéis, buscad ayuda en la paciencia y en la azalá! Alá está con los pacientes.", "it": "O voi che credete, rifugiatevi nella pazienza e nell'orazione. Invero Allah è con coloro che perseverano.", "ar": "يا أيها المؤمنون اطلبوا العون من الله في كل أموركم: بالصبر على النوائب والمصائب، وترك المعاصي والذنوب، والصبر على الطاعات والقربات، والصلاة التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. إن الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الآية: إثبات معيَّة الله الخاصة بالمؤمنين، المقتضية لما سلف ذكره؛ أما المعية العامة، المقتضية للعلم والإحاطة فهي لجميع الخلق."}}, "2:158": {"s": 2, "v": 158, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًۭا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ", "tl": {"en": "Innas Safaa wal-Marwata min sha'aaa'iril laahi faman hajjal Baita awi'tamara falaa junaaha 'alaihi ai yattawwafa bihimaa; wa man tatawwa'a khairan fa innal laaha Shaakirun'Aleem", "tr": "inne-ṣṣafâ velmervete min şe`âiri-llâh. femen ḥacce-lbeyte evi-`temera felâ cünâḥa `aleyhi ey yeṭṭavvefe bihimâ. vemen teṭavve`a ḫayran feinne-llâhe şâkirun `alîm."}, "tr": {"fr": "AS-Safâ et Al-Marwah sont vraiment parmi les lieux sacrés d'Allah. Donc, quiconque fait pèlerinage à la Maison ou fait l'Umra ne commet pas de péché en faisant le va-et-vient entre ces deux monts. Et quiconque fait de son propre gré une bonne œuvre, alors Allah est Reconnaissant, Omniscient.", "en": "Indeed, as-Safa and al-Marwah are among the symbols of Allah. So whoever makes Hajj to the House or performs 'umrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allah is appreciative and Knowing.", "id": "Sesungguhnya Shafaa dan Marwa adalah sebahagian dari syi'ar Allah. Maka barangsiapa yang beribadah haji ke Baitullah atau ber'umrah, maka tidak ada dosa baginya mengerjakan sa'i antara keduanya. Dan barangsiapa yang mengerjakan suatu kebajikan dengan kerelaan hati, maka sesungguhnya Allah Maha Mensyukuri kebaikan lagi Maha Mengetahui.", "tr": "Şüphesiz Safa ile Merve Allah'ın nişanelerindendir. Kim Kabe'yi hacceder veya umre yaparsa, bu ikisini de tavaf etmesinde bir beis yoktur. Kim gönülden iyilik yaparsa, karşılığını görür. Doğrusu Allah şükrün karşılığını verendir ve bilendir.", "de": "Gewiß, as-Safa und al-Marwa gehören zu den (Orten der) Kulthandlungen Allahs. Wenn einer die Pilgerfahrt zum Hause oder die Besuchsfahrt vollzieht, so ist es keine Sünde für ihn, wenn er zwischen ihnen (beiden) den Umgang macht. Und wer (von sich aus) freiwillig Gutes tut, so ist Allah Dankbar und Allwissend.", "nl": "Voorwaar, Shafa en Marwah behoren tot de aan Allah gewijde Tekenen. Wie dan de Haddj of de Oemrah verricht naar het Huis (de Ka'bah): het is geen zonde als hij om beide (Shafâ en Marwah) loopt (tijdens de Sa'î). En wie vrijwillig goede daden verricht: voorwaar, Allah is Waarderend en Alwetend.", "es": "Safa y Marwa figuran entre los ritos prescritos por Alá. Por eso, quien hace la peregrinación mayor a la Casa o la menor, no hace mal en dar las vueltas alrededor de ambas. Y si uno hace el bien espontáneamente, Alá es agradecido, omnisciente.", "it": "Safâ e Marwa sono veramente segni di Allah e non ci sarà male alcuno se coloro che fanno il Pellegrinaggio alla Casa o la Visita, correranno tra questi due [colli]. Allah sarà riconoscente a chi si sarà imposto volontariamente un'opera meritoria. Allah è grato, sapiente.", "ar": "إن الصفا والمروة- وهما جبلان صغيران قرب الكعبة من جهة الشرق- من معالم دين الله الظاهرة التي تعبَّد الله عباده بالسعي بينهما. فمَن قصد الكعبة حاجًّا أو معتمرًا، فلا إثم عليه ولا حرج في أن يسعى بينهما، بل يجب عليه ذلك، ومن فعل الطاعات طواعية من نفسه مخلصًا بها لله تعالى، فإن الله تعالى شاكر يثيب على القليل بالكثير، عليم بأعمال عباده فلا يضعها، ولا يبخس أحدًا مثقال ذرة."}}, "2:183": {"s": 2, "v": 183, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", "tl": {"en": "Yaa ayyuhal lazeena aamanoo kutiba 'alaikumus Siyaamu kamaa kutiba 'alal lazeena min qablikum la'allakum tattaqoon", "tr": "yâ eyyühe-lleẕîne âmenû kütibe `aleykümu-ṣṣiyâmü kemâ kütibe `ale-lleẕîne min ḳabliküm le`alleküm tetteḳûn."}, "tr": {"fr": "O les croyants! On vous a prescrit aS-Siyâm comme on l'a prescrit à ceux d'avant vous, ainsi atteindrez-vous la piété,", "en": "O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -", "id": "Hai orang-orang yang beriman, diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu agar kamu bertakwa,", "tr": "Ey İnananlar! Oruç, sizden öncekilere farz kılındığı gibi, Allah'a karşı gelmekten sakınasınız diye, size sayılı günlerde farz kılındı. İçinizden hasta olan veya yolculukta bulunan, tutamadığı günlerin sayısınca diğer günlerde tutar. Oruca dayanamıyanlar, bir düşkünü doyuracak kadar fidye verir. Kim gönülden iyilik yaparsa o iyilik kendisinedir. Oruç tutmanız eğer bilirseniz sizin için hayırlıdır.", "de": "O die ihr glaubt, vorgeschrieben ist euch das Fasten, so wie es denjenigen vor euch vorgeschrieben war, auf daß ihr gottesfürchtig werden möget.", "nl": "O jullie dei geloven, het vasten is jullie verplicht, zoals het ook verplicht was voor hen vóór jullie, hopelijk zullen jullie (Allah) vrezen.", "es": "¡Creyentes!; Se os ha prescrito el ayuno, al igual que se prescribió a los que os precedieron. Quizás, así, temáis a Alá.", "it": "O voi che credete, vi è prescritto il digiuno come era stato prescritto a coloro che vi hanno preceduto. Forse diverrete timorati;", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، فرض الله عليكم الصيام كما فرضه على الأمم قبلكم؛ لعلكم تتقون ربكم، فتجعلون بينكم وبين المعاصي وقاية بطاعته وعبادته وحده."}}, "2:184": {"s": 2, "v": 184, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "أَيَّامًۭا مَّعْدُودَٰتٍۢ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ ۖ فَمَن تَطَوَّعَ خَيْرًۭا فَهُوَ خَيْرٌۭ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ", "tl": {"en": "Ayyaamam ma'doodaat; faman kaana minkum mareedan aw'alaa safarin fa'iddatum min ayyaamin ukhar; wa 'alal lazeena yuteeqoonahoo fidyatun ta'aamu miskeenin faman tatawwa'a khairan fahuwa khairulo lahoo wa an tasoomoo khairul lakum in kuntum ta'lamoon", "tr": "eyyâmem ma`dûdât. femen kâne minküm merîḍan ev `alâ seferin fe`iddetüm min eyyâmin üḫar. ve`ale-lleẕîne yüṭîḳûnehû fidyetün ṭa`âmü miskîn. femen teṭavve`a ḫayran fehüve ḫayrul leh. veen teṣûmû ḫayrul leküm in küntüm ta`lemûn."}, "tr": {"fr": "pendant un nombre déterminé de jours. Quiconque d'entre vous est malade ou en voyage, devra jeûner un nombre égal d'autres jours. Mais pour ceux qui ne pourraient le supporter qu'(avec grande difficulté), il y a une compensation: nourrir un pauvre. Et si quelqu'un fait plus de son propre gré, c'est pour lui; mais il est mieux pour vous de jeûner; si vous saviez!", "en": "[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers excess - it is better for him. But to fast is best for you, if you only knew.", "id": "(yaitu) dalam beberapa hari yang tertentu. Maka barangsiapa diantara kamu ada yang sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain. Dan wajib bagi orang-orang yang berat menjalankannya (jika mereka tidak berpuasa) membayar fidyah, (yaitu): memberi makan seorang miskin. Barangsiapa yang dengan kerelaan hati mengerjakan kebajikan, maka itulah yang lebih baik baginya. Dan berpuasa lebih baik bagimu jika kamu mengetahui.", "tr": "Ey İnananlar! Oruç, sizden öncekilere farz kılındığı gibi, Allah'a karşı gelmekten sakınasınız diye, size sayılı günlerde farz kılındı. İçinizden hasta olan veya yolculukta bulunan, tutamadığı günlerin sayısınca diğer günlerde tutar. Oruca dayanamıyanlar, bir düşkünü doyuracak kadar fidye verir. Kim gönülden iyilik yaparsa o iyilik kendisinedir. Oruç tutmanız eğer bilirseniz sizin için hayırlıdır.", "de": "(Vorgeschrieben ist es euch) an bestimmten Tagen. Wer von euch jedoch krank ist oder sich auf einer Reise befindet, der soll eine (gleiche) Anzahl von anderen Tagen (fasten). Und denjenigen, die es zu leisten vermögen, ist als Ersatz die Speisung eines Armen auferlegt. Wer aber freiwillig Gutes tut, für den ist es besser. Und daß ihr fastet, ist besser für euch, wenn ihr (es) nur wißt!", "nl": "(Vast) en vastgesteld aantal dagen. Maar degene die dan van jullie ziek is, of op reis, dan een aantal andere dagen. En op degenen (van hen) die het (slechts met grote moeite) kunnen volbrengen, rust de plicht van Fidyah: het voeden van een arme. Maar degene die vrijwillig meer (dan verplicht is) geeft: dat is beter voor hem. En dat jullie vasten is beter voor jullie, als jullie dat maar weten.", "es": "Días contados. Y quien de vosotros esté enfermo o de viaje, un número igual de días. Y los que, pudiendo, no ayunen podrán redimirse dando de comer a un pobre. Y, si uno hace el bien espontáneamente, tanto mejor para él. Pero os conviene más ayunar. Si supierais...", "it": "[digiunerete] per un determinato numero di giorni. Chi però è malato o è in viaggio, digiuni in seguito altrettanti giorni. Ma per coloro che [a stento] potrebbero sopportarlo, c'è un'espiazione: il nutrimento di un povero. E se qualcuno dà di più, è un bene per lui. Ma è meglio per voi digiunare, se lo sapeste!", "ar": "فرض الله عليكم صيام أيام معلومة العدد وهي أيام شهر رمضان. فمن كان منكم مريضًا يشق عليه الصوم، أو مسافرًا فله أن يفطر، وعليه صيام عدد من أيام أُخَر بقدر التي أفطر فيها. وعلى الذين يتكلفون الصيام ويشقُّ عليهم مشقة غير محتملة كالشيخ الكبير، والمريض الذي لا يُرْجَى شفاؤه، فدية عن كل يوم يفطره، وهي طعام مسكين، فمن زاد في قدر الفدية تبرعًا منه فهو خير له، وصيامكم خير لكم -مع تحمُّل المشقة- من إعطاء الفدية، إن كنتم تعلمون الفضل العظيم للصوم عند الله تعالى."}}, "2:185": {"s": 2, "v": 185, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًۭى لِّلنَّاسِ وَبَيِّنَٰتٍۢ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ", "tl": {"en": "Shahru Ramadaanallazeee unzila feehil Qur'aanu hudal linnaasi wa baiyinaatim minal hudaa wal furqaan; faman shahida minkumush shahra falyasumhu wa man kaana mareedan aw 'alaa safarin fa'iddatum min ayyaamin ukhar; yureedul laahu bikumul yusra wa laa yureedu bikumul 'usra wa litukmilul 'iddata wa litukabbirul laaha 'alaa maa hadaakum wa la'allakum tashkuroon", "tr": "şehru rameḍane-lleẕî ünzile fîhi-lḳur'ânü hüdel linnâsi vebeyyinâtim mine-lhüdâ velfürḳân. femen şehide minkümü-şşehra felyeṣumh. vemen kâne merîḍan ev `alâ seferin fe`iddetüm min eyyâmin üḫar. yürîdü-llâhü bikümü-lyüsra velâ yürîdü bikümü-l`usr. velitükmilü-l`iddete velitükebbirü-llâhe `alâ mâ hedâküm vele`alleküm teşkürûn."}, "tr": {"fr": "(Ces jours sont) le mois de Ramadân au cours duquel le Coran a été descendu comme guide pour les gens, et preuves claires de la bonne direction et du discernement. Donc, quiconque d'entre vous est présent en ce mois, qu'il jeûne! Et quiconque est malade ou en voyage, alors qu'il jeûne un nombre égal d'autres jours. - Allah veut pour vous la facilité, Il ne veut pas la difficulté pour vous, afin que vous en complétiez le nombre et que vous proclamiez la grandeur d'Allah pour vous avoir guidés, et afin que vous soyez reconnaissants!", "en": "The month of Ramadhan [is that] in which was revealed the Qur'an, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the new moon of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allah intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allah for that [to] which He has guided you; and perhaps you will be grateful.", "id": "(Beberapa hari yang ditentukan itu ialah) bulan Ramadhan, bulan yang di dalamnya diturunkan (permulaan) Al Quran sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang hak dan yang bathil). Karena itu, barangsiapa di antara kamu hadir (di negeri tempat tinggalnya) di bulan itu, maka hendaklah ia berpuasa pada bulan itu, dan barangsiapa sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa), sebanyak hari yang ditinggalkannya itu, pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Dan hendaklah kamu mencukupkan bilangannya dan hendaklah kamu mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, supaya kamu bersyukur.", "tr": "Ramazan ayı, ki onda Kuran, insanlara yol gösterici ve doğruyu yanlıştan ayırıcı belgeler olarak indirildi. Sizden bu ayı idrak eden, onda oruç tutsun; hasta veya yolculukta olan, tutamadığı günlerin sayısınca diğer günlerde tutsun. Allah size kolaylık ister, zorluk istemez. Bu kolaylıkları, sayıyı tamamlamanız ve size yol gösterdiğine karşılık O'nu ululamanız için meşru kılmıştır; ola ki şükredersiniz.", "de": "Der Monat Ramadan (ist es), in dem der Qur'an als Rechtleitung für die Menschen herabgesandt worden ist und als klare Beweise der Rechtleitung und der Unterscheidung. Wer also von euch während dieses Monats anwesend ist, der soll ihn fasten, wer jedoch krank ist oder sich auf einer Reise befindet, eine (gleiche) Anzahl von anderen Tagen (fasten). Allah will für euch Erleichterung; Er will für euch nicht Erschwernis, - damit ihr die Anzahl vollendet und Allah als den Größten preist, dafür, daß Er euch rechtgeleitet hat, auf daß ihr dankbar sein möget.", "nl": "De maand Ramadhân is het waarin de Koran is neergezonden, als Leiding voor de mensheid en als duidelijke bewijzen van de Leiding en de Foerqân. Wie van jullie aanwezig is in de maand, laat die dan vasten, maar wie ziek is of op reis, dan is er een aantal andere dagen (om de vasten in te halen). Allah wenst voor jullie het gemakkelijke en Hij wenst niet voor jullie het ongemak. En maakt het aantal (dagen) vol en prijst Allah's Grootheid omdat Hij jullie leiding schonk, hopelijk zullen jullie dankbaar zijn.", "es": "Es el mes de ramadán, en que fue revelado el Corán como dirección para los hombres y como pruebas claras de la Dirección y del Criterio. Y quien de vosotros esté presente ese mes, que ayune en él. Y quien esté enfermo o de viaje, un número igual de días. Alá quiere hacéroslo fácil y no difícil. ¡Completad el número señalado de días y ensalzad a Alá por haberos dirigido! Quizás, así seáis agradecidos.", "it": "É nel mese di Ramadân che abbiamo fatto scendere il Corano, guida per gli uomini e prova di retta direzione e distinzione. Chi di voi ne testimoni [l'inizio] digiuni. E chiunque è malato o in viaggio assolva [in seguito] altrettanti giorni. Allah vi vuole facilitare e non procurarvi disagio, affinché completiate il numero dei giorni e proclamiate la grandezza di Allah Che vi ha guidato. Forse sarete riconoscenti!", "ar": "شهر رمضان الذي ابتدأ الله فيه إنزال القرآن في ليلة القدر؛ هداية للناس إلى الحق، فيه أوضح الدلائل على هدى الله، وعلى الفارق بين الحق والباطل. فمن حضر منكم الشهر وكان صحيحًا مقيمًا فليصم نهاره. ويُرخَّص للمريض والمسافر في الفطر، ثم يقضيان عدد تلك الأيام. يريد الله تعالى بكم اليسر والسهولة في شرائعه، ولا يريد بكم العسر والمشقة، ولتكملوا عدة الصيام شهرًا، ولتختموا الصيام بتكبير الله في عيد الفطر، ولتعظموه على هدايته لكم، ولكي تشكروا له على ما أنعم به عليكم من الهداية والتوفيق والتيسير."}}, "2:187": {"s": 2, "v": 187, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌۭ لَّكُمْ وَأَنتُمْ لِبَاسٌۭ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ", "tl": {"en": "Uhilla lakum laylatas Siyaamir rafasu ilaa nisaaa'ikum; hunna libaasullakum wa antum libaasullahunn; 'alimal laahu annakum kuntum takhtaanoona anfusakum fataaba 'alaikum wa 'afaa 'ankum fal'aana baashiroo hunna wabtaghoo maa katabal laahoo lakum; wa kuloo washraboo hattaa yatabaiyana lakumul khaitul abyadu minal khaitil aswadi minal fajri summa atimmus Siyaama ilal layl; wa laa tubaashiroo hunna wa antum 'aakifoona fil masaajid; tilka hudoodul laahi falaa taqraboohaa; kazaalika yubaiyinul laahu aayaatihee linnaasi la'allahum yattaqoon", "tr": "üḥille leküm leylete-ṣṣiyâmi-rrafeŝü ilâ nisâiküm. hünne libâsül leküm veentüm libâsül lehünn. `alime-llâhü enneküm küntüm taḫtânûne enfüseküm fetâbe `aleyküm ve`afâ `anküm. fel'âne bâşirûhünne vebtegû mâ ketebe-llâhü leküm. vekülû veşrabû ḥattâ yetebeyyene lekümü-lḫayṭu-l'ebyeḍu mine-lḫayṭi-l'esvedi mine-lfecr. ŝümme etimmu-ṣṣiyâme ile-lleyl. velâ tübâşirûhünne veentüm `âkifûne fi-lmesâcid. tilke ḥudûdü-llâhi felâ taḳrabûhâ. keẕâlike yübeyyinü-llâhü âyâtihî linnâsi le`allehüm yetteḳûn."}, "tr": {"fr": "On vous a permis, la nuit d'as-Siyâm, d'avoir des rapports avec vos femmes; elles sont un vêtement pour vous et vous êtes un vêtement pour elles. Allah sait que vous aviez clandestinement des rapports avec vos femmes. Il vous a pardonné et vous a graciés. Cohabitez donc avec elles, maintenant, et cherchez ce qu'Allah a prescrit en votre faveur; mangez et buvez jusqu'à ce que se distingue, pour vous, le fil blanc de l'aube du fil noir de la nuit. Puis accomplissez le jeûne jusqu'à la nuit. Mais ne cohabitez pas avec elles pendant que vous êtes en retraite rituelle dans les mosquées. Voilà les lois d'Allah: ne vous en approchez donc pas (pour les transgresser). C'est ainsi qu'Allah expose aux hommes Ses enseignements, afin qu'ils deviennent pieux!", "en": "It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are clothing for you and you are clothing for them. Allah knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allah has decreed for you. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the sunset. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allah, so do not approach them. Thus does Allah make clear His ordinances to the people that they may become righteous.", "id": "Dihalalkan bagi kamu pada malam hari bulan puasa bercampur dengan isteri-isteri kamu; mereka adalah pakaian bagimu, dan kamupun adalah pakaian bagi mereka. Allah mengetahui bahwasanya kamu tidak dapat menahan nafsumu, karena itu Allah mengampuni kamu dan memberi maaf kepadamu. Maka sekarang campurilah mereka dan ikutilah apa yang telah ditetapkan Allah untukmu, dan makan minumlah hingga terang bagimu benang putih dari benang hitam, yaitu fajar. Kemudian sempurnakanlah puasa itu sampai (datang) malam, (tetapi) janganlah kamu campuri mereka itu, sedang kamu beri'tikaf dalam mesjid. Itulah larangan Allah, maka janganlah kamu mendekatinya. Demikianlah Allah menerangkan ayat-ayat-Nya kepada manusia, supaya mereka bertakwa.", "tr": "Oruç tuttuğunuz günlerin gecesi kadınlarınıza yaklaşmanız size helal kılındı, onlar sizin örtünüz, siz de onların örtülerisiniz. Allah, nefsinize güvenemiyeceğinizi biliyordu, bu sebeple tevbenizi kabul edip sizi affetti; artık onlara yaklaşabilirsiniz. Allah'ın sizin için takdir ettiğini dileyin. Tan yerinde, beyaz iplik siyah iplikten sizce ayırdedilinceye kadar, yiyin için, sonra orucu geceye kadar tamamlayın. Mescidlerde itikafa çekildiğinizde kadınlarınıza yaklaşmayın. Allah insanlara yasaklardan sakınsınlar diye ayetlerini böylece apaçık bildirir.", "de": "Erlaubt ist euch, in der Nacht des Fastens mit euren Frauen Beischlaf auszuüben; sie sind euch ein Kleid, und ihr seid ihnen ein Kleid. Allah weiß, daß ihr euch selbst (immer wieder) betrogt, und da hat Er eure Reue angenommen und euch verziehen. Von jetzt an verkehrt mit ihnen und trachtet nach dem, was Allah für euch bestimmt hat, und eßt und trinkt, bis sich für euch der weiße vom schwarzen Faden der Morgendämmerung klar unterscheidet! Hierauf vollzieht das Fasten bis zur Nacht! Und verkehrt nicht mit ihnen, während ihr euch (zur Andacht) in die Gebetsstätten zurückgezogen habt! Dies sind Allahs Grenzen, so kommt ihnen nicht zu nahe! So macht Allah den Menschen Seine Zeichen klar, auf daß sie gottesfürchtig werden mögen.", "nl": "Het is jullie in de nachten van het vasten toegestaan omgang te hebben met jullie vrouwen. Zij zijn (als) kleding voor jullie en jullie zijn (als) kleding voor hen. Allah wist dat jullie jezelf bedrogen, Hij aanvaardde jullie berouw en vergaf jullie. Nu mogen jullie dan omgang met hen hebben. En streeft naar wat Allah voor jullie bepaald heeft. En eet en drinkt tot de witte draad en de zwarte draad voor jullie te onderscheiden is, het is Fadjr (ochtendschemering). Maakt daarna het vasten vol tot zonsondergang. En hebt geen omgang met hen, terwijl jullie I'tikâf in de moskeeen verrichten. Dat zijn de greenzen van Allah, nadert deze daarorn niet. Zo maakt Allah Zijn Tekenen duidelijk voor de mensen, hopelijk zullen zij (Allah) vrezen.", "es": "Durante el mes del ayuno os es lícito por la noche uniros con vuestras mujeres: son vestidura para vosotros y vosotros lo sois para ellas. Alá sabe que os engañabais a vosotros mismos. Se ha vuelto a vosotros y os ha perdonado. Ahora, pues, yaced con ellas y buscad lo que Alá os ha prescrito. Comed y bebed hasta que, a la alborada, se distinga un hilo blanco de un hilo negro. Luego, observad un ayuno riguroso hasta la caída de la noche. Y no las toquéis mientras estéis de retiro en la mezquita. Éstas son las leyes de Alá, no os acerquéis a ellas. Así explica Alá Sus aleyas a los hombres. Quizás, así, Le teman.", "it": "Nelle notti del digiuno vi è stato permesso di accostarvi alle vostre donne; esse sono una veste per voi e voi siete una veste per loro. Allah sa come ingannavate voi stessi. Ha accettato il vostro pentimento e vi ha perdonati. Frequentatele dunque e cercate quello che Allah vi ha concesso. Mangiate e bevete finché, all'alba, possiate distinguere il filo bianco dal filo nero; quindi digiunate fino a sera. Ma non frequentatele se siete in ritiro nelle moschee. Ecco i limiti di Allah, non li sfiorate! Così Allah spiega agli uomini i Suoi segni, affinché siano timorati.", "ar": "أباح الله لكم في ليالي شهر رمضان جماعَ نسائكم، هنَّ ستر وحفظ لكم، وأنتم ستر وحفظ لهن. علم الله أنكم كنتم تخونون أنفسكم؛ بمخالفة ما حرَّمه الله عليكم من مجامعة النساء بعد العشاء في ليالي الصيام -وكان ذلك في أول الإسلام-، فتاب الله عليكم ووسَّع لكم في الأمر، فالآن جامعوهن، واطلبوا ما قدَّره الله لكم من الأولاد، وكلوا واشربوا حتى يتبَيَّن ضياء الصباح من سواد الليل، بظهور الفجر الصادق، ثم أتموا الصيام بالإمساك عن المفطرات إلى دخول الليل بغروب الشمس. ولا تجامعوا نساءكم أو تتعاطوا ما يفضي إلى جماعهن إذا كنتم معتكفين في المساجد؛ لأن هذا يفسد الاعتكاف (وهو الإقامة في المسجد مدة معلومة بنيَّة التقرب إلى الله تعالى). تلك الأحكام التي شرعها الله لكم هي حدوده الفاصلة بين الحلال والحرام، فلا تقربوها حتى لا تقعوا في الحرام. بمثل هذا البيان الواضح يبين الله آياته وأحكامه للناس؛ كي يتقوه ويخشَوْه."}}, "2:189": {"s": 2, "v": 189, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ", "tl": {"en": "Yas'aloonaka 'anil ahillati qul hiya mawaaqeetu linnaasi wal Hajj; wa laisal birru bi an taatul buyoota min zuhoorihaa wa laakinnal birra manit taqaa; waatul buyoota min abwaa bihaa; wattaqullaaha la'allakum tuflihoon", "tr": "yes'elûneke `ani-l'ehilleh. ḳul hiye mevâḳîtü linnâsi velḥacc. veleyse-lbirru bien te'tü-lbüyûte min żuhûrihâ velâkinne-lbirra meni-tteḳâ. ve'tü-lbüyûte min ebvâbihâ. vetteḳu-llâhe le`alleküm tüfliḥûn."}, "tr": {"fr": "Ils t'interrogent sur les nouvelles lunes - Dis: «Elles servent aux gens pour compter le temps, et aussi pour le hajj [pèlerinage]. Et ce n'est pas un acte de bienfaisance que de rentrer chez vous par l'arrière des maisons. Mais la bonté pieuse consiste à craindre Allah. Entrez donc dans les maisons par leurs portes. Et craignez Allah, afin que vous réussissiez!", "en": "They ask you, [O Muhammad], about the new moons. Say, \"They are measurements of time for the people and for Hajj.\" And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allah. And enter houses from their doors. And fear Allah that you may succeed.", "id": "Mereka bertanya kepadamu tentang bulan sabit. Katakanlah: \"Bulan sabit itu adalah tanda-tanda waktu bagi manusia dan (bagi ibadat) haji; Dan bukanlah kebajikan memasuki rumah-rumah dari belakangnya, akan tetapi kebajikan itu ialah kebajikan orang yang bertakwa. Dan masuklah ke rumah-rumah itu dari pintu-pintunya; dan bertakwalah kepada Allah agar kamu beruntung.", "tr": "Sana hilal halindeki ayları sorarlar. De ki: \"Onlar, insanların ve hac vakitlerinin ölçüsüdür\". Evlere arkalarından girmeniz iyilik değildir; iyi kimse kötülükten sakınan kimsedir. Evlere kapılarından girin; Allah'tan sakının ki muradınıza erersiniz.", "de": "Sie fragen dich nach den Jungmonden. Sag: Sie sind festgesetzte Zeiten für die Menschen und für die Pilgerfahrt. Und nicht darin besteht die Frömmigkeit, daß ihr von der Rückseite in die Häuser kommt. Frömmigkeit besteht vielmehr darin, daß man gottesfürchtig ist. So kommt durch die Türen in die Häuser und fürchtet Allah, auf daß es euch wohl ergehen möge!", "nl": "Zij vragen jou (Moehammad) over de nieuwe manen. Zeg: \"Zij zijn tijdsaanduidingen voor de mensen en (voor het vastellen van) de Haddj. En het is geen vroomheid dat jullie de huizen binnengaan aan de achterzijden, vroom zijn zij (Allah) vrezen en die de huizen binnengaan door hun deuren. En vreest Allah, hopelijk zullen jullie welslagen.", "es": "Te preguntan acerca de los novilunios. Di: «Son indicaciones que sirven a los hombres para fijar la época de la peregrinación». La piedad no estriba en que entréis en casa por detrás. sino en que temáis a Alá. ¡Entrad en casa por la puerta y temed a Alá! Quizás, así prosperéis.", "it": "Quando ti interrogano sui noviluni rispondi: “Servono alle genti per il computo del tempo e per il Pellegrinaggio. Non è una azione pia entrare in casa dalla parte posteriore, la pietà è nel timore di Allah. Entrate pure nelle case passando per le porte e temete Allah, affinché possiate essere tra coloro che prospereranno.", "ar": "يسألك أصحابك -أيها النبي-: عن الأهلة وتغيُّر أحوالها، قل لهم: جعل اللهُ الأهلة علامات يعرف بها الناس أوقات عباداتهم المحددة بوقت مثل الصيام والحج، ومعاملاتهم. وليس الخير ما تعودتم عليه في الجاهلية وأول الإسلام من دخول البيوت من ظهورها حين تُحْرِمون بالحج أو العمرة، ظانين أن ذلك قربة إلى الله، ولكن الخير هو فِعْلُ مَنِ اتقى الله واجتنب المعاصي، وادخلوا البيوت من أبوابها عند إحرامكم بالحج أو العمرة، واخشوا الله تعالى في كل أموركم، لتفوزوا بكل ما تحبون من خيري الدنيا والآخرة."}}, "2:201": {"s": 2, "v": 201, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ حَسَنَةًۭ وَقِنَا عَذَابَ ٱلنَّارِ", "tl": {"en": "Wa minhum mai yaqoolu rabbanaaa aatina fid dunyaa hasanatawn wa fil aakhirati hasanatanw wa qinaa azaaban Naar", "tr": "veminhüm mey yeḳûlü rabbenâ âtinâ fi-ddünyâ ḥasenetev vefi-l'âḫirati ḥasenetev veḳinâ `aẕâbe-nnâr."}, "tr": {"fr": "Et il est des gens qui disent: «Seigneur! Accorde nous belle part ici-bas, et belle part aussi dans l'au-delà; et protège-nous du châtiment du Feu!»", "en": "But among them is he who says, \"Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.\"", "id": "Dan di antara mereka ada orang yang berdoa: \"Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat dan peliharalah kami dari siksa neraka\".", "tr": "\"Rabbimiz! Bize dünyada iyiyi, ahirette de iyiyi ver, bizi ateşin azabından koru\" diyenler vardır.", "de": "Unter ihnen gibt es aber auch solche, die sagen: \"Unser Herr, gib uns im Diesseits Gutes und im Jenseits Gutes, und bewahre uns vor der Strafe des (Höllen)feuers!", "nl": "En er zijn er onder hen die smeken: \"Onze Heer, geef ons in de wereld wat goed is en het Hiernamaals wat goed is en bescherm ons tegen de bestraffing van de Hel.\"", "es": "Otros dicen: «¡Señor! ¡Danos bien en la vida de acá y en la otra y presérvanos del castigo del Fuego!»", "it": "E ci sono persone che dicono: “Signor nostro! Dacci le cose buone di questo mondo e le cose buone dell'altra vita e allontanaci dal Fuoco!”.", "ar": "ومن الناس فريق مؤمن يقول في دعائه: ربنا آتنا في الدنيا عافية ورزقًا وعلمًا نافعًا، وعملا صالحًا، وغير ذلك من أمور الدين والدنيا، وفي الآخرة الجنة، واصرف عنَّا عذاب النار. وهذا الدعاء من أجمع الأدعية، ولهذا كان أكثر دعاء النبي صلى الله عليه وسلم، كما ثبت في الصحيحين."}}, "2:255": {"s": 2, "v": 255, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", "tl": {"en": "Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom; laa taakhuzuhoo sinatunw wa laa nawm; lahoo maa fissamaawaati wa maa fil ard; man zal lazee yashfa'u indahooo illaa bi-iznih; ya'lamu maa baina aydeehim wa mww khalfahum wa laa yuheetoona bishai'im min 'ilmihee illaa bimaa shaaa'; wasi'a Kursiyyuhus samaawaati wal arda wa laa ya'ooduho hifzuhumaa; wa Huwal Aliyyul 'Azeem", "tr": "allâhü lâ ilâhe illâ hû. elḥayyü-lḳayyûm. lâ te'ḫuẕühû sinetüv velâ nevm. lehû mâ fi-ssemâvâti vemâ fi-l'arḍ. men ẕe-lleẕî yeşfe`u `indehû illâ biiẕnih. ya`lemü mâ beyne eydîhim vemâ ḫalfehüm. velâ yüḥîṭûne bişey'im min `ilmihî illâ bimâ şâ'. vesi`a kürsiyyühü-ssemâvâti vel'arḍ. velâ yeûdühû ḥifżuhümâ. vehüve-l`aliyyü-l`ażîm."}, "tr": {"fr": "Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand.", "en": "Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.", "id": "Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.", "tr": "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür.", "de": "Allah - es gibt keinen Gott außer Ihm, dem Lebendigen und Beständigen. Ihn überkommt weder Schlummer noch Schlaf. Ihm gehört (alles), was in den Himmeln und was auf der Erde ist. Wer ist es denn, der bei Ihm Fürsprache einlegen könnte - außer mit Seiner Erlaubnis? Er weiß, was vor ihnen und was hinter ihnen liegt, sie aber umfassen nichts von Seinem Wissen - außer, was Er will. Sein Thronschemel umfaßt die Himmel und die Erde, und ihre Behütung beschwert Ihn nicht. Er ist der Erhabene und Allgewaltige.", "nl": "Allah, er is geen god dan Hij, de Levende, de Zelfstandige, sluimer noch slaap kan Hem treffen, aan Hem behoort toe wat er in de hemelen en wat er op de aarde is. Wie is degene die van voorspraak is bij Hem zonder Zijn verlof? Hij kent wat er voor hen is en wat er achter hen is. En zij kunnen niets van Zijn Kennis omvatten, behalve wat Hij wil. En Zijn Zetel strekt zich uit over de Hemelen en de Aarde en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Almachtige.", "es": "¡Alá! No hay más dios que El. el Viviente, el Subsistente. Ni la somnolencia ni el sueño se apoderan de Él. Suyo es lo que está en los cielos y en la tierra. ¿Quién podrá interceder ante Él si no es con Su permiso? Conoce su pasado y su futuro, mientras que ellos no abarcan nada de Su ciencia, excepto lo que Él quiere. Su Trono se extiende sobre los cielos y sobre la tierra y su conservación no le resulta onerosa. Él es el Altísimo, el Grandioso.", "it": "Allah! Non c'è altro dio che Lui, il Vivente, l'Assoluto. Non Lo prendon mai sopore, né sonno. A Lui appartiene tutto quello che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce quello che è davanti a loro e quello che è dietro di loro e, della Sua scienza, essi apprendono solo ciò che Egli vuole. Il Suo Trono è più vasto dei cieli e della terra, e custodirli non Gli costa sforzo alcuno. Egli è l'Altissimo, l'Immenso.", "ar": "الله الذي لا يستحق الألوهية والعبودية إلا هو، الحيُّ الذي له جميع معاني الحياة الكاملة كما يليق بجلاله، القائم على كل شيء، لا تأخذه سِنَة أي: نعاس، ولا نوم، كل ما في السماوات وما في الأرض ملك له، ولا يتجاسر أحد أن يشفع عنده إلا بإذنه، محيط علمه بجميع الكائنات ماضيها وحاضرها ومستقبلها، يعلم ما بين أيدي الخلائق من الأمور المستقبلة، وما خلفهم من الأمور الماضية، ولا يَطَّلعُ أحد من الخلق على شيء من علمه إلا بما أعلمه الله وأطلعه عليه. وسع كرسيه السماوات والأرض، والكرسي: هو موضع قدمي الرب -جل جلاله- ولا يعلم كيفيته إلا الله سبحانه، ولا يثقله سبحانه حفظهما، وهو العلي بذاته وصفاته على جميع مخلوقاته، الجامع لجميع صفات العظمة والكبرياء. وهذه الآية أعظم آية في القرآن، وتسمى: (آية الكرسي)."}}, "2:285": {"s": 2, "v": 285, "nom": {"ar": "سُورَةُ البَقَرَةِ", "lat": "Al-Baqara"}, "ar": "ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ", "tl": {"en": "Aamanar-Rasoolu bimaaa unzila ilaihi mir-Rabbihee walmu'minoon; kullun aamana billaahi wa Malaaa'ikathihee wa Kutubhihee wa Rusulih laa nufarriqu baina ahadim-mir-Rusulihee wa qaaloo sami'naa wa ata'naa ghufraanaka Rabbanaa wa ilaikal-maseer", "tr": "âmene-rrasûlü bimâ ünzile ileyhi mir rabbihî velmü'minûn. küllün âmene billâhi vemelâiketihî vekütübihî verusülih. lâ nüferriḳu beyne eḥadim mir rusülih. veḳâlû semi`nâ veeṭa`nâ gufrâneke rabbenâ veileyke-lmeṣîr."}, "tr": {"fr": "Le Messager a cru en ce qu'on a fait descendre vers lui venant de son Seigneur, et aussi les croyants: tous ont cru en Allah, en Ses anges, à Ses livres et en Ses messagers; (en disant): «Nous ne faisons aucune distinction entre Ses messagers». Et ils ont dit: «Nous avons entendu et obéi. Seigneur, nous implorons Ton pardon. C'est à Toi que sera le retour».", "en": "The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination.\"", "id": "Rasul telah beriman kepada Al Quran yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya. (Mereka mengatakan): \"Kami tidak membeda-bedakan antara seseorangpun (dengan yang lain) dari rasul-rasul-Nya\", dan mereka mengatakan: \"Kami dengar dan kami taat\". (Mereka berdoa): \"Ampunilah kami ya Tuhan kami dan kepada Engkaulah tempat kembali\".", "tr": "Peygamber ve inananlar, ona Rabb'inden indirilene inandı. Hepsi Allah'a, meleklerine, kitaplarına, peygamberlerine inandı. \"Peygamberleri arasından hiçbirini ayırdetmeyiz, işittik, itaat ettik, Rabbimiz! Affını dileriz, dönüş Sanadır\" dediler.", "de": "Der Gesandte (Allahs) glaubt an das, was zu ihm von seinem Herrn (als Offenbarung) herabgesandt worden ist, und ebenso die Gläubigen; alle glauben an Allah, Seine Engel, Seine Bücher und Seine Gesandten - Wir machen keinen Unterschied bei jemandem von Seinen Gesandten. Und sie sagen: \"Wir hören und gehorchen. (Gewähre uns) Deine Vergebung, unser Herr! Und zu Dir ist der Ausgang.\"", "nl": "De Boodschapper gelooft in wat hem van zijn Heer is geopenbaard, en (ook) de gelovigen, allen geloven in Allah, en Zijn Engelen en Zijn Boeken en Zijn Boodschappers. Wij maken geen onderscheid tussen Zijn Boodschappers. Zij zeiden: \"Wij luisteren en wij gehoorzamen, vergeef ons, onze heer, en tot U is de terugkeer.\"", "es": "El Enviado cree en cuanto le ha sido revelado por su Señor, y lo mismo los creyentes. Todos ellos creen en Alá, en Sus ángeles. en Sus Escrituras y en Sus enviados. No hacemos distinción ente ninguno de Sus enviados. Han dicho: «Oímos y obedecemos. ¡Tu perdón, Señor! ¡Eres Tú el fin de todo!»", "it": "Il Messaggero crede in quello che è stato fatto scendere su di lui da parte del suo Signore, come del resto i credenti: tutti credono in Allah, nei Suoi Angeli, nei Suoi Libri e nei Suoi Messaggeri. “Non facciamo differenza alcuna tra i Suoi Messaggeri.” E dicono: “Abbiamo ascoltato e obbediamo. Perdono, Signore! E’ a Te, che tutto ritorna”.", "ar": "صدَّق وأيقن رسول الله محمد صلى الله عليه وسلم بما أوحي إليه من ربه وحُقَّ له أن يُوقن، والمؤمنون كذلك صدقوا وعملوا بالقرآن العظيم، كل منهم صدَّق بالله رباً وإلهًا متصفًا بصفات الجلال والكمال، وأن لله ملائكة كرامًا، وأنه أنزل كتبًا، وأرسل إلى خلقه رسلا لا نؤمن -نحن المؤمنين- ببعضهم وننكر بعضهم، بل نؤمن بهم جميعًا. وقال الرسول والمؤمنون: سمعنا يا ربنا ما أوحيت به، وأطعنا في كل ذلك، نرجو أن تغفر -بفضلك- ذنوبنا، فأنت الذي ربَّيتنا بما أنعمت به علينا، وإليك -وحدك- مرجعنا ومصيرنا."}}, "3:8": {"s": 3, "v": 8, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ", "tl": {"en": "Rabbanaa laa tuzigh quloobanaa ba'da iz hadaitanaa wa hab lanaa mil ladunka rahmah; innaka antal Wahhaab", "tr": "rabbenâ lâ tüzig ḳulûbenâ ba`de iẕ hedeytenâ veheb lenâ mil ledünke raḥmeh. inneke ente-lvehhâb."}, "tr": {"fr": "«Seigneur! Ne laisse pas dévier nos cœurs après que Tu nous aies guidés; et accorde-nous Ta miséricorde. C'est Toi, certes, le Grand Donateur!", "en": "[Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "id": "(Mereka berdoa): \"Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi Engkau; karena sesungguhnya Engkau-lah Maha Pemberi (karunia)\".", "tr": "Rabbimiz! Bizi doğru yola erdirdikten sonra kalblerimizi eğriltme, katından bize rahmet bağışla; şüphesiz Sen sonsuz bağışta bulunansın.", "de": "Unser Herr, lasse unsere Herzen nicht abschweifen, nachdem Du uns rechtgeleitet hast, und schenke uns Erbarmen von Dir aus. Du bist ja der unablässig Schenkende.", "nl": "(Zij zeggen:) \"Onze Heer, laat onze harten niet afwijken nadat U ons geleid heeft en schenk ons van Uw kant Barmhartigheid. Voorwaar. U bent de Schenker.", "es": "¡Señor! ¡No hagas que nuestros corazones se desvíen, después de habernos Tú dirigido! ¡Regálanos, de Ti, misericordia! Tú eres el Munífico.", "it": "“Signor nostro, non lasciare che i nostri cuori si perdano dopo che li hai guidati e concedici misericordia da parte Tua. In verità Tu sei Colui Che dona.", "ar": "ويقولون: يا ربنا لا تَصْرِف قلوبنا عن الإيمان بك بعد أن مننت علينا بالهداية لدينك، وامنحنا من فضلك رحمة واسعة، إنك أنت الوهاب: كثير الفضل والعطاء، تعطي مَن تشاء بغير حساب."}}, "3:42": {"s": 3, "v": 42, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ", "tl": {"en": "Wa iz qaalatil malaaa'ikatu yaa Ya Maryamu innal laahas tafaaki wa tahharaki wastafaaki 'alaa nisaaa'il 'aalameen", "tr": "veiẕ ḳâleti-lmelâiketü yâ meryemü inne-llâhe-ṣṭafâki veṭahheraki vaṣṭafâki `alâ nisâi-l`âlemîn."}, "tr": {"fr": "(Rappelle-toi) quand les Anges dirent: «O Marie, certes Allah t'a élue et purifiée; et Il t'a élue au-dessus des femmes des mondes.", "en": "And [mention] when the angels said, \"O Mary, indeed Allah has chosen you and purified you and chosen you above the women of the worlds.", "id": "Dan (ingatlah) ketika Malaikat (Jibril) berkata: \"Hai Maryam, sesungguhnya Allah telah memilih kamu, mensucikan kamu dan melebihkan kamu atas segala wanita di dunia (yang semasa dengan kamu).", "tr": "Melekler şöyle demişti: \"Ey Meryem! Allah seni seçip temizledi. Dünyaların kadınlarından seni üstün tuttu.\"", "de": "Und als die Engel sagten: \"O Maryam, Allah hat dich auserwählt und dich rein gemacht und dich auserwählt vor den Frauen der (anderen) Weltenbewohner!", "nl": "En toen de Engelen zeiden: \"O Maryam, voorwaarm Allah heeft jou uitverkoren en jou gereinigd en jou boven de vrouwen van de werelden uitverkoren.\"", "es": "Y cuando los ángeles dijeron:«¡María! Alá te ha escogido y purificado. Te ha escogido entre todas las mujeres del universo.", "it": "E quando gli angeli dissero: “In verità, o Maria, Allah ti ha eletta; ti ha purificata ed eletta tra tutte le donne del mondo.", "ar": "واذكر -أيها الرسول- حين قالت الملائكة: يا مريم إن الله اختاركِ لطاعته وطهَّركِ من الأخلاق الرذيلة، واختاركِ على نساء العالمين في زمانك."}}, "3:45": {"s": 3, "v": 45, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍۢ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ", "tl": {"en": "Iz qaalatil malaaa'ikatu yaa Maryamu innal laaha yubashshiruki bi Kalimatim minhus muhul Maseeh u 'Eesab nu Maryama wajeehan fid dunyaa wal Aakhirati wa minal muqarrabeen", "tr": "iẕ ḳâleti-lmelâiketü yâ meryemü inne-llâhe yübeşşiruki bikelimetim minh. ismühü-lmesîḥu `îse-bnü meryeme vecîhen fi-ddünyâ vel'âḫirati vemine-lmüḳarrabîn."}, "tr": {"fr": "(Rappelle-toi) quand les Anges dirent: «O Marie, voilà qu'Allah t'annonce une parole de Sa part: son nom sera «Al-Masîh», «'Issâ», fils de Marie, illustre ici-bas comme dans l'au-delà, et l'un des rapprochés d'Allah».", "en": "[And mention] when the angels said, \"O Mary, indeed Allah gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allah].", "id": "(Ingatlah), ketika Malaikat berkata: \"Hai Maryam, seungguhnya Allah menggembirakan kamu (dengan kelahiran seorang putera yang diciptakan) dengan kalimat (yang datang) daripada-Nya, namanya Al Masih Isa putera Maryam, seorang terkemuka di dunia dan di akhirat dan termasuk orang-orang yang didekatkan (kepada Allah),", "tr": "Melekler demişti ki: \"Ey Meryem! Allah sana, Kendinden bir sözü, adı Meryem oğlu İsa olan Mesihi, dünya ve ahirette şerefli ve Allah'a yakın kılınanlardan olarak müjdeler\".", "de": "Als die Engel sagten: \"O Maryam, Allah verkündet dir ein Wort von Ihm, dessen Name al-Masih 'Isa, der Sohn Maryams ist, angesehen im Diesseits und Jenseits und einer der (Allah) Nahegestellten.", "nl": "(Gedenkt) toen de Engelen zeiden: \"O Maryam, voorwaar, Allah kondigt jou met een Woord van Hem een verheugende tijding aan: zjin naam is de Messîh, 'Îsa, zoon van Maria, in deze wereld en in het Hiernamaals is hij een man van eer en hij behoort tot degenen die dicht (bij Allah) staan.", "es": "Cuando los ángeles dijeron: «¡María! Alá te anuncia la buena nueva de una Palabra que procede de Él. Su nombre es el Ungido, Jesús, hijo de María, considerado en la vida de acá y en la otra y será de los allegados.", "it": "Quando gli angeli dissero: “O Maria, Allah ti annuncia la lieta novella di una Parola da Lui proveniente: il suo nome è il Messia, Gesù figlio di Maria, eminente in questo mondo e nell'Altro, uno dei più vicini.", "ar": "وما كنت - يا نبي الله - هناك حين قالت الملائكة: يا مريم إن الله يُبَشِّرْكِ بولد يكون وجوده بكلمة من الله، أي يقول له: \"كن\"، فيكون، اسمه المسيح عيسى ابن مريم، له الجاه العظيم في الدنيا والآخرة، ومن المقربين عند الله يوم القيامة."}}, "3:59": {"s": 3, "v": 59, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍۢ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ", "tl": {"en": "Inna masala 'Eesaa 'indal laahi kamasali Aadama khalaqahoo min turaabin summa qaala lahoo kun fayakoon", "tr": "inne meŝele `îsâ `inde-llâhi kemeŝeli âdem. ḫaleḳahû min türâbin ŝümme ḳâle lehû kün feyekûn."}, "tr": {"fr": "Pour Allah, Jésus est comme Adam qu'Il créa de poussière, puis Il lui dit: «Sois»: et il fut.", "en": "Indeed, the example of Jesus to Allah is like that of Adam. He created Him from dust; then He said to him, \"Be,\" and he was.", "id": "Sesungguhnya misal (penciptaan) Isa di sisi AllAh, adalah seperti (penciptaan) Adam. Allah menciptakan Adam dari tanah, kemudian Allah berfirman kepadanya: \"Jadilah\" (seorang manusia), maka jadilah dia.", "tr": "Allah'ın katında İsa'nın durumu kendisini topraktan yaratıp sonra ol demesiyle olmuş olan Adem'in durumu gibidir.", "de": "Gewiß, das Gleichnis 'Isas ist bei Allah wie das Gleichnis Adams. Er erschuf ihn aus Erde. Hierauf sagte Er zu ihm: \"Sei!\" und da war er.", "nl": "Voorwaar, de gelijkenis (van de schepping) van 'Îsa is bij Allah als de gelijkenis (van de schepping) van Adam. Hij schiep hem uit aarde en zei vervolgens tot hem: 'Wees', en hij was.", "es": "Para Alá, Jesús es semejante a Adán, a quien creó de tierra y a quien dijo:«¡Sé!» y fue.", "it": "In verità, per Allah Gesù è simile ad Adamo, che Egli creò dalla polvere, poi disse: “Sii”, ed egli fu.", "ar": "إنَّ خَلْقَ الله لعيسى من غير أب مثَلُه كمثل خلق الله لآدم من غير أب ولا أم، إذ خلقه من تراب الأرض، ثم قال له: \"كن بشرًا\" فكان. فدعوى إلهية عيسى لكونه خلق من غير أب دعوى باطلة؛ فآدم عليه السلام خلق من غير أب ولا أم، واتفق الجميع على أنه عَبْد من عباد الله."}}, "3:67": {"s": 3, "v": 67, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّۭا وَلَا نَصْرَانِيًّۭا وَلَٰكِن كَانَ حَنِيفًۭا مُّسْلِمًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ", "tl": {"en": "Maa kaana Ibraaheemu Yahoodiyyanw wa laa Nasraa niyyanw wa laakin kaana Haneefam Muslimanw wa maa kaana minal mushrikeen", "tr": "mâ kâne ibrâhîmü yehûdiyyev velâ naṣrâniyyev velâkin kâne ḥanîfem müslimâ. vemâ kâne mine-lmüşrikîn."}, "tr": {"fr": "Abraham n'était ni Juif ni Chrétien. Il était entièrement soumis à Allah (Musulman). Et il n'était point du nombre des Associateurs.", "en": "Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allah]. And he was not of the polytheists.", "id": "Ibrahim bukan seorang Yahudi dan bukan (pula) seorang Nasrani, akan tetapi dia adalah seorang yang lurus lagi berserah diri (kepada Allah) dan sekali-kali bukanlah dia termasuk golongan orang-orang musyrik.", "tr": "İbrahim, yahudi de, hıristiyan da değildi, ama doğruya yönelen bir müslimdi; ortak koşanlardan değildi.", "de": "Ibrahim war weder ein Jude noch ein Christ, sondern er war Anhänger des rechten Glaubens, einer, der sich Allah ergeben hat, und er gehörte nicht zu den Götzendienern.", "nl": "Ibrâhîm was geen Jood, en geen Christen, maar hij was een Hanîf, die zich (aan Allah) overgegeven had, en hij behoorde niet tot de veelgodenaanbidders.", "es": "Abraham no fue judío ni cristiano, sino que fue hanif, sometido a Alá, no asociador.", "it": "Abramo non era né giudeo, né nazareno, ma puro credente e musulmano. E non era uno degli associatori.", "ar": "ما كان إبراهيم يهودياً ولا نصرانياً، فلم تكن اليهودية ولا النصرانية إلا من بعده، ولكن كان متبعًا لأمر الله وطاعته، مستسلمًا لربه، وما كان من المشركين."}}, "3:96": {"s": 3, "v": 96, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "إِنَّ أَوَّلَ بَيْتٍۢ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًۭا وَهُدًۭى لِّلْعَٰلَمِينَ", "tl": {"en": "Inna awwala Baitinw wudi'a linnaasi lallazee bi Bakkata mubaarakanw wa hudal lil 'aalameen", "tr": "inne evvele beytiv vuḍi`a linnâsi lelleẕî bibekkete mübârakev vehüdel lil`âlemîn."}, "tr": {"fr": "La première Maison qui ait été édifiée pour les gens, c'est bien celle de Bakka (la Mecque) bénie et une bonne direction pour l'univers.", "en": "Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds.", "id": "Sesungguhnya rumah yang mula-mula dibangun untuk (tempat beribadat) manusia, ialah Baitullah yang di Bakkah (Mekah) yang diberkahi dan menjadi petunjuk bagi semua manusia.", "tr": "Doğrusu insanlar için ilk kurulan ev, Mekke'de, dünyalar için mübarek ve doğru yol gösteren Kabe'dir.", "de": "Das erste (Gottes)haus, das für die Menschen gegründet wurde, ist wahrlich dasjenige in Bakka, als ein gesegnetes (Haus) und eine Rechtleitung für die Weltenbewohner.", "nl": "Voorwar, het eerste Huis dat voor de mensheid gestricht werd, is dat in het gezegende Bakka (Mekkah), als leiding voor de werelden.", "es": "La primera Casa erigida para los hombres es, ciertamente, la de Bakka, casa bendita y dirección para todos.", "it": "La prima Casa che è stata eretta per gli uomini è certamente quella di Bakka, benedetta, guida del creato.", "ar": "إن أول بيت بُني لعبادة الله في الأرض لهو بيت الله الحرام الذي في \"مكة\"، وهذا البيت مبارك تضاعف فيه الحسنات، وتتنزل فيه الرحمات، وفي استقباله في الصلاة، وقصده لأداء الحج والعمرة، صلاح وهداية للناس أجمعين."}}, "3:97": {"s": 3, "v": 97, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌۭ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًۭا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ", "tl": {"en": "Feehi Aayaatum baiyinaatum Maqaamu Ibraaheema wa man dakhalahoo kaana aaminaa; wa lillaahi 'alan naasi Hijjul Baiti manis tataa'a ilaihi sabeelaa; wa man kafara fa innal laaha ghaniyyun 'anil 'aalameen", "tr": "fîhi âyâtüm beyyinâtüm meḳâmü ibrâhîm. vemen deḫalehû kâne âminâ. velillâhi `ale-nnâsi ḥiccü-lbeyti meni-steṭâ`a ileyhi sebîlâ. vemen kefera feinne-llâhe ganiyyün `ani-l`âlemîn."}, "tr": {"fr": "Là sont des signes évidents, parmi lesquels l'endroit où Abraham s'est tenu debout; et quiconque y entre est en sécurité. Et c'est un devoir envers Allah pour les gens qui ont les moyens, d'aller faire le pèlerinage de la Maison. Et quiconque ne croit pas... Allah Se passe largement des mondes.", "en": "In it are clear signs [such as] the standing place of Abraham. And whoever enters it shall be safe. And [due] to Allah from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves - then indeed, Allah is free from need of the worlds.", "id": "Padanya terdapat tanda-tanda yang nyata, (di antaranya) maqam Ibrahim; barangsiapa memasukinya (Baitullah itu) menjadi amanlah dia; mengerjakan haji adalah kewajiban manusia terhadap Allah, yaitu (bagi) orang yang sanggup mengadakan perjalanan ke Baitullah. Barangsiapa mengingkari (kewajiban haji), maka sesungguhnya Allah Maha Kaya (tidak memerlukan sesuatu) dari semesta alam.", "tr": "Orada apaçık deliller vardır, İbrahim'in makamı vardır; kim oraya girerse, güvenlik içinde olur; oraya yol bulabilen insana Allah için Kabe'yi haccetmesi gereklidir. Kim inkar ederse, bilsin ki; doğrusu Allah alemlerden müstağnidir.", "de": "Darin liegen klare Zeichen. (Es ist) der Standort Ibrahims. Und wer es betritt, ist sicher. Und Allah steht es den Menschen gegenüber zu, daß sie die Pilgerfahrt zum Hause unternehmen - (diejenigen,) die dazu die Möglichkeit haben. Wer aber ungläubig ist, so ist Allah der Weltenbewohner Unbedürftig.", "nl": "Er in zijn duidelijk Tekenen, (zoals) de standplaats van Ibrâhîm, en hij die er in binnengaat is veilig. En Allah heeft voor de mensen de bedevaart verplicht gesteld, (voor hen) die in staat zijn daarheen op weg te gaan. En wie ongerlovig is: Allah heeft geen behoeft aan de werelden.", "es": "Hay en ella signos claros. Es el lugar de Abraham y quien entre en él estará seguro. Alá ha prescrito a los hombres la peregrinación a la Casa, si disponen de medios. Y quien no crea... Alá puede prescindir de las criaturas.", "it": "In essa, vi sono i segni evidenti, come il luogo in cui ristette Abramo: chi vi entra è al sicuro. Spetta agli uomini che ne hanno la possibilità di andare, per Allah, in pellegrinaggio alla Casa. Quanto a colui che lo nega, sappia che Allah fa a meno delle creature”.", "ar": "في هذا البيت دلالات ظاهرات أنه من بناء إبراهيم، وأن الله عظَّمه وشرَّفه، منها: مقام إبراهيم عليه السلام، وهو الحَجَر الذي كان يقف عليه حين كان يرفع القواعد من البيت هو وابنه إسماعيل، ومن دخل هذا البيت أَمِنَ على نفسه فلا يناله أحد بسوء. وقد أوجب الله على المستطيع من الناس في أي مكان قَصْدَ هذا البيت لأداء مناسك الحج. ومن جحد فريضة الحج فقد كفر، والله غني عنه وعن حجِّه وعمله، وعن سائر خَلْقه."}}, "3:123": {"s": 3, "v": 123, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍۢ وَأَنتُمْ أَذِلَّةٌۭ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ", "tl": {"en": "Wa laqad nasarakumul laahu bi-Badrinw wa antum azillatun fattaqul laaha la'allakum tashkuroon", "tr": "veleḳad neṣarakümü-llâhü bibedriv veentüm eẕilleh. fetteḳu-llâhe le`alleküm teşkürûn."}, "tr": {"fr": "Allah vous a donné la victoire, à Badr, alors que vous étiez humiliés. Craignez Allah donc. Afin que vous soyez reconnaissants!", "en": "And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful.", "id": "Sungguh Allah telah menolong kamu dalam peperangan Badar, padahal kamu adalah (ketika itu) orang-orang yang lemah. Karena itu bertakwalah kepada Allah, supaya kamu mensyukuri-Nya.", "tr": "And olsun ki, siz düşkün bir durumda iken, Bedir'de, Allah size yardım etmişti; Allah'tan sakının ki şükredebilesiniz.", "de": "Allah hat euch doch schon in Badr geholfen, als ihr verächtlich erschient. Darum fürchtet Allah, auf daß ihr dankbar sein möget!", "nl": "En voorzeker, Allah heeft jullie toch op (het slagveld van) Badr geholpen terwijl jullie zwakker waren, vreest daarom Allah, hopelijk zuilen jullie dankbaar zijn.", "es": "Alá, ciertamente, os auxilió en Badr cuando erais humillados. ¡Temed a Alá! Quizás, así, seáis agradecidos.", "it": "Allah già vi soccorse a Badr, mentre eravate deboli. Temete Allah! Forse sarete riconoscenti!", "ar": "ولقد نصركم الله -أيها المؤمنون- بـ \"بدر\" على أعدائكم المشركين مع قلة عَدَدكم وعُدَدكم، فخافوا الله بفعل أوامره واجتناب نواهيه؛ لعلكم تشكرون له نعمه."}}, "3:134": {"s": 3, "v": 134, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ", "tl": {"en": "Allazeena yunfiqoona fissarraaa'i waddarraaa'i wal kaazimeenal ghaiza wal aafeena 'anin-naas; wallaahu yuhibbul muhsineen", "tr": "elleẕîne yünfiḳûne fi-sserrâi veḍḍarrâi velkâżimîne-lgayża vel`âfîne `ani-nnâs. vellâhü yüḥibbü-lmuḥsinîn."}, "tr": {"fr": "qui dépensent dans l'aisance et dans l'adversité, qui dominent leur rage et pardonnent à autrui - car Allah aime les bienfaisants -", "en": "Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good;", "id": "(yaitu) orang-orang yang menafkahkan (hartanya), baik di waktu lapang maupun sempit, dan orang-orang yang menahan amarahnya dan memaafkan (kesalahan) orang. Allah menyukai orang-orang yang berbuat kebajikan.", "tr": "Onlar bollukta ve darlıkta sarfederler, öfkelerini yenerler, insanların kusurlarını affederler. Allah iyilik yapanları sever.", "de": "die in Freude und Leid ausgeben und ihren Grimm zurückhalten und den Menschen verzeihen. Und Allah liebt die Gutes Tuenden", "nl": "(Zij zij het) die uitgeven in voorspoed en in tegenspoed, en die de woede inhouden en vergevers van de mensen zijn. En Allah houdt van de weldoeners.", "es": "que dan limosna tanto en la prosperidad como en la adversidad, reprimen la ira, perdonan a los hombres -Alá ama a quienes hacen el bien-,", "it": "quelli che donano nella buona e nella cattiva sorte, per quelli che controllano la loro collera e perdonano agli altri, poiché Allah ama chi opera il bene,", "ar": "الذين ينفقون أموالهم في اليسر والعسر، والذين يمسكون ما في أنفسهم من الغيظ بالصبر، وإذا قَدَروا عَفَوا عمَّن ظلمهم. وهذا هو الإحسان الذي يحب الله أصحابه."}}, "3:144": {"s": 3, "v": 144, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "وَمَا مُحَمَّدٌ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًۭٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ", "tl": {"en": "Wa maa Muhammadun illaa Rasoolun qad khalat min qablihir Rusul; afa'im maata aw qutilan qalabtum 'alaaa a'qaabikum; wa mai yanqalib 'alaa aqibihi falai yadurral laaha shai'aa; wa sayajzil laahush shaakireen", "tr": "vemâ müḥammedün illâ rasûl. ḳad ḫalet min ḳablihi-rrusül. efeim mâte ev ḳutile-nḳalebtüm `alâ a`ḳâbiküm. vemey yenḳalib `alâ `aḳibeyhi feley yeḍurra-llâhe şey'â. veseyeczi-llâhü-şşâkirîn."}, "tr": {"fr": "Muhammad n'est qu'un messager - des messagers avant lui sont passés -. S'il mourait, donc, ou s'il était tué, retourneriez-vous sur vos talons? Quiconque retourne sur ses talons ne nuira en rien à Allah; et Allah récompensera bientôt les reconnaissants.", "en": "Muhammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allah at all; but Allah will reward the grateful.", "id": "Muhammad itu tidak lain hanyalah seorang rasul, sungguh telah berlalu sebelumnya beberapa orang rasul. Apakah Jika dia wafat atau dibunuh kamu berbalik ke belakang (murtad)? Barangsiapa yang berbalik ke belakang, maka ia tidak dapat mendatangkan mudharat kepada Allah sedikitpun, dan Allah akan memberi balasan kepada orang-orang yang bersyukur.", "tr": "Muhammed ancak bir peygamberdir. Ondan önce de peygamberler geçmişti. Ölür veya öldürülürse geriye mi döneceksiniz? Geriye dönen, Allah'a hiçbir zarar vermez. Allah şükredenlerin mükafatını verecektir.", "de": "Und Muhammad ist doch nur ein Gesandter, vor dem schon Gesandte vorübergegangen sind. Wenn er nun stirbt oder getötet wird, werdet ihr euch (dann) auf den Fersen umkehren? Und wer sich auf den Fersen umkehrt, wird Allah keinerlei Schaden zufügen. Aber Allah wird (es) den Dankbaren vergelten.", "nl": "En Moehammad is niet meer dan een Boodschapper, vóór hem zijn de Boodschappers reeds heengegaan. Als hij dan zou sterven of gedood worden: waarom zouden jullie je dan op jullie hielen omdraaien (terugvallen in ongeloof)? En wie zich op zijn hielen zou omdraaien: het schaadt Allah niets. En Allah zal de dankbaren belonen.", "es": "Mahoma no es sino un enviado, antes del cual han pasado otros enviados. Si, pues, muriera o le mataran, ¿ibais a volveros atrás? Quien se vuelva atrás no causará ningún daño A Alá. Y Alá retribuirá a los agradecidos.", "it": "Muhammad, non è altro che un messaggero, altri ne vennero prima di lui; se morisse o se fosse ucciso, ritornereste sui vostri passi? Chi ritornerà sui suoi passi, non danneggerà Allah in nulla e, ben presto, Allah compenserà i riconoscenti.", "ar": "وما محمد إلا رسول من جنس الرسل الذين قبله يبلغ رسالة ربه. أفإن مات بانقضاء أجله أو قُتِل كما أشاعه الأعداء رجعتم عن دينكم،، تركتم ما جاءكم به نبيكم؟ ومن يرجِعُ منكم عن دينه فلن يضر الله شيئًا، إنما يضر نفسه ضررًا عظيمًا. أما مَن ثبت على الإيمان وشكر ربه على نعمة الإسلام، فإن الله يجزيه أحسن الجزاء."}}, "3:185": {"s": 3, "v": 185, "nom": {"ar": "سُورَةُ آلِ عِمۡرَانَ", "lat": "Aal-i-Imraan"}, "ar": "كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ", "tl": {"en": "Kullu nafsin zaaa'iqatul mawt; wa innamaa tuwaffawna ujoorakum Yawmal Qiyaamati faman zuhziha 'anin Naari waudkhilal Jannata faqad faaz; wa mal hayaatud dunyaaa illaa mataa'ul ghuroor", "tr": "küllü nefsin ẕâiḳatü-lmevt. veinnemâ tüveffevne ücûraküm yevme-lḳiyâmeh. femen zuḥziḥa `ani-nnâri veüdḫile-lcennete feḳad fâz. veme-lḥayâtü-ddünyâ illâ metâ`u-lgurûr."}, "tr": {"fr": "Toute âme goûtera la mort. Mais c'est seulement au Jour de la Résurrection que vous recevrez votre entière rétribution. Quiconque donc est écarté du Feu et introduit au Paradis, a certes réussi. Et la vie présente n'est qu'un objet de jouissance trompeuse.", "en": "Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion.", "id": "Tiap-tiap yang berjiwa akan merasakan mati. Dan sesungguhnya pada hari kiamat sajalah disempurnakan pahalamu. Barangsiapa dijauhkan dari neraka dan dimasukkan ke dalam surga, maka sungguh ia telah beruntung. Kehidupan dunia itu tidak lain hanyalah kesenangan yang memperdayakan.", "tr": "Her insan ölümü tadacaktır. Kıyamet günü, ecirleriniz size mutlaka ödenecektir. Ateşten uzaklaştırılıp cennete sokulan kimse artık kurtulmuştur. Dünya hayatı, zaten, sadece aldatıcı bir geçinmeden ibarettir.", "de": "Jede Seele wird den Tod kosten. Und erst am Tag der Auferstehung wird euch euer Lohn in vollem Maß zukommen. Wer dann dem (Höllen)feuer entrückt und in den (Paradies)garten eingelassen wird, der hat fürwahr einen Erfolg erzielt. Und das diesseitige Leben ist nur trügerischer Genuß.", "nl": "Iedere ziet zal de dood proeven, en voorwaar: pas op de Dag der Opstanding zullen jullie je beloning volledig ontvangen, en slechts degene die van de Het weggehouden wordt en het Paradijs binnengeleid wordt heeft waarlijk succes en het wereldse leven is slechts een misleidende genieting.", "es": "Cada uno gustará la muerte, pero no recibiréis vuestra recompensa íntegra hasta el día dela Resurrección. Habrá triunfado quien sea preservado del Fuego e introducido en el Jardín. La vida de acá no es más que falaz disfrute.", "it": "Ogni anima gusterà la morte, ma riceverete le vostre mercedi solo nel Giorno della Resurrezione. Chi sarà allontanato dal Fuoco e introdotto nel Paradiso, sarà certamente uno dei beati, poiché la vita terrena non è che ingannevole godimento.", "ar": "كل نفس لا بدَّ أن تذوق الموت، وبهذا يرجع جميع الخلق إلى ربهم؛ ليحاسبهم. وإنما تُوفَّون أجوركم على أعمالكم وافية غير منقوصة يوم القيامة، فمن أكرمه ربه ونجَّاه من النار وأدخله الجنة فقد نال غاية ما يطلب. وما الحياة الدنيا إلا متعة زائلة، فلا تغترُّوا بها."}}, "4:36": {"s": 4, "v": 36, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًۭا فَخُورًا", "tl": {"en": "Wa'budul laaha wa laa tushrikoo bihee shai'anw wa bilwaalidaini ihsaananw wa bizil qurbaa walyataamaa walmasaakeeni waljaari zilqurbaa waljaaril junubi wassaahibi biljambi wabnis sabeeli wa maa malakat aimaanukum; innal laaha laa yuhibbu man kaana mukhtaalan fakhooraa", "tr": "va`büdü-llâhe velâ tüşrikû bihî şey'ev vebilvâlideyni iḥsânev vebiẕi-lḳurbâ velyetâmâ velmesâkîni velcâri ẕi-lḳurbâ velcâri-lcünübi veṣṣâḥibi bilcembi vebni-ssebîli vemâ meleket eymânüküm. inne-llâhe lâ yüḥibbü men kâne muḫtâlen feḫûrâ."}, "tr": {"fr": "Adorez Allah et ne Lui donnez aucun associé. Agissez avec bonté envers (vos) père et mère, les proches, les orphelins, les pauvres, le proche voisin, le voisin lointain, le collègue et le voyageur, et les esclaves en votre possession, car Allah n'aime pas, en vérité, le présomptueux, l'arrogant,", "en": "Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful.", "id": "Sembahlah Allah dan janganlah kamu mempersekutukan-Nya dengan sesuatupun. Dan berbuat baiklah kepada dua orang ibu-bapa, karib-kerabat, anak-anak yatim, orang-orang miskin, tetangga yang dekat dan tetangga yang jauh, dan teman sejawat, ibnu sabil dan hamba sahayamu. Sesungguhnya Allah tidak menyukai orang-orang yang sombong dan membangga-banggakan diri,", "tr": "Allah'a kulluk edin, O'na bir şeyi ortak koşmayın. Ana babaya, yakınlara, yetimlere, düşkünlere, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya ve elinizin altında bulunan kimselere iyilik edin. Allah, kendini beğenip öğünenleri elbette sevmez.", "de": "Und dient Allah und gesellt Ihm nichts bei. Und zu den Eltern sollt ihr gütig sein und zu den Verwandten, den Waisen, den Armen, dem verwandten Nachbarn, dem fremden Nachbarn, dem Gefährten zur Seite, dem Sohn des Weges und denen, die eure rechte Hand besitzt. Allah liebt nicht, wer eingebildet und prahlerisch ist,", "nl": "En aanbidt Allah en kent Hem in niets een deelgenoot toe, en weest goed voor de ouders en de verwanten on de wezen en de behoeftigen en de verwante buren en de niet-verwante buren en de goede vrienden en de reiziger en de slaven waarover jullie beschikken. Voorwaar, Allah houdt niet van trotse hoogmoedigen.", "es": "¡Servid a Alá y no Le asociéis nada! ¡Sed buenos con vuestros padres, parientes, huérfanos, pobres, vecinos -parientes y no parientes-, el compañero de viaje, el viajero y vuestros esclavos! Alá no ama al presumido, al jactancioso,", "it": "Adorate Allah e non associateGli alcunché. Siate buoni con i genitori, i parenti, gli orfani, i poveri, i vicini vostri parenti e coloro che vi sono estranei, il compagno che vi sta accanto, il viandante e chi è schiavo in vostro possesso. In verità Allah non ama l'insolente, il vanaglorioso,", "ar": "واعبدوا الله وانقادوا له وحده، ولا تجعلوا له شريكًا في الربوبية والعبادة، وأحسنوا إلى الوالدين، وأدُّوا حقوقهما، وحقوق الأقربين، واليتامى والمحتاجين، والجار القريب منكم والبعيد، والرفيق في السفر وفي الحضر، والمسافر المحتاج، والمماليك من فتيانكم وفتياتكم. إن الله تعالى لا يحب المتكبرين من عباده، المفتخرين على الناس."}}, "4:103": {"s": 4, "v": 103, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًۭا مَّوْقُوتًۭا", "tl": {"en": "Fa izaa qadaitumus Salaata fazkurul laaha qiyaamanw wa qu'oodanw wa 'alaa junoobikum; fa izat maanantum fa aqeemus Salaah; innas Salaata kaanat 'alal mu'mineena kitaabam mawqootaa", "tr": "feiẕâ ḳaḍaytümu-ṣṣalâte feẕkürü-llâhe ḳiyâmev veḳu`ûdev ve`alâ cünûbiküm. feiẕe-ṭme'nentüm feeḳîmu-ṣṣalâh. inne-ṣṣalâte kânet `ale-lmü'minîne kitâbem mevḳûtâ."}, "tr": {"fr": "Quand vous avez accompli la Salât, invoquez le nom d'Allah, debout, assis ou couchés sur vos côtés. Puis lorsque vous êtes en sécurité, accomplissez la Salât (normalement), car la Salât demeure, pour les croyants, une prescription, à des temps déterminés.", "en": "And when you have completed the prayer, remember Allah standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times.", "id": "Maka apabila kamu telah menyelesaikan shalat(mu), ingatlah Allah di waktu berdiri, di waktu duduk dan di waktu berbaring. Kemudian apabila kamu telah merasa aman, maka dirikanlah shalat itu (sebagaimana biasa). Sesungguhnya shalat itu adalah fardhu yang ditentukan waktunya atas orang-orang yang beriman.", "tr": "Namazı kıldıktan başka, Allah'ı ayakta iken, otururken, yan yatarken de anın. Emniyete kavuştuğunuzda, namazı gereğince kılın. Namaz şüphesiz, inananlara belirli vakitlerde farz kılınmıştır.", "de": "Wenn ihr das Gebet vollzogen habt, dann gedenkt Allahs stehend, sitzend und auf der Seite (liegend). Wenn ihr in Ruhe seid, dann verrichtet das Gebet (wie üblich). Das Gebet ist den Gläubigen zu bestimmten Zeiten vorgeschrieben.", "nl": "En als jullie dan de shalât verricht hebben, gedenkt dan Allah, staand en zittend en liggend. En wanneer jullie veilig zijn, verricht dan de shalât. Voorwaar, de shalât is de gelovigen op vaste tijden voorgeschreven.", "es": "Cuando hayáis terminado la azalá recordad a Alá de pie, sentados o echados. Y, si os sentís tranquilos, haced la azalá. La azalá se ha prescrito a los creyentes en tiempos determinados.", "it": "Poi, dopo l'orazione, ricordatevi di Allah, in piedi, seduti o coricati su un fianco. Quando, poi, siete al sicuro eseguite l'orazione [normalmente]. In verità, per il credente, l'orazione è un obbligo in tempi ben determinati.", "ar": "فإذا أدَّيتم الصلاة، فأديموا ذكر الله في جميع أحوالكم، فإذا زال الخوف فأدُّوا الصلاة كاملة، ولا تفرِّطوا فيها فإنها واجبة في أوقات معلومة في الشرع."}}, "4:125": {"s": 4, "v": 125, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "وَمَنْ أَحْسَنُ دِينًۭا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًۭا", "tl": {"en": "Wa man ahsanu deenam mimmman aslama wajhahoo lillaahi wa huwa muhsinunw wattaba'a Millata Ibraaheema haneefaa; wattakhazal laahu Ibraaheema khaleelaa", "tr": "vemen aḥsenü dînem mimmen esleme vechehû lillâhi vehüve muḥsinüv vettebe`a millete ibrâhîme ḥanîfâ. vetteḫaẕe-llâhü ibrâhîme ḫalîlâ."}, "tr": {"fr": "Qui est meilleur en religion que celui qui soumet à Allah son être, tout en se conformant à la Loi révélée et suivant la religion d'Abraham, homme de droiture? Et Allah avait pris Abraham pour ami privilégié.", "en": "And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend.", "id": "Dan siapakah yang lebih baik agamanya dari pada orang yang ikhlas menyerahkan dirinya kepada Allah, sedang diapun mengerjakan kebaikan, dan ia mengikuti agama Ibrahim yang lurus? Dan Allah mengambil Ibrahim menjadi kesayangan-Nya.", "tr": "İyilik yaparak kendisini Allah'a teslim edip, hakka yönelen İbrahim'in dinine uyandan, din bakımından daha iyi kim olabilir? Allah İbrahim'i dost edinmişti.", "de": "Wer hätte eine bessere Religion, als wer sein Gesicht Allah hingibt und dabei Gutes tut und dem Glaubensbekenntnis Ibrahims folgt, (als) Anhänger des rechten Glaubens? Und Allah nahm sich Ibrahim zum Freund.", "nl": "En wie is beter in godsdienst dam degene die zich volledig aan Allah overgeeft en weldoet en de godsdienst van Ibrâhîm, Hanîf volgt. En Allah nam lbrahim als boezemvriend.", "es": "¿Quién es mejor, tocante a religión. que quien se somete a Alá, hace el bien y sigue la religión de Abraham, que fue hanif ? Alá tomó a Abraham como amigo.", "it": "Chi [potrebbe scegliere] religione migliore di colui che sottomette ad Allah il suo volto, opera il bene e segue sinceramente la religione di Abramo il sincero? Allah prese Abramo per amico.", "ar": "لا أحد أحسن دينًا ممن انقاد بقلبه وسائر جوارحه لله تعالى وحده، وهو محسن، واتبع دين إبراهيم وشرعه، مائلا عن العقائد الفاسدة والشرائع الباطلة. وقد اصطفى الله إبراهيم -عليه الصلاة والسلام- واتخذه صفيّاً من بين سائر خلقه. وفي هذه الآية، إثبات صفة الخُلّة لله -تعالى- وهي أعلى مقامات المحبة، والاصطفاء."}}, "4:136": {"s": 4, "v": 136, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْءَاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا", "tl": {"en": "Yaaa aiyuhal lazeena aamanooo aaminoo billaahi wa Rasoolihee wal Kitaabil lazee nazzala 'alaa Rasoolihee wal Kitaabil lazeee anzala min qabl; wa mai yakfur billaahi wa Malaaa'ikatihee wa Kutubihee wa Rusulihee wal Yawmil Aakhiri faqad dalla dalaalam ba'eedaa", "tr": "yâ eyyühe-lleẕîne âmenû âminû billâhi verasûlihî velkitâbi-lleẕî nezzele `alâ rasûlihî velkitâbi-lleẕî enzele min ḳabl. vemey yekfür billâhi vemelâiketihî vekütübihî verusülihî velyevmi-l'âḫiri feḳad ḍalle ḍalâlem be`îdâ."}, "tr": {"fr": "O les croyants! Soyez fermes en votre foi en Allah, en Son messager, au Livre qu'Il a fait descendre sur Son messager, et au Livre qu'Il a fait descendre avant. Quiconque ne croit pas en Allah, en Ses anges, en Ses Livres, en Ses messagers et au Jour dernier, s'égare, loin dans l'égarement.", "en": "O you who have believed, believe in Allah and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allah, His angels, His books, His messengers, and the Last Day has certainly gone far astray.", "id": "Wahai orang-orang yang beriman, tetaplah beriman kepada Allah dan Rasul-Nya dan kepada kitab yang Allah turunkan kepada Rasul-Nya serta kitab yang Allah turunkan sebelumnya. Barangsiapa yang kafir kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, dan hari kemudian, maka sesungguhnya orang itu telah sesat sejauh-jauhnya.", "tr": "Ey İnananlar! Allah'a, Peygamberine, Peygamberine indirdiği Kitap'a ve daha önce indirdiği Kitap'a inanmakta sebat gösterin. Kim Allah'ı, meleklerini, kitaplarını, peygamberlerini ve ahiret gününu inkar ederse, şüphesiz derin bir sapıklığa sapmıştır.", "de": "O die ihr glaubt, glaubt an Allah und Seinen Gesandten und das Buch, das Er Seinem Gesandten offenbart und die Schrift, die Er zuvor herabgesandt hat. Wer Allah, Seine Engel, Seine Schriften, Seine Gesandten und den Jüngsten Tag verleugnet, der ist fürwahr weit abgeirrt.", "nl": "O jullie die geloven! Gelooft in Allah en Zijn Boodschapper en in wat Hij aan Zijn Boodschapper openbaarde en in de Schrift die Hij vroeger openbaarde. En wie ongelovig is aan Allah en Zijn Engelen en Zijn Boeken en Zijn Boodschappers on de Laatste Dag: hij is waarlijk ver weg gedwaald.", "es": "¡Creyentes! Creed en Alá, en Su Enviado, en la Escritura que ha revelado a Su Enviado y en la Escritura que había revelado antes. Quien no cree en Alá, en Sus ángeles, en Sus Escrituras, en Sus enviados y en el último Día, ese tal está profundamente extraviado.", "it": "O voi che credete, credete in Allah e nel Suo Messaggero, al Libro che ha via via fatto scendere sul Suo Messaggero e alle Scritture che ha fatto scendere in precedenza. Chi non crede in Allah, nei Suoi angeli, nei Suoi Libri e nei Suoi Messaggeri e al Giorno Ultimo, si perde lontano nella perdizione.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه داوموا على ما أنتم عليه من التصديق الجازم بالله تعالى وبرسوله محمد صلى الله عليه وسلم، ومن طاعتهما، وبالقرآن الذي نزله عليه، وبجميع الكتب التي أنزلها الله على الرسل. ومن يكفر بالله تعالى، وملائكته المكرمين، وكتبه التي أنزلها لهداية خلقه، ورسله الذين اصطفاهم لتبليغ رسالته، واليوم الآخر الذي يقوم الناس فيه بعد موتهم للعرض والحساب، فقد خرج من الدين، وبَعُدَ بعدًا كبيرًا عن طريق الحق."}}, "4:163": {"s": 4, "v": 163, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "۞ إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍۢ وَٱلنَّبِيِّۦنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًۭا", "tl": {"en": "innaaa awhainaaa ilaika kamaaa awhainaaa ilaa Noohinw wan nabiyyeena mim ba'dih; wa awhainaaa ilaaa ibraaheema wa Ismaaa'eela wa Ishaaqa wa Ya'qooba wal Asbaati wa 'Eesaa wa Ayyooba wa Yoonusa wa haaroona wa Sulaimaan; wa aatainaa Daawooda Zabooraa", "tr": "innâ evḥaynâ ileyke kemâ evḥaynâ ilâ nûḥiv vennebiyyîne mim ba`dih. veevḥaynâ ilâ ibrâhîme veismâ`île veisḥâḳa veya`ḳûbe vel'esbâṭi ve`îsâ veeyyûbe veyûnüse vehârûne vesüleymân. veâteynâ dâvûde zebûrâ."}, "tr": {"fr": "Nous t'avons fait une révélation comme Nous fîmes à Noé et aux prophètes après lui. Et Nous avons fait révélation à Abraham, à Ismaël, à Isaac, à Jacob aux Tribus, à Jésus, à Job, à Jonas, à Aaron et à Salomon, et Nous avons donné le Zabour à David.", "en": "Indeed, We have revealed to you, [O Muhammad], as We revealed to Noah and the prophets after him. And we revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon, and to David We gave the book [of Psalms].", "id": "Sesungguhnya Kami telah memberikan wahyu kepadamu sebagaimana Kami telah memberikan wahyu kepada Nuh dan nabi-nabi yang kemudiannya, dan Kami telah memberikan wahyu (pula) kepada Ibrahim, Isma'il, Ishak, Ya'qub dan anak cucunya, Isa, Ayyub, Yunus, Harun dan Sulaiman. Dan Kami berikan Zabur kepada Daud.", "tr": "Nuh'a, ondan sonra gelen peygamberlere vahyettiğimiz, İbrahim'e, İsmail'e, İshak'a, Yakub'a, torunlarına, İsa'ya, Eyyub'a, Yunus'a, Harun'a ve Süleyman'a vahyettiğimiz gibi şüphesiz sana da vahyettik. Davud'a da Zebur verdik.", "de": "Gewiß, Wir haben dir (Offenbarung) eingegeben, wie Wir Nuh und den Propheten nach ihm (Offenbarung) eingegeben haben. Und Wir haben Ibrahim, Isma'il, Ishaq, Ya'qub, den Stämmen, \"Isa, Ayyub, Yunus, Harun und Sulaiman (Offenbarung) eingegeben, und Dawud haben Wir ein Buch der Weisheit gegeben.", "nl": "Voorwaar, Wij hebben aan jou geopenbaard zoals Wij aan Nôeh en de Profeten na hem opendaarden. En Wij openbanden aan Ibrâhîm en Ismâ'îl on Ishâq en Ya'qôeb en de kinderen (van Ya'qôeb) en 'Isa en Ayyôeb en Yôenoes en Hârôen en Soelaimân, En Wij gaven Dâwôed de Zabôer (Psalmen).", "es": "Te hemos hecho una revelación, como hicimos una revelación a Noé y a los profeta que le siguieron. Hicimos una revelación a Abraham, Ismael, Isaac, Jacob, as tribus, Jesús, Job, Jonás, Aarón y Salomón. Y dimos a David Salmos.", "it": "In verità ti abbiamo dato la rivelazione come la demmo a Noè e ai Profeti dopo di lui. E abbiamo dato la rivelazione ad Abramo, Ismaele, Isacco, Giacobbe e alle Tribù, a Gesù, Giobbe, Giona, Aronne, Salomone, e a Davide demmo il Salterio.", "ar": "إنا أوحينا اليك -أيها الرسول- بتبليغ الرسالة كما أوحينا إلى نوح والنبيين من بعده، وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط -وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة من ولد يعقوب- وعيسى وأيوب ويونس وهارون وسليمان. وآتينا داود زبورًا، وهو كتاب وصحف مكتوبة."}}, "4:164": {"s": 4, "v": 164, "nom": {"ar": "سُورَةُ النِّسَاءِ", "lat": "An-Nisaa"}, "ar": "وَرُسُلًۭا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًۭا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًۭا", "tl": {"en": "Wa Rusulan qad qasas naahum 'alaika min qablu wa Rusulal lam naqsushum 'alaik; wa kallamallaahu Moosaa takleemaa", "tr": "verusülen ḳad ḳaṣaṣnâhüm `aleyke min ḳablü verusülel lem naḳṣuṣhüm `aleyk. vekelleme-llâhü mûsâ teklîmâ."}, "tr": {"fr": "Et il y a des messagers dont Nous t'avons raconté l'histoire précédemment, et des messagers dont Nous ne t'avons point raconté l'histoire - et Allah a parlé à Moïse de vive voix -", "en": "And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allah spoke to Moses with [direct] speech.", "id": "Dan (Kami telah mengutus) rasul-rasul yang sungguh telah Kami kisahkan tentang mereka kepadamu dahulu, dan rasul-rasul yang tidak Kami kisahkan tentang mereka kepadamu. Dan Allah telah berbicara kepada Musa dengan langsung.", "tr": "Peygamberlerden sonra, insanların Allah'a karşı bir hüccetleri olmaması için, gönderilen müjdeci ve uyarıcı peygamberlerden bir kısmını daha önce sana anlatmış, bir kısmını da anlatmamıştık. Allah, Musa'ya hitabetmişti. Allah güçlüdür, Hakim'dir.", "de": "Und (Wir sandten) Gesandte, über die Wir dir schon zuvor berichtet haben, und andere, über die Wir dir nicht berichtet haben, und zu Musa hat Allah unmittelbar gesprochen -,", "nl": "En (Wij zonden) Boodschappers waarover Wij jou waarlijk reeds verhaald hebben en (Wij zonden) Boodschappers waarover Wij jou niet verhaald hebben. En Allah voerde een gesprek met Môesa.", "es": "Te hemos contado previamente de algunos enviados, de otros no -con Moisés Alá habló de hecho-,", "it": "Ci sono messaggeri di cui ti abbiamo narrato e altri di cui non abbiamo fatto menzione - e Allah parlò direttamente a Mosè.", "ar": "وأرسلنا رسلا قد قصصناهم عليك في القرآن من قبل هذه الآية، ورسلا لم نقصصهم عليك لحكمة أردناها. وكلم الله موسى تكليمًا؛ تشريفًا له بهذه الصفة. وفي هذه الآية الكريمة، إثبات صفة الكلام لله -تعالى- كما يليق بجلاله، وأنه سبحانه كلم نبيه موسى -عليه السلام- حقيقة بلا وساطة."}}, "5:6": {"s": 5, "v": 6, "nom": {"ar": "سُورَةُ المَائـِدَةِ", "lat": "Al-Maaida"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍۢ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ", "tl": {"en": "Yaaa aiyuhal lazeena aamanoo izaa qumtum ilas Salaati faghsiloo wujoohakum wa Aidiyakum ilal maraafiqi wamsahoo biru'oosikum wa arjulakum ilal ka'bayn; wa in kuntum junuban fattahharoo; wain kuntum mardaaa aw'alaa safarin aw jaaa'a ahadum minkum minal ghaaa'iti aw laamastumunnisaaa'a falam tajidoo maaa'an fatayammamoo sa'eedan taiyiban famsahoo biwujoohikum wa aideekum minh; ma yureedul laahu liyaj'ala 'alaikum min harajinw wa laakidy yureedu liyutahhirakum wa liyutimma m'matahoo 'alaikum la'allakum tashkuroon", "tr": "yâ eyyühe-lleẕîne âmenû iẕâ ḳumtüm ile-ṣṣalâti fagsilû vucûheküm veeydiyeküm ile-lmerâfiḳi vemseḥû biruûsiküm veercüleküm ile-lka`beyn. vein küntüm cünüben feṭṭahherû. vein küntüm merḍâ ev `alâ seferin ev câe eḥadüm minküm mine-lgâiṭi ev lemestümü-nnisâe felem tecidû mâen feteyemmemû ṣa`îden ṭayyiben femseḥû bivucûhiküm veeydîküm minh. mâ yürîdü-llâhü liyec`ale `aleyküm min ḥaraciv velâkiy yürîdü liyüṭahhiraküm veliyütimme ni`metehû `aleyküm le`alleküm teşkürûn."}, "tr": {"fr": "O les croyants! Lorsque vous vous levez pour la Salât, lavez vos visages et vos mains jusqu'aux coudes; passez les mains mouillées sur vos têtes; et lavez-vous les pieds jusqu'aux chevilles. Et si vous êtes pollués «junub», alors purifiez-vous (par un bain); mais si vous êtes malades, ou en voyage, ou si l'un de vous revient du lieu où il a fait ses besoins ou si vous avez touché aux femmes et que vous ne trouviez pas d'eau, alors recourez à la terre pure, passez-en sur vos visages et vos mains. Allah ne veut pas vous imposer quelque gêne, mais Il veut vous purifier et parfaire sur vous Son bienfait. Peut-être serez-vous reconnaissants.", "en": "O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janabah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allah does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful.", "id": "Hai orang-orang yang beriman, apabila kamu hendak mengerjakan shalat, maka basuhlah mukamu dan tanganmu sampai dengan siku, dan sapulah kepalamu dan (basuh) kakimu sampai dengan kedua mata kaki, dan jika kamu junub maka mandilah, dan jika kamu sakit atau dalam perjalanan atau kembali dari tempat buang air (kakus) atau menyentuh perempuan, lalu kamu tidak memperoleh air, maka bertayammumlah dengan tanah yang baik (bersih); sapulah mukamu dan tanganmu dengan tanah itu. Allah tidak hendak menyulitkan kamu, tetapi Dia hendak membersihkan kamu dan menyempurnakan nikmat-Nya bagimu, supaya kamu bersyukur.", "tr": "Ey İnananlar! Namaza kalktığınızda yüzlerinizi, dirseklere kadar ellerinizi, -başlarınızı meshedip- topuk kemiklerine kadar ayaklarınızı yıkayın. Eğer cünüpseniz yıkanıp temizlenin; şayet hasta veya yolculukta iseniz veya ayak yolundan gelmişseniz yahut kadınlara yaklaşmışsanız ve su bulamamışsanız temiz bir toprağa teyemmüm edin, yüzlerinizi, ellerinizi onunla meshedin. Allah sizi zorlamak istemez, Allah sizi arıtıp üzerinize olan nimetini tamamlamak ister ki şükredesiniz.", "de": "O die ihr glaubt, wenn ihr euch zum Gebet aufstellt, dann wascht euch das Gesicht und die Hände bis zu den Ellbogen und streicht euch über den Kopf und (wascht euch) die Füße bis zu den Knöcheln. Und wenn ihr im Zustand der Unreinheit seid, dann reinigt euch. Und wenn ihr krank seid oder auf einer Reise oder jemand von euch vom Abort kommt oder ihr Frauen berührt habt und dann kein Wasser findet, so wendet euch dem guten Erdboden zu und streicht euch damit über das Gesicht und die Hände. Allah will euch keine Bedrängnis auferlegen, sondern Er will euch reinigen und Seine Gunst an euch vollenden, auf daß ihr dankbar sein möget.", "nl": "O jullie die geloven! Wanneer jullie je voorbereiden op de shalât, wast dan jullie gezichten en jullie handen tot de ellebogen en wrijft over jullie hoofden en wast jullie voeten tot de enkels. Indien jullie Djoenoeb zijn, reinigt jullie dan. En indien jullie ziek zijn, of op reis, of als een van jullie van het toilet gekomen is, of jullie hebben jullie vrouwen aangeraakts en jullie vinden dan geen water: verricht dan Tayammoem met schone aarde. En wrijft ermee over jullie gezichten en jullie handen. Allah wil het jullie niet moeilijk maken, maar Hij wil jullie reinigen, zodat Hij Zijn genieting voor jullie vervolmaakt. Hopelijk zullen jullie dankbaar zijn.", "es": "¡Creyentes! Cuando os dispongáis a hacer la azalá, lavaos el rostro y los brazos hasta el codo, pasad las manos por la cabeza y lavaos los pies hasta el tobillo. Si estáis en estado de impureza legal, purificaos. Y si estáis enfermos o de viaje, si viene uno de vosotros de hacer sus necesidades, o habéis tenido contacto con mujeres y no encontráis agua, recurrid a arena limpia y pasadla por el rostro y por las manos. Alá no quiere imponeros ninguna carga, sino purificaros y completar Su gracia en vosotros. Quizás, así seáis agradecidos.", "it": "O voi che credete! Quando vi levate per la preghiera, lavatevi il volto, le mani [e gli avambracci] fino ai gomiti, passate le mani bagnate sulla testa e lavate i piedi fino alle caviglie. Se siete in stato di impurità, purificatevi. Se siete malati o in viaggio o uscendo da una latrina o dopo aver accostato le donne non trovate acqua, fate la lustrazione con terra pulita, passandola sul volto e sugli avambracci.", "ar": "يا أيها الذين آمنوا إذا أردتم القيام إلى الصلاة، وأنتم على غير طهارة فاغسلوا وجوهكم وأيديكم مع المرافق (والمِرْفَق: المِفْصَل الذي بين الذراع والعَضُد) وامسحوا رؤوسكم، واغسلوا أرجلكم مع الكعبين (وهما: العظمان البارزان عند ملتقى الساق بالقدم). وإن أصابكم الحدث الأكبر فتطهروا بالاغتسال منه قبل الصلاة. فإن كنتم مرضى، أو على سفر في حال الصحة، أو قضى أحدكم حاجته، أو جامع زوجته فلم تجدوا ماء فاضربوا بأيديكم وجه الأرض، وامسحوا وجوهكم وأيديكم منه. ما يريد الله في أمر الطهارة أن يُضَيِّق عليكم، بل أباح التيمم توسعةً عليكم، ورحمة بكم، إذ جعله بديلا للماء في الطهارة، فكانت رخصة التيمُّم من تمام النعم التي تقتضي شكر المنعم؛ بطاعته فيما أمر وفيما نهى."}}, "5:44": {"s": 5, "v": 44, "nom": {"ar": "سُورَةُ المَائـِدَةِ", "lat": "Al-Maaida"}, "ar": "إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًۭى وَنُورٌۭ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ", "tl": {"en": "Innaaa anzalnat Tawraata feehaa hudanw wa noor; yahkumu bihan Nabiyyoonal lazeena aslamoo lillazeena haadoo war rabbaaniyyoona wal ahbaaru bimas tuhfizoo min Kitaabil laahi wa kaanoo 'alaihi shuhadaaa'; falaa takhshawun naasa wakhshawni wa laa tashtaroo bi aayaatee samanan qaleelaa; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa'ika humul kaafiroon", "tr": "innâ enzelne-ttevrâte fîhâ hüdev venûr. yaḥkümü bihe-nnebiyyûne-lleẕîne eslemû lilleẕîne hâdû verrabbâniyyûne vel'aḥbâru bime-stuḥfiżû min kitâbi-llâhi vekânû `aleyhi şühedâ'. felâ taḫşevu-nnâse vaḫşevni velâ teşterû biâyâtî ŝemenen ḳalîlâ. vemel lem yaḥküm bimâ enzele-llâhü feülâike hümü-lkâfirûn."}, "tr": {"fr": "Nous avons fait descendre la Thora dans laquelle il y a guide et lumière. C'est sur sa base que les prophètes qui se sont soumis à Allah, ainsi que les rabbins et les docteurs jugent les affaires des Juifs. Car on leur a confié la garde du Livre d'Allah, et ils en sont les témoins. Ne craignez donc pas les gens, mais craignez Moi. Et ne vendez pas Mes enseignements à vil prix. Et ceux qui ne jugent pas d'après ce qu'Allah a fait descendre, les voilà les mécréants.", "en": "Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allah] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allah, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price. And whoever does not judge by what Allah has revealed - then it is those who are the disbelievers.", "id": "Sesungguhnya Kami telah menurunkan Kitab Taurat di dalamnya (ada) petunjuk dan cahaya (yang menerangi), yang dengan Kitab itu diputuskan perkara orang-orang Yahudi oleh nabi-nabi yang menyerah diri kepada Allah, oleh orang-orang alim mereka dan pendeta-pendeta mereka, disebabkan mereka diperintahkan memelihara kitab-kitab Allah dan mereka menjadi saksi terhadapnya. Karena itu janganlah kamu takut kepada manusia, (tetapi) takutlah kepada-Ku. Dan janganlah kamu menukar ayat-ayat-Ku dengan harga yang sedikit. Barangsiapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang kafir.", "tr": "Doğrusu Biz yol gösterici olarak Tevrat'ı indirdik. Kendisini Allah'a teslim etmiş peygamberler, yahudi olanlara onunla ve Rabbe kul olanlar, bilginler de Allah'ın Kitap'ından elde mahfuz kalanla hükmederlerdi. Tevrat'a şahiddiler. O halde insanlardan korkmayın, benden korkun, ayetlerimi hiçbir değerle değiştirmeyin; Allah'ın indirdiği ile hükmetmeyenler, işte onlar kafirlerdir.", "de": "Gewiß, Wir haben die Tora hinabgesandt, in der Rechtleitung und Licht sind, womit die Propheten, die sich (Allah) ergeben hatten, für diejenigen, die dem Judentum angehören, walten, und so auch die Leute des Herrn und die Gelehrten, nach dem, was ihnen von der Schrift Allahs anvertraut worden war und worüber sie Zeugen waren. So fürchtet nicht die Menschen, sondern fürchtet Mich. Und verkauft Meine Zeichen nicht für einen geringen Preis! Wer nicht nach dem waltet, was Allah (als Offenbarung) herabgesandt hat, das sind die Ungläubigen.", "nl": "Voorwaar, Wij hebben de Taurât neergezonden met daarin leiding en licht. De profeten, die zich (aan Allah) overgegeven hadden, oordeelden ermee over de Joden. En de rabbijnen en de schriftgeleerden (oordeelden ook), met behulp van hetgeen hun van de schrift van Allah was toevertrouwd en zij waren daar getuigen van. Vreest daarom niet de mensen maar vreest Mij en verruilt Mijn tekens niet voor een geringe prijs. En wie niet oordeelt met wat Allah geopenbaard heeft: zij zijn de ongelovigen!", "es": "Hemos revelado la Tora, que contiene Dirección y Luz. Los profetas que se habían sometido administraban justicia a los judíos según ella, como hacían los maestros y doctores, según lo que de la Escritura de Alá se les había confiado y de lo cual eran testigos. ¡No tengáis, pues, miedo a los hombres, sino a Mí! ¡Y no malvendáis Mis signos! Quienes no decidan según lo que Alá ha revelado, ésos son los infieles.", "it": "Facemmo scendere la Torâh, fonte di guida e di luce. Con essa giudicavano tra i giudei, i profeti sottomessi ad Allah, e i rabbini e i dottori: [giudicavano] in base a quella parte dei precetti di Allah che era stata loro affidata e della quale erano testimoni. Non temete gli uomini, ma temete Me. E non svendete a vil prezzo i segni Miei. Coloro che non giudicano secondo quello che Allah ha fatto scendere, questi sono i miscredenti.", "ar": "إنا أنزلنا التوراة فيها إرشاد من الضلالة، وبيان للأحكام، وقد حكم بها النبيُّون -الذين انقادوا لحكم الله، وأقروا به- بين اليهود، ولم يخرجوا عن حكمها ولم يُحَرِّفوها، وحكم بها عُبَّاد اليهود وفقهاؤهم الذين يربُّون الناس بشرع الله؛ ذلك أن أنبياءهم قد استأمنوهم على تبليغ التوراة، وفِقْه كتاب الله والعمل به، وكان الربانيون والأحبار شهداء على أن أنبياءهم قد قضوا في اليهود بكتاب الله. ويقول تعالى لعلماء اليهود وأحبارهم: فلا تخشوا الناس في تنفيذ حكمي؛ فإنهم لا يقدرون على نفعكم ولا ضَرِّكم، ولكن اخشوني فإني أنا النافع الضار، ولا تأخذوا بترك الحكم بما أنزلتُ عوضًا حقيرًا. الحكم بغير ما أنزل الله من أعمال أهل الكفر، فالذين يبدلون حكم الله الذي أنزله في كتابه، فيكتمونه ويجحدونه ويحكمون بغيره معتقدين حله وجوازه فأولئك هم الكافرون."}}, "5:46": {"s": 5, "v": 46, "nom": {"ar": "سُورَةُ المَائـِدَةِ", "lat": "Al-Maaida"}, "ar": "وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًۭى وَنُورٌۭ وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًۭى وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ", "tl": {"en": "Wa qaffainaa 'alaaa aasaaarihim bi 'Eesab ni Maryama musaddiqal limaa baina yadihi minat Tawraati wa aatainaahul Injeela feehi hudanw wa noorunw wa musaddiqal limaa baina yadaihi minat Tawraati wa hudanw wa maw'izatal lilmuttaqeen", "tr": "veḳaffeynâ `alâ âŝârihim bi`îse-bni meryeme müṣaddiḳal limâ beyne yedeyhi mine-ttevrât. veâteynâhü-l'incîle fîhi hüdev venûruv vemüṣaddiḳal limâ beyne yedeyhi mine-ttevrâti vehüdev vemev`iżatel lilmütteḳîn."}, "tr": {"fr": "Et Nous avons envoyé après eux Jésus, fils de Marie, pour confirmer ce qu'il y avait dans la Thora avant lui. Et Nous lui avons donné l'Evangile, où il y a guide et lumière, pour confirmer ce qu'il y avait dans la Thora avant lui, et un guide et une exhortation pour les pieux.", "en": "And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous.", "id": "Dan Kami iringkan jejak mereka (nabi nabi Bani Israil) dengan Isa putera Maryam, membenarkan Kitab yang sebelumnya, yaitu: Taurat. Dan Kami telah memberikan kepadanya Kitab Injil sedang didalamnya (ada) petunjuk dan dan cahaya (yang menerangi), dan membenarkan kitab yang sebelumnya, yaitu Kitab Taurat. Dan menjadi petunjuk serta pengajaran untuk orang-orang yang bertakwa.", "tr": "Onların izi üzerine arkalarından Meryem oğlu İsa'yı, ondan önce gelmiş bulunan Tevrat'ı doğrulayarak gönderdik. Ona, yol gösterici, aydınlatıcı olan ve önünde bulunan Tevrat'ı doğrulayan İncil'i sakınanlara öğüt ve yol gösterici olarak verdik.", "de": "Und Wir ließen auf ihren Spuren 'Isa, den Sohn Maryams, folgen, das zu bestätigen, was von der Tora vor ihm (offenbart) war; und Wir gaben ihm das Evangelium, in dem Rechtleitung und Licht sind, und das zu bestätigen, was von der Tora vor ihm (offenbart) war, und als Rechtleitung und Ermahnung für die Gottesfürchtigen.", "nl": "En Wij lieten 'Isa, zoon van Maryam, in hun voetstappen volgen, ter bevestiging van wat er van de Taurat (reeds) vóór hem was. En Wij gaven hem de Indjîl met daarin Leiding on Licht en een bevestiging van wat er van de Taurât (reeds) vóór hem was: als een leiding en een onderricht voor de Moettaqôen.", "es": "Hicimos que les sucediera Jesús, hijo de María, en confirmación de lo que ya había de la Tora. Le dimos el Evangelio, que contiene Dirección y Luz, en confirmación de lo que ya había de la Tora y como Dirección y Exhortación para los temerosos de Alá.", "it": "Facemmo camminare sulle loro orme Gesù, figlio di Maria, per confermare la Torâh che scese prima di lui. Gli demmo il Vangelo, in cui è guida e luce, a conferma della Torâh, che era scesa precedentemente: monito e direzione per i timorati.", "ar": "وأتبعنا أنبياء بني إسرائيل عيسى ابن مريم مؤمنًا بما في التوراة، عاملا بما فيها مما لم ينسخه كتابه، وأنزلنا إليه الإنجيل هاديا إلى الحق، ومبيِّنًا لما جهله الناس مِن حكم الله، وشاهدًا على صدق التوراة بما اشتمل عليه من أحكامها، وقد جعلناه بيانًا للذين يخافون الله وزاجرًا لهم عن ارتكاب المحرَّمات."}}, "7:23": {"s": 7, "v": 23, "nom": {"ar": "سُورَةُ الأَعۡرَافِ", "lat": "Al-A'raaf"}, "ar": "قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ", "tl": {"en": "Qaalaa Rabbanaa zalamnaaa anfusanaa wa illam taghfir lanaa wa tarhamnaa lanakoonanna minal khaasireen", "tr": "ḳâlâ rabbenâ żalemnâ enfüsenâ veil lem tagfir lenâ veterḥamnâ lenekûnenne mine-lḫâsirîn."}, "tr": {"fr": "Tous deux dirent: «O notre Seigneur, nous avons fait du tort à nous-mêmes. Et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants».", "en": "They said, \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.\"", "id": "Keduanya berkata: \"Ya Tuhan kami, kami telah menganiaya diri kami sendiri, dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya pastilah kami termasuk orang-orang yang merugi.", "tr": "Her ikisi, \"Rabbimiz! Kendimize yazık ettik; bizi bağışlamaz ve bize merhamet etmezsen biz kaybedenlerden oluruz\" dediler.", "de": "Sie sagten: \"Unser Herr, wir haben uns selbst Unrecht zugefügt. Wenn Du uns nicht vergibst und Dich unser erbarmst, werden wir ganz gewiß zu den Verlorenen gehören.\"", "nl": "Zij zeiden: \"Onze Heer, wij hebben onszelf onrecht aangedaan en wanneer U ons niet vergeeft en ons geen genade schenkt, dan zullen wij zeker tot de verliezers behoren.\"", "es": "Dijeron: «¡Señor! Hemos sido injustos con nosostros mismos. Si no nos perdonas y Te apiadas de nosotros, seremos, ciertamente, de los que pierden».", "it": "Dissero: “O Signor nostro, abbiamo mancato contro noi stessi. Se non ci perdoni e non hai misericordia di noi, saremo certamente tra i perdenti”.", "ar": "قال آدم وحواء: ربنا ظلمنا أنفسنا بالأكل من الشجرة، وإن لم تغفر لنا وترحمنا لنكونن ممن أضاعوا حظَّهم في دنياهم وأخراهم. (وهذه الكلمات هي التي تلقاها آدم من ربه، فدعا بها فتاب الله عليه)."}}, "7:180": {"s": 7, "v": 180, "nom": {"ar": "سُورَةُ الأَعۡرَافِ", "lat": "Al-A'raaf"}, "ar": "وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ", "tl": {"en": "Wa lillaahil Asmaaa 'ul Husnaa fad'oohu bihaa wa zarul lazeena yulhidoona feee Asmaaa'ih; sa yujzawna maa kaanoo ya'maloon", "tr": "velillâhi-l'esmâü-lḥusnâ fed`ûhü bihâ. veẕerü-lleẕîne yülḥidûne fî esmâih. seyüczevne mâ kânû ya`melûn."}, "tr": {"fr": "C'est à Allah qu'appartiennent les noms les plus beaux. Invoquez-Le par ces noms et laissez ceux qui profanent Ses noms: ils seront rétribués pour ce qu'ils ont fait.", "en": "And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing.", "id": "Hanya milik Allah asmaa-ul husna, maka bermohonlah kepada-Nya dengan menyebut asmaa-ul husna itu dan tinggalkanlah orang-orang yang menyimpang dari kebenaran dalam (menyebut) nama-nama-Nya. Nanti mereka akan mendapat balasan terhadap apa yang telah mereka kerjakan.", "tr": "En güzel isimler Allah'ındır, O'na o isimlerle dua edin, O'nun isimleri konusunda eğriliğe sapanları bırakın. Onlar yaptıklarının cezasını göreceklerdir.", "de": "Allahs sind die schönsten Namen; so ruft Ihn damit an und laßt diejenigen, die mit Seinen Namen abwegig umgehen. Ihnen wird das vergolten, was sie zu tun pflegten.", "nl": "En aan Allah behoren de Schone Namen, roept Hem daarmee aan en verlaat degenen die misbruik van Zijn Namen maken; zij zullen worden vergolden vooir wat zij plachten te doen.", "es": "Alá posee los nombres más bellos. Empléalos, pues, para invocarle y apártate de quienes los profanen, que serán retribuidos con arreglo a sus obras.", "it": "Ad Allah appartengono i nomi più belli: invocateLo con quelli e allontanatevi da coloro che profanano i nomi Suoi: presto saranno compensati per quello che hanno fatto.", "ar": "ولله سبحانه وتعالى الأسماء الحسنى، الدالة على كمال عظمته، وكل أسمائه حسن، فاطلبوا منه بأسمائه ما تريدون، واتركوا الذين يُغيِّرون في أسمائه بالزيادة أو النقصان أو التحريف، كأن يُسمَّى بها من لا يستحقها، كتسمية المشركين بها آلهتهم، أو أن يجعل لها معنى لم يُردْه الله ولا رسوله، فسوف يجزون جزاء أعمالهم السيئة التي كانوا يعملونها في الدنيا من الكفر بالله، والإلحاد في أسمائه وتكذيب رسوله."}}, "8:9": {"s": 8, "v": 9, "nom": {"ar": "سُورَةُ الأَنفَالِ", "lat": "Al-Anfaal"}, "ar": "إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ", "tl": {"en": "Iz tastagheesoona Rabbakum fastajaaba lakum annee mumiddukum bi alfim minal malaaa'ikati murdifeen", "tr": "iẕ testegîŝûne rabbeküm festecâbe leküm ennî mümiddüküm bielfim mine-lmelâiketi mürdifîn."}, "tr": {"fr": "(Et rappelez-vous) le moment où vous imploriez le secours de votre Seigneur et qu'Il vous exauça aussitôt: «Je vais vous aider d'un millier d'Anges déferlant les uns à la suite des autres.»", "en": "[Remember] when you asked help of your Lord, and He answered you, \"Indeed, I will reinforce you with a thousand from the angels, following one another.\"", "id": "(Ingatlah), ketika kamu memohon pertolongan kepada Tuhanmu, lalu diperkenankan-Nya bagimu: \"Sesungguhnya Aku akan mendatangkan bala bantuan kepada kamu dengan seribu malaikat yang datang berturut-turut\".", "tr": "Rabbinizin yardımına sığınıyordunuz. O, \"Ben size, birbiri peşinden bin melekle yardım ederim\" diye cevap vermişti.", "de": "(Gedenke) als ihr euren Herrn um Hilfe anrieft. Da erhörte Er euch: \"Ich werde euch mit Tausend von den Engeln unterstützen, hintereinander reitend.\"", "nl": "Toen jullie je Heer (bij de Slag bij Badr) om hulp vroegen en Hij jullie verhoorde (en zei:) \"Ik zal jullie (leger) aanvullen met duizend Engelen die elkaar (in strijdgroepen) opvolgen.\"", "es": "Cuando pedisteis auxilio a vuestro Señor y Él os escuchó: «Os reforzaré con mil ángeles uno tras otro».", "it": "E [ricordate] quando imploraste il soccorso del vostro Signore! Vi rispose: “Vi aiuterò con un migliaio di angeli a ondate successive”.", "ar": "اذكروا نعمة الله عليكم يوم \"بدر\" إذ تطلبون النصر على عدوكم، فاستجاب الله لدعائكم قائلا إني ممدُّكم بألف من الملائكة من السماء، يتبع بعضهم بعضًا."}}, "8:41": {"s": 8, "v": 41, "nom": {"ar": "سُورَةُ الأَنفَالِ", "lat": "Al-Anfaal"}, "ar": "۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍۢ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ", "tl": {"en": "Wa'lamooo annamaa ghanimtum min sha'in fa anna lillaahi khumusahoo wa lir Rasooli wa lizil qurba walyataamaa walmasaakeeni wabnis sabeeli in kuntum aamantum billaahi wa maaa anzalnaa 'ala 'abdinaa yawmal Furqaani yawmaltaqal jam'aan; wal laahu 'alaa kulli shai'in Qadeer", "tr": "va`lemû ennemâ ganimtüm min şey'in feenne lillâhi ḫumüsehû velirrasûli veliẕi-lḳurbâ velyetâmâ velmesâkîni vebni-ssebîli in küntüm âmentüm billâhi vemâ enzelnâ `alâ `abdinâ yevme-lfürḳâni yevme-lteḳe-lcem`ân. vellâhü `alâ külli şey'in ḳadîr."}, "tr": {"fr": "Et sachez que, de tout butin que vous avez ramassé, le cinquième appartient à Allah, au messager, à ses proches parents, aux orphelins, aux pauvres, et aux voyageurs (en détresse), si vous croyez en Allah et en ce que Nous avons fait descendre sur Notre serviteur, le jour du Discernement: le jour où les deux groupes s'étaient rencontrés, et Allah est Omnipotent.", "en": "And know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allah and in that which We sent down to Our Servant on the day of criterion - the day when the two armies met. And Allah, over all things, is competent.", "id": "Ketahuilah, sesungguhnya apa saja yang dapat kamu peroleh sebagai rampasan perang, maka sesungguhnya seperlima untuk Allah, Rasul, kerabat Rasul, anak-anak yatim, orang-orang miskin dan ibnussabil, jika kamu beriman kepada Allah dan kepada apa yang kami turunkan kepada hamba Kami (Muhammad) di hari Furqaan, yaitu di hari bertemunya dua pasukan. Dan Allah Maha Kuasa atas segala sesuatu.", "tr": "Eğer Allah'a ve hakkı batıldan ayıran o günde, iki topluluğun karşılaştığı günde kulumuza indirdiğimize inanıyorsanız, bilin ki, ele geçirdiğiniz ganimetin beşte biri Allah'ın, Peygamber'in ve yakınlarının, yetimlerin, düşkünlerin ve yolcularındır. Allah her şeye Kadir'dir.", "de": "Und wisset: Was immer ihr erbeutet, so gehört Allah ein Fünftel davon und dem Gesandten, und den Verwandten, den Waisen, den Armen und dem Sohn des Weges, wenn ihr an Allah glaubt und an das, was Wir auf Unseren Diener am Tag der Unterscheidung (als Offenbarung) hinabgesandt haben, an dem Tag, da die beiden Heere aufeinandertrafen. Und Allah hat zu allem die Macht.", "nl": "En weet dat, wat jullie ook aan oorlogsbuit (Ghanîmah) hebben verkregen: één vijfde deel ervan is voor Allah en voor de Boodschapper en voor de verwanten (van de Boodschapper), en de wezen, en de annen en de reiziger (zonder proviand), als jullie in Allah geloven en in wat Wij aan Onze dienaar hebben neergezonden op de dag van het onderscheid, de dag dat de twee legers elkaar troffen. En Allah is Almachtig over alle dingen.", "es": "Sabed que, si obtenéis algún botín un quinto corresponde a Alá, al Enviado y a sus parientes, a los huérfanos, a los pobres y al viajero, si creéis en Alá y en lo que hemos revelado a Nuestro siervo el día del Criterio, el día que se encontraron los dos ejércitos. Alá es omnipotente.", "it": "Sappiate che del bottino che conquisterete, un quinto appartiene ad Allah e al Suo Messaggero, ai parenti, agli orfani, ai poveri, ai viandanti, se credete in Allah e in quello che abbiamo fatto scendere sul Nostro schiavo, nel giorno del Discrimine, il giorno in cui le due schiere si incontrarono. Allah è onnipotente.", "ar": "واعلموا -أيها المؤمنون- أن ما ظَفِرتم به مِن عدوكم بالجهاد في سبيل الله فأربعة أخماسه للمقاتلين الذين حضروا المعركة، والخمس الباقي يجزَّأُ خمسة أقسام: الأول لله وللرسول، فيجعل في مصالح المسلمين العامة، والثاني لذوي قرابة رسول الله صلى الله عليه وسلم، وهم بنو هاشم وبنو المطلب، جُعِل لهم الخمس مكان الصدقة فإنها لا تحلُّ لهم، والثالث لليتامى، والرابع للمساكين، والخامس للمسافر الذي انقطعت به النفقة، إن كنتم مقرِّين بتوحيد الله مطيعين له، مؤمنين بما أنزل على عبده محمد صلى الله عليه وسلم من الآيات والمدد والنصر يوم فَرَق بين الحق والباطل بـ\"بدر\"، يوم التقى جَمْعُ المؤمنين وجَمْعُ المشركين. والله على كل شيء قدير لا يعجزه شيء."}}, "9:36": {"s": 9, "v": 36, "nom": {"ar": "سُورَةُ التَّوۡبَةِ", "lat": "At-Tawba"}, "ar": "إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةًۭ كَمَا يُقَٰتِلُونَكُمْ كَآفَّةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ", "tl": {"en": "Inna 'iddatash shuhoori 'indal laahis naa 'ashara shahran fee Kitaabil laahi yawma khalaqas samaawaati wal arda minhaaa arba'atun hurum; zaalikad deenul qaiyim; falaa tazlimoo feehinna anfusakum; wa qaatilul mushrikeena kaaaf fattan kamaa yuqaati loonakum kaaaffah; wa'lamooo annal laaha ma'al muttaqeen", "tr": "inne `iddete-şşühûri `inde-llâhi-ŝnâ `aşera şehran fî kitâbi-llâhi yevme ḫaleḳa-ssemâvâti vel'arḍa minhâ erbe`atün ḥurum. ẕâlike-ddînü-lḳayyimü felâ tażlimû fîhinne enfüseküm veḳâtilü-lmüşrikîne kâffeten kemâ yüḳâtilûneküm kâffeh. va`lemû enne-llâhe me`a-lmütteḳîn."}, "tr": {"fr": "Le nombre de mois, auprès d'Allah, est de douze [mois], dans la prescription d'Allah, le jour où Il créa les cieux et la terre. Quatre d'entre eux sont sacrés: telle est la religion droite. [Durant ces mois], ne faites pas de tort à vous-mêmes. Combattez les associateurs sans exception, comme ils vous combattent sans exception. Et sachez qu'Allah est avec les pieux.", "en": "Indeed, the number of months with Allah is twelve [lunar] months in the register of Allah [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion, so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allah is with the righteous [who fear Him].", "id": "Sesungguhnya bilangan bulan pada sisi Allah adalah dua belas bulan, dalam ketetapan Allah di waktu Dia menciptakan langit dan bumi, di antaranya empat bulan haram. Itulah (ketetapan) agama yang lurus, maka janganlah kamu menganiaya diri kamu dalam bulan yang empat itu, dan perangilah kaum musyrikin itu semuanya sebagaimana merekapun memerangi kamu semuanya, dan ketahuilah bahwasanya Allah beserta orang-orang yang bertakwa.", "tr": "Allah'ın gökleri ve yeri yarattığı günkü yazısında, Allah'a göre ayların sayısı onikidir. Bunlardan dördü hürmetli aydır. Bu dosdoğru bir nizamdır. Öyleyse o aylar içinde kendinize yazık etmeyin, topyekun sizinle savaşan putperestlerle siz de topyekun savaşın, Allah'ın sakınanlarla beraber olduğunu bilin.", "de": "Gewiß, die Anzahl der Monate bei Allah ist zwölf Monate, im Buch Allahs (festgelegt) am Tag, da Er die Himmel und die Erde schuf. Davon sind vier geschützt, Das ist die richtige Religion. So fügt euch selbst in ihnen kein Unrecht zu. Und kämpft gegen die Götzendiener allesamt wie sie gegen euch allesamt kämpfen! Und wißt, daß Allah mit den Gottesfürchtigen ist!", "nl": "Voorwaar, het aantal maanden bij Allah is twaalf maanden, volgens de beschikking van Allah op de dag dat Hij de hemelen en de aarde schiep. Daarvan zij er vier gewijd. Dat is de rechte godsdienst. Doet jullie zelf dan daarin geen onrecht aan. Maar bevecht alle veelgodenaanbidders zoals zij jullie allen bevechten. en weet dat Allah met de Moettaqóen is.", "es": "El número de meses, para Alá, es de doce. Fueron inscritos en la Escritura de Alá el día que creó los cielos y la tierra. De ellos, cuatro son sagrados: ésa es la religión verdadera. ¡No seáis injustos con vosotros mismos no respetándolos! ¡Y combatid todos contra los asociadores como ellos también combaten todos contra vosotros! Y sabed que Alá está con los que Le temen.", "it": "Presso Allah il computo dei mesi è di dodici mesi [lunari] nel Suo Libro, sin dal giorno in cui creò i cieli e la terra. Quattro di loro sono sacri. Questa è la religione retta. In questi mesi non opprimete voi stessi, ma combattete tutti assieme i politeisti, come essi vi combattono tutti assieme. Sappiate che Allah è con coloro che [Lo] temono.", "ar": "إنّ عدة الشهور في حكم الله وفيما كُتب في اللوح المحفوظ اثنا عشر شهرًا، يوم خلق السموات والأرض، منها أربعة حُرُم؛ حرَّم الله فيهنَّ القتال (هي: ذو القعدة وذو الحجة والمحرم ورجب) ذلك هو الدين المستقيم، فلا تظلموا فيهن أنفسكم؛ لزيادة تحريمها، وكون الظلم فيها أشد منه في غيرها، لا أنَّ الظلم في غيرها جائز. وقاتلوا المشركين جميعًا كما يقاتلونكم جميعًا، واعلموا أن الله مع أهل التقوى بتأييده ونصره."}}, "9:40": {"s": 9, "v": 40, "nom": {"ar": "سُورَةُ التَّوۡبَةِ", "lat": "At-Tawba"}, "ar": "إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ", "tl": {"en": "Illaa tansuroohu faqad nasarahul laahu iz akhrajahul lazeena kafaroo saaniyasnaini iz humaa filghaari iz yaqoolu lisaahibihee la tahzan innnal laaha ma'anaa fa anzalallaahu sakeenatahoo 'alaihi wa aiyadahoo bijunoodil lam tarawhaa wa ja'ala kalimatal lazeena kafarus suflaa; wa Kalimatul laahi hiyal 'ulyaa; wallaahu 'Azeezun Hakeem;", "tr": "illâ tenṣurûhü feḳad neṣarahü-llâhü iẕ aḫracehü-lleẕîne keferû ŝâniye-ŝneyni iẕ hümâ fi-lgâri iẕ yeḳûlü liṣâḥibihî lâ taḥzen inne-llâhe me`anâ. feenzele-llâhü sekînetehû `aleyhi veeyyedehû bicünûdil lem teravhâ vece`ale kelimete-lleẕîne keferü-ssüflâ. vekelimetü-llâhi hiye-l`ulyâ. vellâhü `azîzün ḥakîm."}, "tr": {"fr": "Si vous ne lui portez pas secours... Allah l'a déjà secouru, lorsque ceux qui avaient mécru l'avaient banni, deuxième de deux. Quand ils étaient dans la grotte et qu'il disait à son compagnon: «Ne t'afflige pas, car Allah est avec nous.» Allah fit alors descendre sur Lui Sa sérénité «Sa sakîna» et le soutint de soldats (Anges) que vous ne voyiez pas, et Il abaissa ainsi la parole des mécréants, tandis que la parole d'Allah eut le dessus. Et Allah est Puissant et Sage.", "en": "If you do not aid the Prophet - Allah has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he said to his companion, \"Do not grieve; indeed Allah is with us.\" And Allah sent down his tranquillity upon him and supported him with angels you did not see and made the word of those who disbelieved the lowest, while the word of Allah - that is the highest. And Allah is Exalted in Might and Wise.", "id": "Jikalau kamu tidak menolongnya (Muhammad) maka sesungguhnya Allah telah menolongnya (yaitu) ketika orang-orang kafir (musyrikin Mekah) mengeluarkannya (dari Mekah) sedang dia salah seorang dari dua orang ketika keduanya berada dalam gua, di waktu dia berkata kepada temannya: \"Janganlah kamu berduka cita, sesungguhnya Allah beserta kita\". Maka Allah menurunkan keterangan-Nya kepada (Muhammad) dan membantunya dengan tentara yang kamu tidak melihatnya, dan Al-Quran menjadikan orang-orang kafir itulah yang rendah. Dan kalimat Allah itulah yang tinggi. Allah Maha Perkasa lagi Maha Bijaksana.", "tr": "Ona (Muhammed'e) yardım etmezseniz, bilin ki, inkar edenler onu Mekke'den çıkardıklarında mağarada bulunan iki kişiden biri olarak Allah ona yardım etmişti. Arkadaşına (Ebu Bekir'e) \"Üzülme, Allah bizimledir\" diyordu; Allah da ona güven vermiş, görmediğiniz askerlerle onu desteklemiş, inkar edenlerin sözünü alçaltmıştı. Ancak Allah'ın sözü yücedir. Allah güçlüdür, hakimdir.", "de": "Wenn ihr ihm nicht helft, so hat Allah ihm (schon damals) geholfen, als diejenigen, die ungläubig waren, ihn als einen von Zweien vertrieben; als sie beide in der Höhle waren und als er zu seinem Gefährten sagte: \"Sei nicht traurig! Gewiß, Allah ist mit uns!\" Da sandte Allah Seine innere Ruhe auf ihn herab und stärkte ihn mit Heerscharen, die ihr nicht saht, und erniedrigte das Wort derjenigen, die ungläubig waren, während Allahs Wort (doch) das hohe ist. Allah ist Allmächtig und Allweise.", "nl": "Als jullie hem (de Profeet) niet helpen: waarlijk, Allah heeft hem reeds eerder geholpen, toen degenen die ongelovig waren hen (uit Mekkah) hadden verdreven, (en) hij de tweede van twee was toen zij zich in de grot bevonden, (en) toen hij tot zijn metgezet (Aboe Bakr) zei: \"Treur niet, voorwaar, Allah is met ons.\" Waarna Allah Zijn rust op hen deed neerdalen en Hij hen bijstand gaf met een leger dat jullie niet zagen. En Hij verlaagde het woord van degenen die ongelovig waren tot het laagste en het Woord van Allah, dat is het hoogste. En Allah is Almachtig, Alwijs.", "es": "Si le negáis auxilio, Alá sí que le auxilió cuando, expulsado por los infieles, con un solo compañero, le decía a éste estando los dos en la cueva: «¡No estés triste! ¡Alá está con nosotros!» Alá hizo descender sobre él Su sakina y le reforzó con legiones invisibles a vuestros ojos. Alá puso Su Palabra por encima de la palabra de los infieles.. Alá es poderoso, sabio.", "it": "Se voi non lo aiutate, Allah lo ha già soccorso il giorno in cui i miscredenti l'avevano bandito, lui, il secondo di due, quando erano nella caverna e diceva al suo compagno: “Non ti affliggere, Allah è con noi”. Poi, Allah fece scendere su di lui la Sua pace, lo sostenne con truppe che voi non vedeste, e rese infima la parola dei miscredenti, mentre la Parola di Allah è la più alta. Allah è eccelso, saggio.", "ar": "يا معشر أصحاب رسول الله صلى الله عليه وسلم إن لا تنفروا معه أيها المؤمنون إذا استَنْفَركم، وإن لا تنصروه؛ فقد أيده الله ونصره يوم أخرجه الكفار من قريش من بلده (مكة)، وهو ثاني اثنين (هو وأبو بكر الصديق رضي الله عنه) وألجؤوهما إلى نقب في جبل ثور \"بمكة\"، فمكثا فيه ثلاث ليال، إذ يقول لصاحبه (أبي بكر) لما رأى منه الخوف عليه: لا تحزن إن الله معنا بنصره وتأييده، فأنزل الله الطمأنينة في قلب رسول الله صلى الله عليه وسلم، وأعانه بجنود لم يرها أحد من البشر وهم الملائكة، فأنجاه الله من عدوه وأذل الله أعداءه، وجعل كلمة الذين كفروا السفلى. وكلمةُ الله هي العليا،، ذلك بإعلاء شأن الإسلام. والله عزيز في ملكه، حكيم في تدبير شؤون عباده. وفي هذه الآية منقبة عظيمة لأبي بكر الصديق رضي الله عنه."}}, "9:60": {"s": 9, "v": 60, "nom": {"ar": "سُورَةُ التَّوۡبَةِ", "lat": "At-Tawba"}, "ar": "۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ", "tl": {"en": "Innamas sadaqaatu lilfuqaraaa'i walmasaakeeni wal 'aamileena 'alaihaa wal mu'al lafati quloobuhum wa fir riqaabi walghaarimeena wa fee sabeelil laahi wabnis sabeeli fareedatam minal laah; wal laahu 'Aleemun Hakeem", "tr": "inneme-ṣṣadeḳâtü lilfüḳarâi velmesâkîni vel`âmilîne `aleyhâ velmüellefeti ḳulûbühüm vefi-rriḳâbi velgârimîne vefî sebîli-llâhi vebni-ssebîl. ferîḍatem mine-llâh. vellâhü `alîmün ḥakîm."}, "tr": {"fr": "Les Ṣadaqâts ne sont destinés que pour les pauvres, les indigents, ceux qui y travaillent, ceux dont les cœurs sont à gagner (à l'Islam), l'affranchissement des jougs, ceux qui sont lourdement endettés, dans le sentier d'Allah, et pour le voyageur (en détresse). C'est un décret d'Allah! Et Allah est Omniscient et Sage.", "en": "Zakah expenditures are only for the poor and for the needy and for those employed to collect [zakah] and for bringing hearts together [for Islam] and for freeing captives [or slaves] and for those in debt and for the cause of Allah and for the [stranded] traveler - an obligation [imposed] by Allah. And Allah is Knowing and Wise.", "id": "Sesungguhnya zakat-zakat itu, hanyalah untuk orang-orang fakir, orang-orang miskin, pengurus-pengurus zakat, para mu'allaf yang dibujuk hatinya, untuk (memerdekakan) budak, orang-orang yang berhutang, untuk jalan Allah dan untuk mereka yuang sedang dalam perjalanan, sebagai suatu ketetapan yang diwajibkan Allah, dan Allah Maha Mengetahui lagi Maha Bijaksana.", "tr": "Zekatlar; Allah'tan bir farz olarak yoksullara, düşkünlere, onu toplayan memurlara, kalbleri Müslümanlığa ısındırılacaklara verilir; kölelerin, borçluların, Allah yolunda olanların ve yolda kalanların uğrunda sarfedilir. Allah bilendir, hakimdir.", "de": "Die Almosen sind nur für die Armen, die Bedürftigen, diejenigen, die damit beschäftigt sind, diejenigen, deren Herzen vertraut gemacht werden sollen, (den Loskauf von) Sklaven, die Verschuldeten, auf Allahs Weg und (für) den Sohn des Weges, als Verpflichtung von Allah. Allah ist Allwissend und Allweise.", "nl": "Voorwaar, de zakât is slechts voor de armen en de behoeftigen en de werkenden (aan de inzameling ervan) en de Moe'allaf en voor (het vrijkopen) van de slaven, en de schuldenaren en om (uit te geven) op de Weg van Allah en voor de reiziger (zonder proviand), als een plicht tegenover Allah. En Allah is Alwetend, Alwijs.", "es": "Las limosnas son sólo para los necesitados, los pobres, los limosneros, aquéllos cuya voluntad hay que captar, los cautivos, los insolventes, la causa de Alá y el viajero. Es un deber impuesto por Alá. Alá es omnisciente, sabio.", "it": "Le elemosine sono per i bisognosi, per i poveri, per quelli incaricati di raccoglierle, per quelli di cui bisogna conquistarsi i cuori, per il riscatto degli schiavi, per quelli pesantemente indebitati, per [la lotta sul] sentiero di Allah e per il viandante. Decreto di Allah! Allah è saggio, sapiente.", "ar": "إنما تعطى الزكوات الواجبة للمحتاجين الذين لا يملكون شيئًا، وللمساكين الذين لا يملكون كفايتهم، وللسعاة الذين يجمعونها، وللذين تؤلِّفون قلوبهم بها ممن يُرْجَى إسلامه أو قوة إيمانه أو نفعه للمسلمين، أو تدفعون بها شرَّ أحد عن المسلمين، وتعطى في عتق رقاب الأرقاء والمكاتبين، وتعطى للغارمين لإصلاح ذات البين، ولمن أثقلَتْهم الديون في غير فساد ولا تبذير فأعسروا، وللغزاة في سبيل الله، وللمسافر الذي انقطعت به النفقة، هذه القسمة فريضة فرضها الله وقدَّرها. والله عليم بمصالح عباده، حكيم في تدبيره وشرعه."}}, "9:100": {"s": 9, "v": 100, "nom": {"ar": "سُورَةُ التَّوۡبَةِ", "lat": "At-Tawba"}, "ar": "وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍۢ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", "tl": {"en": "Was saabiqoonal awwa loona minal Muhaajireena wal Ansaari wallazeenat taba'oo hum bi ihsaanir radiyal laahu 'anhum wa radoo 'anhu wa a'adda lahum jannnaatin tajree tahtahal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul 'azeem", "tr": "vessâbiḳûne-l'evvelûne mine-lmühâcirîne vel'enṣâri velleẕîne-ttebe`ûhüm biiḥsânir raḍiye-llâhü `anhüm veraḍû `anhü vee`adde lehüm cennâtin tecrî taḥtehe-l'enhâru ḫâlidîne fîhâ ebedâ. ẕâlike-lfevzü-l`ażîm."}, "tr": {"fr": "Les tout premiers [croyants] parmi les Emigrés et les Auxiliaires et ceux qui les ont suivis dans un beau comportement, Allah les agrée, et ils L'agréent. Il a préparé pour eux des Jardins sous lesquels coulent les ruisseaux, et ils y demeureront éternellement. Voilà l'énorme succès!", "en": "And the first forerunners [in the faith] among the Muhajireen and the Ansar and those who followed them with good conduct - Allah is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.", "id": "Orang-orang yang terdahulu lagi yang pertama-tama (masuk Islam) dari golongan muhajirin dan anshar dan orang-orang yang mengikuti mereka dengan baik, Allah ridha kepada mereka dan merekapun ridha kepada Allah dan Allah menyediakan bagi mereka surga-surga yang mengalir sungai-sungai di dalamnya selama-lamanya. Mereka kekal di dalamnya. Itulah kemenangan yang besar.", "tr": "İyilik yarışında önceliği kazanan Muhacirler ve Ensar ile, onlara güzelce uyanlardan Allah hoşnut olmuştur, onlar da Allah'tan hoşnuddurlar. Allah onlara, içinde temelli ve ebedi kalacakları, içlerinden ırmaklar akan cennetler hazırlamıştır; işte büyük kurtuluş budur.", "de": "Die vorausgeeilten Ersten von den Auswanderern und den Helfern und diejenigen, die ihnen auf beste Weise gefolgt sind - Allah hat Wohlgefallen an ihnen, und sie haben Wohlgefallen an Ihm. Und Er hat für sie Gärten bereitet, durcheilt von Bächen, ewig und auf immer darin zu bleiben; das ist der großartige Erfolg.", "nl": "De allereerste (Moslims) van de Ukgewekenen (Moehâdjirîn) en de Anshâr en degenen die hen volgden in goede daden. Allah heeft welbehagen aan hen en zij hebben welbehagen aan Hem. Hij heeft voor tien Tuinen (in het Pamdijs) bereid waar onder door de rivieren stromen, zij zijn daarin eeuwig levenden. Dat is de geweldige overwinning.", "es": "Alá está satisfecho de los más distinguidos -los primeros de los emigrados y de los auxiliares-, y de quienes les siguieron en sus buenas obras. Ellos también estarán satisfechos de Él, Que les ha preparado jardines por cuyos bajos fluyen arroyos en los que estarán eternamente, para siempre. ¡Ése es el éxito grandioso!", "it": "Allah Si è compiaciuto dell'avanguardia degli Emigrati e degli Ausiliari e di coloro che li hanno seguiti fedelmente, ed essi sono compiaciuti di Lui. Per loro ha preparato Giardini in cui scorrono i ruscelli dove rimarranno in perpetuo. Questo è il successo immenso.", "ar": "والذين سبقوا الناس أولا إلى الإيمان بالله ورسوله من المهاجرين الذين هجروا قومهم وعشيرتهم وانتقلوا إلى دار الإسلام، والأنصار الذين نصروا رسول الله صلى الله عليه وسلم على أعدائه الكفار، والذين اتبعوهم بإحسان في الاعتقاد والأقوال والأعمال طلبًا لمرضاة الله سبحانه وتعالى، أولئك الذين رضي الله عنهم لطاعتهم الله ورسوله، ورضوا عنه لما أجزل لهم من الثواب على طاعتهم وإيمانهم، وأعدَّ لهم جنات تجري تحتها الأنهار خالدين فيها أبدًا، ذلك هو الفلاح العظيم. وفي هذه الآية تزكية للصحابة -رضي الله عنهم- وتعديل لهم، وثناء عليهم؛ ولهذا فإن توقيرهم من أصول الإيمان."}}, "9:103": {"s": 9, "v": 103, "nom": {"ar": "سُورَةُ التَّوۡبَةِ", "lat": "At-Tawba"}, "ar": "خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةًۭ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌۭ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ", "tl": {"en": "Khuz min amwaalihim sadaqtan tutahhiruhum wa tuzakkeehim bihaa wa salli 'alaihim inna salaataka sakanul lahum; wallaahu Samee'un 'Aleem", "tr": "ḫuẕ min emvâlihim ṣadeḳaten tüṭahhiruhüm vetüzekkîhim bihâ veṣalli `aleyhim. inne ṣalâteke sekenül lehüm. vellâhü semî`un `alîm."}, "tr": {"fr": "Prélève de leurs biens une Sadaqa par laquelle tu les purifies et les bénis, et prie pour eux. Ta prière est une quiétude pour eux. Et Allah est Audient et Omniscient.", "en": "Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah 's blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing.", "id": "Ambillah zakat dari sebagian harta mereka, dengan zakat itu kamu membersihkan dan mensucikan mereka dan mendoalah untuk mereka. Sesungguhnya doa kamu itu (menjadi) ketenteraman jiwa bagi mereka. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "tr": "Mallarının bir kısmını, kendilerini temizleyip arıtacak sadaka olarak al, onlara dua et; senin duan onlar için bir güvendir. Allah işitir ve bilir.", "de": "Nimm von ihrem Besitz ein Almosen, mit dem du sie rein machst und läuterst, und bete für sie, denn dein Gebet ist für sie eine Beruhigung! Allah ist Allhörend und Allwissend.", "nl": "Neem van de bezittingen de zakkât, jij reinigt en zuivert hen daarmee (O Moehammad), en verricht een smeekbede, want jouw smeekbede is een geruststelling voor hen. En Allah is Alhorend, Alwetend.", "es": "¡Deduce de sus bienes una limosna para limpiarles y purificarles con ella! ¡Y ora por ellos! Tu oración les sosiega. Alá todo lo oye, todo lo sabe.", "it": "Preleva sui loro beni un'elemosina, tramite la quale, li purifichi e li mondi e prega per loro. Le tue preghiere saranno un sollievo per loro. Allah tutto ascolta e conosce.", "ar": "خذ -أيها النبي- من أموال هؤلاء التائبين الذين خلطوا عملا صالحا وآخر سيئا صدقة تطهرهم مِن دنس ذنوبهم، وترفعهم عن منازل المنافقين إلى منازل المخلصين، وادع لهم بالمغفرة لذنوبهم واستغفر لهم منها، إن دعاءك واستغفارك رحمة وطمأنينة لهم. والله سميع لكل دعاء وقول، عليم بأحوال العباد ونياتهم، وسيجازي كلَّ عامل بعمله."}}, "11:37": {"s": 11, "v": 37, "nom": {"ar": "سُورَةُ هُودٍ", "lat": "Hud"}, "ar": "وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۚ إِنَّهُم مُّغْرَقُونَ", "tl": {"en": "Wasna'il fulka bi-a'yuninaa wa wahyinaa wa laa tukhaa tibnee fil lazeena zalamoo; innahum mughraqoon", "tr": "vaṣne`i-lfülke bia`yüninâ vevaḥyinâ velâ tüḫâṭibnî fi-lleẕîne żalemû. innehüm mugraḳûn."}, "tr": {"fr": "Et construis l'arche sous Nos yeux et d'après Notre révélation. Et ne M'interpelle plus au sujet des injustes, car ils vont être noyés».", "en": "And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned.\"", "id": "Dan buatlah bahtera itu dengan pengawasan dan petunjuk wahyu Kami, dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim itu; sesungguhnya mereka itu akan ditenggelamkan.", "tr": "Nuh'a, \"Senin milletinden, inanmış olanlardan başkası inanmayacaktır; onların yapageldiklerine üzülme; nezaretimiz altında, sana bildirdiğimiz gibi gemiyi yap. Haksızlık yapanlar için Bana baş vurma, çünkü onlar suda boğulacaklardır\" diye Allah tarafından vahyolundu.", "de": "Und verfertige das Schiff vor Unseren Augen und nach Unserer Eingebung. Und sprich Mich nicht an zugunsten derer, die Unrecht getan haben; sie werden ertränkt werden.\"", "nl": "Bouw het schip onder Ons toezicht en Onze Openbaring en spreek Mij niet aan over degenen die onrecht pleegden. Voorwaar, zij worden verdronken.\"", "es": "¡Construye la nave bajo Nuestra mirada y según Nuestra inspiración y no me hables de los que han obrado impíamente! ¡Van a ser anegados!»", "it": "Costruisci l'Arca sotto i Nostri occhi e secondo la Nostra rivelazione. Non parlarMi a favore degli ingiusti: in verità, saranno annegati”.", "ar": "واصنع السفينة بمرأى منَّا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكلاءتنا، ولا تطلب مني إمهال هؤلاء الذين ظلموا أنفسهم من قومك بكفرهم، فإنهم مغرقون بالطوفان. وفي الآية إثبات صفة العين لله تعالى على ما يليق به سبحانه."}}, "11:40": {"s": 11, "v": 40, "nom": {"ar": "سُورَةُ هُودٍ", "lat": "Hud"}, "ar": "حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّۢ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ ۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌۭ", "tl": {"en": "Hattaaa izaa jaaa'a amrunaa wa faarat tannooru qulnah mil feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa 'alaihil qawlu wa man aaman; wa maaa aamana ma'ahooo illaa qaleel", "tr": "ḥattâ iẕâ câe emrunâ vefâra-ttennûru ḳulne-ḥmil fîhâ min küllin zevceyni-ŝneyni veehleke illâ men sebeḳa `aleyhi-lḳavlü vemen âmen. vemâ âmene me`ahû illâ ḳalîl."}, "tr": {"fr": "Puis, lorsque Notre commandement vint et que le four se mit à bouillonner [d'eau], Nous dîmes: «Charge [dans l'arche] un couple de chaque espèce ainsi que ta famille - sauf ceux contre qui le décret est déjà prononcé - et ceux qui croient». Or, ceux qui avaient cru avec lui étaient peu nombreux.", "en": "[So it was], until when Our command came and the oven overflowed, We said, \"Load upon the ship of each [creature] two mates and your family, except those about whom the word has preceded, and [include] whoever has believed.\" But none had believed with him, except a few.", "id": "Hingga apabila perintah Kami datang dan dapur telah memancarkan air, Kami berfirman: \"Muatkanlah ke dalam bahtera itu dari masing-masing binatang sepasang (jantan dan betina), dan keluargamu kecuali orang yang telah terdahulu ketetapan terhadapnya dan (muatkan pula) orang-orang yang beriman\". Dan tidak beriman bersama dengan Nuh itu kecuali sedikit.", "tr": "Buyruğumuz gelip tandırdan sular kaynamağa başlayınca, \"Her cinsten birer çifti ve aleyhine hüküm verilmiş olanın dışında kalan çoluk çocuğunu ve inananları gemiye bindir\" dedik. Pek az kimse onunla beraber inanmıştı.", "de": "(So ging es,) bis nun Unser Befehl kam und der Ofen brodelte; Wir sagten: \"Lade darin von jeder (Art) zwei, ein Paar, und deine Angehörigen außer demjenigen, gegen den das Wort vorher ergangen ist, und diejenigen, die glauben!\" Mit ihm glaubten aber nur wenige.", "nl": "Totdat, toen Ons bevel (om hen te vernietigen) kwam, en de oven overkookte. En Wij zeiden: \"Laad het (schip) met twee van elke soort, en jouw familie, behalve hen voor wie het woord (van bestraffing) reeds is voorafgegaan. En degene die gelooft. En niemand geloofde met ten, behalve enkelen.", "es": "Hasta que, cuando vino Nuestra orden y el horno hirvió, dijimos: «Carga en ella a una pareja de cada especie, a tu familia -salvo a aquél cuya suerte ha sido ya echada- y a los creyentes»,. Pero no eran sino pocos los que con él creían.", "it": "Quando giunse il Nostro Decreto e il forno buttò fuori, dicemmo: “Fai salire una coppia per ogni specie e la tua famiglia, eccetto colui del quale è già stata decisa la sorte, e coloro che credono”. [“il forno buttò fuori”: il “forno” viene per lo più inteso come un riferimento alla superficie terrestre, e sembra voler dare l'idea che non si trattò di pioggia diluviale, ma di una catastrofe provocata dalla fuoriuscita di acque dalle profondità della terra] Coloro che avevano creduto insieme con lui, erano veramente pochi.", "ar": "حتى إذا جاء أمرنا بإهلاكهم كما وَعدْنا نوحًا بذلك، ونبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، قلنا لنوح: احمل في السفينة من كل نوع من أنواع الحيوانات ذكرًا وأنثى، واحمل فيها أهل بيتك، إلا مَن سبق عليهم القول ممن لم يؤمن بالله كابنه وامرأته، واحمل فيها من آمن معك من قومك، وما آمن معه إلا قليل مع طول المدة والمقام فيهم."}}, "11:43": {"s": 11, "v": 43, "nom": {"ar": "سُورَةُ هُودٍ", "lat": "Hud"}, "ar": "قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍۢ يَعْصِمُنِى مِنَ ٱلْمَآءِ ۚ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ ۚ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ", "tl": {"en": "Qaala sa aaweee ilaa jabaliny ya'simunee minal maaa'; qaala laa 'aasimal yawma min amril laahi illaa mar rahim; wa haala bainahumal mawju fakaana minal mughraqeen", "tr": "ḳâle seâvî ilâ cebeliy ya`ṣimünî mine-lmâ'. ḳâle lâ `âṣime-lyevme min emri-llâhi illâ mer raḥim. veḥâle beynehüme-lmevcü fekâne mine-lmugraḳîn."}, "tr": {"fr": "Il répondit: «Je vais me réfugier vers un mont qui me protègera de l'eau». Et Noé lui dit: «Il n'y a aujourd'hui aucun protecteur contre l'ordre d'Allah. (Tous périront) sauf celui à qui Il fait miséricorde». Et les vagues s'interposèrent entre les deux, et le fils fut alors du nombre des noyés.", "en": "[But] he said, \"I will take refuge on a mountain to protect me from the water.\" [Noah] said, \"There is no protector today from the decree of Allah, except for whom He gives mercy.\" And the waves came between them, and he was among the drowned.", "id": "Anaknya menjawab: \"Aku akan mencari perlindungan ke gunung yang dapat memeliharaku dari air bah!\" Nuh berkata: \"Tidak ada yang melindungi hari ini dari azab Allah selain Allah (saja) Yang Maha Penyayang\". Dan gelombang menjadi penghalang antara keduanya; maka jadilah anak itu termasuk orang-orang yang ditenggelamkan.", "tr": "Oğlu: \"Dağa sığınırım, beni sudan kurtarır\" deyince, Nuh: \"Bugün Allah'ın buyruğundan O'nun acıdıkları dışında kurtulacak yoktur\" dedi. Aralarına dalga girdi, oğlu da boğulanlara karıştı.", "de": "Er sagte: \"Ich werde auf einem Berg Zuflucht suchen, der mich vor dem Wasser schützt.\" Er sagte: \"Es gibt heute nichts, das vor dem Befehl Allahs schützen könnte, außer für den, dessen Er Sich erbarmt.\" Die Wogen trennten sie beide, und so gehörte er zu denjenigen, die ertränkt wurden.", "nl": "Hij zei: \"Ik zal een schuilplaats zoeken in de bergen die mij tegen het water zal beschernen.\" Hij (Nôeh) zei: \"Op deze dag is er geen bescherming tegen het bevel van AlIah, behalve voor wie Hij begenadigt.\" En de golven scheidden hen en bij behoorde tot de verdronkenen.", "es": "Dijo: «Me refugiaré en una montaña que me proteja del agua». Dijo: «Hoy nadie encontrará protección contra la orden de Alá, salvo aquél de quien Él se apiade». Se interpusieron entre ambos las olas y fue de los que se ahogaron.", "it": "Rispose: “Mi rifugerò su un monte che mi proteggerà dall'acqua”. Disse [Noè]: “Oggi non c'è nessun riparo contro il decreto di Allah, eccetto [per] colui che gode della [Sua] misericordia”. Si frapposero le onde tra i due e fu tra gli annegati.", "ar": "قال ابن نوح: سألجأ إلى جبل أتحصَّن به من الماء، فيمنعني من الغرق، فأجابه نوح: لا مانع اليوم من أمر الله وقضائه الذي قد نزل بالخلق من الغرق والهلاك إلا مَن رحمه الله تعالى، فآمِنْ واركب في السفينة معنا، وحال الموج المرتفع بين نوح وابنه، فكان من المغرقين الهالكين."}}, "12:2": {"s": 12, "v": 2, "nom": {"ar": "سُورَةُ يُوسُفَ", "lat": "Yusuf"}, "ar": "إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ", "tl": {"en": "Innaaa anzalnaahu quraanan 'Arabiyyal la 'allakum ta'qiloon", "tr": "innâ enzelnâhü ḳur'ânen `arabiyyel le`alleküm ta`ḳilûn."}, "tr": {"fr": "Nous l'avons fait descendre, un Coran en [langue] arabe, afin que vous raisonniez.", "en": "Indeed, We have sent it down as an Arabic Qur'an that you might understand.", "id": "Sesungguhnya Kami menurunkannya berupa Al Quran dengan berbahasa Arab, agar kamu memahaminya.", "tr": "Biz onu, anlayasınız diye, Arapça bir Kuran olarak indirdik.", "de": "Wir haben es als einen arabischen Qur'an hinabgesandt, auf daß ihr begreifen möget.", "nl": "Voorwaar, Wij hebben hem neergezonden, een Arabische Koran. Hopelijk zuilen jullie begrijpen.", "es": "La hemos revelado como Corán árabe. Quizás, así razonéis.", "it": "In verità lo abbiamo fatto scendere come Corano arabo, affinché possiate comprendere.", "ar": "إنا أنزلنا هذا القرآن بلغة العرب، لعلكم -أيها العرب- تعقلون معانيه وتفهمونها، وتعملون بهديه."}}, "12:3": {"s": 12, "v": 3, "nom": {"ar": "سُورَةُ يُوسُفَ", "lat": "Yusuf"}, "ar": "نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ", "tl": {"en": "Nahnu naqussu 'alaika ahsanal qasasi bimaaa awhainaaa ilaika haazal quraana wa in kunta min qablihee laminal ghaafileen", "tr": "naḥnü neḳuṣṣu `aleyke aḥsene-lḳaṣaṣi bimâ evḥaynâ ileyke hâẕe-lḳur'ân. vein künte min ḳablihî lemine-lgâfilîn."}, "tr": {"fr": "Nous te racontons le meilleur récit, grâce à la révélation que Nous te faisons dans ce Coran même si tu étais auparavant du nombre des inattentifs (à ces récits).", "en": "We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur'an although you were, before it, among the unaware.", "id": "Kami menceritakan kepadamu kisah yang paling baik dengan mewahyukan Al Quran ini kepadamu, dan sesungguhnya kamu sebelum (Kami mewahyukan)nya adalah termasuk orang-orang yang belum mengetahui.", "tr": "Biz bu Kuran'ı vahyederek, sana en güzel kıssaları anlatıyoruz.. Oysa daha önce sen bunlardan habersizdin.", "de": "Wir berichten dir die schönsten Geschichten dadurch, daß Wir dir diesen Qur'an (als Offenbarung) eingegeben haben, obgleich du zuvor wahrlich zu den Unachtsamen gehörtest.", "nl": "Wij vertellen jou het beste verhaal doordat Wij aan jou deze Koran openbaarden, hoewel jij daarvoor tot de onwetenden behoorde.", "es": "Con la revelación que te hacemos de este Corán vamos a contarte Nosotros el más bello de los relatos, aunque hayas sido antes de los despreocupados.", "it": "Grazie a ciò che ti ispiriamo in questo Corano, Noi ti raccontiamo la più bella storia, anche se precedentemente non ne eri a conoscenza.", "ar": "نحن نقصُّ عليك -أيها الرسول- أحسن القصص بوحينا إليك هذا القرآن، وإن كنت قبل إنزاله عليك لمن الغافلين عن هذه الأخبار، لا تدري عنها شيئًا."}}, "12:4": {"s": 12, "v": 4, "nom": {"ar": "سُورَةُ يُوسُفَ", "lat": "Yusuf"}, "ar": "إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ", "tl": {"en": "Iz qaala Yoosufu li abeehi yaaa abati innee ra aytu ahada 'ashara kawkabanw wash shamsa walqamara ra aytuhum lee saajideen", "tr": "iẕ ḳâle yûsüfü liebîhi yâ ebeti innî raeytü eḥade `aşera kevkebev veşşemse velḳamera raeytühüm lî sâcidîn."}, "tr": {"fr": "Quand Joseph dit à son père: «O mon père, j'ai vu [en songe], onze étoiles, et aussi le soleil et la lune; je les ai vus prosternés devant moi».", "en": "[Of these stories mention] when Joseph said to his father, \"O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me.\"", "id": "(Ingatlah), ketika Yusuf berkata kepada ayahnya: \"Wahai ayahku, sesungguhnya aku bermimpi melihat sebelas bintang, matahari dan bulan; kulihat semuanya sujud kepadaku\".", "tr": "Yusuf babasına: \"Babacığım! \"Rüyamda onbir yıldız, güneş ve ayın bana secde ettiklerini gördüm\" demişti.", "de": "Als Yusuf zu seinem Vater sagte: \"O mein Vater, ich sah elf Sterne und die Sonne und den Mond, ich sah sie sich vor mir niederwerfen.\"", "nl": "En (gedenkt) toen Yôusef tot zijn vader zei: \"O mijn vader, voorwaar, ik zag (in een droom) elf sterren en de zon en de maan, ik zag dat zij zich voor mij bogen.\"'", "es": "Cuando José dijo a su padre: «¡Padre! He visto once estrellas, el sol y la luna. Los he visto prosternarse ante mí».", "it": "Quando Giuseppe disse a suo padre: “O padre mio, ho visto [in sogno] undici stelle, il sole e la luna. Li ho visti prosternarsi davanti a me”,", "ar": "اذكر -أيها الرسول- لقومك قول يوسف لأبيه: إني رأيت في المنام أحد عشر كوكبًا، والشمس والقمر رأيتهم لي ساجدين. فكانت هذه الرؤيا بشرى لِمَا وصل إليه يوسف عليه السلام من علوِّ المنزلة في الدنيا والآخرة."}}, "12:15": {"s": 12, "v": 15, "nom": {"ar": "سُورَةُ يُوسُفَ", "lat": "Yusuf"}, "ar": "فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ", "tl": {"en": "Falammaa zahaboo bihee wa ajma'ooo anyyaj'aloohu fee ghayaabatil jubb; wa awyainaaa ilaihi latunabbi 'annahum bi amrihim haaza wa hum laa yash'uroon", "tr": "felemmâ ẕehebû bihî veecme`û ey yec`alûhü fî gayâbeti-lcübb. veevḥaynâ ileyhi letünebbiennehüm biemrihim hâẕâ vehüm lâ yeş`urûn."}, "tr": {"fr": "Et lorsqu'ils l'eurent emmené, et se furent mis d'accord pour le jeter dans les profondeurs invisibles du puits, Nous lui révélâmes: «Tu les informeras sûrement de cette affaire sans qu'ils s'en rendent compte».", "en": "So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, \"You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity].\"", "id": "Maka tatkala mereka membawanya dan sepakat memasukkannya ke dasar sumur (lalu mereka masukkan dia), dan (di waktu dia sudah dalam sumur) Kami wahyukan kepada Yusuf: \"Sesungguhnya kamu akan menceritakan kepada mereka perbuatan mereka ini, sedang mereka tiada ingat lagi\".", "tr": "Yusuf'u oturup bir kuyunun derinliklerine bırakmayı kararlaştırdılar. Biz ona, kardeşlerinin bu işlerini kendileri farkına varmadan haber vereceksin, diye vahyettik.", "de": "Als sie ihn mitnahmen und sich geeinigt hatten, ihn in die verborgene Tiefe des Brunnenlochs zu stecken, gaben Wir ihm ein: \"Du wirst ihnen ganz gewiß noch diese ihre Tat kundtun, ohne daß sie merken.\"", "nl": "Toen zij met hem weggingen en overeenkwamen om hem op de bodem van de put te werpen, openbaarden Wij aan hem: \"Jij zal hen zeker inlichten over die zaak van hun, terwijl zij het niet beseffen.\"", "es": "Cuando se lo llevaron y se pusieron de acuerdo para echarlo al fondo del aljibe... Y le inspiramos: «¡Ya les recordarás más tarde, sin que te reconozcan, lo que ahora han hecho!»", "it": "Quando poi lo ebbero condotto con loro e furono d'accordo nel gettarlo in fondo alla cisterna, Noi gli ispirammo: “Ricorderai loro quello che hanno commesso quando meno se lo aspetteranno”.", "ar": "فأرْسَلَهُ معهم. فلما ذهبوا به وأجمعوا على إلقائه في جوف البئر، وأوحينا إلى يوسف لتخبرنَّ إخوتك مستقبلا بفعلهم هذا الذي فعلوه بك، وهم لا يُحِسُّون بذلك الأمر ولا يشعرون به."}}, "14:39": {"s": 14, "v": 39, "nom": {"ar": "سُورَةُ إِبۡرَاهِيمَ", "lat": "Ibrahim"}, "ar": "ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ ۚ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ", "tl": {"en": "Alhamdu lillaahil lazee wahaba lee 'alal kibari Ismaa'eela wa Ishaaq; inna Rabbee lasamee'ud du'aaa", "tr": "elḥamdü lillâhi-lleẕî vehebe lî `ale-lkiberi ismâ`île veisḥâḳ. inne rabbî lesemî`u-ddü`â'."}, "tr": {"fr": "Louange à Allah, qui en dépit de ma vieillesse, m'a donné Ismaël et Isaac. Certes, mon Seigneur entend bien les prières.", "en": "Praise to Allah, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication.", "id": "Segala puji bagi Allah yang telah menganugerahkan kepadaku di hari tua(ku) Ismail dan Ishaq. Sesungguhnya Tuhanku, benar-benar Maha Mendengar (memperkenankan) doa.", "tr": "\"Kocamışken, bana İsmail ve İshak'ı veren Allah'a hamdolsun. Doğrusu Rabbim duaları işitendir.\"", "de": "(Alles) Lob gehört Allah, Der mir trotz meines hohen Alters Ismail und Ishaq geschenkt hat! Gewiß, mein Herr ist wahrlich der Erhörer des Gebets.", "nl": "Alle lof zij Allah, die mij Isma'îl en Ishaq geschonken heeft, ondanks mijn ouderdom. Voorwaar, mijn Heer verhoort zeker de smeekbeden.", "es": "¡Alabado sea Alá, Que, a pesar de mi vejez, me ha regalado a Ismael e Isaac! Mi Señor oye, ciertamente, a quien Le invoca.", "it": "Lode ad Allah Che, nonostante la vecchiaia, mi ha dato Ismaele ed Isacco. In verità, il mio Signore ascolta l'invocazione.", "ar": "يُثْني إبراهيم على الله تعالى، فيقول: الحمد لله الذي رزقني على كِبَر سني ولديَّ إسماعيل وإسحاق بعد دعائي أن يهب لي من الصالحين، إن ربي لسميع الدعاء ممن دعاه، وقد دعوته ولم يخيِّب رجائي."}}, "14:41": {"s": 14, "v": 41, "nom": {"ar": "سُورَةُ إِبۡرَاهِيمَ", "lat": "Ibrahim"}, "ar": "رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ", "tl": {"en": "Rabbanagh fir lee wa liwaalidaiya wa lilmu'mineena Yawma yaqoomul hisaab", "tr": "rabbene-gfir lî velivâlideyye velilmü'minîne yevme yeḳûmü-lḥisâb."}, "tr": {"fr": "O notre Seigneur! pardonne-moi, ainsi qu'à mes père et mère et aux croyants, le jour de la reddition des comptes».", "en": "Our Lord, forgive me and my parents and the believers the Day the account is established.\"", "id": "Ya Tuhan kami, beri ampunlah aku dan kedua ibu bapaku dan sekalian orang-orang mukmin pada hari terjadinya hisab (hari kiamat)\".", "tr": "\"Rabbimiz! Hesap görülecek günde, beni, anamı babamı ve inananları bağışla.\"", "de": "Unser Herr, vergib mir und meinen Eltern und den Gläubigen an dem Tag, da die Abrechnung stattfinden wird.\"", "nl": "Mijn Heer, vergeef mij en mijn ouders en de gelovigen op de Dag waarop de afrekening plaats vindt.\"", "es": "¡Señor! Perdónanos, a mí, a mis padres y a los creyentes el día que se ajusten cuentas».", "it": "O Signor nostro, perdona a me, ai miei genitori e ai credenti, nel Giorno in cui si tireranno le somme”.", "ar": "ربنا اغفر لي ما وقع مني مما لا يسلم منه البشر واغفر لوالديَّ، (وهذا قبل أن يتبيَّن له أن والده عدو لله) واغفر للمؤمنين جميعًا يوم يقوم الناس للحساب والجزاء."}}, "15:9": {"s": 15, "v": 9, "nom": {"ar": "سُورَةُ الحِجۡرِ", "lat": "Al-Hijr"}, "ar": "إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ", "tl": {"en": "Innaa Nahnu nazalnaz Zikra wa Innaa lahoo lahaa fizoon", "tr": "innâ naḥnü nezzelne-ẕẕikra veinnâ lehû leḥâfiżûn."}, "tr": {"fr": "En vérité c'est Nous qui avons fait descendre le Coran, et c'est Nous qui en sommes gardien.", "en": "Indeed, it is We who sent down the Qur'an and indeed, We will be its guardian.", "id": "Sesungguhnya Kami-lah yang menurunkan Al Quran, dan sesungguhnya Kami benar-benar memeliharanya.", "tr": "Doğrusu Kitap'ı Biz indirdik, onun koruyucusu elbette Biziz.", "de": "Gewiß, Wir sind es, die Wir die Ermahnung offenbart haben, und Wir werden wahrlich ihr Hüter sein.", "nl": "Voorwaar, Wij zijn het Die de Vermaning (de Koran) hebben neergezonden. En voorwaar, Wij zijn daarover zeker de Wakers.", "es": "Somos Nosotros Quienes hemos revelado la Amonestación y somos Nosotros sus custodios.", "it": "Noi abbiamo fatto scendere il Monito, e Noi ne siamo i custodi.", "ar": "إنَّا نحن نزَّلنا القرآن على النبي محمد صلى الله عليه وسلم، وإنَّا نتعهد بحفظه مِن أن يُزاد فيه أو يُنْقَص منه، أو يضيع منه شيء."}}, "15:87": {"s": 15, "v": 87, "nom": {"ar": "سُورَةُ الحِجۡرِ", "lat": "Al-Hijr"}, "ar": "وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًۭا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ", "tl": {"en": "Wa laqad aatainaaka sab'am mnal masaanee wal Qur-aanal 'azeem", "tr": "veleḳad âteynâke seb`am mine-lmeŝânî velḳur'âne-l`ażîm."}, "tr": {"fr": "Nous t'avons certes donné «les sept versets que l'on répète», ainsi que le Coran sublime.", "en": "And We have certainly given you, [O Muhammad], seven of the often repeated [verses] and the great Qur'an.", "id": "Dan sesungguhnya Kami telah berikan kepadamu tujuh ayat yang dibaca berulang-ulang dan Al Quran yang agung.", "tr": "And olsun ki, sana daima tekrarlanan yedi ayetli Fatiha'yı ve Kuran-ı Azim'i verdik.", "de": "Und Wir haben dir doch sieben von den sich wiederholenden Versen gegeben, und (auch) den großartigen Qur'an.", "nl": "En voorzeker, Wij hebben jou de zeven vaak herhaalde (Verzen) gegeven en de geweldige Koran.", "es": "Te hemos dado siete de las mazani y el sublime Corán.", "it": "Ti abbiamo dato i sette ripetuti e il Sublime Corano.", "ar": "ولقد آتيناك -أيها النبي- فاتحة القرآن، وهي سبع آيات تكرر في كل صلاة، وآتيناك القرآن العظيم."}}, "17:23": {"s": 17, "v": 23, "nom": {"ar": "سُورَةُ الإِسۡرَاءِ", "lat": "Al-Israa"}, "ar": "۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا", "tl": {"en": "Wa qadaa Rabbuka allaa ta'budooo illaaa iyyaahu wa bilwaalidaini ihsaanaa; immaa yablughanna 'indakal kibara ahaduhumaaa aw kilaahumaa falaa taqul lahumaaa uffinw wa laa tanharhumaa wa qullahumaa qawlan kareemaa", "tr": "veḳaḍâ rabbüke ellâ ta`büdû illâ iyyâhü vebilvâlideyni iḥsânâ. immâ yeblüganne `indeke-lkibera eḥadühümâ ev kilâhümâ felâ teḳul lehümâ üffiv velâ tenherhümâ veḳul lehümâ ḳavlen kerîmâ."}, "tr": {"fr": "Et ton Seigneur a décrété: «N'adorez que Lui; et (marquez) de la bonté envers les père et mère: si l'un d'eux ou tous deux doivent atteindre la vieillesse auprès de toi, alors ne leur dis point: «Fi!» et ne les brusque pas, mais adresse-leur des paroles respectueuses.", "en": "And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], \"uff,\" and do not repel them but speak to them a noble word.", "id": "Dan Tuhanmu telah memerintahkan supaya kamu jangan menyembah selain Dia dan hendaklah kamu berbuat baik pada ibu bapakmu dengan sebaik-baiknya. Jika salah seorang di antara keduanya atau kedua-duanya sampai berumur lanjut dalam pemeliharaanmu, maka sekali-kali janganlah kamu mengatakan kepada keduanya perkataan \"ah\" dan janganlah kamu membentak mereka dan ucapkanlah kepada mereka perkataan yang mulia.", "tr": "Rabbin, yalnız Kendisine tapmanızı ve ana babaya iyilik etmeyi buyurmuştur. Eğer ikisinden biri veya her ikisi, senin yanında iken ihtiyarlayacak olursa, onlara karşı \"Öf\" bile demeyesin, onları azarlamayasın. İkisine de hep tatlı söz söyleyesin.", "de": "Und dein Herr hat bestimmt, daß ihr nur Ihm dienen und zu den Eltern gütig sein sollt. Wenn nun einer von ihnen oder beide bei dir ein hohes Alter erreichen, so sag nicht zu ihnen: \"Pfui!\" und fahre sie nicht an, sondern sag zu ihnen ehrerbietige Worte.", "nl": "En jullie Heer heeft bepaald dat jullie niets dan Hem alleen aanbidden, en goedheid betrachten tegenover de ouders. Als een van de twee of beiden de ouderdom bereiken in jouw aanwezigheid, zeg dan nooit \"foei\" tegen ben, snauw hen niet af en spreek tot hen een vriendelijk woord.", "es": "Tu Señor ha decretado que no debéis servir sino a Él y que debéis ser buenos con vuestros padres. Si uno de ellos o ambos envejecen en tu casa, no les digas: «¡Uf!» y trates con antipatía, sino sé cariñoso con ellos.", "it": "Il tuo Signore ha decretato di non adorare altri che Lui e di trattare bene i vostri genitori. Se uno di loro, o entrambi, dovessero invecchiare presso di te, non dir loro “uff!” e non li rimproverare; ma parla loro con rispetto,", "ar": "وأَمَر ربك -أيها الإنسان- وألزم وأوجب أن يفرد سبحانه وتعالى وحده بالعبادة، وأمر بالإحسان إلى الأب والأم، وبخاصة حالةُ الشيخوخة، فلا تضجر ولا تستثقل شيئًا تراه من أحدهما أو منهما، ولا تسمعهما قولا سيئًا، حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ، ولا يصدر منك إليهما فعل قبيح، ولكن ارفق بهما، وقل لهما -دائما- قولا لينًا لطيفًا."}}, "17:24": {"s": 17, "v": 24, "nom": {"ar": "سُورَةُ الإِسۡرَاءِ", "lat": "Al-Israa"}, "ar": "وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا", "tl": {"en": "Wakhfid lahumaa janaahaz zulli minar rahmati wa qur Rabbir hamhumaa kamaa rabbayaanee sagheera", "tr": "vaḫfiḍ lehümâ cenâḥa-ẕẕülli mine-rraḥmeti veḳur rabbi-rḥamhümâ kemâ rabbeyânî ṣagîrâ."}, "tr": {"fr": "et par miséricorde, abaisse pour eux l'aile de l'humilité, et dis: «O mon Seigneur, fais-leur, à tous deux, miséricorde comme ils m'ont élevé tout petit».", "en": "And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small.\"", "id": "Dan rendahkanlah dirimu terhadap mereka berdua dengan penuh kesayangan dan ucapkanlah: \"Wahai Tuhanku, kasihilah mereka keduanya, sebagaimana mereka berdua telah mendidik aku waktu kecil\".", "tr": "Onlara acıyarak alçak gönüllülük kanatlarını ger ve: \"Rabbim! Küçükken beni yetiştirdikleri gibi sen de onlara merhamet et!\" de.", "de": "Und senke für sie aus Barmherzigkeit den Flügel der Demut und sag: \"Mein Herr, erbarme Dich ihrer, wie sie mich aufgezogen haben, als ich klein war.\"", "nl": "En wees zachtmoedig voor beiden, en nederig en liefdevol, en zeg: \"O mijn Heer, schenk hun Genade, zoals zij mij opvoedden toen ik klein was.\"", "es": "Por piedad, muéstrate deferente con ellos y di: «¡Señor, ten misericordia de ellos como ellos la tuvieron cuando me educaron siendo niño!»", "it": "e inclina con bontà, verso di loro, l'ala della tenerezza; e di': “O Signore, sii misericordioso nei loro confronti, come essi lo sono stati nei miei, allevandomi quando ero piccolo”.", "ar": "وكُنْ لأمك وأبيك ذليلا متواضعًا رحمة بهما، واطلب من ربك أن يرحمهما برحمته الواسعة أحياءً وأمواتًا، كما صبرا على تربيتك طفلا ضعيف الحول والقوة."}}, "17:81": {"s": 17, "v": 81, "nom": {"ar": "سُورَةُ الإِسۡرَاءِ", "lat": "Al-Israa"}, "ar": "وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ ۚ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًۭا", "tl": {"en": "Wa qul jaaa'al haqqu wa zahaqal baatil; innal baatila kaana zahooqaa", "tr": "veḳul câe-lḥaḳḳu vezeheḳa-lbâṭil. inne-lbâṭile kâne zehûḳâ."}, "tr": {"fr": "Et dis: «La Vérité (l'Islam) est venue et l'Erreur a disparu. Car l'Erreur est destinée à disparaître».", "en": "And say, \"Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart.\"", "id": "Dan katakanlah: \"Yang benar telah datang dan yang batil telah lenyap\". Sesungguhnya yang batil itu adalah sesuatu yang pasti lenyap.", "tr": "De ki: \"Hak geldi, batıl ortadan kalkmaya mahkumdur.\"", "de": "Und sag: Die Wahrheit ist gekommen, und das Falsche geht dahin; das Falsche ist ja dazu bestimmt, dahinzugehen.", "nl": "En zeg: \"De Waarheid is gekomen en de valsheid is ten onder gegaan. Voorwaar, de valsheid gaat ten onder.\"", "es": "Y di: «¡Ha venido la Verdad y se ha disipado lo falso! ¡Lo falso tiene que disiparse!»", "it": "E di': “È giunta la verità, la falsità è svanita”. Invero la falsità è destinata a svanire.", "ar": "وقل -أيها الرسول- للمشركين: جاء الإسلام وذهب الشرك، إن الباطل لا بقاء له ولا ثبات، والحق هو الثابت الباقي الذي لا يزول."}}, "19:16": {"s": 19, "v": 16, "nom": {"ar": "سُورَةُ مَرۡيَمَ", "lat": "Maryam"}, "ar": "وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًۭا شَرْقِيًّۭا", "tl": {"en": "Wazkur fil Kitaabi Marya; izin tabazat min ahlihaa makaanan shariqyyaa", "tr": "veẕkür fi-lkitâbi meryem. iẕi-ntebeẕet min ehlihâ mekânen şerḳiyyâ."}, "tr": {"fr": "Mentionne, dans le Livre (le Coran), Marie, quand elle se retira de sa famille en un lieu vers l'Orient.", "en": "And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.", "id": "Dan ceritakanlah (kisah) Maryam di dalam Al Quran, yaitu ketika ia menjauhkan diri dari keluarganya ke suatu tempat di sebelah timur,", "tr": "Kitabda Meryem'i de an. O, ailesinden ayrılarak, doğu yönünde bir yere çekilmişti.", "de": "Und gedenke im Buch Maryams, als sie sich von ihren Angehörigen an einen östlichen Ort zurückzog.", "nl": "En noem in het boek (de Koran) Maryam, toen zij zich terugtrok van haar familie naar een oostelijke plaats (in de tempel).", "es": "Y recuerda a María en la Escritura, cuando dejó a su familia para retirarse a un lugar de Oriente.", "it": "Ricorda Maria nel Libro, quando si allontanò dalla sua famiglia, in un luogo ad oriente.", "ar": "واذكر - أيها الرسول - في هذا القرآن خبر مريم إذ تباعدت عن أهلها، فاتخذت لها مكانًا مما يلي الشرق عنهم."}}, "19:19": {"s": 19, "v": 19, "nom": {"ar": "سُورَةُ مَرۡيَمَ", "lat": "Maryam"}, "ar": "قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًۭا زَكِيًّۭا", "tl": {"en": "Qaala innamaa ana rasoolu Rabbiki li ahaba laki ghulaaman zakiyyaa", "tr": "ḳâle innemâ ene rasûlü rabbik. liehebe leki gulâmen zekiyyâ."}, "tr": {"fr": "Il dit: «Je suis en fait un Messager de ton Seigneur pour te faire don d'un fils pur».", "en": "He said, \"I am only the messenger of your Lord to give you [news of] a pure boy.\"", "id": "Ia (jibril) berkata: \"Sesungguhnya aku ini hanyalah seorang utusan Tuhanmu, untuk memberimu seorang anak laki-laki yang suci\".", "tr": "Cebrail: \"Ben temiz bir oğlan bağışlamak için Rabbinin sana gönderdiği elçiden başkası değilim\" dedi.", "de": "Er sagte: \"Ich bin nur der Gesandte deines Herrn, um dir einen lauteren Jungen zu schenken.\"", "nl": "Hij zei: \"Voorwaar, ik ben slechts een gezant van jouw Heer, om jou een reine jongen te schenken.\"", "es": "Dijo él: «Yo soy sólo el enviado de tu Señor para regalarte un muchacho puro».", "it": "Rispose: “Non sono altro che un messaggero del tuo Signore, per darti un figlio puro”.", "ar": "قال لها المَلَك: إنما أنا رسول ربك بعثني إليك؛ لأهب لك غلامًا طاهرًا من الذنوب."}}, "19:30": {"s": 19, "v": 30, "nom": {"ar": "سُورَةُ مَرۡيَمَ", "lat": "Maryam"}, "ar": "قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّۭا", "tl": {"en": "Qaala innee 'abdullaahi aataaniyal Kitaaba wa ja'alanee Nabiyyaa", "tr": "ḳâle innî `abdü-llâh. âtâniye-lkitâbe vece`alenî nebiyyâ."}, "tr": {"fr": "Mais (le bébé) dit: «Je suis vraiment le serviteur d'Allah. Il m'a donné le Livre et m'a désigné Prophète.", "en": "[Jesus] said, \"Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.", "id": "Berkata Isa: \"Sesungguhnya aku ini hamba Allah, Dia memberiku Al Kitab (Injil) dan Dia menjadikan aku seorang nabi,", "tr": "Çocuk: \"Ben şüphesiz Allah'ın kuluyum. Bana kitap verdi ve beni peygamber yaptı, nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı, zekat vermemi ve anneme iyi davranmamı emretti. Beni bedbaht bir zorba kılmadı. Doğduğum günde, öleceğim günde, dirileceğim günde bana selam olsun\" dedi.", "de": "Er sagte: \"Ich bin wahrlich Allahs Diener; Er hat mir die Schrift gegeben und mich zu einem Propheten gemacht.", "nl": "Hij ('Îsa) zei: \"Voorwaar, ik ben een dienaar van Allah. Hij heeft mij de Schrift gegeven en mij tot een Profeet gemaakt.", "es": "Dijo él: «Soy el siervo de Alá. Él me ha dado la Escritura y ha hecho de mí un profeta.", "it": "[Ma Gesù] disse: “In verità, sono un servo di Allah. Mi ha dato la Scrittura e ha fatto di me un profeta.", "ar": "قال عيسى وهو في مهده يرضع: إني عبد الله، قضى بإعطائي الكتاب، وهو الإنجيل، وجعلني نبيًا."}}, "20:20": {"s": 20, "v": 20, "nom": {"ar": "سُورَةُ طه", "lat": "Taa-Haa"}, "ar": "فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌۭ تَسْعَىٰ", "tl": {"en": "Fa-alqaahaa fa -izaa hiya haiyatun tas'aa", "tr": "feelḳâhâ feiẕâ hiye ḥayyetün tes`â."}, "tr": {"fr": "Il le jeta: et le voici un serpent qui rampait.", "en": "So he threw it down, and thereupon it was a snake, moving swiftly.", "id": "Lalu dilemparkannyalah tongkat itu, maka tiba-tiba ia menjadi seekor ular yang merayap dengan cepat.", "tr": "Bırakınca, değnek hemen, koşan bir yılan oluverdi.", "de": "Er warf ihn hin, und sogleich war er eine Schlange, die sich rasch bewegte.", "nl": "Toen wierp hij hem neer en hij word een slang die zich snel voortbewoog.", "es": "La tiró y he aquí que se convirtió en una serpiente que reptaba.", "it": "Lo gettò ed ecco che divenne un serpente che strisciava veloce.", "ar": "فألقاها موسى على الأرض، فانقلبت بإذن الله حية تسعى، فرأى موسى أمرًا عظيمًا وولى هاربًا."}}, "20:24": {"s": 20, "v": 24, "nom": {"ar": "سُورَةُ طه", "lat": "Taa-Haa"}, "ar": "ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ", "tl": {"en": "Izhab ilaa Fir'awna innahoo taghaa", "tr": "iẕheb ilâ fir`avne innehû ṭagâ."}, "tr": {"fr": "Rends-toi auprès de Pharaon car il a outrepassé toute limite.", "en": "Go to Pharaoh. Indeed, he has transgressed.\"", "id": "Pergilah kepada Fir'aun; sesungguhnya ia telah melampaui batas\".", "tr": "\"Firavun'a git, doğrusu o azmıştır.\"", "de": "Geh zu Fir'aun, denn gewiß, er überschreitet das Maß (an Frevel).\"", "nl": "Ga naar Fir'aun: voorwaar, hij overtrad.\"", "es": "¡Ve a Faraón! Se muestra reacio».", "it": "Vai da Faraone. In verità si è ribellato”.", "ar": "اذهب - يا موسى - إلى فرعون؛ إنه قد تجاوز قدره وتمرَّد على ربه، فادعه إلى توحيد الله وعبادته."}}, "20:30": {"s": 20, "v": 30, "nom": {"ar": "سُورَةُ طه", "lat": "Taa-Haa"}, "ar": "هَٰرُونَ أَخِى", "tl": {"en": "Haaroona akhee", "tr": "hârûne eḫî."}, "tr": {"fr": "Aaron, mon frère,", "en": "Aaron, my brother.", "id": "(yaitu) Harun, saudaraku,", "tr": "Musa: \"Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin\" dedi.", "de": "Harun, meinen Bruder.", "nl": "Hârôen, mijn broeder.", "es": "a Aarón, mi hermano.", "it": "Aronne, mio fratello.", "ar": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا."}}, "20:114": {"s": 20, "v": 114, "nom": {"ar": "سُورَةُ طه", "lat": "Taa-Haa"}, "ar": "فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۗ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ ۖ وَقُل رَّبِّ زِدْنِى عِلْمًۭا", "tl": {"en": "Fata'aalal laahul Malikul Haqq; wa laa ta'jal bil Quraani min qabli ai yuqdaaa ilaika wahyuhoo wa qur Rabbi zidnee 'ilmaa", "tr": "fete`âle-llâhü-lmelikü-lḥaḳḳ. velâ ta`cel bilḳur'âni min ḳabli ey yuḳḍâ ileyke vaḥyüh. veḳur rabbi zidnî `ilmâ."}, "tr": {"fr": "Que soit éxalté Allah, le Vrai Souverain! Ne te hâte pas [de réciter] le Coran avant que ne te soit achevée sa révélation. Et dis: «O mon Seigneur, accroît mes connaissances!»", "en": "So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur'an before its revelation is completed to you, and say, \"My Lord, increase me in knowledge.\"", "id": "Maka Maha Tinggi Allah Raja Yang sebenar-benarnya, dan janganlah kamu tergesa-gesa membaca Al qur'an sebelum disempurnakan mewahyukannya kepadamu, dan katakanlah: \"Ya Tuhanku, tambahkanlah kepadaku ilmu pengetahuan\".", "tr": "Gerçek hükümdar olan Allah Yüce'dir. Kuran sana vahyedilirken, vahy bitmezden önce, unutmamak için, tekrarda acele edip durma, \"Rabbim! ilmimi artır\" de.", "de": "Erhaben ist Allah, der König, der Wahre! Und übereile dich nicht mit dem Qur'an, bevor dir seine Offenbarung vollständig eingegeben worden ist. Und sag: Mein Herr, lasse mich an Wissen zunehmen.", "nl": "En Verheven is Allah, de Ware Koning. En haast je niet met de Koran (O Moehammad), voordat zijn openbaring an jou voltooid is. En zeg: \"'Mijn Heer, vermeerder voor mijn kennis.\"", "es": "¡Exaltado sea Alá, el Rey verdadero! ¡No te precipites en la Recitación antes de que te sea revelada por entero! Y di: «¡Señor! ¡Aumenta mi ciencia!»", "it": "Sia esaltato Allah, il Re, il Vero. Non aver fretta di recitare, prima che sia conclusa la rivelazione, ma di': “Signor mio, accresci la mia scienza”.", "ar": "فتنزَّه الله - سبحانه - وارتفع، وتقدَّس عن كل نقص، الملك الذي قهر سلطانه كل ملك وجبار، المتصرف بكل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق. ولا تعجل - أيها الرسول - بمسابقة جبريل في تَلَقِّي القرآن قبل أن يَفْرَغ منه، وقل: ربِّ زدني علمًا إلى ما علمتني."}}, "21:47": {"s": 21, "v": 47, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌۭ شَيْـًۭٔا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍۢ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَٰسِبِينَ", "tl": {"en": "Wa nada'ul mawaazeenal qista li Yawmil Qiyaamati falaa tuzlamu nafsun shai'aa; wa in kaana misqaala habbatim min khardalin atainaa bihaa; wa kafaa binaa haasibeen", "tr": "veneḍa`u-lmevâzîne-lḳiṣṭa liyevmi-lḳiyâmeti felâ tużlemü nefsün şey'â. vein kâne miŝḳâle ḥabbetim min ḫardelin eteynâ bihâ. vekefâ binâ ḥâsibîn."}, "tr": {"fr": "Au Jour de la Résurrection, Nous placerons les balances exactes. Nulle âme ne sera lésée en rien, fût-ce du poids d'un grain de moutarde que Nous ferons venir. Nous suffisons largement pour dresser les comptes.", "en": "And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant.", "id": "Kami akan memasang timbangan yang tepat pada hari kiamat, maka tiadalah dirugikan seseorang barang sedikitpun. Dan jika (amalan itu) hanya seberat biji sawipun pasti Kami mendatangkan (pahala)nya. Dan cukuplah Kami sebagai pembuat perhitungan.", "tr": "Kıyamet günü doğru teraziler kurarız; hiçbir kimse hiçbir haksızlığa uğratılmaz. Hardal tanesi kadar olsa bile yapılanı ortaya koyarız. Hesap gören olarak Biz yeteriz.", "de": "Und Wir stellen die gerechten Waagen für den Tag der Auferstehung auf. So wird keiner Seele um irgend etwas Unrecht zugefügt; und wäre es auch das Gewicht eines Senfkorns, Wir bringen es bei. Und Wir genügen als Berechner.", "nl": "En Wij zullen betrouwbare weegschalen opstellen op de Dag der Opstanding, zodat geen ziet iets van onrecht aangedaan wordt. En al gaat het om het gewicht van een mosterdzaadje: Wij zullen het naar voren brengen. En Wij zijn voldoende als Berekenaars.", "es": "Para el día de la Resurrección dispondremos balanzas que den el peso justo y nadie será tratado injustamente en nada. Aunque se trate de algo del peso de un grano de mostaza, lo tendremos en cuenta. ¡Bastamos Nosotros para ajustar cuentas!", "it": "Rizzeremo bilance esatte, nel Giorno della Resurrezione e nessuna anima subirà alcun torto; foss'anche del peso di un granello di senape, lo riesumeremo. Basteremo Noi a tirare le somme.", "ar": "ويضع الله تعالى الميزان العادل للحساب في يوم القيامة، ولا يظلم هؤلاء ولا غيرهم شيئًا، وإن كان هذا العمل قدْرَ ذرة مِن خير أو شر اعتبرت في حساب صاحبها. وكفى بالله محصيًا أعمال عباده، ومجازيًا لهم عليها."}}, "21:52": {"s": 21, "v": 52, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ", "tl": {"en": "Iz qaala li abeehi wa qawmihee maa haazihit tamaaseelul lateee antum lahee 'aakifoon", "tr": "iẕ ḳâle liebîhi veḳavmihî mâ hâẕihi-ttemâŝîlü-lletî entüm lehâ `âkifûn."}, "tr": {"fr": "Quand il dit à son père et à son peuple: «Que sont ces statues auxquelles vous vous attachez?»", "en": "When he said to his father and his people, \"What are these statues to which you are devoted?\"", "id": "(Ingatlah), ketika Ibrahim berkata kepada bapaknya dan kaumnya: \"Patung-patung apakah ini yang kamu tekun beribadat kepadanya?\"", "tr": "İbrahim, babasına ve milletine: \"Bu tapınıp durduğunuz heykeller nedir?\" demişti.", "de": "Als er zu seinem Vater und seinem Volk sagte: \"Was sind das für Bildwerke, deren Andacht ihr euch hingebt?\"", "nl": "(Gedenkt) toen hij tegen zijn vader en zijn voik zei: \"Wat zijn dat voor beelden, die jullie aanbidden?\"", "es": "Cuando dijo a su padre y a su pueblo: «¿Qué son estas estatuas a cuyo culto estáis entregados?»", "it": "Quando disse a suo padre e alla sua gente: “Cosa sono queste statue in cui credete?”.", "ar": "حين قال لأبيه وقومه: ما هذه الأصنام التي صنعتموها، ثم أقمتم على عبادتها ملازمين لها؟"}}, "21:69": {"s": 21, "v": 69, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "قُلْنَا يَٰنَارُ كُونِى بَرْدًۭا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ", "tl": {"en": "Qulnaa yaa naaru koonee bardanw wa salaaman 'alaaa Ibraaheem", "tr": "ḳulnâ yâ nâru kûnî berdev veselâmen `alâ ibrâhîm."}, "tr": {"fr": "Nous dîmes: «O feu, sois pour Abraham une fraîcheur salutaire».", "en": "Allah said, \"O fire, be coolness and safety upon Abraham.\"", "id": "Kami berfirman: \"Hai api menjadi dinginlah, dan menjadi keselamatanlah bagi Ibrahim\",", "tr": "Biz: \"Ey ateş! İbrahim'e karşı serin ve zararsız ol\" dedik.", "de": "Wir sagten: \"O Feuer, sei Kühlung und Unversehrtheit für Ibrahim.\"", "nl": "Wij (Allah) zeiden: \"O vuur, wees koud en veilig voor Ibrâhîm.", "es": "Dijimos: «¡Fuego! ¡Sé frío para Abraham y no le dañes!»", "it": "Dicemmo: “Fuoco, sii frescura e pace per Abramo”.", "ar": "لما بطلت حجتهم وظهر الحق عدلوا إلى استعمال سلطانهم، وقالوا: حَرِّقوا إبراهيم بالنار؛ غضبًا لآلهتكم إن كنتم ناصرين لها. فأشْعَلوا نارًا عظيمة وألقوه فيها، فانتصر الله لرسوله وقال للنار: كوني بردًا وسلامًا على إبراهيم، فلم يَنَلْه فيها أذى، ولم يصبه مكروه."}}, "21:87": {"s": 21, "v": 87, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًۭا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ", "tl": {"en": "Wa Zan Nooni iz zahaba mughaadiban fazaanna al lan naqdira 'alaihi fanaanna al lan naqdira 'alaihi fanaadaa fiz zulumaati al laaa ilaaha illaaa Anta Subhaanaka innee kuntu minaz zaalimeen", "tr": "veẕe-nnûni iẕ ẕehebe mügâḍiben feżanne el len naḳdira `aleyhi fenâdâ fi-żżulümâti el lâ ilâhe illâ ente sübḥânek. innî küntü mine-żżâlimîn."}, "tr": {"fr": "Et Dû'n-Nûn (Jonas) quand il partit, irrité. Il pensa que Nous N'allions pas l'éprouver. Puis il fit, dans les ténèbres, l'appel que voici: «Pas de divinité à part Toi! Pureté à Toi! J'ai été vraiment du nombre des injustes».", "en": "And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, \"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.\"", "id": "Dan (ingatlah kisah) Dzun Nun (Yunus), ketika ia pergi dalam keadaan marah, lalu ia menyangka bahwa Kami tidak akan mempersempitnya (menyulitkannya), maka ia menyeru dalam keadaan yang sangat gelap: \"Bahwa tidak ada Tuhan selain Engkau. Maha Suci Engkau, sesungguhnya aku adalah termasuk orang-orang yang zalim\".", "tr": "Zünnun (Balık Sahibi; Yunus) hakkında söylediğimizi de an. O, öfkelenerek giderken, kendisini sıkıntıya sokmayacağımızı sanmıştı; fakat sonunda karanlıklar içinde: \"Senden başka tanrı yoktur, Sen münezzehsin, doğrusu ben haksızlık edenlerdenim\" diye seslenmişti.", "de": "Und (auch) dem Mann mit dem Fisch', als er erzürnt wegging. Da meinte er, Wir würden ihm nicht (den Lebensunterhalt) bemessen. Dann rief er in den Finsternissen: \"Es gibt keinen Gott außer Dir! Preis sei Dir! Gewiß, ich gehöre zu den Ungerechten.\"", "nl": "En (gedenkt) Dzôennôen toen hij kwaad wegging en meende dat Wij geen macht over hem hadden. Toen riep hij uit in de duisternissen: \"Er is geen god dan U, Heilig bent U: voorwaar, ik behoorde tot de onrechtvaardigen.\"", "es": "Y al del pez. Cuando se fue airado y creyó que no podríamos hacer nada contra él. Y clamó en las tinieblas: «¡No hay más dios que Tú! ¡Gloria a Ti! He sido de los impíos».", "it": "E l'Uomo del Pesce, quando se ne andò irritato. Pensava che non potessimo niente contro di lui. Poi implorò così nelle tenebre: “Non c'è altro dio all'infuori di Te! Gloria a Te! Io sono stato un ingiusto!”.", "ar": "واذكر قصة صاحب الحوت، وهو يونس بن مَتَّى عليه السلام، أرسله الله إلى قومه فدعاهم فلم يؤمنوا، فتوعَّدهم بالعذاب فلم ينيبوا، ولم يصبر عليهم كما أمره الله، وخرج مِن بينهم غاضبًا عليهم، ضائقًا صدره بعصيانهم، وظن أن الله لن يضيِّق عليه ويؤاخذه بهذه المخالفة، فابتلاه الله بشدة الضيق والحبس، والتقمه الحوت في البحر، فنادى ربه في ظلمات الليل والبحر وبطن الحوت تائبًا معترفًا بظلمه؛ لتركه الصبر على قومه، قائلا: لا إله إلا أنت سبحانك، إني كنت من الظالمين."}}, "21:88": {"s": 21, "v": 88, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ", "tl": {"en": "Fastajabnaa lahoo wa najjainaahu minal ghamm; wa kazaalika nunjil mu'mineen", "tr": "festecebnâ lehû venecceynâhü mine-lgamm. vekeẕâlike nünci-lmü'minîn."}, "tr": {"fr": "Nous l'exauçâmes et le sauvâmes de son angoisse. Et c'est ainsi que Nous sauvons les croyants.", "en": "So We responded to him and saved him from the distress. And thus do We save the believers.", "id": "Maka Kami telah memperkenankan doanya dan menyelamatkannya dari pada kedukaan. Dan demikianlah Kami selamatkan orang-orang yang beriman.", "tr": "Biz de ona cevap verip, onu üzüntüden kurtarmıştık. inananları böyle kurtarırız.", "de": "Da erhörten Wir ihn und erretteten ihn aus dem Kummer. So retten Wir die Gläubigen.", "nl": "Toen verhoorden Wij hem en Wij redden hem iuit de nood. En zo redden Wij de gelovigen.", "es": "Le escuchamos, pues, y le salvamos de la tribulación. Así es como salvamos a los creyentes.", "it": "Gli rispondemmo e lo salvammo dalla disperazione. Così salviamo coloro che credono.", "ar": "فاستجبنا له دعاءه، وخلَّصناه مِن غَم هذه الشدة، وكذلك ننجي المصدِّقين العاملين بشرعنا."}}, "21:107": {"s": 21, "v": 107, "nom": {"ar": "سُورَةُ الأَنبِيَاءِ", "lat": "Al-Anbiyaa"}, "ar": "وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةًۭ لِّلْعَٰلَمِينَ", "tl": {"en": "Wa maaa arsalnaaka illaa rahmatal lil'aalameen", "tr": "vemâ erselnâke illâ raḥmetel lil`âlemîn."}, "tr": {"fr": "Et Nous ne t'avons envoyé qu'en miséricorde pour l'univers.", "en": "And We have not sent you, [O Muhammad], except as a mercy to the worlds.", "id": "Dan tiadalah Kami mengutus kamu, melainkan untuk (menjadi) rahmat bagi semesta alam.", "tr": "Biz seni ancak alemlere rahmet olarak gönderdik.", "de": "Und Wir haben dich nur als Barmherzigkeit für die Weltenbewohner gesandt.", "nl": "En Wij hebben jou (O Moehammad) slechts gezonden als een barmhartigheid voor de werelden.", "es": "Nosotros no te hemos enviado sino como misericordia para todo el mundo.", "it": "Non ti mandammo se non come misericordia per il creato.", "ar": "وما أرسلناك - أيها الرسول - إلا رحمة لجميع الناس، فمن آمن بك سَعِد ونجا، ومن لم يؤمن خاب وخسر."}}, "22:27": {"s": 22, "v": 27, "nom": {"ar": "سُورَةُ الحَجِّ", "lat": "Al-Hajj"}, "ar": "وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًۭا وَعَلَىٰ كُلِّ ضَامِرٍۢ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍۢ", "tl": {"en": "Wa azzin fin naasi bil Hajji yaatooka rijaalanw wa 'alaa kulli daamiriny yaateena min kulli fajjin 'ameeq", "tr": "veeẕẕin fi-nnâsi bilḥacci ye'tûke ricâlev ve`alâ külli ḍâmiriy ye'tîne min külli feccin `amîḳ."}, "tr": {"fr": "Et fais aux gens une annonce pour le Hajj. Ils viendront vers toi, à pied, et aussi sur toute monture, venant de tout chemin éloigné,", "en": "And proclaim to the people the Hajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -", "id": "Dan berserulah kepada manusia untuk mengerjakan haji, niscaya mereka akan datang kepadamu dengan berjalan kaki, dan mengendarai unta yang kurus yang datang dari segenap penjuru yang jauh,", "tr": "İnsanları hacca çağır; yürüyerek veya binekler üstünde uzak yollardan sana gelsinler.", "de": "Und rufe unter den Menschen die Pilgerfahrt aus, so werden sie zu dir kommen zu Fuß und auf vielen hageren (Reittieren), die aus jedem tiefen Paßweg da herkommen,", "nl": "En verkondig onder de mensen de Haddj, zij zullen te voet naar jou komen of op magere kamelen, van elke vergelegen plek.", "es": "¡Llama a los hombres a la peregrinación para que vengan a ti a pie o en todo flaco camello, venido de todo paso ancho y profundo,", "it": "Chiama le genti al pellegrinaggio: verranno a te a piedi e con cammelli slanciati, da ogni remota contrada,", "ar": "وأعلِمْ- يا إبراهيم- الناس بوجوب الحج عليهم يأتوك على مختلف أحوالهم مشاةً وركبانًا على كل ضامر من الإبل، وهو: (الخفيف اللحم من السَّيْر والأعمال لا من الهُزال)، يأتين من كل طريق بعيد؛ ليحضروا منافع لهم من: مغفرة ذنوبهم، وثواب أداء نسكهم وطاعتهم، وتكَسُّبِهم في تجاراتهم، وغير ذلك؛ وليذكروا اسم الله على ذَبْح ما يتقربون به من الإبل والبقر والغنم في أيام معيَّنة هي: عاشر ذي الحجة وثلاثة أيام بعده؛ شكرًا لله على نعمه، وهم مأمورون أن يأكلوا مِن هذه الذبائح استحبابًا، ويُطعموا منها الفقير الذي اشتد فقره."}}, "25:74": {"s": 25, "v": 74, "nom": {"ar": "سُورَةُ الفُرۡقَانِ", "lat": "Al-Furqaan"}, "ar": "وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا", "tl": {"en": "Wallazeena yaqooloona Rabbanaa hab lanaa min azwaajinaa wa zurriyaatinaa qurrata a'yuninw waj 'alnaa lilmuttaqeena Imaamaa", "tr": "velleẕîne yeḳûlûne rabbenâ heb lenâ min ezvâcinâ veẕürriyyâtinâ ḳurrate a`yüniv vec`alnâ lilmütteḳîne imâmâ."}, "tr": {"fr": "et qui disent: «Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux».", "en": "And those who say, \"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous.\"", "id": "Dan orang orang yang berkata: \"Ya Tuhan kami, anugrahkanlah kepada kami isteri-isteri kami dan keturunan kami sebagai penyenang hati (kami), dan jadikanlah kami imam bagi orang-orang yang bertakwa.", "tr": "Onlar: \"Rabbimiz! Bize eşlerimizden ve çocuklarımızdan gözümüzün aydınlığı olacak insanlar ihsan et ve bizi, Allah'a karşı gelmekten sakınanlara önder yap\" derler.", "de": "Und diejenigen, die sagen: \"Unser Herr, schenke uns an unseren Gattinnen und unseren Nachkommenschaften Grund zur Freude, und mache uns für die Rechtschaffenen zu einem Vorbild.\"", "nl": "En (ook) degenen die zeggen: \"Onze Heer, voor ons onze echtgenotes en onze nakomelingen een verkoeling voor de ogen en maak ons leiders voor de Moettaqôen.", "es": "Dicen: «¡Señor! ¡Haznos el regalo de que nuestras esposas y descendencia sean nuestra alegría, haz que seamos modelo para los temerosos de Alá!»", "it": "e dicono: “Signore, dacci conforto nelle nostre spose e nei nostri figli e fai di noi una guida per i timorati [di Allah]”.", "ar": "والذين يسألون الله تعالى قائلين: ربنا هب لنا مِن أزواجنا وذريَّاتنا ما تَقَرُّ به أعيننا، وفيه أنسنا وسرورنا، واجعلنا قدوة يُقتدى بنا في الخير."}}, "26:63": {"s": 26, "v": 63, "nom": {"ar": "سُورَةُ الشُّعَرَاءِ", "lat": "Ash-Shu'araa"}, "ar": "فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍۢ كَٱلطَّوْدِ ٱلْعَظِيمِ", "tl": {"en": "Fa awhainaaa ilaa Moosaaa anidrib bi'asaakal bahra fanfalaqa fakaana kullu firqin kattawdil 'azeem", "tr": "feevḥaynâ ilâ mûsâ eni-ḍrib bi`aṣâke-lbaḥr. fenfeleḳa fekâne küllü firḳin keṭṭavdi-l`ażîm."}, "tr": {"fr": "Alors Nous révélâmes à Moïse: «Frappe la mer de ton bâton». Elle se fendit alors, et chaque versant fut comme une énorme montagne.", "en": "Then We inspired to Moses, \"Strike with your staff the sea,\" and it parted, and each portion was like a great towering mountain.", "id": "Lalu Kami wahyukan kepada Musa: \"Pukullah lautan itu dengan tongkatmu\". Maka terbelahlah lautan itu dan tiap-tiap belahan adalah seperti gunung yang besar.", "tr": "Bunun üzerine Biz Musa'ya: \"Değneğinle denize vur\" diye vahyettik. Hemen deniz ikiye ayrıldı, her parçası yüce bir dağ gibiydi.", "de": "Da gaben Wir Musa ein: \"Schlag mit deinem Stock auf das Meer.\"", "nl": "Toen openbaarden Wij aan Môesa: \"Sla de zee met jouw staf.\" Toen spleet de zee en elk gedeelte was als een geweldige berg.", "es": "E inspiramos a Moisés: «¡Golpea el mar con tu vara!» El mar, entonces, se partió y cada parte era como una imponente montaña.", "it": "Rivelammo a Mosè: “Colpisci il mare con il tuo bastone”. Subito si aprì e ogni parte [dell'acqua] fu come una montagna enorme.", "ar": "فأوحينا إلى موسى أن اضرب بعصاك البحر، فضرب، فانفلق البحر إلى اثني عشر طريقًا بعدد قبائل بني إسرائيل، فكانت كل قطعة انفصلت من البحر كالجبل العظيم."}}, "26:66": {"s": 26, "v": 66, "nom": {"ar": "سُورَةُ الشُّعَرَاءِ", "lat": "Ash-Shu'araa"}, "ar": "ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ", "tl": {"en": "Summa aghraqnal aakhareen", "tr": "ŝümme agraḳne-l'âḫarîn."}, "tr": {"fr": "ensuite Nous noyâmes les autres.", "en": "Then We drowned the others.", "id": "Dan Kami tenggelamkan golongan yang lain itu.", "tr": "Öbürlerini suda boğduk.", "de": "Hierauf ließen Wir die anderen ertrinken.", "nl": "Vervolgens verdronken Wij de anderen.", "es": "Luego, anegamos a los otros.", "it": "mentre annegammo gli altri.", "ar": "وقرَّبْنا هناك فرعون وقومه حتى دخلوا البحر، وأنجينا موسى ومَن معه أجمعين. فاستمر البحر على انفلاقه حتى عبروا إلى البر، ثم أغرقنا فرعون ومن معه بإطباق البحر عليهم بعد أن دخلوا فيه متبعين موسى وقومه."}}, "27:16": {"s": 27, "v": 16, "nom": {"ar": "سُورَةُ النَّمۡلِ", "lat": "An-Naml"}, "ar": "وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ ۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ", "tl": {"en": "Wa warisa Sulaimaanu Daawooda wa qaala yaaa aiyuhan naasu 'ullimnaa mantiqat tairi wa ooteenaa min kulli shai'in inna haazaa lahuwal fadlul mubeen", "tr": "veveriŝe süleymânü dâvûde veḳâle yâ eyyühe-nnâsü `ullimnâ menṭiḳa-ṭṭayri veûtînâ min külli şey'. inne hâẕâ lehüve-lfaḍlü-lmübîn."}, "tr": {"fr": "Et Salomon hérita de David et dit: «O hommes! On nous a appris le langage des oiseaux; et on nous a donné part de toutes choses. C'est là vraiment la grâce évidente.", "en": "And Solomon inherited David. He said, \"O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty.\"", "id": "Dan Sulaiman telah mewarisi Daud, dan dia berkata: \"Hai Manusia, kami telah diberi pengertian tentang suara burung dan kami diberi segala sesuatu. Sesungguhnya (semua) ini benar-benar suatu kurnia yang nyata\".", "tr": "Süleyman Davud'a varis oldu: \"Ey insanlar! Bize kuş dili öğretildi ve bize herşeyden bolca verildi. Doğrusu bu apaçık bir lütuftur\" dedi.", "de": "Und Sulaiman beerbte Dawud und sagte: \"O ihr Menschen, uns ist die Sprache der Vögel gelehrt worden, und uns wurde von allem gegeben. Das ist wahrlich die deutliche Huld.\"", "nl": "En Soelaimân volgde Dâwôed op. En hij zei: \"O mensen, aan ons is de taal van de vogels onderwezen, en ons is alles gegeven. Voorwaar, dit is zeker de duidelijke gunst.\"", "es": "Salomón heredó a David y dijo: «¡Hombres! Se nos ha enseñado el lenguaje de los pájaros y se nos ha dado de todo. ¡ Es un favor manifiesto!»", "it": "Salomone succedette a Davide e disse: “O uomini, ci è stato insegnato il linguaggio degli uccelli e ci è stata data abbondanza di ogni cosa: invero questa è grazia evidente!”.", "ar": "وورث سليمان أباه داود في النبوة والعلم والملك، وقال سليمان لقومه: يا أيها الناس عُلِّمنا وفُهِّمنا كلام الطير، وأُعطينا مِن كل شيء تدعو إليه الحاجة، إن هذا الذي أعطانا الله تعالى إياه لهو الفضل الواضح الذي يُمَيِّزنا على مَن سوانا."}}, "27:18": {"s": 27, "v": 18, "nom": {"ar": "سُورَةُ النَّمۡلِ", "lat": "An-Naml"}, "ar": "حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌۭ يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ", "tl": {"en": "hattaaa izaaa ataw 'alaa waadin namli qaalat namlatuny yaaa aiyuhan namlud khuloo masaakinakum laa yahtimannakum Sulaimaanu wa junooduhoo wa hum laa yash'uroon", "tr": "ḥattâ iẕâ etev `alâ vâdi-nnemli ḳâlet nemletüy yâ eyyühe-nnemlü-dḫulû mesâkineküm. lâ yaḥṭimenneküm süleymânü vecünûdühû vehüm lâ yeş`urûn."}, "tr": {"fr": "Quand ils arrivèrent à la Vallée des Fourmis, une fourmi dit: «O fourmis, entrez dans vos demeures, [de peur] que Salomon et ses armées ne vous écrasent [sous leurs pieds] sans s'en rendre compte».", "en": "Until, when they came upon the valley of the ants, an ant said, \"O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not.\"", "id": "Hingga apabila mereka sampai di lembah semut berkatalah seekor semut: Hai semut-semut, masuklah ke dalam sarang-sarangmu, agar kamu tidak diinjak oleh Sulaiman dan tentaranya, sedangkan mereka tidak menyadari\";", "tr": "Sonunda, karıncaların bulunduğu vadiye geldiklerinde bir dişi (kraliçe) karınca: \"Ey karıncalar! Yuvalarınıza girin, Süleyman'ın ordusu farkına varmadan sizi ezmesin\" dedi.", "de": "Als sie dann zum Ameisental kamen, sagte eine Ameise: \"O ihr Ameisen, geht in eure Wohnungen hinein, damit euch ja nicht Sulaiman und seine Heerscharen niederwalzen, ohne daß sie merken.\"", "nl": "Totdat zij langs de vallei van de mieren kwamen, en een mier zei: \"O jullie mieren, gaat jullie woningen binnen, anders zullen Soelaimân en zijn troepen jullie vertrappen, zonder dat zij het beseffen!\"", "es": "Hasta que, llegados al Valle de las Hormigas, una hormiga dijo: «¡Hormigas! ¡Entrad en vuestras viviendas, no sea que Salomón y sus tropas os aplasten sin darse cuenta!»", "it": "Quando giunsero alla valle delle formiche, una formica disse: “O formiche, rientrate nelle vostre dimore, che non vi schiaccino inavvertitamente Salomone e le sue truppe”.", "ar": "حتى إذا بلغوا وادي النمل قالت نملة: يا أيها النمل ادخلوا مساكنكم لا يهلكنَّكم سليمان وجنوده، وهم لا يعلمون بذلك. فتبسم ضاحكًا من قول هذه النملة لفهمها واهتدائها إلى تحذير النمل، واستشعر نعمة الله عليه، فتوجَّه إليه داعيًا: ربِّ ألْهِمْني، ووفقني، أن أشكر نعمتك التي أنعمت عليَّ وعلى والديَّ، وأن أعمل عملا صالحًا ترضاه مني، وأدخلني برحمتك في نعيم جنتك مع عبادك الصالحين الذين ارتضيت أعمالهم."}}, "28:7": {"s": 28, "v": 7, "nom": {"ar": "سُورَةُ القَصَصِ", "lat": "Al-Qasas"}, "ar": "وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ ۖ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ", "tl": {"en": "Wa awhainaaa ilaaa ummi Moosaaa an ardi'eehi faizaa khifti 'alaihi fa alqeehi filyammi wa laa takhaafee wa laa tahzaneee innaa raaaddoohu ilaiki wa jaa'iloohu minal mursaleen", "tr": "veevḥaynâ ilâ ümmi mûsâ en arḍi`îh. feiẕâ ḫifti `aleyhi feelḳîhi fi-lyemmi velâ teḫâfî velâ taḥzenî. innâ râddûhü ileyki vecâ`ilûhü mine-lmürselîn."}, "tr": {"fr": "Et Nous révélâmes à la mère de Moïse [ceci]: «Allaite-le. Et quand tu craindras pour lui, jette-le dans le flot. Et n'aie pas peur et ne t'attriste pas: Nous te le rendrons et ferons de lui un Messager».", "en": "And We inspired to the mother of Moses, \"Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers.\"", "id": "Dan kami ilhamkan kepada ibu Musa; \"Susuilah dia, dan apabila kamu khawatir terhadapnya maka jatuhkanlah dia ke sungai (Nil). Dan janganlah kamu khawatir dan janganlah (pula) bersedih hati, karena sesungguhnya Kami akan mengembalikannya kepadamu, dan menjadikannya (salah seorang) dari para rasul.", "tr": "Musa'nın annesine: \"Çocuğu emzir, başına gelecekten korktuğun zaman onu suya bırak; korkma, üzülme; Biz şüphesiz onu sana döndüreceğiz ve peygamber yapacağız\" diye bildirmiştik.", "de": "Und Wir gaben der Mutter Musas ein: \"Stille ihn. Und wenn du um ihn fürchtest, dann setze ihn in das Wasser und fürchte dich nicht und sei nicht traurig. Wir werden ihn dir zurückbringen und ihn zu einem der Gesandten machen.\"", "nl": "En Wij inspireerden aan de moeder van Môesa: \"Zoog hem\", maar als jij voor hem vreest, werp hem dan in de rivier, en vrees niet en treur niet: voorwaar, Wij zullen hem bij jou terugbrengen en hem tot één van de Boodschappers maken.", "es": "Inspiramos a la madre de Moisés: «Dale de mamar y, en caso de peligro, ponlo en el río! ¡No temas por él, no estés triste! Te lo devolveremos y haremos de él un enviado».", "it": "Rivelammo alla madre di Mosè: “Allattalo e, quando temerai per lui, gettalo nel fiume e non temere e non essere afflitta: Noi te lo restituiremo e faremo di lui uno degli Inviati”.", "ar": "وألْهمنا أم موسى حين ولدته وخشيت عليه أن يذبحه فرعون كما يذبح أبناء بني إسرائيل: أن أرضعيه مطمئنة، فإذا خشيت أن يُعرف أمره فضعيه في صندوق وألقيه في النيل، دون خوف من فرعون وقومه أن يقتلوه، ودون حزن على فراقه، إنا رادُّو ولدك إليك وباعثوه رسولا. فوضعته في صندوق وألقته في النيل، فعثر عليه أعوان فرعون وأخذوه، فكانت عاقبةُ ذلك أن جعله الله لهم عدوًّا وحزنًا، فكان إهلاكُهم على يده. إن فرعون وهامان وأعوانهما كانوا آثمين مشركين."}}, "28:8": {"s": 28, "v": 8, "nom": {"ar": "سُورَةُ القَصَصِ", "lat": "Al-Qasas"}, "ar": "فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّۭا وَحَزَنًا ۗ إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا۟ خَٰطِـِٔينَ", "tl": {"en": "Faltaqatahooo Aalu Fir'awna li yakoona lahum 'aduwwanw wa hazanaa; inna Fir'awna wa Haamaana wa junooda humaa kaanoo khaati'een", "tr": "felteḳaṭahû âlü fir`avne liyekûne lehüm `adüvvev veḥazenâ. inne fir`avne vehâmâne vecünûdehümâ kânû ḫâṭiîn."}, "tr": {"fr": "Les gens de Pharaon le recueillirent, pour qu'il leur soit un ennemi et une source d'affliction! Pharaon, Hâmân et leurs soldats étaient fautifs.", "en": "And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners.", "id": "Maka dipungutlah ia oleh keluarga Fir'aun yang akibatnya dia menjadi musuh dan kesedihan bagi mereka. Sesungguhnya Fir'aun dan Haman beserta tentaranya adalah orang-orang yang bersalah.", "tr": "Firavun'un adamları onu almışlardı. Firavun, Haman ve askerleri, suçlu olduklarından, o onlara düşman ve başlarına da dert olacaktı.", "de": "Da lasen ihn die Angehörigen Fir'auns auf, damit er ihnen zum Feind und (Grund zum) Kummer werde. Gewiß, Fir'aun, Haman und deren Heerscharen pflegten verfehlt zu handeln.", "nl": "Toen pikten de mensen van Fir'aun hem op (uit de rivier), zodat hij een vijand van hen zou worden en een bron van droefenis. Voorwaar, Fir'aun, Hâmân en hun legers waren zondaren.", "es": "Lo recogió la familia de Faraón, para terminar siendo para ellos enemigo y causa de tristeza. Faraón, Hamán y sus ejércitos eran pecadores.", "it": "Lo raccolse la gente di Faraone, sì che potesse diventare loro nemico e causa di tristezza. Davvero Faraone e Hâmân e le loro armate erano colpevoli.", "ar": "وألْهمنا أم موسى حين ولدته وخشيت عليه أن يذبحه فرعون كما يذبح أبناء بني إسرائيل: أن أرضعيه مطمئنة، فإذا خشيت أن يُعرف أمره فضعيه في صندوق وألقيه في النيل، دون خوف من فرعون وقومه أن يقتلوه، ودون حزن على فراقه، إنا رادُّو ولدك إليك وباعثوه رسولا. فوضعته في صندوق وألقته في النيل، فعثر عليه أعوان فرعون وأخذوه، فكانت عاقبةُ ذلك أن جعله الله لهم عدوًّا وحزنًا، فكان إهلاكُهم على يده. إن فرعون وهامان وأعوانهما كانوا آثمين مشركين."}}, "29:14": {"s": 29, "v": 14, "nom": {"ar": "سُورَةُ العَنكَبُوتِ", "lat": "Al-Ankaboot"}, "ar": "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًۭا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ", "tl": {"en": "Wa laqad arsalnaa Noohan ilaa qawmihee falabisa feehim alfa sanatin illaa khamseena 'aaman fa akhazahumut toofaanu wa hum zaalimoon", "tr": "veleḳad erselnâ nûḥan ilâ ḳavmihî felebiŝe fîhim elfe senetin illâ ḫamsîne `âmâ. feeḫaẕehümu-ṭṭûfânü vehüm żâlimûn."}, "tr": {"fr": "Et en effet, Nous avons envoyé Noé vers son peuple. Il demeura parmi eux mille ans moins cinquante années. Puis le déluge les emporta alors qu'ils étaient injustes.", "en": "And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.", "id": "Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, maka ia tinggal di antara mereka seribu tahun kurang lima puluh tahun. Maka mereka ditimpa banjir besar, dan mereka adalah orang-orang yang zalim.", "tr": "And olsun ki, Nuh'u milletine gönderdik; aralarında bin seneden elli yıl eksik kaldı. Sonunda onlar haksızlık yaparken, tufan onları yakalayıverdi.", "de": "Und Wir sandten bereits Nuh zu seinem Volk. Er verweilte unter ihnen tausend Jahre weniger fünfzig Jahre. Da ergriff sie die Überschwemmung, während sie Unrecht taten.", "nl": "En voorzeker, Wij hebben Nôeh tot zijn volk gezonden en hij verbleef duizend jaar bij hen, op vijftig jaar na. Toen overviel de zondvloed hen, terwijl zij onrechtvaardigen waren.", "es": "Enviamos Noé a su pueblo y permaneció con él durante mil años menos cincuenta. Luego, el diluvio les sorprendió en su impiedad.", "it": "Già inviammo Noè al suo popolo; rimase con loro mille anni meno cinquant'anni. Li colpì poi il Diluvio perché erano ingiusti.", "ar": "ولقد أرسلنا نوحًا إلى قومه فمكث فيهم ألف سنة إلا خمسين عامًا، يدعوهم إلى التوحيد وينهاهم عن الشرك، فلم يستجيبوا له، فأهلكهم الله بالطوفان، وهم ظالمون لأنفسهم بكفرهم وطغيانهم."}}, "31:14": {"s": 31, "v": 14, "nom": {"ar": "سُورَةُ لُقۡمَانَ", "lat": "Luqman"}, "ar": "وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ", "tl": {"en": "Wa wassainal bi waalidaihi hamalat hu ummuhoo wahnan 'alaa wahninw wa fisaaluhoo fee 'aamaini anishkur lee wa liwaalidaika ilaiyal maseer", "tr": "veveṣṣayne-l'insâne bivâlideyh. ḥamelethü ümmühû vehnen `alâ vehniv vefiṣâlühû fî `âmeyni eni-şkür lî velivâlideyk. ileyye-lmeṣîr."}, "tr": {"fr": "Nous avons commandé à l'homme [la bienfaisance envers] ses père et mère; sa mère l'a porté [subissant pour lui] peine sur peine: son sevrage a lieu à deux ans. «Sois reconnaissant envers Moi ainsi qu'envers tes parents. Vers Moi est la destination.", "en": "And We have enjoined upon man [care] for his parents. His mother carried him, [increasing her] in weakness upon weakness, and his weaning is in two years. Be grateful to Me and to your parents; to Me is the [final] destination.", "id": "Dan Kami perintahkan kepada manusia (berbuat baik) kepada dua orang ibu-bapaknya; ibunya telah mengandungnya dalam keadaan lemah yang bertambah-tambah, dan menyapihnya dalam dua tahun. Bersyukurlah kepada-Ku dan kepada dua orang ibu bapakmu, hanya kepada-Kulah kembalimu.", "tr": "Biz insana, ana ve babasına karşı iyi davranmasını tavsiye etmişizdir. Annesi onu, güçsüzlükten güçsüzlüğe uğrayarak karnında taşımıştı. Çocuğun sütten kesilmesi iki yıl içinde olur. Bana ve ana babana şükret diye tavsiyede bulunmuşuzdur. Dönüş Bana'dır.", "de": "Und Wir haben dem Menschen seine Eltern anbefohlen - seine Mutter hat ihn unter wiederholter Schwäche getragen, und seine Entwöhnung (erfolgt) innerhalb von zwei Jahren -: \"Sei Mir und deinen Eltern dankbar. Zu Mir ist der Ausgang.\"", "nl": "En Wij bevolen de mens (goedheid) jegens zijn ouders. Zijn moeder droeg heen in zwakheid op zwakheid, en het zogen van hem duurde twee jaren. Wees daarom Mij en jouw ouders dankbaar. Tot Mij is de terugkeer.", "es": "Hemos ordenado al hombre con respecto a sus padres -su madre le llevó sufriendo pena tras pena y le destetó a los dos años-: «Sé agradecido conmigo y con tus padres. ¡Soy Yo el fin de todo!", "it": "Abbiamo imposto all'uomo di trattare bene i suoi genitori: lo portò sua madre di travaglio in travaglio e lo svezzò dopo due anni: “Sii riconoscente a Me e ai tuoi genitori. Il destino ultimo è verso di Me.", "ar": "وأَمَرْنا الإنسان ببرِّ والديه والإحسان إليهما، حَمَلَتْه أمه ضعفًا على ضعف، وحمله وفِطامه عن الرضاعة في مدة عامين، وقلنا له: اشكر لله، ثم اشكر لوالديك، إليَّ المرجع فأُجازي كُلا بما يستحق."}}, "31:15": {"s": 31, "v": 15, "nom": {"ar": "سُورَةُ لُقۡمَانَ", "lat": "Luqman"}, "ar": "وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌۭ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًۭا ۖ وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ۚ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", "tl": {"en": "Wa in jaahadaaka 'alaaa an tushrika bee maa laisa laka bihee 'ilmun falaa tuti'humaa wa saahib humaa fid dunyaa ma'roofanw wattabi' sabeela man anaaba ilayy; summa ilaiya marji'ukum fa unabbi'ukum bimaa kuntum ta'maloon", "tr": "vein câhedâke `alâ en tüşrike bî mâ leyse leke bihî `ilmün felâ tüṭi`hümâ veṣâḥibhümâ fi-ddünyâ ma`rûfâ. vettebi` sebîle men enâbe ileyy. ŝümme ileyye merci`uküm feünebbiüküm bimâ küntüm ta`melûn."}, "tr": {"fr": "Et si tous deux te forcent à M'associer ce dont tu n'as aucune connaissance, alors ne leur obéis pas; mais reste avec eux ici-bas de façon convenable. Et suis le sentier de celui qui se tourne vers Moi. Vers Moi, ensuite, est votre retour, et alors Je vous informerai de ce que vous faisiez».", "en": "But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them but accompany them in [this] world with appropriate kindness and follow the way of those who turn back to Me [in repentance]. Then to Me will be your return, and I will inform you about what you used to do.", "id": "Dan jika keduanya memaksamu untuk mempersekutukan dengan Aku sesuatu yang tidak ada pengetahuanmu tentang itu, maka janganlah kamu mengikuti keduanya, dan pergaulilah keduanya di dunia dengan baik, dan ikutilah jalan orang yang kembali kepada-Ku, kemudian hanya kepada-Kulah kembalimu, maka Kuberitakan kepadamu apa yang telah kamu kerjakan.", "tr": "Ey insanoğlu! Ana baba, seni, körü körüne Bana ortak koşman için zorlarlarsa, onlara itaat etme; dünya işlerinde onlarla güzel geçin; Bana yönelen kimsenin yoluna uy; sonunda dönüşünüz Bana'dır. O zaman, yaptıklarınızı size bildiririm.", "de": "Wenn sie sich aber darum bemühen, daß du Mir das beigesellst, wovon du kein Wissen hast, dann gehorche ihnen nicht, doch geh mit ihnen im Diesseits in rechtli cher Weise um. Und folge dem Weg dessen, der sich Mir reuig zuwendet. Zu Mir wird hierauf eure Rückkehr sein, da werde Ich euch kundtun, was ihr zu tun pflegtet.", "nl": "En als zij jou dwingen dat jij iets aan Mij toekent, zonder dat jij er kennis over hebt: gehoorzam ham dan niet. En vergezel hen vriendelijk op de wereld. En volg de Weg van degenen die zich tot Mij hebben gewend. Daarna is tot Mij jullie terugkeer. Dan zal Ik jullie op de hoogte brengen van wat jullie plachten te doen.", "es": "Pero, si te insisten en que Me asocies aquello de que no tienes conocimiento, ¡no les obedezcas! En la vida de acá ¡pórtate amablemente con ellos! ¡Sigue el camino de quien vuelve a Mí arrepentido! Luego, volveréis a Mí y ya os informaré de lo que hacíais».", "it": "E se entrambi ti obbligassero ad associarMi ciò di cui non hai conoscenza alcuna, non obbedire loro, ma sii comunque cortese con loro in questa vita e segui la via di chi si rivolge a Me. Poi a Me farete ritorno e vi informerò su quello che avrete fatto”.", "ar": "وإن جاهدك- أيها الولد المؤمن- والداك على أن تشرك بي غيري في عبادتك إياي مما ليس لك به عِلم، أو أمراك بمعصية مِن معاصي الله فلا تطعهما؛ لأنه لا طاعة لمخلوق في معصية الخالق، وصاحبهما في الدنيا بالمعروف فيما لا إثم فيه، واسلك- أيها الابن المؤمن- طريق مَن تاب من ذنبه، ورجع إليَّ وآمن برسولي محمد صلى الله عليه وسلم، ثم إليَّ مرجعكم، فأخبركم بما كنتم تعملونه في الدنيا، وأجازي كلَّ عامل بعمله."}}, "32:11": {"s": 32, "v": 11, "nom": {"ar": "سُورَةُ السَّجۡدَةِ", "lat": "As-Sajda"}, "ar": "۞ قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ", "tl": {"en": "Qul yatawaffaakum malakul mawtil lazee wukkila bikum Thumma ilaa rabbikum turja'oon", "tr": "ḳul yeteveffâküm melekü-lmevti-lleẕî vukkile biküm ŝümme ilâ rabbiküm türce`ûn."}, "tr": {"fr": "Dis: «L'Ange de la mort qui est chargé de vous, vous fera mourir. Ensuite, vous serez ramenés vers Votre Seigneur».", "en": "Say, \"The angel of death will take you who has been entrusted with you. Then to your Lord you will be returned.\"", "id": "Katakanlah: \"Malaikat maut yang diserahi untuk (mencabut nyawa)mu akan mematikanmu, kemudian hanya kepada Tuhanmulah kamu akan dikembalikan\".", "tr": "De ki: \"Size vekil kılınan ölüm meleği canınızı alacak, sonra Rabbinize döndürüleceksiniz.\"", "de": "Sag: Abberufen wird euch der Engel des Todes, der mit euch betraut ist, hierauf werdet ihr zu eurem Herrn zurückgebracht.", "nl": "Zeg (O Moehammad): \"De Engel des doods die over jullie is aangesteld, zal jullie wegnemen. Vervolgens worden jullie tot jullie Heer teruggekeerd.\"", "es": "Di: «El ángel de la muerte, encargado de vosotros, os llamara y, luego, seréis devueltos a vuestro Señor».", "it": "Di': “L'angelo della morte che si occuperà di voi, vi farà morire e poi sarete ricondotti al vostro Signore”.", "ar": "قل -أيها الرسول- لهؤلاء المشركين: يتوفاكم ملك الموت الذي وُكِّل بكم، فيقبض أرواحكم إذا انتهت آجالكم، ولن تتأخروا لحظة واحدة، ثم تُردُّون إلى ربكم، فيجازيكم على جميع أعمالكم: إن خيرًا فخير وإن شرًا فشر."}}, "33:13": {"s": 33, "v": 13, "nom": {"ar": "سُورَةُ الأَحۡزَابِ", "lat": "Al-Ahzaab"}, "ar": "وَإِذْ قَالَت طَّآئِفَةٌۭ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ ۚ وَيَسْتَـْٔذِنُ فَرِيقٌۭ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌۭ وَمَا هِىَ بِعَوْرَةٍ ۖ إِن يُرِيدُونَ إِلَّا فِرَارًۭا", "tl": {"en": "Wa iz qaalat taaa'ifatum minhum yaaa ahla Yasriba laa muqaamaa lakum farji'oo; wa yastaazina fareequm minhumun Nabiyya yaqooloona inna buyootanaa 'awrah; wa maa hiya bi'awratin iny yureedoona illaa firaaraa", "tr": "veiẕ ḳâleṭ ṭâifetüm minhüm yâ ehle yeŝribe lâ müḳâme leküm ferci`û. veyeste'ẕinü ferîḳum minhümü-nnebiyye yeḳûlûne inne büyûtenâ `avratüv vemâ hiye bi`avrah. iy yürîdûne illâ firârâ."}, "tr": {"fr": "De même, un groupe d'entre eux dit: «Gens de Yathrib! Ne demeurez pas ici. Retournez [chez vous]». Un groupe d'entre eux demande au Prophète la permission de partir en disant: «Nos demeures sont sans protection», alors qu'elles ne l'étaient pas: ils ne voulaient que s'enfuir.", "en": "And when a faction of them said, \"O people of Yathrib, there is no stability for you [here], so return [home].\" And a party of them asked permission of the Prophet, saying, \"Indeed, our houses are unprotected,\" while they were not exposed. They did not intend except to flee.", "id": "Dan (ingatlah) ketika segolongan di antara mreka berkata: \"Hai penduduk Yatsrib (Madinah), tidak ada tempat bagimu, maka kembalilah kamu\". Dan sebahagian dari mereka minta izin kepada Nabi (untuk kembali pulang) dengan berkata: \"Sesungguhnya rumah-rumah kami terbuka (tidak ada penjaga)\". Dan rumah-rumah itu sekali-kali tidak terbuka, mereka tidak lain hanya hendak lari.", "tr": "İçlerinden bir takımı: \"Ey Medineliler! Tutunacak yeriniz yok, geri dönün\" demişti. İçlerinden bir topluluk da Peygamberden: \"Evlerimiz düşmana açıktır\" diyerek izin istemişlerdi. Oysa evleri açık değildi sadece kaçmak istiyorlardı.", "de": "Und als eine Gruppe von ihnen sagte: \"O ihr Leute von Yatrib, ihr könnt euch (hier) nicht aufhalten. Kehrt zurück.\" Und ein Teil von ihnen bat den Propheten um Erlaubnis, (heimzukehren,) indem sie sagten: \"Unsere Häuser sind ohne Schutz.\" Dabei waren sie nicht ohne Schutz, sie wollten nur fliehen.", "nl": "En (gedenk) toen een groep van hen zei: \"O bewoners van Yatsrib (Medinah), er is geen plaats voor jullie. gaat daarom terug.\" En een groep onder hen vroeg (de Profeet) ontheffing, zeggend: \"Voorwaar, onze huizen zijn onbeschermd,\" terwijl deze niet onbeschermd waren, zij wilden alleen maar vluchten.", "es": "Y cuando un grupo de ellos dijo: «¡Gente de Yatrib! ¡No os quedéis aquí! ¡Regresad!» Parte de ellos pidió autorización al Profeta, diciendo: «¡Nuestras casas están indefensas!» En realidad, no es que sus casa estuvieran indefensas, lo que querían era huir.", "it": "E un gruppo di loro disse: “Gente di Yatrib! Non potrete resistere, desistete”, cosicché una parte di loro chiese al Profeta di poter andar via dicendo: “Le nostre case sono indifese”, mentre non lo erano; volevano solo fuggire.", "ar": "واذكر -أيها النبي- قول طائفة من المنافقين منادين المؤمنين من أهل \"المدينة\": يا أهل \"يثرب\"(وهو الاسم القديم \"للمدينة\") لا إقامة لكم في معركة خاسرة، فارجعوا إلى منازلكم داخل \"المدينة\"، ويستأذن فريق آخر من المنافقين الرسول صلى الله عليه وسلم بالعودة إلى منازلهم بحجة أنها غير محصنة، فيخشون عليها، والحق أنها ليست كذلك، وما قصدوا بذلك إلا الفرار من القتال."}}, "33:40": {"s": 33, "v": 40, "nom": {"ar": "سُورَةُ الأَحۡزَابِ", "lat": "Al-Ahzaab"}, "ar": "مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍۢ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۦنَ ۗ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًۭا", "tl": {"en": "Maa kaana Muhammmadun abaaa ahadim mir rijaalikum wa laakir Rasoolal laahi wa Khaataman Nabiyyeen; wa kaanal laahu bikulli shai'in 'Aleema", "tr": "mâ kâne müḥammedün ebâ eḥadim mir ricâliküm velâkir rasûle-llâhi veḫâteme-nnebiyyîn. vekâne-llâhü bikülli şey'in `alîmâ."}, "tr": {"fr": "Muhammad n'a jamais été le père de l'un de vos hommes, mais le messager d'Allah et le dernier des prophètes. Allah est Omniscient.", "en": "Muhammad is not the father of [any] one of your men, but [he is] the Messenger of Allah and last of the prophets. And ever is Allah, of all things, Knowing.", "id": "Muhammad itu sekali-kali bukanlah bapak dari seorang laki-laki di antara kamu, tetapi dia adalah Rasulullah dan penutup nabi-nabi. Dan adalah Allah Maha Mengetahui segala sesuatu.", "tr": "Muhammed içinizden herhangi bir adamın babası değil, Allah'ın elçisi ve peygamberlerin sonuncusudur. Allah her şeyi bilendir.", "de": "Muhammad ist nicht der Vater irgend jemandes von euren Männern, sondern Allahs Gesandter und das Siegel der Propheten. Und Allah weiß über alles Bescheid.", "nl": "Moehammad is niet de vader van één van jullie mannen, maar hij is de Boodschapper van Allah en de laatste van de Profeten. En Allah is Alwetend over alle zaken.", "es": "Mahoma no es el padre de ninguno de vuestros varones, sino el Enviado de Alá y el sello de los profetas. Alá es omnisciente.", "it": "Muhammad non è padre di nessuno dei vostri uomini, egli è l'Inviato di Allah e il sigillo dei profeti. Allah conosce ogni cosa.", "ar": "ما كان محمد أبًا لأحد من رجالكم، ولكنه رسول الله وخاتم النبيين، فلا نبوة بعده إلى يوم القيامة. وكان الله بكل شيء من أعمالكم عليمًا، لا يخفى عليه شيء."}}, "33:70": {"s": 33, "v": 70, "nom": {"ar": "سُورَةُ الأَحۡزَابِ", "lat": "Al-Ahzaab"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًۭا سَدِيدًۭا", "tl": {"en": "Yaaa aiyuhal lazeena aamanut taqul laaha wa qooloo qawlan sadeedaa", "tr": "yâ eyyühe-lleẕîne âmenü-tteḳu-llâhe veḳûlû ḳavlen sedîdâ."}, "tr": {"fr": "O vous qui croyez! Craignez Allah et parlez avec droiture,", "en": "O you who have believed, fear Allah and speak words of appropriate justice.", "id": "Hai orang-orang yang beriman, bertakwalah kamu kepada Allah dan katakanlah perkataan yang benar,", "tr": "Ey inananlar! Allah'tan sakının, dürüst söz söyleyin de Allah işlerinizi kendinize yararlı kılsın ve günahlarınızı size bağışlasın. Kim Allah'a ve Peygamber'ine itaat ederse, şüphesiz büyük bir kurtuluşa ermiş olur.", "de": "O die ihr glaubt, fürchtet Allah und sagt treffende Worte,", "nl": "O jullie die geloven, vreest Allah en spreekt het ware woord.", "es": "¡Creyentes! ¡Temed a Alá y no digáis despropósitos,", "it": "O credenti, temete Allah e parlate onestamente,", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، اعملوا بطاعته، واجتنبوا معصيته؛ لئلا تستحقوا بذلك العقاب، وقولوا في جميع أحوالكم وشؤونكم قولا مستقيمًا موافقًا للصواب خاليًا من الكذب والباطل."}}, "35:1": {"s": 35, "v": 1, "nom": {"ar": "سُورَةُ فَاطِرٍ", "lat": "Faatir"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍۢ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۚ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ", "tl": {"en": "Alhamdu lillaahi faatiris samaawaati wal ardi jaa'ilil malaaa'ikati rusulan uleee ajnihatim masnaa wa sulaasa wa rubaa'; yazeedu fil khalqi maa yashaaa'; innal laaha 'alaa kulli shai'in Qadeer", "tr": "elḥamdü lillâhi fâṭiri-ssemâvâti vel'arḍi câ`ili-lmelâiketi rusülen ülî ecniḥatim meŝnâ veŝülâŝe verubâ`. yezîdü fi-lḫalḳi mâ yeşâ'. inne-llâhe `alâ külli şey'in ḳadîr."}, "tr": {"fr": "Louange à Allah, Créateur des cieux et de la terre, qui a fait des Anges des messagers dotés de deux, trois ou quatre ailes. Il ajoute à la création ce qu'Il veut, car Allah est Omnipotent.", "en": "[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent.", "id": "Segala puji bagi Allah Pencipta langit dan bumi, Yang menjadikan malaikat sebagai utusan-utusan (untuk mengurus berbagai macam urusan) yang mempunyai sayap, masing-masing (ada yang) dua, tiga dan empat. Allah menambahkan pada ciptaan-Nya apa yang dikehendaki-Nya. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "tr": "Hamd, gökleri ve yeri yaratan, melekleri ikişer, üçer, dörder kanatlı elçiler kılan Allah'a mahsustur. Yaratmada dilediğini artırır. Doğrusu Allah, her şeye Kadir olandır.", "de": "(Alles) Lob gehört Allah, dem Erschaffer der Himmel und der Erde, Der die Engel zu Gesandten gemacht hat mit Flügeln, (je) zwei, drei und vier! Er fügt der Schöpfung hinzu, was Er will. Gewiß, Allah hat zu allem die Macht.", "nl": "Alle tof zij Allah, de Schepper van de hemelen en de aarde. Hij heeft de Engelen tot gezanten gemaakt, met twee, drie of vier vleugels. Hij voegt aan de schepping toe wat Hij wil. Voorwaar, Allah is Almachtig over alle zaken.", "es": "¡Alabado sea Alá, creador de los cielos y de la tierra, Que de los ángeles ha hecho enviados de dos, tres o cuatro alas! Añade a la creación lo que Él quiere. Alá es omnipotente.", "it": "Lode ad Allah, Creatore dei cieli e della terra, che ha fatto degli angeli, messaggeri dotati di due, tre o quattro ali. Egli aggiunge alla creazione quello che vuole. In verità Allah è onnipotente.", "ar": "الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، خالق السماوات والأرض ومبدعهما، جاعل الملائكة رسلا إلى مَن يشاء من عباده، وفيما شاء من أمره ونهيه، ومِن عظيم قدرة الله أن جعل الملائكة أصحاب أجنحة مثنى وثلاث ورباع تطير بها؛ لتبليغ ما أمر الله به، يزيد الله في خلقه ما يشاء. إن الله على كل شيء قدير، لا يستعصي عليه شيء."}}, "36:78": {"s": 36, "v": 78, "nom": {"ar": "سُورَةُ يسٓ", "lat": "Yaseen"}, "ar": "وَضَرَبَ لَنَا مَثَلًۭا وَنَسِىَ خَلْقَهُۥ ۖ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌۭ", "tl": {"en": "Wa daraba lanaa maslanw-wa nasiya khalqahoo qaala mai-yuhyil'izaama wa hiya rameem", "tr": "veḍarabe lenâ meŝelev venesiye ḫalḳah. ḳâle mey yuḥyi-l`iżâme vehiye ramîm."}, "tr": {"fr": "Il cite pour Nous un exemple, tandis qu'il oublie sa propre création; il dit: «Qui va redonner la vie à des ossements une fois réduits en poussière?»", "en": "And he presents for Us an example and forgets his [own] creation. He says, \"Who will give life to bones while they are disintegrated?\"", "id": "Dan ia membuat perumpamaan bagi Kami; dan dia lupa kepada kejadiannya; ia berkata: \"Siapakah yang dapat menghidupkan tulang belulang, yang telah hancur luluh?\"", "tr": "İnsan kendisini bir nutfeden yarattığımızı görmez mi ki hemen apaçık bir hasım kesilir ve kendi yaratılışını unutur da; \"Çürümüş kemikleri kim yaratacak\" diyerek, Bize misal vermeye kalkar?", "de": "Er führt Uns ein Beispiel an und vergißt seine (eigene) Erschaffung. Er sagt: \"Wer macht die Knochen wieder lebendig, wenn sie zerfallen sind?\"", "nl": "En hij geeft Ons een voorbeeld, terwijl hij vergeet hoe hij zelf geschapen is. Hij zei: \"Wie doet de beenderen tot leven komen, terwijl ze gruis zijn?\"", "es": "Nos propone una parábola y se olvida de su propia creación. Dice: «¿Quién dará vida a los huesos, estando podridos?»", "it": "Ci propone un luogo comune e, dimentico della sua creazione, [dice]: “Chi ridarà la vita ad ossa polverizzate?”.", "ar": "وضرب لنا المنكر للبعث مثلا لا ينبغي ضربه، وهو قياس قدرة الخالق بقدرة المخلوق، ونسي ابتداء خلقه، قال: مَن يحيي العظام البالية المتفتتة؟"}}, "36:79": {"s": 36, "v": 79, "nom": {"ar": "سُورَةُ يسٓ", "lat": "Yaseen"}, "ar": "قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍۢ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ", "tl": {"en": "Qul yuh yeehal lazeee ansha ahaaa awwala marrah; wa Huwa bikulli khalqin 'Aleem", "tr": "ḳul yuḥyîhe-lleẕî enşeehâ evvele merrah. vehüve bikülli ḫalḳin `alîm."}, "tr": {"fr": "Dis: «Celui qui les a créés une première fois, leur redonnera la vie. Il Se connaît parfaitement à toute création.", "en": "Say, \"He will give them life who produced them the first time; and He is, of all creation, Knowing.\"", "id": "Katakanlah: \"Ia akan dihidupkan oleh Tuhan yang menciptakannya kali yang pertama. Dan Dia Maha Mengetahui tentang segala makhluk.", "tr": "De ki: \"Onları ilk defa yaratan diriltecektir. O, her türlü yaratmayı bilendir.\"", "de": "Sag: Wieder lebendig macht sie Derjenige, Der sie das erste Mal hat entstehen lassen. Und Er weiß über jede Schöpfung Bescheid,", "nl": "Zeg: \"Hij Die ze de eerste keer heeft doen ontstaan, Die zal ze doen leven. En Hij is de Kenner van de gehele schepping.", "es": "Di: «Les dará vida Quien los creó una vez primera -Él conoce bien toda creación-,", "it": "Di': “Colui Che le ha create la prima volta ridarà loro la vita. Egli conosce perfettamente ogni creazione.", "ar": "قل له: يحييها الذي خلقها أول مرة، وهو بجميع خلقه عليم، لا يخفى عليه شيء."}}, "37:107": {"s": 37, "v": 107, "nom": {"ar": "سُورَةُ الصَّافَّاتِ", "lat": "As-Saaffaat"}, "ar": "وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍۢ", "tl": {"en": "Wa fadainaahu bizibhin 'azeem", "tr": "vefedeynâhü biẕibḥin `ażîm."}, "tr": {"fr": "Et Nous le rançonnâmes d'une immolation généreuse.", "en": "And We ransomed him with a great sacrifice,", "id": "Dan Kami tebus anak itu dengan seekor sembelihan yang besar.", "tr": "Ona fidye olarak büyük bir kurbanlık verdik.", "de": "Und Wir lösten ihn mit einem großartigen Schlachtopfer aus.", "nl": "En Wij gaven hem ter vervanging een groot offerdier.", "es": "Le rescatamos mediante un espléndido sacrificio", "it": "E lo riscattammo con un sacrificio generoso.", "ar": "واستنقذنا إسماعيل، فجعلنا بديلا عنه كبشًا عظيمًا."}}, "37:142": {"s": 37, "v": 142, "nom": {"ar": "سُورَةُ الصَّافَّاتِ", "lat": "As-Saaffaat"}, "ar": "فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ", "tl": {"en": "Faltaqamahul hootu wa huwa muleem", "tr": "felteḳamehü-lḥûtü vehüve mülîm."}, "tr": {"fr": "Le poisson l'avala alors qu'il était blâmable.", "en": "Then the fish swallowed him, while he was blameworthy.", "id": "Maka ia ditelan oleh ikan besar dalam keadaan tercela.", "tr": "Kendini kınarken onu bir balık yutmuştu.", "de": "Da verschlang ihn der (große) Fisch\", während er sich Tadel zugezogen hatte.", "nl": "Toen slokte de vis hem op en hij verweet zichzelf.", "es": "El pez se lo tragó, había incurrido en censura.", "it": "Lo inghiottì un pesce, mentre si rammaricava.", "ar": "فأُلقي في البحر، فابتلعه الحوت، ويونس عليه السلام آتٍ بما يُلام عليه."}}, "39:9": {"s": 39, "v": 9, "nom": {"ar": "سُورَةُ الزُّمَرِ", "lat": "Az-Zumar"}, "ar": "أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًۭا وَقَآئِمًۭا يَحْذَرُ ٱلْءَاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ ۗ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ", "tl": {"en": "Amman huwa qaanitun aanaaa'al laili saajidanw wa qaaa'imai yahzarul Aakhirata wa yarjoo rahmata Rabbih; qul hal yastawil lazeena ya'lamoona wallazeena laa ya'lamoon; innamaa yatazakkaru ulul albaab", "tr": "emmen hüve ḳânitün ânâe-lleyli sâcidev veḳâimey yaḥẕeru-l'âḫirate veyercû raḥmete rabbih. ḳul hel yestevi-lleẕîne ya`lemûne velleẕîne lâ ya`lemûn. innemâ yeteẕekkeru ülü-l'elbâb."}, "tr": {"fr": "Est-ce que celui qui, aux heures de la nuit, reste en dévotion, prosterné et debout, prenant garde à l'au-delà et espérant la miséricorde de son Seigneur... Dis: «Sont-ils égaux, ceux qui savent et ceux qui ne savent pas?» Seuls les doués d'intelligence se rappellent.", "en": "Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, \"Are those who know equal to those who do not know?\" Only they will remember [who are] people of understanding.", "id": "(Apakah kamu hai orang musyrik yang lebih beruntung) ataukah orang yang beribadat di waktu-waktu malam dengan sujud dan berdiri, sedang ia takut kepada (azab) akhirat dan mengharapkan rahmat Tuhannya? Katakanlah: \"Adakah sama orang-orang yang mengetahui dengan orang-orang yang tidak mengetahui?\" Sesungguhnya orang yang berakallah yang dapat menerima pelajaran.", "tr": "Geceleyin secde ederek ve ayakta durarak boyun büken, ahiretten çekinen, Rabbinin rahmetini dileyen kimse inkar eden kimse gibi olur mu? De ki: \"Bilenlerle bilmeyenler bir olur mu? Doğrusu ancak akıl sahipleri öğüt alırlar.\"", "de": "Ist etwa einer, der sich zu (verschiedenen) Stunden der Nacht in demütiger Andacht befindet, (ob er) sich niederwirft oder aufrecht steht, der sich vor dem Jenseits vorsieht und auf seines Herrn Barmherzigkeit hofft ...? - Sag: Sind etwa dieje nigen, die wissen, und diejenigen, die nicht wissen, gleich? Doch bedenken nur diejenigen, die Verstand besitzen.", "nl": "Is de gehoorzame die een gedeelte van de nacht, zich neerknielend en staand (in de shalât doorbrengt), die het Hiernamaals vreest en hoopt op de Barmhartigheid van zijn Heer beter (... of de ongelovige?) Zeg: \"Zijn degenen die kennis hebben gelijk aan degenen die geen kennis hebben?\" Voorwaar, het zijn slechts de bezitters van gezond verstand die er lering uit trekken.", "es": "¿Es el devoto, que vela por la noche, postrado o de pie, que teme la otra vida y espera en la misericordia de su Señor...? Di: «¿Son iguales los que saben y los que no saben?» Sólo se dejan amonestar los dotados de intelecto.", "it": "Ma come? Chi passa in devozione le ore della notte, prosternato e ritto, timorato per l'Altra vita e speranzoso nella misericordia del suo Signore... Di': “Sono forse uguali e coloro che sanno e coloro che non sanno?”. Solo gli uomini dotati di intelletto riflettono.", "ar": "أهذا الكافر المتمتع بكفره خير، أم من هو عابد لربه طائع له، يقضي ساعات الليل في القيام والسجود لله، يخاف عذاب الآخرة، ويأمُل رحمة ربه؟ قل -أيها الرسول-: هل يستوي الذين يعلمون ربهم ودينهم الحق والذين لا يعلمون شيئًا من ذلك؟ لا يستوون. إنما يتذكر ويعرف الفرق أصحاب العقول السليمة."}}, "39:10": {"s": 39, "v": 10, "nom": {"ar": "سُورَةُ الزُّمَرِ", "lat": "Az-Zumar"}, "ar": "قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ ۚ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۗ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ ۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍۢ", "tl": {"en": "Qul yaa 'ibaadil lazeena aamanut taqoo Rabbakum; lillazeena ahsanoo fee haazihid dunyaa hasanah; wa ardul laahi waasi'ah; innamaa yuwaffas saabiroona ajrahum bighayri hisab", "tr": "ḳul yâ `ibâdi-lleẕîne âmenü-tteḳû rabbeküm. lilleẕîne aḥsenû fî hâẕihi-ddünyâ ḥaseneh. vearḍu-llâhi vâsi`ah. innemâ yüveffe-ṣṣâbirûne ecrahüm bigayri ḥisâb."}, "tr": {"fr": "Dis: «O Mes serviteurs qui avez cru! Craignez votre Seigneur». Ceux qui ici-bas font le bien, auront une bonne [récompense]. La terre d'Allah est vaste et les endurants auront leur pleine récompense sans compter.", "en": "Say, \"O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account.\"", "id": "Katakanlah: \"Hai hamba-hamba-Ku yang beriman. bertakwalah kepada Tuhanmu\". Orang-orang yang berbuat baik di dunia ini memperoleh kebaikan. Dan bumi Allah itu adalah luas. Sesungguhnya hanya orang-orang yang bersabarlah Yang dicukupkan pahala mereka tanpa batas.", "tr": "Şöyle de: \"Ey inanan kullarım! Rabbinize karşı gelmekten sakının; bu dünyada iyilik yapanlara iyilik vardır. Allah'ın yarattığı yeryüzü geniştir. Yalnız sabredenlere, ecirleri sonsuz olarak ödenecektir.\"", "de": "Sag: O meine Diener, die ihr gläubig seid, fürchtet euren Herrn. Für diejenigen, die Gutes tun, gibt es hier im Diesseits Gutes. Und Allahs Erde ist weit. Gewiß, den Standhaften wird ihr Lohn ohne Berechnung in vollem Maß zukommen.", "nl": "Zeg: \"O Mijn dienaren die geloven, vreest jullie Heer. Voor degenen die het goede doen in deze wereld is er goedheid, en de aarde van Allah is uitgegtrekt. Voorwaar, het zijn de geduldigen die hun beloning zonder berekening zal worden gegeven.\"", "es": "Di: «¡Siervos Míos que creéis! ¡Temed a vuestro Señor! Quienes obren bien tendrán en la vida de acá una bella recompensa. La tierra de Alá es vasta. Los pacientes recibierán una recompensa ilimitada».", "it": "Di': “O Miei servi che credete, temete il vostro Signore!”. Coloro che in questa vita fanno il bene, [avranno] un bene. Vasta è la terra di Allah. Coloro che sono perseveranti riceveranno la loro incalcolabile ricompensa.", "ar": "قل -أيها النبي- لعبادي المؤمنين بالله ورسوله: اتقوا ربكم بطاعته واجتناب معصيته. للذين أحسنوا في هذه الدينا بعبادة ربهم وطاعته حسنة في الآخرة، وهي الجنة، وحسنة في الدنيا من صحة ورزق ونصر وغير ذلك. وأرض الله واسعة، فهاجِروا فيها إلى حيث تعبدون ربكم، وتتمكنون من إقامة دينكم. إنما يُعطَى الصابرون ثوابهم في الآخرة بغير حدّ ولا عدّ ولا مقدار، وهذا تعظيم لجزاء الصابرين وثوابهم."}}, "39:53": {"s": 39, "v": 53, "nom": {"ar": "سُورَةُ الزُّمَرِ", "lat": "Az-Zumar"}, "ar": "۞ قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", "tl": {"en": "Qul yaa'ibaadiyal lazeena asrafoo 'alaaa anfusihim laa taqnatoo mirrahmatil laah; innal laaha yaghfiruz zunooba jamee'aa; innahoo Huwal Ghafoorur Raheem", "tr": "ḳul yâ `ibâdîye-lleẕîne esrafû `alâ enfüsihim lâ taḳneṭû mir raḥmeti-llâh. inne-llâhe yagfiru-ẕẕünûbe cemî`â. innehû hüve-lgafûru-rraḥîm."}, "tr": {"fr": "Dis: «O Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d'Allah. Car Allah pardonne tous les péchés. Oui, c'est Lui le Pardonneur, le Très Miséricordieux.", "en": "Say, \"O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful.\"", "id": "Katakanlah: \"Hai hamba-hamba-Ku yang malampaui batas terhadap diri mereka sendiri, janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.", "tr": "De ki: \"Ey kendilerine kötülük edip aşırı giden kullarım! Allah'ın rahmetinden umudunuzu kesmeyin. Doğrusu Allah günahların hepsini bağışlar. Çünkü O, bağışlayandır, merhametlidir.\"", "de": "Sag: O Meine Diener, die ihr gegen euch selbst maßlos gewesen seid, verliert nicht die Hoffnung auf Allahs Barmherzigkeit. Gewiß, Allah vergibt die Sünden alle. Er ist ja der Allvergebende und Barmherzige.", "nl": "Zeg: \"O mijn dienaren die buitensporig zijn tegenover zichzelf, wanhoopt niet aan de Genade van Allah. Voorwaar, Allah vetgeeft alle zonden. Voorwaar, Hij is de Vergevensgezinde, de Meest Barmhartige.", "es": "Di: «¡Siervos que habéis prevaricado en detrimento propio! ¡No desesperéis de la misericordia de Alá! Alá perdona todos los pecados. Él es el Indulgente, el Misericordioso».", "it": "Di': “O Miei servi, che avete ecceduto contro voi stessi, non disperate della misericordia di Allah. Allah perdona tutti i peccati. In verità Egli è il Perdonatore, il Misericordioso.", "ar": "قل -أيها الرسول- لعبادي الذين تمادَوا في المعاصي، وأسرفوا على أنفسهم بإتيان ما تدعوهم إليه نفوسهم من الذنوب: لا تَيْئسوا من رحمة الله؛ لكثرة ذنوبكم، إن الله يغفر الذنوب جميعًا لمن تاب منها ورجع عنها مهما كانت، إنه هو الغفور لذنوب التائبين من عباده، الرحيم بهم."}}, "41:34": {"s": 41, "v": 34, "nom": {"ar": "سُورَةُ فُصِّلَتۡ", "lat": "Fussilat"}, "ar": "وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ", "tl": {"en": "Wa laa tastawil hasanatu wa las saiyi'ah; idfa' billatee hiya ahsanu fa'izal lazee bainaka wa bainahoo 'adaawatun ka'annahoo waliyun hameem", "tr": "velâ testevi-lḥasenetü vele-sseyyieh. idfa` billetî hiye aḥsenü feiẕe-lleẕî beyneke vebeynehû `adâvetün keennehû veliyyün ḥamîm."}, "tr": {"fr": "La bonne action et la mauvaise ne sont pas pareilles. Repousse (le mal) par ce qui est meilleur; et voilà que celui avec qui tu avais une animosité devient tel un ami chaleureux.", "en": "And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend.", "id": "Dan tidaklah sama kebaikan dan kejahatan. Tolaklah (kejahatan itu) dengan cara yang lebih baik, maka tiba-tiba orang yang antaramu dan antara dia ada permusuhan seolah-olah telah menjadi teman yang sangat setia.", "tr": "İyilik ve fenalık bir değildir. Ey inanan kişi: Sen, fenalığı en güzel şekilde sav; o zaman, seninle arasında düşmanlık bulunan kişinin yakın bir dost gibi olduğunu görürsün.", "de": "Nicht gleich sind die gute Tat und die schlechte Tat. Wehre mit einer Tat, die besser ist, (die schlechte) ab, dann wird derjenige, zwischen dem und dir Feindschaft besteht, so, als wäre er ein warmherziger Freund.", "nl": "En het goede en het kwade zijn niet gelijk: beantwoord (het kwade) met wat beter is, dan zal degene met wie je in vijandschap leefde als een oprechte vriend worden.", "es": "No es igual obrar bien y obrar mal. ¡Repele con lo que sea mejor y he aquí que aquél de quien te separe la enemistad se convetirá en amigo ferviente!", "it": "Non sono certo uguali la cattiva [azione] e quella buona. Respingi quella con qualcosa che sia migliore: colui dal quale ti divideva l'inimicizia, diventerà un amico affettuoso.", "ar": "ولا تستوي حسنة الذين آمنوا بالله، واستقاموا على شرعه، وأحسنوا إلى خلقه، وسيئة الذين كفروا به وخالفوا أمره، وأساؤوا إلى خلقه. ادفع بعفوك وحلمك وإحسانك مَن أساء إليك، وقابل إساءته لك بالإحسان إليه، فبذلك يصير المسيء إليك الذي بينك وبينه عداوة كأنه قريب لك شفيق عليك. وما يُوفَّق لهذه الخصلة الحميدة إلا الذين صبروا أنفسهم على ما تكره، وأجبروها على ما يحبه الله، وما يُوفَّق لها إلا ذو نصيب وافر من السعادة في الدنيا والآخرة."}}, "42:11": {"s": 42, "v": 11, "nom": {"ar": "سُورَةُ الشُّورَىٰ", "lat": "Ash-Shura"}, "ar": "فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًۭا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ", "tl": {"en": "Faatirus samaawaati wal ard; ja'ala lakum min anfusikum azwaajanw wa minal an'aami azwaajany yazra'ukum feeh; laisa kamislihee shai'unw wa Huwas Samee'ul Baseer", "tr": "fâṭiru-ssemâvâti vel'arḍ. ce`ale leküm min enfüsiküm ezvâcev vemine-l'en`âmi ezvâcâ. yeẕraüküm fîh. leyse kemiŝlihî şey'. vehüve-ssemî`u-lbeṣîr."}, "tr": {"fr": "...Créateur des cieux et de la terre. Il vous a donné des épouses [issues] de vous-mêmes et des bestiaux par couples; par ce moyen Il vous multiplie. Il n'y a rien qui Lui ressemble; et c'est Lui l'Audient, le Clairvoyant.", "en": "[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.", "id": "(Dia) Pencipta langit dan bumi. Dia menjadikan bagi kamu dari jenis kamu sendiri pasangan-pasangan dan dari jenis binatang ternak pasangan-pasangan (pula), dijadikan-Nya kamu berkembang biak dengan jalan itu. Tidak ada sesuatupun yang serupa dengan Dia, dan Dialah yang Maha Mendengar dan Melihat.", "tr": "Göklerin ve yerin yaratanı, size içinizden eşler, çift çift hayvanlar var etmiştir. Bu suretle, çoğalmanızı sağlamıştır. O'nun benzeri hiçbir şey yoktur. O, işitendir, görendir.", "de": "(Er ist) der Erschaffer der Himmel und der Erde. Er hat euch aus euch selbst Gattinnen gemacht, und auch aus dem Vieh Paare, wodurch Er euch vermehrt. Nichts ist Ihm gleich; und Er ist der Allhörende und Allsehende.", "nl": "De Schepper van de hemelen en de aarde, Hij heeft voor jullie van julliezelf en van de dieren paren geschapen. Hij vermenigvuldigt jullie, niets is aan Hem gelijk. En Hij is de Alhorende, de Alziende.", "es": "Creador de los cielos y de la tierra. Os ha dado esposas salidas de vosotros y parejas salidas de vuestros rebaños, diseminándoos así. No hay nada que se Le asemeje. Él es Quien todo lo oye, Quien todo lo ve.", "it": "È il Creatore dei cieli e della terra. Da voi stessi ha tratto le vostre spose, e [vi ha dato] il bestiame a coppie. Così vi moltiplica. Niente è simile a Lui. Egli è l'Audiente, Colui Che tutto osserva.", "ar": "الله سبحانه وتعالى هو خالق السماوات والأرض ومبدعهما بقدرته ومشيئته وحكمته، جعل لكم من أنفسكم أزواجًا؛ لتسكنوا إليها، وجعل لكم من الأنعام أزواجًا ذكورًا وإناثًا، يكثركم بسببه بالتوالد، ليس يشبهه تعالى ولا يماثله شيء من مخلوقاته، لا في ذاته ولا في أسمائه ولا في صفاته ولا في أفعاله؛ لأن أسماءه كلَّها حسنى، وصفاتِه صفات كمال وعظمة، وأفعالَه تعالى أوجد بها المخلوقات العظيمة من غير مشارك، وهو السميع البصير، لا يخفى عليه مِن أعمال خلقه وأقوالهم شيء، وسيجازيهم على ذلك."}}, "43:77": {"s": 43, "v": 77, "nom": {"ar": "سُورَةُ الزُّخۡرُفِ", "lat": "Az-Zukhruf"}, "ar": "وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ ۖ قَالَ إِنَّكُم مَّٰكِثُونَ", "tl": {"en": "Wa naadaw yaa Maaliku liyaqdi 'alainaa Rabbuka qaala innakum maakisson", "tr": "venâdev yâ mâlikü liyaḳḍi `aleynâ rabbük. ḳâle inneküm mâkiŝûn."}, "tr": {"fr": "et ils crieront: «O Mâlik! Que ton Seigneur nous achève!» Il dira: «En vérité, vous êtes pour y demeurer [éternellement]»!", "en": "And they will call, \"O Malik, let your Lord put an end to us!\" He will say, \"Indeed, you will remain.\"", "id": "Mereka berseru: \"Hai Malik biarlah Tuhanmu membunuh kami saja\". Dia menjawab: \"Kamu akan tetap tinggal (di neraka ini)\".", "tr": "Cehennemde şöyle seslenilir: \"Ey Nöbetçi! Rabbin hiç değilse canımızı alsın.\" Nöbetçi: \"Siz böyle kalacaksınız\" der.", "de": "Und sie rufen: \"O Malik, dein Herr soll unserem Leben ein Ende setzen.\" Er sagt: \"Gewiß, ihr werdet (hier) bleiben.\"", "nl": "Zij roepen: \"O Mâlik (bewaker van de Hel), laat jouw Heer een eind aan ons maken.\" Hij zegt: \"Voorwaar, jullie blijven hier.\"", "es": "Llamarán: «¡Malik! ¡Que tu Señor acabe con nosotros!» Él dirá: «¡Os quedaréis ahí!»", "it": "Urleranno: “O Mâlik, che ci finisca il tuo Signore!”.", "ar": "ونادى هؤلاء المجرمون بعد أن أدخلهم الله جهنم \"مالكًا\" خازن جهنم: يا مالك لِيُمِتنا ربك، فنستريح ممَّا نحن فيه، فأجابهم مالكٌ: إنكم ماكثون، لا خروج لكم منها، ولا محيد لكم عنها، لقد جئناكم بالحق ووضحناه لكم، ولكن أكثركم لما جاء به الرسل من الحق كارهون."}}, "47:19": {"s": 47, "v": 19, "nom": {"ar": "سُورَةُ مُحَمَّدٍ", "lat": "Muhammad"}, "ar": "فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ", "tl": {"en": "Fa'lam annahoo laaa ilaaha illal laahu wastaghfir lizambika wa lilmu'mineena walmu'minaat; wallaahu ya'lamu mutaqallabakum wa maswaakum", "tr": "fa`lem ennehû lâ ilâhe ille-llâhü vestagfir liẕembike velilmü'minîne velmü'minât. vellâhü ya`lemü müteḳallebeküm vemeŝvâküm."}, "tr": {"fr": "Sache donc qu'en vérité il n'y a point de divinité à part Allah et implore le pardon pour ton péché, ainsi que pour les croyants et les croyantes. Allah connaît vos activités (sur terre) et votre lieu de repos (dans l'au-delà).", "en": "So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place.", "id": "Maka ketahuilah, bahwa sesungguhnya tidak ada Ilah (sesembahan, tuhan) selain Allah dan mohonlah ampunan bagi dosamu dan bagi (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat kamu berusaha dan tempat kamu tinggal.", "tr": "Bil ki, Allah'tan başka tanrı yoktur; kendinin, inanmış erkek ve kadınların günahlarının bağışlanmasını dile. Allah, gezip dolaştığınız ve duracağınız yerleri bilir.", "de": "Wisse also, daß es keinen Gott außer Allah gibt. Und bitte um Vergebung für deine Sünde und für die gläubigen Männer und die gläubigen Frauen. Allah kennt euren Wandel und euren Aufenthalt.", "nl": "Weet dat er geen god is dan Allah en vraag om vergeving voor jouw zonden en voor (de zonden van) de gelovige mannen en de gelovige vrouwen. En Allah kent jullie bezigheden (op aarde) en jullie verblijfplaats (in het Hiernamaals).", "es": "Sabe, pues, que no hay más dios que Alá y pide perdón por tu pecado, así como por los creyentes y las creyentes. Alá conoce vuestras idas y venidas y dónde moráis.", "it": "Sappi che in verità non c'è dio all'infuori di Allah e implora perdono per la tua colpa e per i credenti e le credenti. Allah ben conosce il vostro affanno e il vostro rifugio.", "ar": "فاعلم -أيها النبي- أنه لا معبود بحق إلا الله، واستغفر لذنبك، واستغفر للمؤمنين والمؤمنات. والله يعلم تصرفكم في يقظتكم نهارًا، ومستقركم في نومكم ليلا."}}, "48:29": {"s": 48, "v": 29, "nom": {"ar": "سُورَةُ الفَتۡحِ", "lat": "Al-Fath"}, "ar": "مُّحَمَّدٌۭ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ ۖ تَرَىٰهُمْ رُكَّعًۭا سُجَّدًۭا يَبْتَغُونَ فَضْلًۭا مِّنَ ٱللَّهِ وَرِضْوَٰنًۭا ۖ سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ۚ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ ۚ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ ۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةًۭ وَأَجْرًا عَظِيمًۢا", "tl": {"en": "Muhammadur Rasoolul laah; wallazeena ma'ahooo ashiddaaa'u 'alal kuffaaari ruhamaaa'u bainahum taraahum rukka'an sujjadany yabtaghoona fadlam minal laahi wa ridwaanan seemaahum fee wujoohihim min asaris sujood; zaalika masaluhum fit tawraah; wa masaluhum fil Injeeli kazar'in akhraja shat 'ahoo fa 'aazarahoo fastaghlaza fastawaa 'alaa sooqihee yu'jibuz zurraa'a liyagheeza bihimul kuffaar; wa'adal laahul lazeena aamanoo wa 'amilus saalihaati minhum maghfiratanw wa ajran 'azeemaa", "tr": "müḥammedür rasûlü-llâh. velleẕîne me`ahû eşiddâü `ale-lküffâri ruḥamâü beynehüm terâhüm rukke`an süccedey yebtegûne faḍlem mine-llâhi veriḍvânâ. sîmâhüm fî vucûhihim min eŝeri-ssücûd. ẕâlike meŝelühüm fi-ttevrâh. vemeŝelühüm fi-l'incîl. kezer`in aḫrace şaṭ'ehû feâzerahû festagleża festevâ `alâ sûḳihî yü`cibü-zzürrâ`a liyegîża bihimü-lküffâr. ve`ade-llâhü-lleẕîne âmenû ve`amilu-ṣṣâliḥâti minhüm magfiratev veecran `ażîmâ."}, "tr": {"fr": "Muhammad est le Messager d'Allah. Et ceux qui sont avec lui sont durs envers les mécréants, miséricordieux entre eux. Tu les vois inclinés, prosternés, recherchant d'Allah grâce et agrément. Leurs visages sont marqués par la trace laissée par la prosternation. Telle est leur image dans la Thora. Et l'image que l'on donne d'eux dans l'Evangile est celle d'une semence qui sort sa pousse, puis se raffermit, s'épaissit, et ensuite se dresse sur sa tige, à l'émerveillement des semeurs. [Allah] par eux [les croyants] remplit de dépit les mécréants. Allah promet à ceux d'entre eux qui croient et font de bonnes œuvres, un pardon et une énorme récompense.", "en": "Muhammad is the Messenger of Allah; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allah and [His] pleasure. Their mark is on their faces from the trace of prostration. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that Allah may enrage by them the disbelievers. Allah has promised those who believe and do righteous deeds among them forgiveness and a great reward.", "id": "Muhammad itu adalah utusan Allah dan orang-orang yang bersama dengan dia adalah keras terhadap orang-orang kafir, tetapi berkasih sayang sesama mereka. Kamu lihat mereka ruku' dan sujud mencari karunia Allah dan keridhaan-Nya, tanda-tanda mereka tampak pada muka mereka dari bekas sujud. Demikianlah sifat-sifat mereka dalam Taurat dan sifat-sifat mereka dalam Injil, yaitu seperti tanaman yang mengeluarkan tunasnya maka tunas itu menjadikan tanaman itu kuat lalu menjadi besarlah dia dan tegak lurus di atas pokoknya; tanaman itu menyenangkan hati penanam-penanamnya karena Allah hendak menjengkelkan hati orang-orang kafir (dengan kekuatan orang-orang mukmin). Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang saleh di antara mereka ampunan dan pahala yang besar.", "tr": "Muhammed Allah'ın elçisidir. Onun beraberinde bulunanlar, inkarcılara karşı sert, birbirlerine merhametlidirler. Onları rükua varırken, secde ederken, Allah'tan lütuf ve hoşnudluk dilerken görürsün. Onlar, yüzlerindeki secde izi ile tanınırlar. İşte bu, onların Tevrat'ta anlatılan vasıflarıdır. İncil'de de şöyle vasıflandırılmışlardı: Filizini çıkarmış, onu kuvvetlendirmiş, kalınlaşmış, gövdesi üzerine dikilmiş, ekincilerin hoşuna giden ekin gibidirler. Allah böylece bunları çoğaltıp kuvvetlendirmekle inkarcıları öfkelendirir. Allah, inanıp yararlı işler işleyenlere, bağışlama ve büyük ecir vadetmiştir.", "de": "Muhammad ist Allahs Gesandter. Und diejenigen, die mit ihm sind, sind den Ungläubigen gegenüber hart, zueinander aber barmherzig. Du siehst sie sich verbeugen und niederwerfen, indem sie nach Huld von Allah und Wohlgefallen trachten. Ihr Merkmal steht auf ihren Gesichtern durch die Niederwerfung. Das ist ihr Gleichnis in der Tora. Und ihr Gleichnis im Evangelium ist das eines Getreidefeldes, das seine Triebe hervorbringt und dann stärker werden läßt, so daß sie verdicken und ebenmäßig auf ihren Halmen stehen, so daß es den Anbauern gefällt. (Dies,) damit Er die Ungläubigen durch sie ergrimmen lasse. Allah hat denjenigen von ihnen, die glauben und rechtschaffene Werke tun, Vergebung und großartigen Lohn versprochen.", "nl": "Moehammad is de Boodschapper van Allah en degenen die met hem zijn, zijn streng tegenover de ongelovigen, maar onderling barmhartig. Jij ziet hen zich neerbuigen en zich neerknielen. Zij zoeken een gunst van Allah en Zijn welgevallen. Hun kenmerken zijn zichtbaar in hun gezichten door de sporen van neerknielingen. Dat is hun beschrijving in de Taurât. En hun beschrijving in de Indjîl is als een jonge plant waarvan de loten ontspruiten, waardoor hij sterker wordt. Daarna wordt hij steviger en staat hij recht op zijn wortel. Bij de planters veroorzaakt hij blijdschap. Hij (Allah) wil daarmee de ongelovigen woedend maken. Allah heeft degenen onder hen die geloven en goede werken verrichten vergeving en een geweldige beloning beloofd.", "es": "Mahoma es el Enviado de Alá. Quienes están con él son severos con los infieles y cariñosos entre sí. Se les ve inclinados o prosternados, buscando favor de Alá y satisfacerle. Se les nota en el rostro que se prosternan. Tal es su imagen en la Tora. Y en el Evangelio se les compara con la semilla que, habiendo germinado, fortifica su brote y éste crece y se yergue en el tallo, constituyendo la alegría del sembrador, para terminar irritando a los infieles por su medio. A quienes de ellos crean y obren bien, Alá les ha prometido perdón y una magnífica recompensa.", "it": "Muhammad è il Messaggero di Allah e quanti sono con lui sono duri con i miscredenti e compassionevoli fra loro. Li vedrai inchinarsi e prosternarsi, bramando la grazia di Allah e il Suo compiacimento. Il loro segno è, sui loro volti, la traccia della prosternazione: ecco l'immagine che ne dà di loro la Torâh. L'immagine che invece ne dà il Vangelo è quella di un seme che fa uscire il suo germoglio, poi lo rafforza e lo ingrossa, ed esso si erge sul suo stelo nell'ammirazione dei seminatori. Tramite loro Allah fa corrucciare i miscredenti. Allah promette perdono e immensa ricompensa a coloro che credono e compiono il bene.", "ar": "محمد رسول الله، والذين معه على دينه أشداء على الكفار، رحماء فيما بينهم، تراهم ركعًا سُجَّدًا لله في صلاتهم، يرجون ربهم أن يتفضل عليهم، فيدخلهم الجنة، ويرضى عنهم، علامة طاعتهم لله ظاهرة في وجوههم من أثر السجود والعبادة، هذه صفتهم في التوراة. وصفتهم في الإنجيل كصفة زرع أخرج ساقه وفرعه، ثم تكاثرت فروعه بعد ذلك، وشدت الزرع، فقوي واستوى قائمًا على سيقانه جميلا منظره، يعجب الزُّرَّاع؛ ليَغِيظ بهؤلاء المؤمنين في كثرتهم وجمال منظرهم الكفار. وفي هذا دليل على كفر من أبغض الصحابة -رضي الله عنهم-؛ لأن من غاظه الله بالصحابة، فقد وُجد في حقه موجِب ذاك، وهو الكفر. وعد الله الذين آمنوا منهم بالله ورسوله وعملوا ما أمرهم الله به، واجتنبوا ما نهاهم عنه، مغفرة لذنوبهم، وثوابًا جزيلا لا ينقطع، وهو الجنة. (ووعد الله حق مصدَّق لا يُخْلَف، وكل من اقتفى أثر الصحابة رضي الله عنهم فهو في حكمهم في استحقاق المغفرة والأجر العظيم، ولهم الفضل والسبق والكمال الذي لا يلحقهم فيه أحد من هذه الأمة، رضي الله عنهم وأرضاهم)."}}, "49:6": {"s": 49, "v": 6, "nom": {"ar": "سُورَةُ الحُجُرَاتِ", "lat": "Al-Hujuraat"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍۢ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍۢ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ", "tl": {"en": "Yaaa ayyuhal lazeena aamanoo in jaaa'akum faasqum binaba in fatabaiyanooo an tuseeboo qawmam bijahalatin fatusbihoo 'alaa maa fa'altum naadimeen", "tr": "yâ eyyühe-lleẕîne âmenû in câeküm fâsiḳum binebein fetebeyyenû en tüṣîbû ḳavmem bicehâletin fetuṣbiḥû `alâ mâ fe`altüm nâdimîn."}, "tr": {"fr": "O vous qui avez cru! Si un pervers vous apporte une nouvelle, voyez bien clair [de crainte] que par inadvertance vous ne portiez atteinte à des gens et que vous ne regrettiez par la suite ce que vous avez fait.", "en": "O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful.", "id": "Hai orang-orang yang beriman, jika datang kepadamu orang fasik membawa suatu berita, maka periksalah dengan teliti agar kamu tidak menimpakan suatu musibah kepada suatu kaum tanpa mengetahui keadaannya yang menyebabkan kamu menyesal atas perbuatanmu itu.", "tr": "Ey inananlar! Eğer yoldan çıkmışın biri size bir haber getirirse, onun iç yüzünü araştırın, yoksa bilmeden bir millete fenalık edersiniz de sonra ettiğinize pişman olursunuz.", "de": "O die ihr glaubt, wenn ein Frevler zu euch mit einer Kunde kommt, dann schafft Klarheit, damit ihr (nicht einige) Leute in Unwissenheit (mit einer Anschuldigung) trefft und dann über das, was ihr getan habt, Reue empfinden werdet.", "nl": "O jullie die geloven, als een verdorvene met een bericht komt, onderzoekt het dan nauwkeurig, anders treffen jullie uit onwetendheid een volk met een ramp, waarna jullie spijt zouden krijgen van wat jullie deden.", "es": "¡Creyentes! Si un malvado os trae una noticia, examinadla bien, no sea que lastiméis a gente por ignorancia y tengáis que arrepentiros de lo que habéis hecho.", "it": "O credenti, se un malvagio vi reca una notizia, verificatela, affinché non portiate, per disinformazione, pregiudizio a qualcuno e abbiate poi a pentirvi di quel che avrete fatto.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن جاءكم فاسق بخبر فتثبَّتوا من خبره قبل تصديقه ونقله حتى تعرفوا صحته؛ خشية أن تصيبوا قومًا برآء بجناية منكم، فتندموا على ذلك."}}, "49:10": {"s": 49, "v": 10, "nom": {"ar": "سُورَةُ الحُجُرَاتِ", "lat": "Al-Hujuraat"}, "ar": "إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ", "tl": {"en": "Innamal mu'minoona ikhwatun fa aslihoo baina akhawaykum wattaqul laaha la'allakum tuhamoon", "tr": "inneme-lmü'minûne iḫvetün feaṣliḥû beyne eḫaveyküm vetteḳu-llâhe le`alleküm türḥamûn."}, "tr": {"fr": "Les croyants ne sont que des frères. Etablissez la concorde entre vos frères, et craignez Allah, afin qu'on vous fasse miséricorde.", "en": "The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy.", "id": "Orang-orang beriman itu sesungguhnya bersaudara. Sebab itu damaikanlah (perbaikilah hubungan) antara kedua saudaramu itu dan takutlah terhadap Allah, supaya kamu mendapat rahmat.", "tr": "Şüphesiz müminler birbiri ile kardeştirler; öyle ise dargın olan kardeşlerinizin arasını düzeltin; Allah'tan sakının ki size acısın.", "de": "Die Gläubigen sind doch Brüder. So stiftet Frieden zwischen euren beiden Brüdern und fürchtet Allah, auf daß ihr Erbarmen finden möget.", "nl": "Voorwaar, de gelovigen zijn elkaars broeders, sticht daarom vrede tussen jouw broeders. En vreest Allah. Hopelijk zullen jullie begenadigd worden.", "es": "Los creyentes son, en verdad, hermanos. ¡Reconciliad, pues, a vuestos hermanos y temed a Alá! Quizás, así, se os tenga piedad.", "it": "In verità i credenti sono fratelli: ristabilite la concordia tra i vostri fratelli e temete Allah. Forse vi sarà usata misericordia.", "ar": "إنما المؤمنون إخوة في الدين، فأصلحوا بين أخويكم إذا اقتتلا وخافوا الله في جميع أموركم؛ رجاء أن تُرحموا."}}, "49:12": {"s": 49, "v": 12, "nom": {"ar": "سُورَةُ الحُجُرَاتِ", "lat": "Al-Hujuraat"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ", "tl": {"en": "Yaaa ayyuhal lazeena aamanuj taniboo kaseeram minaz zanni inna ba'daz zanniismunw wa laa tajassasoo wa la yaghtab ba'dukum ba'daa; a yuhibbu ahadukum any yaakula lahma akheehi maitan fakarih tumooh; wattaqul laa; innal laaha tawwaabur Raheem", "tr": "yâ eyyühe-lleẕîne âmenü-ctenibû keŝîram mine-żżann. inne ba`ḍa-żżanni iŝmüv velâ tecessesû velâ yagteb ba`ḍuküm ba`ḍâ. eyüḥibbü eḥadüküm ey ye'küle laḥme eḫîhi meyten fekerihtümûh. vetteḳu-llâh. inne-llâhe tevvâbür raḥîm."}, "tr": {"fr": "O vous qui avez cru! Evitez de trop conjecturer [sur autrui] car une partie des conjectures est péché. Et n'espionnez pas; et ne médisez pas les uns des autres. L'un de vous aimerait-il manger la chair de son frère mort? (Non!) vous en aurez horreur. Et craignez Allah. Car Allah est Grand Accueillant au repentir, Très Miséricordieux.", "en": "O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful.", "id": "Hai orang-orang yang beriman, jauhilah kebanyakan purba-sangka (kecurigaan), karena sebagian dari purba-sangka itu dosa. Dan janganlah mencari-cari keburukan orang dan janganlah menggunjingkan satu sama lain. Adakah seorang diantara kamu yang suka memakan daging saudaranya yang sudah mati? Maka tentulah kamu merasa jijik kepadanya. Dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Penerima Taubat lagi Maha Penyayang.", "tr": "Ey inananlar! Zannın çoğundan sakının, zira zannın bir kısmı günahtır. Birbirinizin suçunu araştırmayın; kimse kimseyi çekiştirmesin; hangi biriniz ölü kardeşinin etini yemekten hoşlanır? Ondan tiksinirsiniz; Allah'tan sakının, şüphesiz Allah tevbeleri daima kabul edendir, acıyandır.", "de": "O die ihr glaubt, meidet viel von den Mutmaßungen; gewiß, manche Mutmaßung ist Sünde. Und sucht nicht (andere) auszukundschaften und führt nicht üble Nachrede übereinander. Möchte denn einer von euch gern das Fleisch seines Bruders, wenn er tot sei, essen? Es wäre euch doch zuwider. Fürchtet Allah. Gewiß, Allah ist Reue-Annehmend und Barmherzig.", "nl": "O jullie die geloven, vermijdt veel van de kwade vermoedens. Voorwaar, een deel van de kwade vermoedens zijn zonden. En bespioneert elkaar niet en spreekt geen kwaad over elkaar in elkaars afwezigheid. Zou iemand van jullie het vlees van zijn dode broeder willen eten? Jullie zouden het zeker haten. En vreest Allah. Voorwaar, Allah is Berouwaanvaardend, Meest Barmhartig.", "es": "¡Creyentes! ¡Evitad conjeturar demasiado! Algunas conjeturas son pecado. ¡No espiéis! ¡No calumniéis! ¿Os gustaría comer la carne de un hermano muerto? Os causaría horror... ¡Temed a Alá! Alá es indulgente, misericordioso.", "it": "O credenti, evitate di far troppe illazioni, ché una parte dell'illazione è peccato. Non vi spiate e non sparlate gli uni degli altri. Qualcuno di voi mangerebbe la carne del suo fratello morto? Ne avreste anzi orrore! Temete Allah! Allah sempre accetta il pentimento, è misericordioso.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اجتنبوا كثيرًا من ظن السوء بالمؤمنين؛ إن بعض ذلك الظن إثم، ولا تُفَتِّشوا عن عورات المسلمين، ولا يقل بعضكم في بعضٍ بظهر الغيب ما يكره. أيحب أحدكم أكل لحم أخيه وهو ميت؟ فأنتم تكرهون ذلك، فاكرهوا اغتيابه. وخافوا الله فيما أمركم به ونهاكم عنه. إن الله تواب على عباده المؤمنين، رحيم بهم."}}, "50:17": {"s": 50, "v": 17, "nom": {"ar": "سُورَةُ قٓ", "lat": "Qaaf"}, "ar": "إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌۭ", "tl": {"en": "'Iz yatalaqqal mutalaqqi yaani 'anil yameeni wa 'anish shimaali qa'eed", "tr": "iẕ yeteleḳḳe-lmüteleḳḳiyâni `ani-lyemîni ve`ani-şşimâli ḳa`îd."}, "tr": {"fr": "quand les deux recueillants, assis à droite et à gauche, recueillent.", "en": "When the two receivers receive, seated on the right and on the left.", "id": "(yaitu) ketika dua orang malaikat mencatat amal perbuatannya, seorang duduk di sebelah kanan dan yang lain duduk di sebelah kiri.", "tr": "Sağında ve solunda, onunla beraber oturan iki alıcı melek, yanında hazır birer gözcü olarak söylediği her sözü zaptederler.", "de": "wo die beiden Empfänger (der Taten) empfangen, zur Rechten und zur Linken sitzend.", "nl": "Wanneer de twee ontvangers (Engelen) aan de rechterzijde en aan de linkerzijde zitten te schrijven.", "es": "Cuando los dos encargados de recoger recojan, sentados el uno a la derecha y el otro a la izquierda,", "it": "Quando i due che registrano seduti alla sua destra e alla sua sinistra, raccoglieranno [il suo dire],", "ar": "حين يكتب المَلَكان المترصدان عن يمينه وعن شماله أعماله. فالذي عن اليمين يكتب الحسنات، والذي عن الشمال يكتب السيئات."}}, "50:18": {"s": 50, "v": 18, "nom": {"ar": "سُورَةُ قٓ", "lat": "Qaaf"}, "ar": "مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌۭ", "tl": {"en": "Maa yalfizu min qawlin illaa ladaihi raqeebun 'ateed", "tr": "mâ yelfiżu min ḳavlin illâ ledeyhi raḳîbün `atîd."}, "tr": {"fr": "Il ne prononce pas une parole sans avoir auprès de lui un observateur prêt à l'inscrire.", "en": "Man does not utter any word except that with him is an observer prepared [to record].", "id": "Tiada suatu ucapanpun yang diucapkannya melainkan ada di dekatnya malaikat pengawas yang selalu hadir.", "tr": "Sağında ve solunda, onunla beraber oturan iki alıcı melek, yanında hazır birer gözcü olarak söylediği her sözü zaptederler.", "de": "Kein Wort äußert er, ohne daß bei ihm ein Beobachter bereit wäre.", "nl": "Is er geen woord dat Hij uit, of aan zijn Zijde bevindt zich een waker die gereed is.", "es": "no pronunciará ninguna palabra que no tenga siempre a su lado a un observador preparado.", "it": "[l'uomo] non pronuncerà nessuna parola senza che presso di lui ci sia un osservatore solerte.", "ar": "ما يلفظ من قول فيتكلم به إلا لديه مَلَك يرقب قوله، ويكتبه، وهو مَلَك حاضر مُعَدٌّ لذلك."}}, "54:49": {"s": 54, "v": 49, "nom": {"ar": "سُورَةُ القَمَرِ", "lat": "Al-Qamar"}, "ar": "إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍۢ", "tl": {"en": "Innaa kulla shai'in khalaqnaahu biqadar", "tr": "innâ külle şey'in ḫalaḳnâhü biḳader."}, "tr": {"fr": "Nous avons créé toute chose avec mesure,", "en": "Indeed, all things We created with predestination.", "id": "Sesungguhnya Kami menciptakan segala sesuatu menurut ukuran.", "tr": "Şüphesiz Biz her şeyi bir ölçüye göre yaratmışızdır.", "de": "Gewiß, Wir haben alles in (bestimmtem) Maß erschaffen.", "nl": "Voorwaar, Wij hebben alle zaken volgens een bepaalde maatgeving geschapen.", "es": "Todo lo hemos creado con medida.", "it": "Ogni cosa creammo in giusta misura,", "ar": "إنَّا كل شيء خلقناه بمقدار قدرناه وقضيناه، وسبق علمنا به، وكتابتنا له في اللوح المحفوظ."}}, "58:11": {"s": 58, "v": 11, "nom": {"ar": "سُورَةُ المُجَادلَةِ", "lat": "Al-Mujaadila"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ", "tl": {"en": "Yaaa ayyuhal lazeena aamanoo izaa qeela lakum tafassahoo fil majaalisi fafsahoo yafsahil laahu lakum wa izaa qeelan shuzoo fanshuzoo yarfa'il laahul lazeena aamanoo minkum wallazeena ootul 'ilma darajaat; wallaahu bimaa ta'maloona khabeer", "tr": "yâ eyyühe-lleẕîne âmenû iẕâ ḳîle leküm tefesseḥû fi-lmecâlisi fefseḥû yefseḥi-llâhü leküm. veiẕâ ḳîle-nşüzû fenşüzû yerfe`i-llâhü-lleẕîne âmenû minküm velleẕîne ûtü-l`ilme deracât. vellâhü bimâ ta`melûne ḫabîr."}, "tr": {"fr": "O vous qui avez cru! Quand on vous dit: «Faites place [aux autres] dans les assemblées», alors faites place. Allah vous ménagera une place (au Paradis). Et quand on vous dit de vous lever, levez-vous. Allah élèvera en degrés ceux d'entre vous qui auront cru et ceux qui auront reçu le savoir. Allah est Parfaitement Connaisseur de ce que vous faites.", "en": "O you who have believed, when you are told, \"Space yourselves\" in assemblies, then make space; Allah will make space for you. And when you are told, \"Arise,\" then arise; Allah will raise those who have believed among you and those who were given knowledge, by degrees. And Allah is Acquainted with what you do.", "id": "Hai orang-orang beriman apabila dikatakan kepadamu: \"Berlapang-lapanglah dalam majlis\", maka lapangkanlah niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan: \"Berdirilah kamu\", maka berdirilah, niscaya Allah akan meninggikan orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu pengetahuan beberapa derajat. Dan Allah Maha Mengetahui apa yang kamu kerjakan.", "tr": "Ey inananlar! Toplantılarda, size, \"Yer açın\" denince yer açın ki Allah da size genişlik versin; \"Kalkın\" denildiği zaman da hemen kalkın ki, Allah, içinizden inanmış olanları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah işlediklerinizden haberdardır.", "de": "O die ihr glaubt, wenn zu euch gesagt wird: \"Macht Platz!\" in den Versammlungen!, dann schafft Platz, so schafft auch Allah euch Platz. Und wenn gesagt wird: \"Erhebt euch!\", dann erhebt euch eben, so erhöht auch Allah diejenigen von euch, die glauben, und diejenigen, denen das Wissen gegeben worden ist, um Rangstufen. Und Allah ist dessen, was ihr tut, Kundig.", "nl": "O jullie die geloven, wanneer tot jullie gezegd wordt: \"Maakt ruimte in de plaatsen van samenkomsten,\" maakt dan ruimte; Allah zal voor jullie ruimte maken. En wanneer tot jullie gezegd wordt: \"Staat op,\" staat dan op; Allah zal degenen onder jullie die geloven en degenen aan wie kennis is gegeven in rang verheffen. En Allah is Alwetend over wat jullie doen.", "es": "¡Creyentes! Cuando se os dice: «¡Haced sitio en las asambleas!» hacedlo así para que Alá os haga también sitio. Y si se os dice: «¡Levantaos!», hacedlo así para que Alá también eleve la categoría de aquéllos de vosotros que crean y reciban la Ciencia. Alá está informado de lo que hacéis.", "it": "O credenti, quando vi si dice: “Fate spazio [agli altri] nelle assemblee”, allora fatelo: Allah vi farà spazio [in Paradiso]. E quando vi si dice: “Alzatevi”, fatelo. Allah innalzerà il livello di coloro che credono e che hanno ricevuto la scienza. Allah è ben informato di quel che fate.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا طُلب منكم أن يوسع بعضكم لبعض المجالس فأوسعوا، يوسع الله عليكم في الدنيا والآخرة، وإذا طلب منكم- أيها المؤمنون- أن تقوموا من مجالسكم لأمر من الأمور التي يكون فيها خير لكم فقوموا، يرفع الله مكانة المؤمنين المخلصين منكم، ويرفع مكانة أهل العلم درجات كثيرة في الثواب ومراتب الرضوان، والله تعالى خبير بأعمالكم لا يخفى عليه شيء منها، وهو مجازيكم عليها. وفي الآية تنويه بمكانة العلماء وفضلهم، ورفع درجاتهم."}}, "59:23": {"s": 59, "v": 23, "nom": {"ar": "سُورَةُ الحَشۡرِ", "lat": "Al-Hashr"}, "ar": "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", "tl": {"en": "Huwal-laahul-lazee laaa Ilaaha illaa Huwal-Malikul Quddoosus-Salaamul Muminul Muhaiminul-'aAzeezul Jabbaarul-Mutakabbir; Subhaanal laahi 'Ammaa yushrikoon", "tr": "hüve-llâhü-lleẕî lâ ilâhe illâ hû. elmelikü-lḳuddûsü-sselâmü-lmü'minü-lmüheyminü-l`azîzü-lcebbâru-lmütekebbir. sübḥâne-llâhi `ammâ yüşrikûn."}, "tr": {"fr": "C'est Lui, Allah. Nulle divinité autre que Lui; Le Souverain, Le Pur, L'Apaisant, Le Rassurant, Le Prédominant, Le Tout Puissant, Le Contraignant, L'Orgueilleux. Gloire à Allah! Il transcende ce qu'ils Lui associent.", "en": "He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him.", "id": "Dialah Allah Yang tiada Tuhan selain Dia, Raja, Yang Maha Suci, Yang Maha Sejahtera, Yang Mengaruniakan Keamanan, Yang Maha Memelihara, Yang Maha Perkasa, Yang Maha Kuasa, Yang Memiliki segala Keagungan, Maha Suci Allah dari apa yang mereka persekutukan.", "tr": "O, kendisinden başka tanrı olmayan, hükümran, çok kutsal; esenlik veren, güvenlik veren, görüp gözeten, güçlü, buyruğunu herşeye geçiren, ulu olan, Allah'tır. Allah onların koştukları eşlerden (ortaklardan) münezzehtir.", "de": "Er ist Allah, außer dem es keinen Gott gibt, der König, der Heilige, der Friede', der Gewährer der Sicherheit, der Wächter, der Allmächtige, der Gewalthaber, der Stolze. Preis sei Allah! (Und Erhaben ist Er) über das, was sie (Ihm) beigesellen.", "nl": "Hij is Allah, Degene naast Wie er geen god is dan Hij, de Heerser, de Heilige, de Schenker van veiligheid, de Vertrouwende, de Beschermer, de Almachtige, de Onweerstaanbare Onderwerper, de Trotse. Heilig is Hij boven wat zij Hem toekennen.", "es": "Es Alá -no hay más dios que Él-, el Rey, el Santísimo, la Paz, Quien da Seguridad, el Custodio, el Poderoso, el Fuerte, el Sumo. ¡Gloria a Alá! ¡Está por encima de lo que Le asocian!", "it": "Egli è Allah, Colui all'infuori del Quale non c'è altro dio, il Re, il Santo, la Pace, il Fedele, il Custode, l'Eccelso, Colui Che costringe al Suo volere, Colui Che è cosciente della Sua grandezza. Gloria ad Allah, ben al di là di quanto Gli associano.", "ar": "هو الله المعبود بحق، الذي لا إله إلا هو، الملك لجميع الأشياء، المتصرف فيها بلا ممانعة ولا مدافعة، المنزَّه عن كل نقص، الذي سلِم من كل عيب، المصدِّق رسله وأنبياءه بما ترسلهم به من الآيات البينات، الرقيب على كل خلقه في أعمالهم، العزيز الذي لا يغالَب، الجبار الذي قهر جميع العباد، وأذعن له سائر الخلق، المتكبِّر الذي له الكبرياء والعظمة. تنزَّه الله تعالى عن كل ما يشركونه به في عبادته."}}, "62:9": {"s": 62, "v": 9, "nom": {"ar": "سُورَةُ الجُمُعَةِ", "lat": "Al-Jumu'a"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", "tl": {"en": "Yaaa ayyuhal lazeena aamanoo izaa noodiya lis-Salaati miny yawmil Jumu'ati fas'aw ilaa zikril laahi wa zarul bai'; zaalikum khayrul lakum in kuntum ta'lamoon", "tr": "yâ eyyühe-lleẕîne âmenû iẕâ nûdiye liṣṣalâti miy yevmi-lcümü`ati fes`av ilâ ẕikri-llâhi veẕerü-lbey`. ẕâliküm ḫayrul leküm in küntüm ta`lemûn."}, "tr": {"fr": "O vous qui avez cru! Quand on appelle à la Salât du jour du Vendredi, accourez à l'invocation d'Allah et laissez tout négoce. Cela est bien meilleur pour vous, si vous saviez!", "en": "O you who have believed, when [the adhan] is called for the prayer on the day of Jumu'ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.", "id": "Hai orang-orang beriman, apabila diseru untuk menunaikan shalat Jum'at, maka bersegeralah kamu kepada mengingat Allah dan tinggalkanlah jual beli. Yang demikian itu lebih baik bagimu jika kamu mengetahui.", "tr": "Ey inananlar! Cuma günü namaz için ezan okunduğu zaman Allah'ı anmaya koşun; alım satımı bırakın; bilseniz, bu sizin için daha iyidir.", "de": "O die ihr glaubt, wenn zum Gebet gerufen wird am Freitag, dann eilt zu Allahs Gedenken und laßt das Kaufgeschäft. Das ist besser für euch, wenn ihr wißt.", "nl": "O jullie die geloven, wanneer jullie tot het vrijdaggebed worden geroepen, haast jullie dan naar het gedenken van Allah en laat de handel achter. Dat is beter voor jullie, als jullie het wisten!", "es": "¡Creyentes! Cuando se llame el viernes a la azalá, ¡corred a recordar a Alá y dejad el comercio! Es mejor para vosotros. Si supierais...", "it": "O credenti, quando viene fatto l'annuncio per l'orazione del Venerdì, accorrete al ricordo di Allah e lasciate ogni traffico. Ciò è meglio per voi, se lo sapeste.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا نادى المؤذن للصلاة في يوم الجمعة، فامضوا إلى سماع الخطبة وأداء الصلاة، واتركوا البيع، وكذلك الشراء وجميع ما يَشْغَلُكم عنها، ذلك الذي أُمرتم به خير لكم؛ لما فيه من غفران ذنوبكم ومثوبة الله لكم، إن كنتم تعلمون مصالح أنفسكم فافعلوا ذلك. وفي الآية دليل على وجوب حضور الجمعة واستماع الخطبة."}}, "66:6": {"s": 66, "v": 6, "nom": {"ar": "سُورَةُ التَّحۡرِيمِ", "lat": "At-Tahrim"}, "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًۭا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌۭ شِدَادٌۭ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ", "tl": {"en": "Yaaa ayyuhal lazeena samanoo qooo anfusakum wa ahleekum naaranw waqoodu han naasu wal hijaaratu 'alaihaa malaaa'ikatun ghilaazun shidaadul laa ya'soonal laaha maa amarahum wa yaf'aloona maa yu'maroon", "tr": "yâ eyyühe-lleẕîne âmenû ḳû enfüseküm veehlîküm nârav veḳûdühe-nnâsü velḥicâratü `aleyhâ melâiketün gilâżun şidâdül lâ ya`ṣûne-llâhe mâ emerahüm veyef`alûne mâ yü'merûn."}, "tr": {"fr": "O vous qui avez cru! Préservez vos personnes et vos familles, d'un Feu dont le combustible sera les gens et les pierres, surveillé par des Anges rudes, durs, ne désobéissant jamais à Allah en ce qu'Il leur commande, et faisant strictement ce qu'on leur ordonne.", "en": "O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.", "id": "Hai orang-orang yang beriman, peliharalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu; penjaganya malaikat-malaikat yang kasar, keras, dan tidak mendurhakai Allah terhadap apa yang diperintahkan-Nya kepada mereka dan selalu mengerjakan apa yang diperintahkan.", "tr": "Ey inananlar! Kendinizi ve çoluk çocuğunuzu cehennem ateşinden koruyun; onun yakıtı, insanlar ve taşlardır; görevlileri, Allah'ın kendilerine verdiği emirlere baş kaldırmayan, kendilerine buyrulanları yerine getiren pek haşin meleklerdir.", "de": "O die ihr glaubt, bewahrt euch selbst und eure Angehörigen vor einem Feuer, dessen Brennstoff Menschen und Steine sind, über das hartherzige, strenge Engel (gesetzt) sind, die sich Allah nicht widersetzen in dem, was Er ihnen befiehlt, sondern tun, was ihnen befohlen wird.", "nl": "O jullie die geloven, behoedt julliezelf en jullie gezinsleden voor de Hel, die als brandstof mensen en stenen heeft, waarover strenge en hard optredende Engelen zijn aangesteld, die Allah niet ongehoorzaam zijn in wat Hij hun beveelt, en die uitvoeren wat hun is bevolen.", "es": "¡Creyentes! Guardaos, vosotros y vuestras familias, de un Fuego cuyo combustible lo forman hombres y piedras, y sobre el que habrá ángeles gigantescos, poderosos, que no desobedecen a Alá en lo que les ordena, sino que hacen lo que se les ordena.", "it": "O credenti, preservate voi stessi e le vostre famiglie, da un fuoco il cui combustibile saranno uomini e pietre e sul quale vegliano angeli formidabili, severi, che non disobbediscono a ciò che Allah comanda loro e che eseguono quello che viene loro ordinato.", "ar": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، احفظوا أنفسكم بفعل ما أمركم الله به وترك ما نهاكم عنه، واحفظوا أهليكم بما تحفظون به أنفسكم من نار وقودها الناس والحجارة، يقوم على تعذيب أهلها ملائكة أقوياء قساة في معاملاتهم، لا يخالفون الله في أمره، وينفذون ما يؤمرون به."}}, "68:4": {"s": 68, "v": 4, "nom": {"ar": "سُورَةُ القَلَمِ", "lat": "Al-Qalam"}, "ar": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ", "tl": {"en": "Wa innaka la'alaa khuluqin 'azeem", "tr": "veinneke le`alâ ḫulüḳin `ażîm."}, "tr": {"fr": "Et tu es certes, d'une moralité éminente.", "en": "And indeed, you are of a great moral character.", "id": "Dan sesungguhnya kamu benar-benar berbudi pekerti yang agung.", "tr": "Şüphesiz sen büyük bir ahlaka sahipsindir.", "de": "Und du bist wahrlich von großartiger Wesensart.", "nl": "En voorwaar, jij beschikt over een hoogstaand karakter.", "es": "Eres, sí, de eminente carácter.", "it": "e in verità di un'immensa grandezza è il tuo carattere.", "ar": "(ن) سبق الكلام على الحروف المقطعة في أول سورة البقرة. أقسم الله بالقلم الذي يكتب به الملائكة والناس، وبما يكتبون من الخير والنفع والعلوم. ما أنت -أيها الرسول- بسبب نعمة الله عليك بالنبوة والرسالة بضعيف العقل، ولا سفيه الرأي، وإن لك على ما تلقاه من شدائد على تبليغ الرسالة لَثوابًا عظيمًا غير منقوص ولا مقطوع، وإنك -أيها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القرآن من مكارم الأخلاق؛ فقد كان امتثال القرآن سجية له يأتمر بأمره، وينتهي عما ينهى عنه."}}, "82:10": {"s": 82, "v": 10, "nom": {"ar": "سُورَةُ الانفِطَارِ", "lat": "Al-Infitaar"}, "ar": "وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ", "tl": {"en": "Wa inna 'alaikum lahaa fizeen", "tr": "veinne `aleyküm leḥâfiżîn."}, "tr": {"fr": "alors que veillent sur vous des gardiens,", "en": "And indeed, [appointed] over you are keepers,", "id": "Padahal sesungguhnya bagi kamu ada (malaikat-malaikat) yang mengawasi (pekerjaanmu),", "tr": "Oysa, yaptıklarınızı bilen değerli yazıcılar sizi gözetlemektedirler.", "de": "Über euch sind wahrlich Hüter (eingesetzt),", "nl": "En voorwaar, er zijn zeker bewakers (Engelen) over jullie.", "es": "pero hay quienes os guardan:", "it": "nonostante [veglino] su di voi dei custodi,", "ar": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر."}}, "82:11": {"s": 82, "v": 11, "nom": {"ar": "سُورَةُ الانفِطَارِ", "lat": "Al-Infitaar"}, "ar": "كِرَامًۭا كَٰتِبِينَ", "tl": {"en": "Kiraaman kaatibeen", "tr": "kirâmen kâtibîn."}, "tr": {"fr": "de nobles scribes,", "en": "Noble and recording;", "id": "yang mulia (di sisi Allah) dan mencatat (pekerjaan-pekerjaanmu itu),", "tr": "Oysa, yaptıklarınızı bilen değerli yazıcılar sizi gözetlemektedirler.", "de": "edle, die (alles) aufschreiben", "nl": "Eervollen, schrijvenden.", "es": "nobles, escribas,", "it": "nobili scribi,", "ar": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر."}}, "96:1": {"s": 96, "v": 1, "nom": {"ar": "سُورَةُ العَلَقِ", "lat": "Al-Alaq"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ", "tl": {"en": "Iqra bismi rab bikal lazee khalaq", "tr": "iḳra' bismi rabbike-lleẕî ḫaleḳ."}, "tr": {"fr": "Lis, au nom de ton Seigneur qui a créé,", "en": "Recite in the name of your Lord who created -", "id": "Bacalah dengan (menyebut) nama Tuhanmu Yang menciptakan,", "tr": "Yaratan Rabbinin adıyla oku!", "de": "Lies im Namen deines Herrn, Der erschaffen hat,", "nl": "Lees voor! In de naam van jouw Heer, Die heeft geschapen.", "es": "¡Recita en el nombre de tu Señor, Que ha creado,", "it": "Leggi! In nome del tuo Signore che ha creato,", "ar": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم."}}, "97:1": {"s": 97, "v": 1, "nom": {"ar": "سُورَةُ القَدۡرِ", "lat": "Al-Qadr"}, "ar": "بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ", "tl": {"en": "Innaa anzalnaahu fee lailatil qadr", "tr": "innâ enzelnâhü fî leyleti-lḳadr."}, "tr": {"fr": "Nous l'avons certes, fait descendre (le Coran) pendant la nuit d'Al-Qadr.", "en": "Indeed, We sent the Qur'an down during the Night of Decree.", "id": "Sesungguhnya Kami telah menurunkannya (Al Quran) pada malam kemuliaan.", "tr": "Doğrusu, Biz, Kuran'ı kadir gecesinde indirmişizdir.", "de": "Wir haben ihn ja in der Nacht der Bestimmung hinabgesandt.", "nl": "Voorwaar, Wij hebben hem (de Koran) neergezonden in de Waardevolle Nacht (Lailatoel Qadr).", "es": "Lo hemos revelado en la noche del Destino.", "it": "Invero lo abbiamo fatto scendere nella Notte del Destino.", "ar": "إنا أنزلنا القرآن في ليلة الشرف والفضل، وهي إحدى ليالي شهر رمضان."}}, "97:3": {"s": 97, "v": 3, "nom": {"ar": "سُورَةُ القَدۡرِ", "lat": "Al-Qadr"}, "ar": "لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ", "tl": {"en": "Lailatul qadri khairum min alfee shahr", "tr": "leyletü-lḳadri ḫayrum min elfi şehr."}, "tr": {"fr": "La nuit d'Al-Qadr est meilleure que mille mois.", "en": "The Night of Decree is better than a thousand months.", "id": "Malam kemuliaan itu lebih baik dari seribu bulan.", "tr": "Kadir gecesi bin aydan hayırlıdır.", "de": "Die Nacht der Bestimmung ist besser als tausend Monate.", "nl": "De Waardevolle Nacht is beter dan duizend maanden.", "es": "La noche del Destino vale más de mil meses.", "it": "La Notte del Destino è migliore di mille mesi.", "ar": "ليلة القدر ليلة مباركة، فَضْلُها خير من فضل ألف شهر ليس فيها ليلة قدر."}}, "97:4": {"s": 97, "v": 4, "nom": {"ar": "سُورَةُ القَدۡرِ", "lat": "Al-Qadr"}, "ar": "تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ", "tl": {"en": "Tanaz zalul malaa-ikatu war roohu feeha bi izni-rab bihim min kulli amr", "tr": "tenezzelü-lmelâiketü verrûḥu fîhâ biiẕni rabbihim. min külli emr."}, "tr": {"fr": "Durant celle-ci descendent les Anges ainsi que l'Esprit, par permission de leur Seigneur pour tout ordre.", "en": "The angels and the Spirit descend therein by permission of their Lord for every matter.", "id": "Pada malam itu turun malaikat-malaikat dan malaikat Jibril dengan izin Tuhannya untuk mengatur segala urusan.", "tr": "Melekler ve Cebrail o gecede Rablerinin izniyle her türlü iş için inerler.", "de": "Es kommen die Engel und der Geist in ihr mit der Erlaubnis ihres Herrn mit jeder Angelegenheit herab.", "nl": "De Engelen en de Geest (Djibrîl) daalden in haar neer met de toestemming van hun Heer, voor elke beschikking.", "es": "Los ángeles y el Espíritu descienden en ella, con permiso de su Señor, para fijarlo todo.", "it": "In essa discendono gli angeli e lo Spirito, con il permesso del loro Signore, per [fissare] ogni decreto.", "ar": "يكثر نزول الملائكة وجبريل عليه السلام فيها، بإذن ربهم من كل أمر قضاه في تلك السنة."}}, "97:5": {"s": 97, "v": 5, "nom": {"ar": "سُورَةُ القَدۡرِ", "lat": "Al-Qadr"}, "ar": "سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ", "tl": {"en": "Salaamun hiya hattaa mat la'il fajr", "tr": "selâmün. hiye ḥattâ maṭle`i-lfecr."}, "tr": {"fr": "Elle est paix et salut jusqu'à l'apparition de l'aube.", "en": "Peace it is until the emergence of dawn.", "id": "Malam itu (penuh) kesejahteraan sampai terbit fajar.", "tr": "O gece, tan yerinin ağarmasına kadar bir esenliktir.", "de": "Frieden ist sie bis zum Anbruch der Morgendämmerung.", "nl": "Vrede heerst (in deze nacht), tot aan de ochtendschemering.", "es": "¡Es una noche de paz, hasta el rayar del alba!", "it": "È pace, fino al levarsi dell'alba.", "ar": "هي أمن كلها، لا شرَّ فيها إلى مطلع الفجر."}}, "99:7": {"s": 99, "v": 7, "nom": {"ar": "سُورَةُ الزَّلۡزَلَةِ", "lat": "Az-Zalzala"}, "ar": "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ", "tl": {"en": "Famaiy ya'mal mithqala zarratin khai raiy-yarah", "tr": "femey ya`mel miŝḳâle ẕerratin ḫayray yerah."}, "tr": {"fr": "Quiconque fait un bien fût-ce du poids d'un atome, le verra,", "en": "So whoever does an atom's weight of good will see it,", "id": "Barangsiapa yang mengerjakan kebaikan seberat dzarrahpun, niscaya dia akan melihat (balasan)nya.", "tr": "Kim zerre kadar iyilik yapmışsa onu görür.", "de": "Wer nun im Gewicht eines Stäubchens Gutes tut, wird es sehen.", "nl": "Wie iets goeds deed ter grootte van een mosterdzaadje, zal het dan zien.", "es": "Quien haya hecho el peso de un átomo de bien, lo verá.", "it": "Chi avrà fatto [anche solo] il peso di un atomo di bene lo vedrà,", "ar": "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة."}}, "99:8": {"s": 99, "v": 8, "nom": {"ar": "سُورَةُ الزَّلۡزَلَةِ", "lat": "Az-Zalzala"}, "ar": "وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ", "tl": {"en": "Wa maiy-y'amal mithqala zarratin sharraiy-yarah", "tr": "vemey ya`mel miŝḳâle ẕerratin şerray yerah."}, "tr": {"fr": "et quiconque fait un mal fût-ce du poids d'un atome, le verra.", "en": "And whoever does an atom's weight of evil will see it.", "id": "Dan barangsiapa yang mengerjakan kejahatan sebesar dzarrahpun, niscaya dia akan melihat (balasan)nya pula.", "tr": "Kim de zerre kadar kötülük yapmışsa onu görür.", "de": "Und wer im Gewicht eines Stäubchens Böses tut, wird es sehen.", "nl": "En wie iets kwaads deed ter grootte van een mosterdzaadje, zal het dan zien.", "es": "Y quien haya hecho el peso de un átomo de mal, lo verá.", "it": "e chi avrà fatto [anche solo] il peso di un atomo di male lo vedrà.", "ar": "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة."}}, "101:1": {"s": 101, "v": 1, "nom": {"ar": "سُورَةُ القَارِعَةِ", "lat": "Al-Qaari'a"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْقَارِعَةُ", "tl": {"en": "Al qaari'ah", "tr": "elḳâri`ah."}, "tr": {"fr": "Le fracas!", "en": "The Striking Calamity -", "id": "Hari Kiamat,", "tr": "Gürültü koparacak olan", "de": "Das Verhängnis!", "nl": "De Daverende (De Dag der Opstanding).", "es": "¡La Calamidad!", "it": "La Percotente,", "ar": "الساعة التي تقرع قلوب الناس بأهوالها."}}, "105:1": {"s": 105, "v": 1, "nom": {"ar": "سُورَةُ الفِيلِ", "lat": "Al-Fil"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ", "tl": {"en": "Alam tara kaifa fa'ala rabbuka bi ashaabil feel", "tr": "elem tera keyfe fe`ale rabbüke biaṣḥâbi-lfîl."}, "tr": {"fr": "N'as-tu pas vu comment ton Seigneur a agi envers les gens de l'Eléphant?", "en": "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?", "id": "Apakah kamu tidak memperhatikan bagaimana Tuhanmu telah bertindak terhadap tentara bergajah?", "tr": "Fil sahiplerine Rabbinin ne ettiğini görmedin mi?", "de": "Siehst du nicht, wie dein Herr mit den Leuten des Elefanten verfuhr?", "nl": "Heb jij niet vernomen hoe jouw Heer met de mensen van de olifant heeft gehandeld?", "es": "¿No has visto cómo obró tu Señor con los del elefante?", "it": "Non hai visto come agì il tuo Signore con quelli dell’elefante?", "ar": "ألم تعلم -أيها الرسول- كيف فعل ربك بأصحاب الفيل: أبرهة الحبشي وجيشه الذين أرادوا تدمير الكعبة المباركة؟"}}, "108:1": {"s": 108, "v": 1, "nom": {"ar": "سُورَةُ الكَوۡثَرِ", "lat": "Al-Kawthar"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ", "tl": {"en": "Innaa a'taina kal kauthar", "tr": "innâ a`ṭaynâke-lkevŝer."}, "tr": {"fr": "Nous t'avons certes, accordé l'Abondance.", "en": "Indeed, We have granted you, [O Muhammad], al-Kawthar.", "id": "Sesungguhnya Kami telah memberikan kepadamu nikmat yang banyak.", "tr": "Doğrusu sana pek çok nimet vermişizdir.", "de": "Wir haben dir ja al-Kautar gegeben.", "nl": "Waarlijk, Wij hebben jou de overvloed geschonken.", "es": "Te hemos dado la abundancia.", "it": "In verità ti abbiamo dato l’abbondanza.", "ar": "إنا أعطيناك -أيها النبي- الخير الكثير في الدنيا والآخرة، ومن ذلك نهر الكوثر في الجنة الذي حافتاه خيام اللؤلؤ المجوَّف، وطينه المسك."}}, "110:1": {"s": 110, "v": 1, "nom": {"ar": "سُورَةُ النَّصۡرِ", "lat": "An-Nasr"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ", "tl": {"en": "Iza jaa-a nas rullahi walfath", "tr": "iẕâ câe naṣru-llâhi velfetḥ."}, "tr": {"fr": "Lorsque vient le secours d'Allah ainsi que la victoire,", "en": "When the victory of Allah has come and the conquest,", "id": "Apabila telah datang pertolongan Allah dan kemenangan,", "tr": "Allah'ın yardımı ve zafer günü gelip, insanların Allah'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.", "de": "Wenn Allahs Hilfe kommt und der Sieg", "nl": "Als de hulp van Allah en de overwinning zijn gekomen.", "es": "Cuando venga el auxilio de Alá, así como el éxito,", "it": "Quando verrà l’ausilio di Allah e la vittoria,", "ar": "إذا تمَّ لك -أيها الرسول- النصر على كفار قريش، وتم لك فتح \"مكة\"."}}, "110:2": {"s": 110, "v": 2, "nom": {"ar": "سُورَةُ النَّصۡرِ", "lat": "An-Nasr"}, "ar": "وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا", "tl": {"en": "Wa ra-aitan naasa yadkhuloona fee deenil laahi afwajah", "tr": "veraeyte-nnâse yedḫulûne fî dîni-llâhi efvâcâ."}, "tr": {"fr": "et que tu vois les gens entrer en foule dans la religion d'Allah,", "en": "And you see the people entering into the religion of Allah in multitudes,", "id": "dan kamu lihat manusia masuk agama Allah dengan berbondong-bondong,", "tr": "Allah'ın yardımı ve zafer günü gelip, insanların Allah'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.", "de": "und du die Menschen in Allahs Religion in Scharen eintreten siehst,", "nl": "En jij (O Mohammed) de mensen in grote groepen tot de godsdienst van Allah ziet toetreden.", "es": "y veas que los hombres entran en masa en la religión de Alá,", "it": "e vedrai le genti entrare in massa nella religione di Allah,", "ar": "ورأيت الكثير من الناس يدخلون في الإسلام جماعات جماعات."}}, "110:3": {"s": 110, "v": 3, "nom": {"ar": "سُورَةُ النَّصۡرِ", "lat": "An-Nasr"}, "ar": "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا", "tl": {"en": "Fa sab bih bihamdi rabbika was taghfir, innahu kaana tawwaaba", "tr": "fesebbiḥ biḥamdi rabbike vestagfirh. innehû kâne tevvâbâ."}, "tr": {"fr": "alors, par la louange, célèbre la gloire de ton Seigneur et implore Son pardon. Car c'est Lui le grand Accueillant au repentir.", "en": "Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.", "id": "maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sesungguhnya Dia adalah Maha Penerima taubat.", "tr": "Allah'ın yardımı ve zafer günü gelip, insanların Allah'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.", "de": "dann lobpreise deinen Herrn und bitte Ihn um Vergebung; gewiß, Er ist Reueannehmend.", "nl": "Prijs dan de Glorie van jouw Heer en vraag Hem om vergeving. Voorwaar, Hij is Berouwaanvaardend.", "es": "entonces, ¡celebra las alabanzas de tu Señor y pide Su perdón! Es indulgente.", "it": "glorifica il tuo Signore lodandoLo e chiediGli perdono: in verità Egli è Colui che accetta il pentimento.", "ar": "إذا وقع ذلك فتهيأ للقاء ربك بالإكثار من التسبيح بحمده والإكثار من استغفاره، إنه كان توابًا على المسبحين والمستغفرين، يتوب عليهم ويرحمهم ويقبل توبتهم."}}, "112:1": {"s": 112, "v": 1, "nom": {"ar": "سُورَةُ الإِخۡلَاصِ", "lat": "Al-Ikhlaas"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ هُوَ ٱللَّهُ أَحَدٌ", "tl": {"en": "Qul huwal laahu ahad", "tr": "ḳul hüve-llâhü eḥad."}, "tr": {"fr": "Dis: «Il est Allah, Unique.", "en": "Say, \"He is Allah, [who is] One,", "id": "Katakanlah: \"Dialah Allah, Yang Maha Esa.", "tr": "De ki: O Allah bir tektir.", "de": "Sag: Er ist Allah, ein Einer,", "nl": "Zeg: \"Hij is Allah, de Enige.", "es": "Di: «¡Él es Alá, Uno,", "it": "Di’: “Egli Allah è Unico,", "ar": "قل -أيها الرسول-: هو الله المتفرد بالألوهية والربوبية والأسماء والصفات، لا يشاركه أحد فيها."}}, "112:2": {"s": 112, "v": 2, "nom": {"ar": "سُورَةُ الإِخۡلَاصِ", "lat": "Al-Ikhlaas"}, "ar": "ٱللَّهُ ٱلصَّمَدُ", "tl": {"en": "Allah hus-samad", "tr": "allâhu-ṣṣamed."}, "tr": {"fr": "Allah, Le Seul à être imploré pour ce que nous désirons.", "en": "Allah, the Eternal Refuge.", "id": "Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu.", "tr": "Allah her şeyden müstağni ve her şey O'na muhtaçtır.", "de": "Allah, der Überlegene.", "nl": "Allah is de Enige van Wie al het geschapene afhankelijk is.", "es": "Dios, el Eterno.", "it": "Allah è l’Assoluto.", "ar": "الله وحده المقصود في قضاء الحوائج والرغائب."}}, "112:3": {"s": 112, "v": 3, "nom": {"ar": "سُورَةُ الإِخۡلَاصِ", "lat": "Al-Ikhlaas"}, "ar": "لَمْ يَلِدْ وَلَمْ يُولَدْ", "tl": {"en": "Lam yalid wa lam yoolad", "tr": "lem yelid velem yûled."}, "tr": {"fr": "Il n'a jamais engendré, n'a pas été engendré non plus.", "en": "He neither begets nor is born,", "id": "Dia tiada beranak dan tidak pula diperanakkan,", "tr": "O doğurmamış ve doğmamıştır.", "de": "Er hat nicht gezeugt und ist nicht gezeugt worden,", "nl": "Hij heeft niet verwekt en is niet verwekt.", "es": "No ha engendrado, ni ha sido engendrado.", "it": "Non ha generato, non è stato generato", "ar": "ليس له ولد ولا والد ولا صاحبة."}}, "112:4": {"s": 112, "v": 4, "nom": {"ar": "سُورَةُ الإِخۡلَاصِ", "lat": "Al-Ikhlaas"}, "ar": "وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ", "tl": {"en": "Wa lam yakul-lahu kufuwan ahad", "tr": "velem yekül lehû küfüven eḥad."}, "tr": {"fr": "Et nul n'est égal à Lui».", "en": "Nor is there to Him any equivalent.\"", "id": "dan tidak ada seorangpun yang setara dengan Dia\".", "tr": "Hiçbir şey O'na denk değildir.", "de": "und niemand ist Ihm jemals gleich.", "nl": "En niet één is aan Hem gelijkwaardig.\"", "es": "No tiene par».", "it": "e nessuno è eguale a Lui”.", "ar": "ولم يكن له مماثلا ولا مشابهًا أحد من خلقه، لا في أسمائه ولا في صفاته، ولا في أفعاله، تبارك وتعالى وتقدَّس."}}, "114:1": {"s": 114, "v": 1, "nom": {"ar": "سُورَةُ النَّاسِ", "lat": "An-Naas"}, "ar": "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ", "tl": {"en": "Qul a'uzu birabbin naas", "tr": "ḳul e`ûẕü birabbi-nnâs."}, "tr": {"fr": "Dis: «Je cherche protection auprès du Seigneur des hommes.", "en": "Say, \"I seek refuge in the Lord of mankind,", "id": "Katakanlah: \"Aku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia.", "tr": "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım.\"", "de": "Sag: Ich nehme Zuflucht beim Herrn der Menschen,", "nl": "Zeg: \"Ik zoek bescherming bij de Heer van de mensen.", "es": "Di: «Me refugio en el Señor de los hombres,", "it": "Di’: “Mi rifugio nel Signore degli uomini,", "ar": "قل -أيها الرسول-: أعوذ وأعتصم برب الناس، القادر وحده على ردِّ شر الوسواس."}}};
const HADITHS={"piliers": {"refs": [["bukhari", 8], ["muslim", 16]], "txt": {"ar": "حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، قَالَ أَخْبَرَنَا حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ، عَنْ عِكْرِمَةَ بْنِ خَالِدٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ ‏\"‏‏.‏", "en": "Narrated Ibn 'Umar: Allah's Messenger (ﷺ) said: Islam is based on (the following) five (principles): 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah's Messenger (ﷺ). 2. To offer the (compulsory congregational) prayers dutifully and perfectly. 3. To pay Zakat (i.e. obligatory charity) . 4. To perform Hajj. (i.e. Pilgrimage to Mecca) 5. To observe fast during the month of Ramadan", "fr": "Rapporté par Ibn 'Umar : Le Messager d'Allah (ﷺ) a dit : L'islam repose sur cinq principes : 1. Attester qu'il n'y a de dieu qu'Allah et que Muhammad est le Messager d'Allah (ﷺ). 2. Accomplir les prières obligatoires avec sérieux et régularité. 3. Donner la Zakat (l'aumône obligatoire). 4. Faire le Hajj (le pèlerinage à La Mecque). 5. Jeûner pendant le mois de Ramadan", "id": "Telah menceritakan kepada kami [Abdullah bin Musa] dia berkata, telah mengabarkan kepada kami [Hanzhalah bin Abu Sufyan] dari ['Ikrimah bin Khalid] dari [Ibnu Umar] berkata: Rasulullah shallallahu 'alaihi wasallam bersabda: \"Islam dibangun diatas lima (landasan); persaksian tidak ada ilah selain Allah dan sesungguhnya Muhammad utusan Allah, mendirikan shalat, menunaikan zakat, haji dan puasa Ramadlan", "tr": "İbn-i Ömer r.a.’den Resulullah sallallahu aleyhi ve sellem buyurdu ki: İslam beş şey üzerine bina olunmuştur: Allah`dan başka ilâh olmadığına ve Muhammed`in (sallallahu aleyhi ve sellem)'in Allâh`ın Resulü olduğuna Şahadet etmek, Namaz kılmak, Zekat vermek, Haccetmek, Ramazan orucunu tutmaktır. Tekrarı: 4515 (Diğer Tahric edenler: Müslim, İman; Tirmizî, İman)"}}, "croissant": {"refs": [["bukhari", 1909], ["muslim", 1081]], "txt": {"ar": "حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا مُحَمَّدُ بْنُ زِيَادٍ، قَالَ سَمِعْتُ أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ يَقُولُ قَالَ النَّبِيُّ صلى الله عليه وسلم أَوْ قَالَ قَالَ أَبُو الْقَاسِمِ صلى الله عليه وسلم ‏ \"‏ صُومُوا لِرُؤْيَتِهِ، وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ غُبِّيَ عَلَيْكُمْ فَأَكْمِلُوا عِدَّةَ شَعْبَانَ ثَلاَثِينَ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:The Prophet (ﷺ) or Abul-Qasim said, \"Start fasting on seeing the crescent (of Ramadan), and give up fasting on seeing the crescent (of Shawwal), and if the sky is overcast (and you cannot see it), complete thirty days of Sha'ban", "fr": "Rapporté par Abu Huraira : Le Prophète (ﷺ) ou Abul-Qasim a dit : « Commencez à jeûner en voyant le croissant (de Ramadan), et arrêtez de jeûner en voyant le croissant (de Shawwal), et si le ciel est couvert (et que vous ne pouvez pas le voir), complétez trente jours de Sha'ban. »", "id": "Telah menceritakan kepada kami [Adam] telah menceritakan kepada kami [Syu'bah] telah menceritakan kepada kami [Muhammad bin Ziyad] berkata, aku mendengar [Abu Hurairah radliallahu 'anhu] berkata; Nabi shallallahu 'alaihi wasallam bersabda, atau katanya Abu Al Qasim shallallahu 'alaihi wasallam telah bersabda: \"Berpuasalah kalian dengan melihatnya (hilal) dan berbukalah dengan melihatnya pula. Apabila kalian terhalang oleh awan maka sempurnakanlah jumlah bilangan hari bulan Sya'ban menjadi tiga puluh", "tr": "Ebu Hureyre'nin naklettiğine göre Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Hilal'i gördüğünüzde oruç tutun ve hilal'i yeniden gördüğünüzde oruç tutmayı bırakın. Hilal'i göremezseniz Şa'ban ayını otuz güne tamamlayın!\" DİKKAT: Şa'ban gibi dünya'nın en güzel isimlerinden birini geri zekalılıkla eşleştiren Kemal Sunal ve bunu tesis eden tüm kişileri ... ile anıyoruz. 2013 te Türkiye de sadece 120 civarında Şa'ban isimli kişi nüfusa kayıtlı bulunmaktadır. Osmanlı'yı da Rahmetle anıyoruz ki: Muhammed ismi ile alay edilme endişesi ile Mehmet ismini çıkardılar"}}, "cinq": {"refs": [["bukhari", 349], ["muslim", 162]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ يُونُسَ، عَنِ ابْنِ شِهَابٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كَانَ أَبُو ذَرٍّ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ فُرِجَ عَنْ سَقْفِ بَيْتِي وَأَنَا بِمَكَّةَ، فَنَزَلَ جِبْرِيلُ فَفَرَجَ صَدْرِي، ثُمَّ غَسَلَهُ بِمَاءِ زَمْزَمَ، ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا، فَأَفْرَغَهُ فِي صَدْرِي ثُمَّ أَطْبَقَهُ، ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَى السَّمَاءِ الدُّنْيَا، فَلَمَّا جِئْتُ إِلَى السَّمَاءِ الدُّنْيَا قَالَ جِبْرِيلُ لِخَازِنِ السَّمَاءِ افْتَحْ‏.‏ قَالَ مَنْ هَذَا قَالَ هَذَا جِبْرِيلُ‏.‏ قَالَ هَلْ مَعَكَ أَحَدٌ قَالَ نَعَمْ مَعِي مُحَمَّدٌ صلى الله عليه وسلم‏.‏ فَقَالَ أُرْسِلَ إِلَيْهِ قَالَ نَعَمْ‏.‏ فَلَمَّا فَتَحَ عَلَوْنَا السَّمَاءَ الدُّنْيَا، فَإِذَا رَجُلٌ قَاعِدٌ عَلَى يَمِينِهِ أَسْوِدَةٌ وَعَلَى يَسَارِهِ أَسْوِدَةٌ، إِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ، وَإِذَا نَظَرَ قِبَلَ يَسَارِهِ بَكَى، فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالاِبْنِ الصَّالِحِ‏.‏ قُلْتُ لِجِبْرِيلَ مَنْ هَذَا قَالَ هَذَا آدَمُ‏.‏ وَهَذِهِ الأَسْوِدَةُ عَنْ يَمِينِهِ وَشِمَالِهِ نَسَمُ بَنِيهِ، فَأَهْلُ الْيَمِينِ مِنْهُمْ أَهْلُ الْجَنَّةِ، وَالأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ، فَإِذَا نَظَرَ عَنْ يَمِينِهِ ضَحِكَ، وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى، حَتَّى عَرَجَ بِي إِلَى السَّمَاءِ الثَّانِيَةِ فَقَالَ لِخَازِنِهَا افْتَحْ‏.‏ فَقَالَ لَهُ خَازِنُهَا مِثْلَ مَا قَالَ الأَوَّلُ فَفَتَحَ ‏\"‏‏.‏ قَالَ أَنَسٌ فَذَكَرَ أَنَّهُ وَجَدَ فِي السَّمَوَاتِ آدَمَ وَإِدْرِيسَ وَمُوسَى وَعِيسَى وَإِبْرَاهِيمَ ـ صَلَوَاتُ اللَّهِ عَلَيْهِمْ ـ وَلَمْ يُثْبِتْ كَيْفَ مَنَازِلُهُمْ، غَيْرَ أَنَّهُ ذَكَرَ أَنَّهُ وَجَدَ آدَمَ فِي السَّمَاءِ الدُّنْيَا، وَإِبْرَاهِيمَ فِي السَّمَاءِ السَّادِسَةِ‏.‏ قَالَ أَنَسٌ فَلَمَّا مَرَّ جِبْرِيلُ بِالنَّبِيِّ صلى الله عليه وسلم بِإِدْرِيسَ قَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ‏.‏ فَقُلْتُ مَنْ هَذَا قَالَ هَذَا إِدْرِيسُ‏.‏ ثُمَّ مَرَرْتُ بِمُوسَى فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ‏.‏ قُلْتُ مَنْ هَذَا قَالَ هَذَا مُوسَى‏.‏ ثُمَّ مَرَرْتُ بِعِيسَى فَقَالَ مَرْحَبًا بِالأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ‏.‏ قُلْتُ مَنْ هَذَا قَالَ هَذَا عِيسَى‏.‏ ثُمَّ مَرَرْتُ بِإِبْرَاهِيمَ فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالاِبْنِ الصَّالِحِ‏.‏ قُلْتُ مَنْ هَذَا قَالَ هَذَا إِبْرَاهِيمُ صلى الله عليه وسلم ‏\"‏‏.‏ قَالَ ابْنُ شِهَابٍ فَأَخْبَرَنِي ابْنُ حَزْمٍ أَنَّ ابْنَ عَبَّاسٍ وَأَبَا حَبَّةَ الأَنْصَارِيَّ كَانَا يَقُولاَنِ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ ثُمَّ عُرِجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الأَقْلاَمِ ‏\"‏‏.‏ قَالَ ابْنُ حَزْمٍ وَأَنَسُ بْنُ مَالِكٍ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ فَفَرَضَ اللَّهُ عَلَى أُمَّتِي خَمْسِينَ صَلاَةً، فَرَجَعْتُ بِذَلِكَ حَتَّى مَرَرْتُ عَلَى مُوسَى فَقَالَ مَا فَرَضَ اللَّهُ لَكَ عَلَى أُمَّتِكَ قُلْتُ فَرَضَ خَمْسِينَ صَلاَةً‏.‏ قَالَ فَارْجِعْ إِلَى رَبِّكَ، فَإِنَّ أُمَّتَكَ لاَ تُطِيقُ ذَلِكَ‏.‏ فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَى مُوسَى قُلْتُ وَضَعَ شَطْرَهَا‏.‏ فَقَالَ رَاجِعْ رَبَّكَ، فَإِنَّ أُمَّتَكَ لاَ تُطِيقُ، فَرَاجَعْتُ فَوَضَعَ شَطْرَهَا، فَرَجَعْتُ إِلَيْهِ فَقَالَ ارْجِعْ إِلَى رَبِّكَ، فَإِنَّ أُمَّتَكَ لاَ تُطِيقُ ذَلِكَ، فَرَاجَعْتُهُ‏.‏ فَقَالَ هِيَ خَمْسٌ وَهْىَ خَمْسُونَ، لاَ يُبَدَّلُ الْقَوْلُ لَدَىَّ‏.‏ فَرَجَعْتُ إِلَى مُوسَى فَقَالَ رَاجِعْ رَبَّكَ‏.‏ فَقُلْتُ اسْتَحْيَيْتُ مِنْ رَبِّي‏.‏ ثُمَّ انْطَلَقَ بِي حَتَّى انْتَهَى بِي إِلَى سِدْرَةِ الْمُنْتَهَى، وَغَشِيَهَا أَلْوَانٌ لاَ أَدْرِي مَا هِيَ، ثُمَّ أُدْخِلْتُ الْجَنَّةَ، فَإِذَا فِيهَا حَبَايِلُ اللُّؤْلُؤِ، وَإِذَا تُرَابُهَا الْمِسْكُ ‏\"‏‏.‏", "en": "Narrated Abu Dhar:Allah's Messenger (ﷺ) said, \"While I was at Mecca the roof of my house was opened and Gabriel descended, opened my chest, and washed it with Zamzam water. Then he brought a golden tray full of wisdom and faith and having poured its contents into my chest, he closed it. Then he took my hand and ascended with me to the nearest heaven, when I reached the nearest heaven, Gabriel said to the gatekeeper of the heaven, 'Open (the gate).' The gatekeeper asked, 'Who is it?' Gabriel answered: 'Gabriel.' He asked, 'Is there anyone with you?' Gabriel replied, 'Yes, Muhammad I is with me.' He asked, 'Has he been called?' Gabriel said, 'Yes.' So the gate was opened and we went over the nearest heaven and there we saw a man sitting with some people on his right and some on his left. When he looked towards his right, he laughed and when he looked toward his left he wept. Then he said, 'Welcome! O pious Prophet and pious son.' I asked Gabriel, 'Who is he?' He replied, 'He is Adam and the people on his right and left are the souls of his offspring. Those on his right are the people of Paradise and those on his left are the people of Hell and when he looks towards his right he laughs and when he looks towards his left he weeps.' Then he ascended with me till he reached the second heaven and he (Gabriel) said to its gatekeeper, 'Open (the gate).' The gatekeeper said to him the same as the gatekeeper of the first heaven had said and he opened the gate. Anas said: \"Abu Dhar added that the Prophet (ﷺ) met Adam, Idris, Moses, Jesus and Abraham, he (Abu Dhar) did not mention on which heaven they were but he mentioned that he (the Prophet (ﷺ) ) met Adam on the nearest heaven and Abraham on the sixth heaven. Anas said, \"When Gabriel along with the Prophet (ﷺ) passed by Idris, the latter said, 'Welcome! O pious Prophet and pious brother.' The Prophet (ﷺ) asked, 'Who is he?' Gabriel replied, 'He is Idris.\" The Prophet (ﷺ) added, \"I passed by Moses and he said, 'Welcome! O pious Prophet and pious brother.' I asked Gabriel, 'Who is he?' Gabriel replied, 'He is Moses.' Then I passed by Jesus and he said, 'Welcome! O pious brother and pious Prophet.' I asked, 'Who is he?' Gabriel replied, 'He is Jesus. Then I passed by Abraham and he said, 'Welcome! O pious Prophet and pious son.' I asked Gabriel, 'Who is he?' Gabriel replied, 'He is Abraham. The Prophet (ﷺ) added, 'Then Gabriel ascended with me to a place where I heard the creaking of the pens.\" Ibn Hazm and Anas bin Malik said: The Prophet (ﷺ) said, \"Then Allah enjoined fifty prayers on my followers when I returned with this order of Allah, I passed by Moses who asked me, 'What has Allah enjoined on your followers?' I replied, 'He has enjoined fifty prayers on them.' Moses said, 'Go back to your Lord (and appeal for reduction) for your followers will not be able to bear it.' (So I went back to Allah and requested for reduction) and He reduced it to half. When I passed by Moses again and informed him about it, he said, 'Go back to your Lord as your followers will not be able to bear it.' So I returned to Allah and requested for further reduction and half of it was reduced. I again passed by Moses and he said to me: 'Return to your Lord, for your followers will not be able to bear it. So I returned to Allah and He said, 'These are five prayers and they are all (equal to) fifty (in reward) for My Word does not change.' I returned to Moses and he told me to go back once again. I replied, 'Now I feel shy of asking my Lord again.' Then Gabriel took me till we reached Sidrat-il-Muntaha (Lote tree of; the utmost boundary) which was shrouded in colors, indescribable. Then I was admitted into Paradise where I found small (tents or) walls (made) of pearls and its earth was of musk", "fr": "Rapporté par Abu Dhar : Le Messager d’Allah (ﷺ) a dit : « Pendant que j’étais à La Mecque, le toit de ma maison s’est ouvert et Gabriel est descendu, a ouvert ma poitrine et l’a lavée avec l’eau de Zamzam. Ensuite, il a apporté un plateau en or rempli de sagesse et de foi, en a versé le contenu dans ma poitrine et l’a refermée. Puis il a pris ma main et m’a fait monter au ciel le plus proche. Quand nous sommes arrivés au ciel le plus proche, Gabriel a dit au gardien du ciel : “Ouvre (la porte).” Le gardien a demandé : “Qui est-ce ?” Gabriel a répondu : “Gabriel.” Il a demandé : “Y a-t-il quelqu’un avec toi ?” Gabriel a répondu : “Oui, Muhammad est avec moi.” Il a demandé : “A-t-il été appelé ?” Gabriel a dit : “Oui.” La porte a été ouverte et nous sommes passés au ciel le plus proche où nous avons vu un homme assis avec des gens à sa droite et à sa gauche. Quand il regardait à droite, il riait, et quand il regardait à gauche, il pleurait. Il a dit : “Bienvenue ! Ô Prophète pieux et fils pieux.” J’ai demandé à Gabriel : “Qui est-ce ?” Il a répondu : “C’est Adam et les gens à sa droite et à sa gauche sont les âmes de ses descendants. Ceux à sa droite sont les gens du Paradis et ceux à sa gauche sont les gens de l’Enfer. Quand il regarde à droite, il rit, et quand il regarde à gauche, il pleure.” Ensuite, il m’a fait monter jusqu’au deuxième ciel et il (Gabriel) a dit à son gardien : “Ouvre (la porte).” Le gardien lui a dit la même chose que le gardien du premier ciel et il a ouvert la porte. Anas a dit : « Abu Dhar a ajouté que le Prophète (ﷺ) a rencontré Adam, Idris, Moïse, Jésus et Abraham, mais il n’a pas précisé dans quel ciel ils étaient, sauf qu’il a mentionné qu’il a rencontré Adam au ciel le plus proche et Abraham au sixième ciel. » Anas a dit : « Quand Gabriel et le Prophète (ﷺ) sont passés devant Idris, ce dernier a dit : “Bienvenue ! Ô Prophète pieux et frère pieux.” Le Prophète (ﷺ) a demandé : “Qui est-ce ?” Gabriel a répondu : “C’est Idris.” Le Prophète (ﷺ) a ajouté : “Je suis passé devant Moïse et il a dit : ‘Bienvenue ! Ô Prophète pieux et frère pieux.’ J’ai demandé à Gabriel : ‘Qui est-ce ?’ Gabriel a répondu : ‘C’est Moïse.’ Puis je suis passé devant Jésus et il a dit : ‘Bienvenue ! Ô frère pieux et Prophète pieux.’ J’ai demandé : ‘Qui est-ce ?’ Gabriel a répondu : ‘C’est Jésus.’ Ensuite, je suis passé devant Abraham et il a dit : ‘Bienvenue ! Ô Prophète pieux et fils pieux.’ J’ai demandé à Gabriel : ‘Qui est-ce ?’ Gabriel a répondu : ‘C’est Abraham.’ » Le Prophète (ﷺ) a ajouté : « Ensuite, Gabriel m’a fait monter à un endroit où j’ai entendu le grincement des plumes. » Ibn Hazm et Anas bin Malik ont dit : Le Prophète (ﷺ) a dit : « Ensuite, Allah a prescrit cinquante prières à mes fidèles. Quand je suis revenu avec cet ordre d’Allah, je suis passé devant Moïse qui m’a demandé : ‘Qu’est-ce qu’Allah a prescrit à tes fidèles ?’ J’ai répondu : ‘Il leur a prescrit cinquante prières.’ Moïse a dit : ‘Retourne vers ton Seigneur (et demande une réduction), car tes fidèles ne pourront pas le supporter.’ (Je suis donc retourné vers Allah et j’ai demandé une réduction) et Il a réduit de moitié. Quand je suis repassé devant Moïse et que je l’en ai informé, il a dit : ‘Retourne vers ton Seigneur, car tes fidèles ne pourront pas le supporter.’ Je suis donc retourné vers Allah et j’ai demandé une autre réduction, et la moitié a été enlevée. Je suis encore passé devant Moïse et il m’a dit : ‘Retourne vers ton Seigneur, car tes fidèles ne pourront pas le supporter.’ Je suis donc retourné vers Allah et Il a dit : ‘Ce sont cinq prières et elles valent cinquante (en récompense), car Ma Parole ne change pas.’ Je suis retourné vers Moïse et il m’a dit de retourner encore une fois. J’ai répondu : ‘Maintenant, j’ai honte de demander encore à mon Seigneur.’ Ensuite, Gabriel m’a emmené jusqu’à Sidrat-ul-Muntaha (l’arbre du lotus à la limite ultime) qui était couvert de couleurs indescriptibles. Puis j’ai été admis au Paradis où j’ai trouvé de petites tentes ou des murs faits de perles et son sol était de musc. »", "id": "Telah menceritakan kepada kami [Yahya bin Bukair] berkata, telah menceritakan kepada kami [Al Laits] dari [Yunus] dari [Ibnu Syihab] dari [Anas bin Malik] berkata, [Abu Dzar] menceritakan bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Saat aku di Makkah atap rumahku terbuka, tiba-tiba datang Malaikat Jibril Alaihis Salam. Lalu dia membelah dadaku kemudian mencucinya dengan menggunakan air zamzam. Dibawanya pula bejana terbuat dari emas berisi hikmah dan iman, lalu dituangnya ke dalam dadaku dan menutupnya kembali. Lalu dia memegang tanganku dan membawaku menuju langit dunia. Tatkala aku sudah sampai di langit dunia, Jibril Alaihis Salam berkata kepada Malaikat penjaga langit, 'Bukalah'. Malaikat penjaga langit berkata, 'Siapa Ini? ' Jibril menjawab, 'Ini Jibril'. Malaikat penjaga langit bertanya lagi, 'Apakah kamu bersama orang lain? ' Jibril menjawab, \"Ya, bersamaku Muhammad shallallahu 'alaihi wasallam.' Penjaga itu bertanya lagi, 'Apakah dia diutus sebagai Rasul? ' Jibril menjawab, 'Benar.' Ketika dibuka dan kami sampai di langit dunia, ketika itu ada seseorang yang sedang duduk, di sebelah kanan orang itu ada sekelompok manusia begitu juga di sebelah kirinya. Apabila dia melihat kepada sekelompok orang yang di sebelah kanannya ia tertawa, dan bila melihat ke kirinya ia menangis. Lalu orang itu berkata, 'Selamat datang Nabi yang shalih dan anak yang shalih.' Aku bertanya kepada Jibril, 'Siapakah dia? ' Jibril menjawab, \"Dialah Adam Alaihis Salam, dan orang-orang yang ada di sebelah kanan dan kirinya adalah ruh-ruh anak keturunannya. Mereka yang ada di sebelah kanannya adalah para ahli surga sedangkan yang di sebelah kirinya adalah ahli neraka. Jika dia memandang ke sebelah kanannya dia tertawa dan bila memandang ke sebelah kirinya dia menangis.' Kemudian aku dibawa menuju ke langit kedua, Jibril lalu berkata kepada penjaganya seperti terhadap penjaga langit pertama. Maka langit pun dibuka'.\" Anas berkata, \"Kemudian Nabi shallallahu 'alaihi wasallam menyebutkan bahwa pada tingkatan langit-langit itu beliau bertemu dengan Adam, Idris, Musa, 'Isa dan Ibrahim semoga Allah memberi shalawat-Nya kepada mereka. Beliau tidak menceritakan kepadaku keberadaan mereka di langit tersebut, kecuali bahwa beliau bertemu Adam di langit dunia dan Ibrahim di langit keenam.\" Anas melanjutkan, \"Ketika Jibril berjalan bersama Nabi shallallahu 'alaihi wasallam, ia melewati Idris. Maka Idris pun berkata, 'Selamat datang Nabi yang shalih dan saudara yang shalih.' Aku bertanya kepada Jibril, 'Siapakah dia? ' Jibril menjawab, 'Dialah Idris.' Lalu aku berjalan melewati Musa, ia pun berkata, 'Selamat datang Nabi yang shalih dan saudara yang shalih.' Aku bertanya kepada Jibril, 'Siapakah dia? ' Jibril menjawab, 'Dialah Musa.' Kemudian aku berjalan melewati 'Isa, dan ia pun berkata, 'Selamat datang saudara yang shalih dan Nabi yang shalih.' Aku bertanya kepada Jibril, 'Siapakah dia? ' Jibril menjawab, 'Dialah 'Isa.' Kemudian aku melewati Ibrahim dan ia pun berkata, 'Selamat datang Nabi yang shalih dan anak yang shalih.' Aku bertanya kepada Jibril, 'Siapakah dia? ' Jibril menjawab, 'Dialah Ibrahim shallallahu 'alaihi wasallam.' Ibnu Syihab berkata, Ibnu Hazm mengabarkan kepadaku bahwa Ibnu 'Abbas dan Abu Habbah Al Anshari keduanya berkata, \"Nabi shallallahu 'alaihi wasallam bersabda: \"Kemudian aku dimi'rajkan hingga sampai ke suatu tempat yang aku dapat mendengar suara pena yang menulis.\" Ibnu Hazm berkata, \"Anas bin Malik menyebutkan, \"Nabi shallallahu 'alaihi wasallam bersabda: \"Kemudian Allah 'azza wajalla mewajibkan kepada ummatku shalat sebanyak lima puluh kali. Maka aku pergi membawa perintah itu hingga aku berjumpa dengan Musa, lalu ia bertanya, 'Apa yang Allah perintahkan buat umatmu? ' Aku jawab: 'Shalat lima puluh kali.' Lalu dia berkata, 'Kembalilah kepada Rabbmu, karena umatmu tidak akan sanggup! ' Maka aku kembali dan Allah mengurangi setengahnya. Aku kemudian kembali menemui Musa dan aku katakan bahwa Allah telah mengurangi setengahnya. Tapi ia berkata, 'Kembalilah kepada Rabbmu karena umatmu tidak akan sanggup.' Aku lalu kembali menemui Allah dan Allah kemudian mengurangi setengahnya lagi.' Kemudian aku kembali menemui Musa, ia lalu berkata, 'Kembalilah kepada Rabbmu, karena umatmu tetap tidak akan sanggup.' Maka aku kembali menemui Allah Ta'ala, Allah lalu berfirman: 'Lima ini adalah sebagai pengganti dari lima puluh. Tidak ada lagi perubahan keputusan di sisi-Ku! ' Maka aku kembali menemui Musa dan ia kembali berkata, 'Kembailah kepada Rabb-Mu! ' Aku katakan, 'Aku malu kepada Rabb-ku.' Jibril lantas membawaku hingga sampai di Sidratul Muntaha yang diselimuti dengan warna-warni yang aku tidak tahu benda apakah itu. Kemudian aku dimasukkan ke dalam surga, ternyata di dalamnya banyak kubah-kubah terbuat dari mutiara dan tanahnya dari minyak kesturi", "tr": "قال ابن شهاب فأخبرني ابن حزم: أن ابن عباس وأبا حبة الأنصاري: كانا يقولان: قال النبي صلى الله عليه وسلم: (ثم عرج بي حتى ظهرت لمستوى أسمع فيه صريف الأقلام). قال ابن حزم وأنس بن مالك: قال النبي صلى الله عليه وسلم: (ففرض الله على أمتي خمسين صلاة، فرجعت بذلك، حتى مررت على موسى، فقال: ما فرض الله لك على أمتك؟ قلت: فرض خمسين صلاة، قال: فارجع إلى ربك، فإن أمتك لا تطيق ذلك، فراجعني فوضع شطرها، فرجعت إلى موسى، قلت: وضع شطرها، فقال: راجع ربك، فإن أمتك لا تطيق، فراجعت فوضع شطرها، فرجعت إليه، فقال ارجع إلى ربك، فإن أمتك لا تطيق ذلك، فراجعته، فقال: هي خمس، وهي خمسون، لا يبدل القول لدي، فرجعت إلى موسى، فقال: راجع ربك، فقلت: استحييت من ربي، ثم انطلق بي، حتى انتهى بي إلى سدرة المنتهى، وغشيها ألوان لا أدري ما هي، ثم أدخلت الجنة، فإذا فيها حبايل اللؤلؤ، وإذا ترابها المسك [-349-] Enes b. Mâlik, Ebu Zer' 'in Nebi (Sallallahu aleyhi ve Sellem)’in şöyle buyurduğunu anlattığını nakletmiştir: \"Ben Mekke'deyken evimin tavanı açıldı ve Cebrail indi. Göğsümü yardı, sonra (kalbimi) zemzem suyu ile yıkadı. Daha sonra, hikmet ve iman dolu altın bir kap getirip içindekileri göğsüme boşalttı. En sonunda göğsümü kapadı. Daha sonra elimden tutup beni yakın semaya doğru çıkardı. Yakın semaya geldiğim zaman, Cebrail semanın bekçisine: 'Aç' dedi. Bekçi 'Kim o?' diye sordu. Melek 'Cebrail diye cevap verdi. Bu defa bekçi, Yanında biri var mı?' diye sordu. Cebrail, 'Evet, yanımda Muhammed var' diye yanıt verdi. Bekçi, 'ona vahiy verildi mi?' diye sordu. Cebrail, 'Evet' dedi. Bekçi kapıyı açınca yakın semanın üzerine çıktık. Birden karşıma oturan bir adam çıktı. Sağ ve sol tarafında karaltılar vardı. Sağına baktığı zaman gülümsüyor, soluna baktığı zaman ise ağlıyordu. (Bana:) 'Hoş geldin salih Nebi ve salih oğul' dedi. Cebrail'e: 'Bu kim?' diye sordum. O da, 'Bu Adem'dir, sağındaki ve solundaki karaltılar da, evlatlarının ruhudur. Sağında yer alanlar, cennet ehli, solunda yer alanlar ise, cehennem ehlidir. Sağına baktığı zaman gülümser, soluna baktığı zaman ise ağlar' dedi. Sonra beni, ikinci semaya çıkardı. Bekçisine, 'Aç' dedi. O da, daha önceki bekçi gibi davrandı, sonra kapıyı açtı.\" Enes bu olayı anlatmaya şu şekilde devam etti: \"Ebu Zerr şöyle dedi: Nebi (Sallallahu aleyhi ve Sellem) Adem, İdris, Musa, İsa ve ibrahim Nebileri gördüğünden bahsetti. Ancak, onların derecelerinden söz etmedi. Sadece Hz. Adem'i yakın semada, Hz. ibrahim'i ise, altıncı semada gördüğünü belirtti. Cebrail, Nebi (Sallallahu aleyhi ve Sellem)'i İdris aleyhisselam'ın yanına getirdi. İdris Nebi ona, 'hoş geldin salih Nebi, salih kardeş' dedi. Cebrail'e 'bu kim?' diye sordum. O da, Bu İdris diye cevap verdi. Sonra Musa Nebi'in yanına geldim. O da, 'Hoş geldin, salih Nebi, salih kardeş' dedi. Cebrail'e, 'Bu kim?' diye sordum, o da, 'Musa' dîye cevap verdi. Sonra İsa Nebi'in yanına vardım. Bana, 'hoş geldin, salih Nebi, salih kardeş' dedi. Cebrail'e 'Bu kim?' diye sordum, o da, 'İsa' diye ce­vap verdi. Nihayet ibrahim Nebi'in yanına geldim. Bana, 'hoş geldin, salih Nebi, salih oğul dedi. Cebrail e 'Bu kim?' diye sor­dum, o da İbrahim' diye cevap verdi\" İbn Şihâb, İbn Hazm kanalıyla İbn Abbâs ve Ebu Habbe'nin Nebi s.a.v.'in Şöyle buyurduğunu söylediklerini nakletmiştir: \"Sonra Cebrail, beni yukarı çıkardı. Nihayet öyle bir noktaya geldim ki, (kaza ve kaderi yazan) kalemlerin çıkardığı sesi duyuyordum.\" İbn Hazm ile Enes b. Malik şöyle demiştir: \"Allah Teâlâ, ümmetime, namazı elli vakit olarak farz kıldı. Bu farz ile dönerken Musa peygamberle karşılaştım. Bana 'Hak Teâlâ ümmetine neyi farz kıldı?' diye sordu. Ben de 'elli vakit namazı farz kıldı' dedim. Bunun üzerine 'Rabbine dön (ve bunu azaltmasını dile!) Zira, ümmetin buna güç yetiremez' dedi. Ben de gidip müracaatta bulundum. Bunun üzerine Rabbim yarısını indirdi. Tekrar Musa peygamber'e döndüm ve Yarısını indirdi' dedim. Yine bana Rabbine dön (ve bunun azaltılmasını dile!) Zira, ümmetin buna güç yetiremez' dedi. Ben de gidip müracaatta bulundum. Rabbim yarısını daha indirdi. Tekrar Musa peygamber'e gittim. Yine Rabbine dön (ve bunun azaltılmasını dile!) Zira, ümmetin buna güç yetiremez' dedi. Bende Rabbim'e müracaatta bulundum. Nihayet Allah Teâlâ, 'Onlar beştir, aynı zaman da ellidir de. Benim katımda söz değişmez' buyurdu. Musa peygamber'e döndüm. Yine Rabbine dön (ve bunun azaltılmasını dile!) dedi. Ben de, 'Rabbimden utanır oldum' diye karşılık verdim. Sonra Cebrail sidretü'l-müntehâ'ya kadar beni götürdü. Burayı bilmediğim renkler kaplamıştı. Daha sonra cennete girdirildim. Orada inciden gerdanlıklar vardı. Toprağı da misk idi"}}, "enfants": {"refs": [["bukhari", 1960]], "txt": {"ar": "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا بِشْرُ بْنُ الْمُفَضَّلِ، حَدَّثَنَا خَالِدُ بْنُ ذَكْوَانَ، عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ، قَالَتْ أَرْسَلَ النَّبِيُّ صلى الله عليه وسلم غَدَاةَ عَاشُورَاءَ إِلَى قُرَى الأَنْصَارِ ‏ \"‏ مَنْ أَصْبَحَ مُفْطِرًا فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ، وَمَنْ أَصْبَحَ صَائِمًا فَلْيَصُمْ ‏\"‏‏.‏ قَالَتْ فَكُنَّا نَصُومُهُ بَعْدُ، وَنُصَوِّمُ صِبْيَانَنَا، وَنَجْعَلُ لَهُمُ اللُّعْبَةَ مِنَ الْعِهْنِ، فَإِذَا بَكَى أَحَدُهُمْ عَلَى الطَّعَامِ أَعْطَيْنَاهُ ذَاكَ، حَتَّى يَكُونَ عِنْدَ الإِفْطَارِ‏.‏", "en": "Narrated Ar-Rubai' bint Mu'awwidh:\"The Prophet (ﷺ) sent a messenger to the village of the Ansar in the morning of the day of 'Ashura' (10th of Muharram) to announce: 'Whoever has eaten something should not eat but complete the fast, and whoever is observing the fast should complete it.' \"She further said, \"Since then we used to fast on that day regularly and also make our boys fast. We used to make toys of wool for the boys and if anyone of them cried for food, he was given those toys till it was the time of the breaking of the fast", "fr": "Rapporté par Ar-Rubai’ bint Mu’awadh : « Le Prophète ﷺ a envoyé un messager au village des Ansar le matin du jour de ‘Ashura (le 10 Muharram) pour annoncer : ‘Celui qui a mangé quelque chose ne doit plus manger et doit compléter le jeûne, et celui qui jeûne doit continuer jusqu’au bout.’ » Elle a ajouté : « Depuis ce jour, nous avons pris l’habitude de jeûner ce jour-là régulièrement et nous faisions aussi jeûner nos garçons. Nous fabriquions des jouets en laine pour eux, et si l’un d’eux pleurait à cause de la faim, on lui donnait ces jouets jusqu’à l’heure de la rupture du jeûne. »", "id": "Telah menceritakan kepada kami [Musaddad] telah menceritakan kepada kami [Bisyir bin Al Mufadhdhal] telah menceritakan kepada kami [Khalid bin Dzakwan] dari [Ar-Rubai' binti Mu'awwidz] berkata; Nabi shallallahu 'alaihi wasallam mengirim utusan ke kampung Kaum Anshar pada siang hari 'Asyura (untuk menyampaikan): \"Bahwa siapa yang tidak berpuasa sejak pagi hari maka dia harus menggantinya pada hari yang lain, dan siapa yang sudah berpuasa sejak pagi hari maka hendaklah dia melanjutkan puasanya\". Dia (Ar-Rubai' binti Mu'awwidz) berkata; \"Setelah itu kami selalu berpuasa dan kami juga mendidik anak-anak kecil kami untuk berpuasa dan kami sediakan untuk mereka semacam alat permainan terbuat dari bulu domba, apabila seorang dari mereka ada yang menangis meminta makan maka kami beri dia permainan itu. Demikianlah terus kami lakukan hingga tiba waktu berbuka", "tr": "Rübeyyi' binti Muavviz r.a. şöyle demiştir: Nebi Sallallahu Aleyhi ve Sellem aşure gününün sabahı ensarın oturduğu köylere şu haberi gönderdi: \"Oruçsuz olarak sabahlayan günün geri kalan kısmını (bir şey yiyip içmeksizin) tamamlasın. Oruçlu olarak sabahlayan ise orucunu tutsun\". Rübeyyi' şöyle dedi: Bundan sonraki zamanlarda biz o günü oruçlu geçirir, çocuklarımıza da oruç tuttururduk. Onlara (açlığı unutturmak için) yünden oyuncaklar yapardık. Onlardan biri açlıktan ağladığında kendisine oyuncağı verir, böylece iftara kadar onları oyalardık"}}, "regles": {"refs": [["muslim", 335]], "txt": {"ar": "حَدَّثَنَا أَبُو الرَّبِيعِ الزَّهْرَانِيُّ، حَدَّثَنَا حَمَّادٌ، عَنْ أَيُّوبَ، عَنْ أَبِي قِلاَبَةَ، عَنْ مُعَاذَةَ، ح وَحَدَّثَنَا حَمَّادٌ، عَنْ يَزِيدَ الرِّشْكِ، عَنْ مُعَاذَةَ، أَنَّ امْرَأَةً، سَأَلَتْ عَائِشَةَ فَقَالَتْ أَتَقْضِي إِحْدَانَا الصَّلاَةَ أَيَّامَ مَحِيضِهَا فَقَالَتْ عَائِشَةُ أَحَرُورِيَّةٌ أَنْتِ قَدْ كَانَتْ إِحْدَانَا تَحِيضُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ لاَ تُؤْمَرُ بِقَضَاءٍ ‏.‏", "en": "Mu'adha reported:A woman asked 'A'isha: Should one amongst us complete prayers abandoned during the period of menses? 'A'isha said: Are you a Haruriya? When any one of us during the time of the Messenger of Allah (ﷺ) was in her menses (and abandoned prayer) she was not required to complete them", "fr": "Rapporté par Mu’âdha : Une femme a demandé à Aïsha : « Est-ce que l’une d’entre nous doit rattraper les prières manquées pendant ses règles ? » Aïsha a répondu : « Es-tu une Haruriya ? À l’époque du Messager d’Allah ﷺ, quand l’une d’entre nous avait ses règles et ne priait pas, elle n’était pas obligée de rattraper ces prières. »", "id": "Telah menceritakan kepada kami [Abu ar-Rabi' az-Zahrani] telah menceritakan kepada kami [Hammad] dari [Ayyub] dari [Abu Qilabah] dari [Mu'adzah] --lewat jalur periwayatan lain--, dan telah menceritakan kepada kami [Hammad] dari [Yazid ar-Rasyk] dari [Mu'adzah] bahwa seorang perempuan bertanya kepada [Aisyah] seraya berkata, \"Apakah salah seorang di antara kami harus mengqadha' shalat semasa didatangi haid kami?\" Aisyah menjawab, \"Apakah kamu dari golongan Haruriyyah? Suatu ketika dulu ada di antara kami yang didatangi haid pada masa Rasulullah Shallallahu'alaihiwasallam tetapi kami tidak diperintahkan mengqadha shalat", "tr": "Bize Ebu'r Rabi'ez Zehram rivayet etti. (Dediki): Bize Hammad Eyyub'dan, o da Ebu Kılabe'den, o da Muaze'den naklen rivayet etti. H. Bize Hammad da Yezid er-Rişk'den, o da Muaze'den naklen rivayet etti ki bir kadın Aişe'ye bizden herhangi birisi ay hali olduğu günlerdeki namazı kaza etmeli mi, diye sordu. Aişe: Sen Haruri misin? Bizden herhangi birimiz Resulullah (Sallallahu aleyhi ve Sellem) döneminde ay hali olurdu sonra da (kılamadığı namazlarını) kaza etmesi emredilmezdi, dedi. Diğer tahric: Buhari, 321; Ebu Davud, 262, 263; Tirmizi, 130; Nesai, 380, 2317; İbn Mace, 631; Tuhfetu'l-Eşraf"}}, "coucher": {"refs": [["bukhari", 1954], ["muslim", 1100]], "txt": {"ar": "حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، قَالَ سَمِعْتُ أَبِي يَقُولُ، سَمِعْتُ عَاصِمَ بْنَ عُمَرَ بْنِ الْخَطَّابِ، عَنْ أَبِيهِ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِذَا أَقْبَلَ اللَّيْلُ مِنْ هَا هُنَا، وَأَدْبَرَ النَّهَارُ مِنْ هَا هُنَا، وَغَرَبَتِ الشَّمْسُ، فَقَدْ أَفْطَرَ الصَّائِمُ ‏\"‏‏.‏", "en": "Narrated `Umar bin Al-Khattab:Allah's Messenger (ﷺ) said, \"When night falls from this side and the day vanishes from this side and the sun sets, then the fasting person should break his fast", "fr": "Rapporté par `Umar ibn Al-Khattab : Le Messager d’Allah ﷺ a dit : « Quand la nuit tombe de ce côté, que le jour disparaît de l’autre côté et que le soleil se couche, alors la personne qui jeûne doit rompre son jeûne. »", "id": "Telah menceritakan kepada kami [Al Humaidiy] telah menceritakan kepada kami [Sufyan] telah menceritakan kepada kami [Hisyam bin 'Urwah] berkata, aku mendengar [bapakku] berkata, aku mendengar ['Ashim bin 'Umar bin Al Khaththob] dari [bapaknya radliallahu 'anhu] berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Jika malam telah datang dari sana dan siang telah berlalu dari sana serta matahari telah tenggelam, maka orang yang berpuasa sudah boleh berbuka", "tr": "Asım İbn Ömer İbnü'l-Hattab'ın babasından naklettiğine göre Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Gece karanlığı bu taraftan bastırıp, gündüz şu taraftan geri çekilir ve güneş batarsa artık oruçlunun iftar etme vakti gelmiştir"}}, "oubli": {"refs": [["bukhari", 1933], ["muslim", 1155]], "txt": {"ar": "حَدَّثَنَا عَبْدَانُ، أَخْبَرَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا هِشَامٌ، حَدَّثَنَا ابْنُ سِيرِينَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا نَسِيَ فَأَكَلَ وَشَرِبَ فَلْيُتِمَّ صَوْمَهُ، فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:The Prophet (ﷺ) said, \"If somebody eats or drinks forgetfully then he should complete his fast, for what he has eaten or drunk, has been given to him by Allah", "id": "Telah menceritakan kepada kami ['Abdan] telah mengabarkan kepada kami [Yazid bin Zurai'] telah menceritakan kepada kami [Hisyam] telah menceritakan kepada kami [Ibnu Sirin] dari [Abu Hurairah radliallahu 'anhu] dari Nabi shallallahu 'alaihi wasallam bersabda: \"Jika seseorang lupa lalu dia makan dan minum (ketika sedang berpuasa) maka hendaklah dia meneruskan puasanya karena hal itu berarti Allah telah memberinya makan dan minum", "tr": "Ebu Hureyre'nin naklettiğine göre Nebi Sallallahu Aleyhi ve Sellem şöyle bu­yurmuştur: \"Oruçlu bir kimse unutarak yer ve içerse orucunu tamamlasın. Zira ona Allah yedirmiş ve içirmiştir", "fr": "Rapporté par Abu Huraira : Le Prophète (ﷺ) a dit : « Si quelqu’un mange ou boit par oubli, il doit continuer son jeûne, car c’est Allah qui lui a donné ce qu’il a mangé ou bu. »"}}, "suhur": {"refs": [["bukhari", 1923], ["muslim", 1095]], "txt": {"ar": "حَدَّثَنَا آدَمُ بْنُ أَبِي إِيَاسٍ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏ \"‏ تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً ‏\"‏‏.‏", "en": "Narrated Anas bin Malik:The Prophet (ﷺ) said, \"Take Suhur as there is a blessing in it", "fr": "Rapporté par Anas bin Malik : Le Prophète (ﷺ) a dit : « Prenez le Suhur car il y a une bénédiction dedans. »", "tr": "Enes İbn Malik r.a.'in naklettiğine göre Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Sahur yapınl Çünkü sahurda bereket vardır", "id": "Telah menceritakan kepada kami [Adam bin Abu Iyas] telah menceritakan kepada kami [Syu'bah] telah menceritakan kepada kami ['Abdul 'Aziz bin Shuhaib] berkata, aku mendengar [Anas bin Malik radliallahu 'anhu] berkata; Nabi shallallahu 'alaihi wasallam bersabda: \"Bersahurlah kalian, karena didalam sahur ada barakah"}}, "dattes": {"refs": [["abudawud", 2356], ["tirmidhi", 696]], "txt": {"ar": "حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ، حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ فَإِنْ لَمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَمَرَاتٍ فَإِنْ لَمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ ‏.‏", "en": "Narrated Anas ibn Malik: The Messenger of Allah (ﷺ) used to break his fast before praying with some fresh dates; but if there were no fresh dates, he had a few dry dates, and if there were no dry dates, he took some mouthfuls of water", "fr": "Rapporté par Anas ibn Malik رضي الله عنه : Le Messager d’Allah ﷺ avait l’habitude de rompre son jeûne avant de prier avec quelques dattes fraîches ; s’il n’y en avait pas, il prenait quelques dattes sèches, et s’il n’y en avait pas non plus, il buvait quelques gorgées d’eau", "id": "Telah menceritakan kepada kami [Ahmad bin Hanbal], telah menceritakan kepada kami [Abdurrazzaq], telah menceritakan kepada kami [Ja'far bin Sulaiman], telah menceritakan kepada kami [Tsabit Al Bunani] bahwa ia telah mendengar [Anas bin Malik] berkata; dahulu Rasulullah shallallahu 'alaihi wasallam berbuka dengan beberapa ruthab (kurma yang belum masak) sebelum melakukan shalat, jika tidak dengan air maka dengan beberapa kurma, dan apabila tidak ada kurma maka beliau menghisap air beberapa kali", "tr": "Enes b. Mâlik (r.a.)'in şöyle dediği rivayet edilmiştir: Rasûlullah (s.a.v.) akşam namazını kılmadan önce bir kaç taze hurma ile, eğer hurma yoksa kuru hurma ile iftar ederdi o da bulunmazsa bir kaç yudum su yudumlardı"}}, "hater": {"refs": [["bukhari", 1957], ["muslim", 1098]], "txt": {"en": "Narrated Sahl bin Sa`d:Allah's Messenger (ﷺ) said, \"The people will remain on the right path as long as they hasten the breaking of the fast", "fr": "Rapporté par Sahl ibn Sa`d : Le Messager d’Allah ﷺ a dit : « Les gens resteront sur la bonne voie tant qu’ils se dépêcheront de rompre le jeûne. »", "id": "Telah menceritakan kepada kami ['Abdullah bion Yusuf] telah mengabarkan kepada kami [Malik] dari [Abu HAzim] dari [Sahal bin Sa'ad] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Senantiasa manusia berada dalam kebaikan selama mereka menyegerakan berbuka", "tr": "Sehl Ibn Sa'd'dan nakledildiğine göre Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur; İftar vakti girer girmez oruçlarını açtıkları sürece insanlar hayır üzerindedir", "ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ أَبِي حَازِمٍ، عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ ‏\"‏‏.‏"}}, "hira": {"refs": [["bukhari", 3]], "txt": {"en": "Narrated 'Aisha (the mother of the faithful believers):The commencement of the Divine Inspiration to Allah's Messenger (ﷺ) was in the form of good dreams which came true like bright daylight, and then the love of seclusion was bestowed upon him. He used to go in seclusion in the cave of Hira where he used to worship (Allah alone) continuously for many days before his desire to see his family. He used to take with him the journey food for the stay and then come back to (his wife) Khadija to take his food likewise again till suddenly the Truth descended upon him while he was in the cave of Hira. The angel came to him and asked him to read. The Prophet (ﷺ) replied, \"I do not know how to read.\" The Prophet (ﷺ) added, \"The angel caught me (forcefully) and pressed me so hard that I could not bear it any more. He then released me and again asked me to read and I replied, 'I do not know how to read.' Thereupon he caught me again and pressed me a second time till I could not bear it any more. He then released me and again asked me to read but again I replied, 'I do not know how to read (or what shall I read)?' Thereupon he caught me for the third time and pressed me, and then released me and said, 'Read in the name of your Lord, who has created (all that exists), created man from a clot. Read! And your Lord is the Most Generous.\" (96.1, 96.2, 96.3) Then Allah's Messenger (ﷺ) returned with the Inspiration and with his heart beating severely. Then he went to Khadija bint Khuwailid and said, \"Cover me! Cover me!\" They covered him till his fear was over and after that he told her everything that had happened and said, \"I fear that something may happen to me.\" Khadija replied, \"Never! By Allah, Allah will never disgrace you. You keep good relations with your kith and kin, help the poor and the destitute, serve your guests generously and assist the deserving calamity-afflicted ones.\" Khadija then accompanied him to her cousin Waraqa bin Naufal bin Asad bin 'Abdul 'Uzza, who, during the pre-Islamic Period became a Christian and used to write the writing with Hebrew letters. He would write from the Gospel in Hebrew as much as Allah wished him to write. He was an old man and had lost his eyesight. Khadija said to Waraqa, \"Listen to the story of your nephew, O my cousin!\" Waraqa asked, \"O my nephew! What have you seen?\" Allah's Messenger (ﷺ) described whatever he had seen. Waraqa said, \"This is the same one who keeps the secrets (angel Gabriel) whom Allah had sent to Moses. I wish I were young and could live up to the time when your people would turn you out.\" Allah's Messenger (ﷺ) asked, \"Will they drive me out?\" Waraqa replied in the affirmative and said, \"Anyone (man) who came with something similar to what you have brought was treated with hostility; and if I should remain alive till the day when you will be turned out then I would support you strongly.\" But after a few days Waraqa died and the Divine Inspiration was also paused for a while", "fr": "Rapporté par 'Aisha (la mère des croyants) : Le début de la Révélation divine à l’Envoyé d’Allah (ﷺ) s’est manifesté par de bons rêves qui se réalisaient aussi clairement que la lumière du jour. Ensuite, il a ressenti un amour pour la solitude. Il allait alors se retirer dans la grotte de Hira où il adorait Allah seul, plusieurs jours d’affilée, avant de ressentir l’envie de retrouver sa famille. Il emportait avec lui de quoi se nourrir pendant son séjour, puis revenait auprès de son épouse Khadija pour reprendre des provisions, et repartait ainsi jusqu’à ce que soudain, la Vérité lui soit révélée alors qu’il était dans la grotte de Hira. L’ange est venu à lui et lui a demandé de lire. Le Prophète (ﷺ) a répondu : « Je ne sais pas lire. » Le Prophète (ﷺ) a ajouté : « L’ange m’a alors saisi avec force et m’a serré si fort que je n’ai plus pu supporter, puis il m’a relâché et m’a de nouveau demandé de lire. J’ai répondu : “Je ne sais pas lire.” Il m’a saisi une seconde fois et m’a serré jusqu’à ce que je ne puisse plus supporter, puis il m’a relâché et m’a encore demandé de lire. J’ai répondu encore : “Je ne sais pas lire (ou que dois-je lire) ?” Il m’a alors saisi une troisième fois, m’a serré, puis m’a relâché et a dit : “Lis au nom de ton Seigneur qui a créé, qui a créé l’homme d’une adhérence. Lis ! Et ton Seigneur est le plus Généreux.” (96.1, 96.2, 96.3) Ensuite, l’Envoyé d’Allah (ﷺ) est rentré avec la Révélation, le cœur battant très fort. Il est allé chez Khadija bint Khuwailid et a dit : “Couvrez-moi ! Couvrez-moi !” Ils l’ont couvert jusqu’à ce que sa peur disparaisse. Ensuite, il lui a tout raconté et a dit : “J’ai peur qu’il m’arrive quelque chose.” Khadija a répondu : “Jamais ! Par Allah, Allah ne t’abandonnera jamais. Tu entretiens les liens de parenté, tu aides les pauvres et les démunis, tu es généreux envers tes invités et tu soutiens ceux qui sont frappés par le malheur.” Khadija l’a alors accompagné chez son cousin Waraqa bin Naufal bin Asad bin 'Abdul 'Uzza, qui, avant l’Islam, était devenu chrétien et écrivait en hébreu. Il copiait de l’Évangile en hébreu autant qu’Allah le lui permettait. C’était un vieil homme devenu aveugle. Khadija a dit à Waraqa : “Écoute l’histoire de ton neveu, ô mon cousin !” Waraqa a demandé : “Ô mon neveu ! Qu’as-tu vu ?” L’Envoyé d’Allah (ﷺ) lui a décrit ce qu’il avait vu. Waraqa a dit : “C’est le même gardien des secrets (l’ange Gabriel) qu’Allah a envoyé à Moïse. J’aimerais être jeune et vivre jusqu’au jour où ton peuple te chassera.” L’Envoyé d’Allah (ﷺ) a demandé : “Vont-ils vraiment me chasser ?” Waraqa a répondu que oui et a dit : “Personne n’est venu avec quelque chose de semblable à ce que tu as apporté sans être traité avec hostilité. Et si je vis jusqu’au jour où tu seras chassé, je te soutiendrai de toutes mes forces.” Mais quelques jours plus tard, Waraqa est décédé et la Révélation s’est interrompue pendant un certain temps", "id": "Telah menceritakan kepada kami [Yahya bin Bukair] berkata, Telah menceritakan kepada kami dari [Al Laits] dari ['Uqail] dari [Ibnu Syihab] dari ['Urwah bin Az Zubair] dari [Aisyah] -Ibu Kaum Mu'minin-, bahwasanya dia berkata: \"Permulaaan wahyu yang datang kepada Rasulullah shallallahu 'alaihi wasallam adalah dengan mimpi yang benar dalam tidur. Dan tidaklah Beliau bermimpi kecuali datang seperti cahaya subuh. Kemudian Beliau dianugerahi kecintaan untuk menyendiri, lalu Beliau memilih gua Hiro dan bertahannuts yaitu 'ibadah di malam hari dalam beberapa waktu lamanya sebelum kemudian kembali kepada keluarganya guna mempersiapkan bekal untuk bertahannuts kembali. Kemudian Beliau menemui Khadijah mempersiapkan bekal. Sampai akhirnya datang Al Haq saat Beliau di gua Hiro, Malaikat datang seraya berkata: \"Bacalah?\" Beliau menjawab: \"Aku tidak bisa baca\". Nabi shallallahu 'alaihi wasallam menjelaskan: Maka Malaikat itu memegangku dan memelukku sangat kuat kemudian melepaskanku dan berkata lagi: \"Bacalah!\" Beliau menjawab: \"Aku tidak bisa baca\". Maka Malaikat itu memegangku dan memelukku sangat kuat kemudian melepaskanku dan berkata lagi: \"Bacalah!\". Beliau menjawab: \"Aku tidak bisa baca\". Malaikat itu memegangku kembali dan memelukku untuk ketiga kalinya dengan sangat kuat lalu melepaskanku, dan berkata lagi: (Bacalah dengan (menyebut) nama Tuhanmu yang Menciptakan, Dia Telah menciptakan manusia dari segumpal darah. Bacalah, dan Tuhanmulah yang Maha Pemurah).\" Nabi shallallahu 'alaihi wasallam kembali kepada keluarganya dengan membawa kalimat wahyu tadi dalam keadaan gelisah. Beliau menemui Khadijah binti Khawailidh seraya berkata: \"Selimuti aku, selimuti aku!\". Beliau pun diselimuti hingga hilang ketakutannya. Lalu Beliau menceritakan peristiwa yang terjadi kepada Khadijah: \"Aku mengkhawatirkan diriku\". Maka Khadijah berkata: \"Demi Allah, Allah tidak akan mencelakakanmu selamanya, karena engkau adalah orang yang menyambung silaturrahim.\" Khadijah kemudian mengajak Beliau untuk bertemu dengan Waroqoh bin Naufal bin Asad bin Abdul 'Uzza, putra paman Khadijah, yang beragama Nasrani di masa Jahiliyyah, dia juga menulis buku dalam bahasa Ibrani, juga menulis Kitab Injil dalam Bahasa Ibrani dengan izin Allah. Saat itu Waroqoh sudah tua dan matanya buta. Khadijah berkata: \"Wahai putra pamanku, dengarkanlah apa yang akan disampaikan oleh putra saudaramu ini\". Waroqoh berkata: \"Wahai putra saudaraku, apa yang sudah kamu alami\". Maka Rasulullah shallallahu 'alaihi wasallam menuturkan peristiwa yang dialaminya. Waroqoh berkata: \"Ini adalah Namus, seperti yang pernah Allah turunkan kepada Musa. Duhai seandainya aku masih muda dan aku masih hidup saat kamu nanti diusir oleh kaummu\". Rasulullah shallallahu 'alaihi wasallam bertanya: \"Apakah aku akan diusir mereka?\" Waroqoh menjawab: \"Iya. Karena tidak ada satu orang pun yang datang dengan membawa seperti apa yang kamu bawa ini kecuali akan disakiti (dimusuhi). Seandainya aku ada saat kejadian itu, pasti aku akan menolongmu dengan sekemampuanku\". Waroqoh tidak mengalami peristiwa yang diyakininya tersebut karena lebih dahulu meninggal dunia pada masa fatroh (kekosongan) wahyu. [Ibnu Syihab] berkata; telah mengabarkan kepadaku [Abu Salamah bin Abdurrahman] bahwa [Jabir bin Abdullah Al Anshari] bertutur tentang kekosongan wahyu, sebagaimana yang Rasulullah shallallahu 'alaihi wasallam ceritakan: \"Ketika sedang berjalan aku mendengar suara dari langit, aku memandang ke arahnya dan ternyata Malaikat yang pernah datang kepadaku di gua Hiro, duduk di atas kursi antara langit dan bumi. Aku pun ketakutan dan pulang, dan berkata: \"Selimuti aku. Selimuti aku\". Maka Allah Ta'ala menurunkan wahyu: (Wahai orang yang berselimut) sampai firman Allah (dan berhala-berhala tinggalkanlah). Sejak saat itu wahyu terus turun berkesinambungan.\" Hadits ini juga diriwayatkan oleh [Abdullah bin Yusuf] dan [Abu Shalih] juga oleh [Hilal bin Raddad] dari [Az Zuhri]. Dan [Yunus] berkata; dan [Ma'mar] menyepakati bahwa dia mendapatkannya dari Az Zuhri", "tr": "Mu’minlerin annesi Aişe r.anha.’dan (dedilerki:) Resulullah sallallahu aleyhi ve sellem`in ilk vahiy başlangıcı uykuda rü`ya-yı saliha (yani sıdık –doğru- rüya) görmekle olmuştur. Hiçbir rü`ya görmezdi ki sabah aydınlığı gibi aynen çıkardı. Ondan sonra kalbine yalnızlık sevgisi yerleştirildi. Artık Hira (dağın)`daki mağara içinde yalnızlığa çekilir, oradan ailesinin yanına gelinceye kadar sayısı belirli gecelerde tahannüs -ki taabbüd demektir.- eder bir süre sonra) yine azık alıp mağaraya geri giderdi. Sonra yine Hatice'nin yanına dönüp, bir o kadar zaman için azık tedarik ederdi. Nihayet Resulullah sallallahu aleyhi ve sellem`e birgün Hira mağarasında bulunduğu sırada (emr-i) Hak (yani vahiy) geldi. Şöyle ki Ona Melek gelip: (İkra) yani \"Oku\" dedi. O da: \"Ben okumak bilmem.\" cevabını verdi. Zat-ı Akdesi Risalet-Penahî buyurur ki o zaman Melek beni alıp takatim kesilinceye kadar sıkıştırdı. Sonra beni bırakıp yine: (İkra) dedi. Ben de ona: \"Okumak bilmem.\" dedim. Yine beni alıp ikinci def`a takatim kesilinceye kadar sıkıştırdı. Sonra beni bırakıp yine: (İkra) dedi. Ben de: \"Okumak bilmem.\" dedim. Nihayet beni yine alıp üçüncü def`a sıkıştırdı. Sonra beni bıraktı:", "ar": "حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، أَنَّهَا قَالَتْ أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنَ الْوَحْىِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ، فَكَانَ لاَ يَرَى رُؤْيَا إِلاَّ جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلاَءُ، وَكَانَ يَخْلُو بِغَارِ حِرَاءٍ فَيَتَحَنَّثُ فِيهِ ـ وَهُوَ التَّعَبُّدُ ـ اللَّيَالِيَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَى أَهْلِهِ، وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ، فَيَتَزَوَّدُ لِمِثْلِهَا، حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ فَقَالَ اقْرَأْ‏.‏ قَالَ ‏\"‏ مَا أَنَا بِقَارِئٍ ‏\"‏‏.‏ قَالَ ‏\"‏ فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ‏.‏ قُلْتُ مَا أَنَا بِقَارِئٍ‏.‏ فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ‏.‏ فَقُلْتُ مَا أَنَا بِقَارِئٍ‏.‏ فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ ‏{‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الإِنْسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الأَكْرَمُ‏}‏ ‏\"‏‏.‏ فَرَجَعَ بِهَا رَسُولُ اللَّهِ صلى الله عليه وسلم يَرْجُفُ فُؤَادُهُ، فَدَخَلَ عَلَى خَدِيجَةَ بِنْتِ خُوَيْلِدٍ رضى الله عنها فَقَالَ ‏\"‏ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ، فَقَالَ لِخَدِيجَةَ وَأَخْبَرَهَا الْخَبَرَ ‏\"‏ لَقَدْ خَشِيتُ عَلَى نَفْسِي ‏\"‏‏.‏ فَقَالَتْ خَدِيجَةُ كَلاَّ وَاللَّهِ مَا يُخْزِيكَ اللَّهُ أَبَدًا، إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ‏.‏ فَانْطَلَقَتْ بِهِ خَدِيجَةُ حَتَّى أَتَتْ بِهِ وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ابْنَ عَمِّ خَدِيجَةَ ـ وَكَانَ امْرَأً تَنَصَّرَ فِي الْجَاهِلِيَّةِ، وَكَانَ يَكْتُبُ الْكِتَابَ الْعِبْرَانِيَّ، فَيَكْتُبُ مِنَ الإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ، وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ ـ فَقَالَتْ لَهُ خَدِيجَةُ يَا ابْنَ عَمِّ اسْمَعْ مِنَ ابْنِ أَخِيكَ‏.‏ فَقَالَ لَهُ وَرَقَةُ يَا ابْنَ أَخِي مَاذَا تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم خَبَرَ مَا رَأَى‏.‏ فَقَالَ لَهُ وَرَقَةُ هَذَا النَّامُوسُ الَّذِي نَزَّلَ اللَّهُ عَلَى مُوسَى صلى الله عليه وسلم يَا لَيْتَنِي فِيهَا جَذَعًا، لَيْتَنِي أَكُونُ حَيًّا إِذْ يُخْرِجُكَ قَوْمُكَ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَوَمُخْرِجِيَّ هُمْ ‏\"‏‏.‏ قَالَ نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ بِهِ إِلاَّ عُودِيَ، وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا‏.‏ ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْىُ‏.‏"}}, "qadr": {"refs": [["bukhari", 2017]], "txt": {"ar": "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، حَدَّثَنَا أَبُو سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْوِتْرِ مِنَ الْعَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ ‏\"‏‏.‏", "en": "Narrated `Aisha:Allah's Messenger (ﷺ) said, \"Search for the Night of Qadr in the odd nights of the last ten days of Ramadan", "fr": "Rapporté par `Aisha : Le Messager d’Allah (ﷺ) a dit : « Cherchez la nuit du Qadr dans les nuits impaires des dix derniers jours de Ramadan. »", "tr": "Aişe r.anha Resulullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu söylemiştir: \"Kadir gecesini, Ramazan'ın son on gününün tekli gecelerinde arayınız\". Tekrar:", "id": "Telah menceritakan kepada kami [Qutaibah bin Sa'id] telah menceritakan kepada kami [Isma'il bin Ja'far] telah menceritakan kepada kami [Abu Suhail] dari [bapaknya] dari ['Aisyah radliallahu 'anha] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Carilah Lailatul Qadar pada malam yang ganjil dalam sepuluh malam yang akhir dari Ramadhan"}}, "pardon": {"refs": [["bukhari", 38], ["muslim", 760]], "txt": {"ar": "حَدَّثَنَا ابْنُ سَلاَمٍ، قَالَ أَخْبَرَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، قَالَ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏\"‏‏.‏", "en": "Narrated Abu Huraira: Allah's Messenger (ﷺ) said, \"Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah's rewards, then all his past sins will be forgiven", "fr": "Rapporté par Abu Huraira : Le Messager d'Allah (ﷺ) a dit : « Celui qui jeûne pendant le mois de Ramadan avec une foi sincère et dans l’espoir d’obtenir la récompense d’Allah, alors tous ses péchés passés seront pardonnés. »", "id": "Telah menceritakan kepada kami [Muhammad bin Salam] berkata, telah mengabarkan kepada kami [Muhammad bin Fudlail] berkata, telah menceritakan kepada kami [Yahya bin Sa'id] dari [Abu Salamah] dari [Abu Hurairah] berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Barangsiapa yang berpuasa karena iman dan mengharap pahala, maka diampuni dosa-dosanya yang telah lalu", "tr": "Ebu Hureyre r.a. şöyle dedi: Resulullah sallallahu aleyhi ve sellem buyurdu ki: \"Kim inanarak ve sevabını yalnızca Allah tan umarak Ramazan orucunu tutarsa geçmiş günahları bağışlanır"}}, "fitr": {"refs": [["bukhari", 1503], ["muslim", 984]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ مُحَمَّدِ بْنِ السَّكَنِ، حَدَّثَنَا مُحَمَّدُ بْنُ جَهْضَمٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ عُمَرَ بْنِ نَافِعٍ، عَنْ أَبِيهِ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ قَالَ فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى الْعَبْدِ وَالْحُرِّ، وَالذَّكَرِ وَالأُنْثَى، وَالصَّغِيرِ وَالْكَبِيرِ مِنَ الْمُسْلِمِينَ، وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلاَةِ‏.‏", "en": "Narrated Ibn `Umar:Allah's Messenger (ﷺ) enjoined the payment of one Sa' of dates or one Sa' of barley as Zakat-ul-Fitr on every Muslim slave or free, male or female, young or old, and he ordered that it be paid before the people went out to offer the `Id prayer. (One Sa' = 3 Kilograms approx)", "id": "Telah menceritakan kepada kami [Yahya bin Muhammad bin As-Sakkan] telah menceritakan kepada kami [Muhammad bin Jahdham] telah menceritakan kepada kami [Isma'il bin Ja'far] dari ['Umar bin Nafi'] dari [bapaknya] dari ['Abdullah bin 'Umar radliallahu 'anhua] berkata: \"Rasulullah shallallahu 'alaihi wasallam mewajibkan zakat fithri satu sha' dari kurma atau sha' dari gandum bagi setiap hamba sahaya (budak) maupun yang merdeka, laki-laki maupun perempuan, kecil maupun besar dari kaum Muslimin. Dan Beliau memerintahkan agar menunaikannya sebelum orang-orang berangkat untuk shalat ('Ied)", "tr": "İbn Ömer r.a. şöyle anlatır: Resulullah Sallallahu Aleyhi ve Sellem, köle, hür, erkek, kadın, küçük ya da büyük olsun Müslümanlara bir sa' hurma veya bir sa' arpayı fıtır sadakası olarak vermelerini farz kılmıştır. (Ramazan bayramı) namazına gitmeden önce bunun ödenmesini emretmiştir. Tekrar: 1504, 1507, 1509, 1511 ve", "fr": "Rapporté par Ibn `Umar : Le Messager d’Allah (ﷺ) a prescrit de donner un Sa’ de dattes ou un Sa’ d’orge comme Zakat-ul-Fitr pour chaque musulman, esclave ou libre, homme ou femme, jeune ou vieux, et il a ordonné que cela soit donné avant que les gens ne sortent pour la prière de l’`Id. (Un Sa’ = environ 3 kilos)"}}, "fitr_but": {"refs": [["abudawud", 1609]], "txt": {"ar": "حَدَّثَنَا مَحْمُودُ بْنُ خَالِدٍ الدِّمَشْقِيُّ، وَعَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ السَّمَرْقَنْدِيُّ، قَالاَ حَدَّثَنَا مَرْوَانُ، قَالَ عَبْدُ اللَّهِ حَدَّثَنَا أَبُو يَزِيدَ الْخَوْلاَنِيُّ، - وَكَانَ شَيْخَ صِدْقٍ وَكَانَ ابْنُ وَهْبٍ يَرْوِي عَنْهُ - حَدَّثَنَا سَيَّارُ بْنُ عَبْدِ الرَّحْمَنِ، - قَالَ مَحْمُودٌ الصَّدَفِيُّ - عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِينِ مَنْ أَدَّاهَا قَبْلَ الصَّلاَةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ وَمَنْ أَدَّاهَا بَعْدَ الصَّلاَةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ ‏.‏", "en": "Narrated Abdullah ibn Abbas: The Messenger of Allah (ﷺ) prescribed the sadaqah (alms) relating to the breaking of the fast as a purification of the fasting from empty and obscene talk and as food for the poor. If anyone pays it before the prayer (of 'Id), it will be accepted as zakat. If anyone pays it after the prayer, that will be a sadaqah like other sadaqahs (alms)", "fr": "Rapporté par Abdullah ibn Abbas : Le Messager d’Allah ﷺ a prescrit la sadaqa liée à la rupture du jeûne comme purification du jeûneur contre les paroles inutiles et grossières, et comme nourriture pour les pauvres. Celui qui la donne avant la prière (‘Id), elle sera acceptée comme zakat. Celui qui la donne après la prière, ce sera une simple aumône comme les autres", "id": "Telah menceritakan kepada Kami [Mahmud bin Khalid Ad Dimasyqi] dan [Abdullah bin Abdurrahman As Samarqandi] berkata; telah menceritakan kepada Kami [Marwan], Abdullah berkata; telah menceritakan kepada Kami [Abu Yazid Al Khaulani] ia adalah syekh yang jujur, dan Ibnu Wahb telah meriwayatkan darinya, telah menceritakan kepada Kami [Sayyar bin Abdurrahman], Mahmud Ash Shadafi berkata; dari [Ikrimah] dari [Ibnu Abbas], ia berkata; Rasulullah shallAllahu wa'alaihi wa sallam mewajibkan zakat fitrah untuk mensucikan orang yang berpuasa dari bersenda gurau dan kata-kata keji, dan juga untuk memberi makan miskin. Barangsiapa yang menunaikannya sebelum shalat maka zakatnya diterima dan barangsiapa yang menunaikannya setelah shalat maka itu hanya sedekah diantara berbagai sedekah", "tr": "İbn Abbâs (r.a.)'dan; demiştir ki: Resûlullah (s.a.v.) fıtır sadakasını oruçluyu faydasız ve müstehcen söz ve fiillerden temizleyici, fakirlere de yiyecek olmak üzere farz kıldı. Kim onu bayram namazından önce verirse, o kabul olunmuş bir zekâttır. Kim de onu bayram namazından sonra verirse, o sadakalardan bir sadakadır"}}, "fatiha": {"refs": [["bukhari", 756], ["muslim", 394]], "txt": {"ar": "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا سُفْيَانُ، قَالَ حَدَّثَنَا الزُّهْرِيُّ، عَنْ مَحْمُودِ بْنِ الرَّبِيعِ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ ‏\"‏‏.‏", "en": "Narrated 'Ubada bin As-Samit:Allah's Messenger (ﷺ) said, \"Whoever does not recite Al-Fatiha in his prayer, his prayer is invalid", "fr": "Rapporté par ‘Ubada bin As-Samit : Le Messager d’Allah ﷺ a dit : « Celui qui ne récite pas Al-Fatiha dans sa prière, sa prière n’est pas valable. »", "id": "Telah menceritakan kepada kami ['Ali bin 'Adullah] berkata, telah menceritakan kepada kami [Sufyan] berkata, telah menceritakan kepada kami [Az Zuhri] dari [Mahmud bin Ar Rabi'] dari ['Ubadah bin Ash Shamit], bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Tidak ada shalat bagi yang tidak membaca Faatihatul Kitab (Al Fatihah)", "tr": "Ubâde İbn es-Sâmit (r.a.) Resûlullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu nakletmiştir: \"Kur'an'ın ilk sûresi olan Fâtihatül-Kitâb'ı okumayan bir kimsenin namazı olmaz"}}, "adhan": {"refs": [["abudawud", 499]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ مَنْصُورٍ الطُّوسِيُّ، حَدَّثَنَا يَعْقُوبُ، حَدَّثَنَا أَبِي، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، حَدَّثَنِي مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ، عَنْ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ، قَالَ حَدَّثَنِي أَبِي عَبْدُ اللَّهِ بْنُ زَيْدٍ، قَالَ لَمَّا أَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالنَّاقُوسِ يُعْمَلُ لِيُضْرَبَ بِهِ لِلنَّاسِ لِجَمْعِ الصَّلاَةِ طَافَ بِي وَأَنَا نَائِمٌ رَجُلٌ يَحْمِلُ نَاقُوسًا فِي يَدِهِ فَقُلْتُ يَا عَبْدَ اللَّهِ أَتَبِيعُ النَّاقُوسَ قَالَ وَمَا تَصْنَعُ بِهِ فَقُلْتُ نَدْعُو بِهِ إِلَى الصَّلاَةِ ‏.‏ قَالَ أَفَلاَ أَدُلُّكَ عَلَى مَا هُوَ خَيْرٌ مِنْ ذَلِكَ فَقُلْتُ لَهُ بَلَى ‏.‏ قَالَ فَقَالَ تَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَىَّ عَلَى الصَّلاَةِ حَىَّ عَلَى الصَّلاَةِ حَىَّ عَلَى الْفَلاَحِ حَىَّ عَلَى الْفَلاَحِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللَّهُ قَالَ ثُمَّ اسْتَأْخَرَ عَنِّي غَيْرَ بَعِيدٍ ثُمَّ قَالَ وَتَقُولُ إِذَا أَقَمْتَ الصَّلاَةَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَىَّ عَلَى الصَّلاَةِ حَىَّ عَلَى الْفَلاَحِ قَدْ قَامَتِ الصَّلاَةُ قَدْ قَامَتِ الصَّلاَةُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللَّهُ فَلَمَّا أَصْبَحْتُ أَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ بِمَا رَأَيْتُ فَقَالَ ‏\"‏ إِنَّهَا لَرُؤْيَا حَقٌّ إِنْ شَاءَ اللَّهُ فَقُمْ مَعَ بِلاَلٍ فَأَلْقِ عَلَيْهِ مَا رَأَيْتَ فَلْيُؤَذِّنْ بِهِ فَإِنَّهُ أَنْدَى صَوْتًا مِنْكَ ‏\"‏ ‏.‏ فَقُمْتُ مَعَ بِلاَلٍ فَجَعَلْتُ أُلْقِيهِ عَلَيْهِ وَيُؤَذِّنُ بِهِ - قَالَ - فَسَمِعَ ذَلِكَ عُمَرُ بْنُ الْخَطَّابِ وَهُوَ فِي بَيْتِهِ فَخَرَجَ يَجُرُّ رِدَاءَهُ وَيَقُولُ وَالَّذِي بَعَثَكَ بِالْحَقِّ يَا رَسُولَ اللَّهِ لَقَدْ رَأَيْتُ مِثْلَ مَا رَأَى ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ فَلِلَّهِ الْحَمْدُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ هَكَذَا رِوَايَةُ الزُّهْرِيِّ عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ وَقَالَ فِيهِ ابْنُ إِسْحَاقَ عَنِ الزُّهْرِيِّ ‏\"‏ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ‏\"‏ ‏.‏ وَقَالَ مَعْمَرٌ وَيُونُسُ عَنِ الزُّهْرِيِّ فِيهِ ‏\"‏ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ‏\"‏ ‏.‏ لَمْ يُثَنِّيَا ‏.‏", "en": "‘Abd Allah b. Zaid reported :when the Messenger of Allah (ﷺ) ordered a bell to be made so that it might be struck to gather the people for prayer, a man carrying a bell in his hand appeared to me while I was asleep, and I said; servant of ‘abd Allah, will you sell the bell? He asked; what will you do with it? I replied; we shall use it to call the people to prayer. He said; should I not suggest you something better than that. I replied: certainly. Then he told me to say: Allah is most great, Allah is most great, Allah is most great, Allah is most great. I testify that there is no god but Allah, I testify that Muhammad is the Messenger of Allah. Come to pray, come to pray; come to salvation; come to salvation. Allah is most great, Allah is most great. I testify that there is no god but Allah. He then moved backward a few steps and said: when you utter the IQAMAH, you should say: Allah is most great, Allah is most great. I testify that there is no god but Allah, I testify that Muhammad is the Messenger of Allah. Come to prayer, come to salvation. The time for prayer has come, the time for prayer has come: Allah is most great, Allah is most great. There is no god but Allah. When the morning came, I came to the Messenger of Allah (May peace be upon him) and informed him of what I had seen in the dream. He said: it is a genuine vision, and he then should use it to call people to prayer, for he has a louder voice than you have. So I got up along with Bilal and began to teach it to him and he used it in making the call to prayer. ‘Umar b. al-khattab (Allah be pleased with him) heard it while he was in his house and came out trailing his cloak and said: Messenger of Allah. By him who has sent you with the truth, I have also seen the kind of thing as has been shown to him. The Messenger of Allah (May peace be upon him) said: To Allah be the praise. Abu Dawud said; Al-Zuhri narrated this tradition in a similar way from Sa’id b. al-Musayyib on the authority of ‘Abd Allah b. Zaid. In this version Ibn Ishaq narrated from al-Zuhri: Allah is most great. Allah is most great, Allah is most great, Allah is most great. Ma;mar and yunus narrated from al-Zuhri; Allah is most great, Allah is most great. They did not report it twice again", "fr": "Rapporté par ‘Abd Allah ibn Zayd : Lorsque le Messager d’Allah ﷺ ordonna de fabriquer une cloche pour rassembler les gens à la prière, un homme portant une cloche à la main m’apparut en rêve. Je lui dis : « Serviteur d’‘Abd Allah, veux-tu vendre la cloche ? » Il demanda : « Qu’en feras-tu ? » Je répondis : « Nous l’utiliserons pour appeler les gens à la prière. » Il dit : « Veux-tu que je te propose quelque chose de meilleur ? » Je répondis : « Bien sûr. » Il m’apprit alors à dire : « Allah est le plus Grand, Allah est le plus Grand, Allah est le plus Grand, Allah est le plus Grand. J’atteste qu’il n’y a pas d’autre divinité qu’Allah, j’atteste que Muhammad est le Messager d’Allah. Venez à la prière, venez à la prière ; venez au salut, venez au salut. Allah est le plus Grand, Allah est le plus Grand. Il n’y a pas d’autre divinité qu’Allah. » Il recula ensuite de quelques pas et dit : « Quand tu fais l’IQAMAH, tu dois dire : Allah est le plus Grand, Allah est le plus Grand. J’atteste qu’il n’y a pas d’autre divinité qu’Allah, j’atteste que Muhammad est le Messager d’Allah. Venez à la prière, venez au salut. La prière est sur le point de commencer, la prière est sur le point de commencer. Allah est le plus Grand, Allah est le plus Grand. Il n’y a pas d’autre divinité qu’Allah. » Au matin, je me rendis chez le Messager d’Allah ﷺ et lui racontai ce que j’avais vu en rêve. Il dit : « C’est une vision véridique, et il doit l’utiliser pour appeler les gens à la prière, car il a une voix plus forte que la tienne. » Je me levai alors avec Bilal et je lui appris, et il fit l’appel à la prière. ‘Umar ibn al-Khattab رضي الله عنه l’entendit alors qu’il était chez lui, sortit en traînant son manteau et dit : « Messager d’Allah, par Celui qui t’a envoyé avec la vérité, j’ai vu la même chose que lui. » Le Messager d’Allah ﷺ dit : « Louange à Allah. » Abu Dawud dit : Al-Zuhri a rapporté cette tradition de façon similaire d’après Sa’id ibn al-Musayyib, d’après ‘Abd Allah ibn Zayd. Dans cette version, Ibn Ishaq rapporte d’al-Zuhri : « Allah est le plus Grand, Allah est le plus Grand, Allah est le plus Grand, Allah est le plus Grand. » Ma’mar et Yunus rapportent d’al-Zuhri : « Allah est le plus Grand, Allah est le plus Grand. » Ils ne l’ont pas répété deux fois de plus", "id": "Telah menceritakan kepada kami [Muhammad bin Manshur Ath-Thusi] telah menceritakan kepada kami [Ya'qub] telah menceritakan kepada kami [Ayahku] dari [Muhammad bin Ishaq] telah menceritakan kepadaku [Muhammad bin Ibrahim bin Al-Harits At-Taimi] dari [Muhammad bin Abdullah bin Zaid bin Abdi Rabbih] dia berkata; Telah menceritakan kepadaku [Ayahku, Abdullah bin Zaid] dia berkata; Sewaktu Rasulullah shallallahu 'alaihi wasallam hendak memerintahkan supaya memakai lonceng yang dipukul untuk mengumpulkan orang-orang yang mengerjakan shalat, ada seorang laki-laki berkeliling bertemu denganku, sedang saya dalam keadaan tidur. Ia membawa lonceng di tangannya, maka saya berkata; Wahai hamba Allah, apakah kamu mau menjual lonceng ini? Dia bertanya; Apa yang akan kamu lakukan dengannya? Saya menjawab; Saya akan pakai untuk memanggil orang-orang mengerjakan shalat. Kata orang itu; Maukah saya tunjukan kepadamu yang lebih baik dari itu? Saya katakan kepadanya; Tentu. Orang itu berkata; Engkau ucapkan; \"Allaahu Akbar Allaahu Akbar, Allaahu Akbar Allaahu Akbar (Allah Maha Besar Allah Maha Besar, Allah Maha Besar Allah Maha Besar), Asyhaduan laa ilaaha Illallah, Asyhaduan laa ilaaha Illallah (Aku bersaksi bahwa tidak ada tuhan yang berhak disembah selain Allah, aku bersaksi bahwa tidak ada tuhan yang berhak disembah selain Allah), Ayshadu anna Muhammadar Rasuulallah, Ayshadu anna Muhammadar Rasuulallah (Aku bersaksi bahwasannya Muhammad adalah utusan Allah, Aku bersaksi bahwasannya Muhammad adalah utusan Allah), Hayya 'alash shalaah, Hayya 'alash shalaah (Marlilah kita shalat, Marlilah kita shalat). Hayya 'alal falah, Hayya 'alal falah (Marilah meraih kemenangan, marilah meraih kemenangan). Allaahu Akbar, Allaahu Akbar (Allah Maha Besar, Allah Maha Besar). Laailaaha illallah (Tiada tuhan yang berhak disembah selain Allah). Abdullah berkata; Kemudian orang itu mundur tidak jauh dariku, lalu berkata; Apabila kamu membaca iqamah shalat, ucapkanlah; Allahu Akbar Allahu Akbar, (Allah Maha Besar Allah Maha Besar). Asyhaduan laa ilaaha Illallah, (Aku bersaksi bahwa tidak ada tuhan yang berhak disembah selain Allah). Ayshadu anna Muhammadar Rasuulallah (Aku bersaksi bahwasannya Muhammad adalah utusan Allah), Hayya 'alash shalaah (Marlilah kita shalat). Hayya 'alal falah (Marilah meraiah kemenangan). Qad qaamatish shalat Qad qaamatish shalat (Sungguh shalat telah mulai didirikan Sungguh shalat telah mulai didirikan). Allahu Akbar Allahu Akbar (Allah Maha Besar, Allah Maha Besar). Laailaaha illallah (Tiada tuhan yang berhak disembah selain Allah). Maka keesokan harinya, saya pergi menemui Rasulallah shallallahu 'alaihi wasallam dan memberitahukan kejadian mimpiku itu, maka beliau bersabda: \"Sesungguhnya mimpimu itu adalah mimpi yang benar Insya Allah. Karena itu berdirilah bersama Bilal dan ajarkan kepadanya mimpimu itu, dan hendaklah dia yang adzan, karena suaranya lebih lantang dari suaramu.\" Maka saya pun berdiri bersama Bilal, lalu saya ajarkan kepadanya bacaan-bacaan itu, sementara dia menyerukan adzan itu. Dia berkata; Kemudian Umar bin Al-Khaththab mendengar seruan adzan itu ketika dia sedang berada di rumahnya, lalu dia keluar sambil menarik pakaiannya dan berkata; Demi Dzat yang mengutusmu dengan al-Haq, wahai Rasulullah, sungguh saya telah bermimpi seperti mimpi Abdullah itu. Maka Rasulallah bersabda: \"Maka segala puji hanya bagi Allah. Abu Dawud berkata; Demikian riwayat [Az-Zuhri] dari [Sa'id bin Al-Musayyib] dari [Abdullah bin Zaid], dan disebutkan oleh [Ibnu Ishaq] dari [Az-Zuhri]; Allahu Akbar Allahu Akbar, Allahu Akbar Allahu Akbar. Dan [Ma'mar] dan [Yunus] dari [Az-Zuhri] menyebutkan; Allahu akbar Allahu akbar, tanpa diulangi dua kali", "tr": "Abdullah b. Zeyd şöyle demiştir: Resulullah (Sallallahu aleyhi ve Sellem) halkı namaz'a toplamak maksadıyla çalınmak üzere bir çan yapılmasını emrettiği sıralarda idi. Ben uyurken (rü'yamda) yanıma elinde çan taşıyan bir adam çıkageldi. Ben ona: Ey Allah'ın kulu! Bu çanı bana satmaz mısın? dedim. Onu ne yapacaksın? dedi. Onunla (halkı) namaza çağıracağız, dedim. Sana bundan daha hayırlısını göstereyim mi? dedi. Ben de ona: Evet (göster), dedim. Dedi ki: \"Şöyle dersin: ALLAHU EKBER. ALLAHU EKBER. ALLAHU EKBER. ALLAHU EKBER. EŞHEDU EN LA İLAHE İLLALLAH= Ben, Allah'dan başka ilah olmadığına şehadet ederim. EŞHEDU EN LA İLAHE İLLALLAH=Ben,Allah'dan başka ilah olmadığına şehadet ederim. EŞHEDU ENNE MUHAMMEDEN RESULULLAH=Ben.Muhammed'in Allah'ın elçisi olduğuna şahitlik ederim. EŞHEDU ENNE MUHAMMEDEN RESULULLAH=Ben, Muhammed'in Allah'ın elçisi olduğuna şahitlik ederim. HAYYA ALE'S-SELAH=Haydin namaza, HAYYA ALE'S-SELAH=haydin namaza. HAYYA ALE'L-FELAH=Haydin kurtuluşa, HAYYA ALE'L-FELAH=Haydin kurtuluşa. ALLAHU EKBER. ALLAHU EKBER. LA İLAHE İLLALLAH=Allah'tan başka ilah yoktur.\" Sonra benden biraz uzaklaştı ve (şöyle) dedi; \"Namaza kalktığın vakitte de (şöyle) dersin: ALLAHU EKBER. ALLAHU EKBER. EŞHEDU EN LA İLAHE İLLALLAH EŞHEDU ENNE MUHAMMEDEN RESULULLAH HAYYA ALE'S-SELAH HAYYA ALE'L-FELAH KED KAMETU'S-SALAT=Namaz başladı. KED KAMETU'S-SALATNamaz başladı. ALLAHU EKBER. ALLAHU EKBER LA İLAHE İLLALLAH.\" Sabah olunca Resul-i Ekrem'e gelip gördüklerimi haber verdim. \"İnşallah hak rü'yadır. Bilal ile beraber kalk gördüklerini O'na öğret de ezanı o okusun. Çünkü onun sesi seninkinden daha gür ve tatlıdır\" buyurdu. Bilal ile beraber kalktık. Ben O'na öğretmeye başladım, o da okumaya (başladı). Abdullah b. Zeyd (devamla) dedi ki: Bu ezanı evinde işiten Ömer b. el-Hattab (r.a.) sür'atle dışarı çıktı ve, \"Ya Rasulullah, seni hak Nebi olarak gönderen Allah'a yemin ederim ki O'nun gördüğünü ben de gördüm\" diyordu. (Bunun üzerine) Resul-i Ekrem (Sallallahu aleyhi ve Sellem) de: \"Allah'a hamd olsun\" buyurdu. Ebu Davud dedi ki: Zührî'nin, Said b. el-Müseyyeb vasıtasıyla Abdullah b. Zeyd'den rivayet ettiği (hadis) de aynen yukarıdaki hadis gibidir. Ancak îbn İshak, ZührVden rivayetinde: -ALLAHU EKBER-\"Allah en büyüktür, Allah en büyüktür, Allah en büyüktür. Allah en büyüktür\" (lafızlarını dört defa) söylemişse de Ma'mer ve Yunus Zühri'den yaptıkları rivayetlerinde (iki defa) \"Allah en büyüktür, Allah en büyüktür\" demişler. Bir daha tekrarlamamışlardır. Diğer tahric: Tirmizî, mevakît; ibn Mace, ezan; Darimî, salat; Ahmed b. Hanbel, IV"}}, "qiyam": {"refs": [["bukhari", 37], ["muslim", 759]], "txt": {"en": "Narrated Abu Huraira: Allah's Messenger (ﷺ) said: \"Whoever establishes prayers during the nights of Ramadan faithfully out of sincere faith and hoping to attain Allah's rewards (not for showing off), all his past sins will be forgiven", "fr": "Rapporté par Abu Huraira : Le Messager d'Allah (ﷺ) a dit : Celui qui prie pendant les nuits du Ramadan avec une foi sincère et dans l'espoir de la récompense d'Allah (et non pour se faire remarquer), tous ses péchés passés seront pardonnés", "id": "Telah menceritakan kepada kami [Isma'il] berkata, telah menceritakan kepadaku [Malik] dari [Ibnu Syihab] dari [Humaid bin Abdurrahman] dari [Abu Hurairah] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Barangsiapa menegakkan Ramadlan karena iman dan mengharap pahala, maka diampuni dosa-dosanya yang telah lalu", "tr": "Ebu Hureyre r.a. Resulullâh sallallahu aleyhi ve sellem buyurdu ki: \"Kim inanarak ve sevabını yalnızca Allah'tan umarak Ramazan'ı (gecelerini) ihya ederse geçmiş günahları bağışlanır. AÇIKLAMA 36’DA", "ar": "حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏\"‏‏.‏"}}, "dixnuits": {"refs": [["bukhari", 2024], ["muslim", 1174]], "txt": {"ar": "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ أَبِي يَعْفُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَهُ، وَأَحْيَا لَيْلَهُ، وَأَيْقَظَ أَهْلَهُ‏.‏", "tr": "Aişe r.anha şöyle demiştir: Ramazanın son on günü geldiğinde Hz. Nebi Sallallahu Aleyhi ve Sellem kemerini sıkı bağlar (sıkı ibadette bulunur ve hanımları ile cinsel ilişkiyi terk eder), geceyi ihya eder ve hanımlarına (bu gecelerde ibadete daha çok yönelmeleri için) uyarıda bulunurdu", "en": "Narrated Aisha:With the start of the last ten days of Ramadan, the Prophet (ﷺ) used to tighten his waist belt (i.e. work hard) and used to pray all the night, and used to keep his family awake for the prayers", "fr": "Rapporté par Aisha : Dès le début des dix derniers jours de Ramadan, le Prophète (ﷺ) serrait sa ceinture (c’est-à-dire qu’il se consacrait davantage à l’adoration), priait toute la nuit et réveillait sa famille pour la prière", "id": "Telah menceritakan kepada kami ['Ali bin 'Abdullah] telah menceritakan kepada kami [Sufyan] dari [Abu Ya'fur] dari [Abu Adh-Dhuha] dari [Masruq] dari ['Aisyah radliallahu 'anha] berkata: \"Nabi shallallahu 'alaihi wasallam bila memasuki sepuluh akhir (dari bulan Ramadhan), Beliau mengencangkan sarung Beliau, menghidupkan malamnya dengan ber'ibadah dan membangunkan keluarga Beliau"}}, "itikaf": {"refs": [["bukhari", 2026], ["muslim", 1172]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ زَوْجِ النَّبِيِّ صلى الله عليه وسلم أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَعْتَكِفُ الْعَشْرَ الأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى تَوَفَّاهُ اللَّهُ، ثُمَّ اعْتَكَفَ أَزْوَاجُهُ مِنْ بَعْدِهِ‏.‏", "en": "Narrated `Aisha:(the wife of the Prophet) The Prophet (ﷺ) used to practice I`tikaf in the last ten days of Ramadan till he died and then his wives used to practice I`tikaf after him", "fr": "Rapporté par `Aisha (l’épouse du Prophète) : Le Prophète (ﷺ) faisait l’I`tikaf pendant les dix derniers jours de Ramadan jusqu’à sa mort, puis ses épouses faisaient l’I`tikaf après lui", "id": "Telah menceritakan kepada kami ['Abdullah bin Yusuf] berkata, telah menceritakan kepada kami [Al Laits] dari ['Uqail] dari [Ibnu Syihab] dari ['Urwah bin Az Zubair] dari ['Aisyah radliallahu 'anha], isteri Nabi shallallahu 'alaihi wasallam bahwa Nabi shallallahu 'alaihi wasallam beri'tikaf pada sepuluh hari yang akhir dari Ramadhan hingga wafatnya kemudian isteri-isteri Beliau beri'tikaf setelah kepergian Beliau", "tr": "Nebi Sallallahu Aleyhi ve Sellem'in eşi Aişe (r.anha) şöyle dedi; Resulullah Sallallahu Aleyhi ve Sellem vefat edinceye kadar Ramazanın son on gülünde itikaf yapardı. Onun vefatından sonra hanımları bu itikafa devam etmişlerdi"}}, "tarawih": {"refs": [["bukhari", 2012], ["muslim", 761]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عُرْوَةُ، أَنَّ عَائِشَةَ ـ رضى الله عنها ـ أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم خَرَجَ لَيْلَةً مِنْ جَوْفِ اللَّيْلِ، فَصَلَّى فِي الْمَسْجِدِ، وَصَلَّى رِجَالٌ بِصَلاَتِهِ، فَأَصْبَحَ النَّاسُ فَتَحَدَّثُوا، فَاجْتَمَعَ أَكْثَرُ مِنْهُمْ، فَصَلَّوْا مَعَهُ، فَأَصْبَحَ النَّاسُ فَتَحَدَّثُوا، فَكَثُرَ أَهْلُ الْمَسْجِدِ مِنَ اللَّيْلَةِ الثَّالِثَةِ، فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَصَلَّى، فَصَلَّوْا بِصَلاَتِهِ، فَلَمَّا كَانَتِ اللَّيْلَةُ الرَّابِعَةُ عَجَزَ الْمَسْجِدُ عَنْ أَهْلِهِ، حَتَّى خَرَجَ لِصَلاَةِ الصُّبْحِ، فَلَمَّا قَضَى الْفَجْرَ أَقْبَلَ عَلَى النَّاسِ، فَتَشَهَّدَ ثُمَّ قَالَ ‏ \"‏ أَمَّا بَعْدُ، فَإِنَّهُ لَمْ يَخْفَ عَلَىَّ مَكَانُكُمْ، وَلَكِنِّي خَشِيتُ أَنْ تُفْتَرَضَ عَلَيْكُمْ فَتَعْجِزُوا عَنْهَا ‏\"‏‏.‏ فَتُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَالأَمْرُ عَلَى ذَلِكَ", "en": "Narrated 'Urwa:That he was informed by `Aisha, \"Allah's Messenger (ﷺ) went out in the middle of the night and prayed in the mosque and some men prayed behind him. In the morning, the people spoke about it and then a large number of them gathered and prayed behind him (on the second night). In the next morning the people again talked about it and on the third night the mosque was full with a large number of people. Allah's Messenger (ﷺ) came out and the people prayed behind him. On the fourth night the Mosque was overwhelmed with people and could not accommodate them, but the Prophet (ﷺ) came out (only) for the morning prayer. When the morning prayer was finished he recited Tashah-hud and (addressing the people) said, \"Amma ba'du, your presence was not hidden from me but I was afraid lest the night prayer (Qiyam) should be enjoined on you and you might not be able to carry it on.\" So, Allah's Apostle died and the situation remained like that (i.e. people prayed individually)", "fr": "Rapporté par ‘Urwa : Il a été informé par `Aisha : « Le Messager d’Allah (ﷺ) est sorti au milieu de la nuit et a prié à la mosquée, et quelques hommes ont prié derrière lui. Le matin, les gens en ont parlé, puis beaucoup se sont rassemblés et ont prié derrière lui la deuxième nuit. Le lendemain matin, les gens en ont encore parlé, et la troisième nuit la mosquée était pleine. Le Messager d’Allah (ﷺ) est sorti et les gens ont prié derrière lui. La quatrième nuit, la mosquée était tellement remplie qu’elle ne pouvait plus contenir tout le monde, mais le Prophète (ﷺ) n’est sorti que pour la prière du matin. Quand la prière du matin fut terminée, il a récité le Tashahhud et a dit : « Quant à ce qui suit : votre présence ne m’a pas échappé, mais j’ai eu peur que la prière de la nuit (Qiyam) ne devienne obligatoire pour vous et que vous ne puissiez pas la supporter. » Ainsi, le Messager d’Allah est décédé et la situation est restée comme cela (c’est-à-dire que les gens priaient individuellement)", "id": "Telah menceritakan kepada kami [Yahya bin Bukair] telah menceritakan kepada kami [Al Laits] dari ['Uqail] dari [Ibnu Syihab] telah mengabarkan kepada saya ['Urwah] bahwa ['Aisyah radliallahu 'anha] mengabarkannya bahwa Rasulullah shallallahu 'alaihi wasallam pada suatu malam keluar kamar di tengah malam untuk melaksanakan shalat di masjid. Maka orang-orang kemudian ikut shalat mengikuti shalat Beliau. Pada waktu paginya orang-orang membicarakan kejadian tersebut sehingga pada malam berikutnya orang-orang yang berkumpul bertambah banyak lalu ikut shalat dengan Beliau. Pada waktu paginya orang-orang kembali membicarakan kejadian tersebut. Kemudian pada malam yang ketiga orang-orang yang hadir di masjid semakin bertambah banyak lagi lalu Rasulullah shallallahu 'alaihi wasallam keluar untuk shalat dan mereka ikut shalat bersama Beliau. Kemudian pada malam yang keempat, masjid sudah penuh dengan jama'ah hingga akhirnya Beliau keluar hanya untuk shalat Shubuh. Setelah Beliau selesai shalat Fajar, Beliau menghadap kepada orang banyak kemudian Beliau membaca syahadat lalu bersabda: \"Amma ba'du, sesungguhnya aku bukannya tidak tahu keberadaan kalian (semalam). Akan tetapi aku takut nanti menjadi diwajibkan atas kalian sehingga kalian menjadi keberatan karenanya\". Kemudian setelah Rasulullah shallallahu 'alaihi wasallam meninggal dunia, tradisi shalat (tarawih) secara berjamaah terus berlangsung seperti itu", "tr": "Aişe r.anha rivayet etmiştir: Resulullah Sallallahu Aleyhi ve Sellem bir gece ortasında çıkarak mescitte namaz kıldı. Bazı kimseler de onun namazına uyup namaz kıldılar. Ertesi gün insanlar bundan bahsettiler. İkinci gece daha çok kimse toplandı. Nebi Sallallahu Aleyhi ve Sellem namaz kıldı, insanlar da onunla birlikte namaz kıldılar. Ertesi gün yine insanlar bundan bahsettiler. Üçüncü gece mesciddekilerin sayısı daha da çoğaldı. Hz. Nebi çıkıp namaz kıldı, insanlar da onunla birlikte namaz kıldılar. Dördüncü gece olunca mescid o kadar doldu ki İnsanları almadı. Ancak Hz. Nebi Sallallahu Aleyhi ve Sellem sabah namazına kadar çıkmadı. Sabah namazını kıldırınca insanlara döndü, şehadet getirdi sonra şunları söyledi: \"Sizin yaptığınız bana gizli kalmadı. Ancak ben bu namazın size farz kılınmasından ve sonra da bu namazı kılamamanızdan korktum\". Hz. Nebi, durum bu halde devam ederken vefat etti"}}, "aid_dattes": {"refs": [["bukhari", 953]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ، حَدَّثَنَا سَعِيدُ بْنُ سُلَيْمَانَ، قَالَ حَدَّثَنَا هُشَيْمٌ، قَالَ أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ، عَنْ أَنَسٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم لاَ يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ تَمَرَاتٍ‏.‏ وَقَالَ مُرَجَّى بْنُ رَجَاءٍ حَدَّثَنِي عُبَيْدُ اللَّهِ قَالَ حَدَّثَنِي أَنَسٌ عَنِ النَّبِيِّ صلى الله عليه وسلم وَيَأْكُلُهُنَّ وِتْرًا‏.‏", "en": "Narrated Anas bin Malik:Allah's Messenger (ﷺ) never proceeded (for the prayer) on the Day of `Id-ul-Fitr unless he had eaten some dates. Anas also narrated: The Prophet (ﷺ) used to eat odd number of dates", "fr": "Rapporté par Anas bin Malik : Le Messager d’Allah (ﷺ) ne sortait jamais pour la prière du jour de l’`Id al-Fitr sans avoir mangé quelques dattes. Anas a aussi rapporté : Le Prophète (ﷺ) mangeait un nombre impair de dattes", "id": "Telah menceritakan kepada kami [Muhammad bin 'Abdurrahim] telah menceritakan kepada kami [Sa'id bin Sulaiman] berkata, telah menceritakan kepada kami [Husyaim] berkata, telah mengabarkan kepada kami ['Ubaidullah bin Abu Bakar bin Anas] dari [Anas bin Malik] berkata, \"Pada hari raya Rasulullah shallallahu 'alaihi wasallam tidak berangkat untuk melaksanakan shalat hingga beliau makan beberapa butir kurma.\" [Murajja' bin Raja'] berkata; telah menceritakan kepadaku ['Ubaidullah] berkata, telah menceritakan kepadaku [Anas] dari Nabi shallallahu 'alaihi wasallam, \"Beliau makan beberapa kurma dengan bilangan ganjil", "tr": "Enes İbn Mâlik (r.a.)'den nakledilmiştir: \"Resûlullah Sallallahu Aleyhi ve Sellem, birkaç hurma yemeden, Ramazan bayramı namazı için namazgah’a gitmezdi.\" Murecca' ibn Recâ' yoluyla gelen rivayette de şöyle bir ilave vardır. \"Yediği hurma taneleri de hep tek sayı olurdu.\" Diğer tahric: Tirmiziî, Iydeyn; Muvatta, Iydeyn"}}, "shawwal": {"refs": [["muslim", 1164]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، وَعَلِيُّ بْنُ حُجْرٍ، جَمِيعًا عَنْ إِسْمَاعِيلَ، - قَالَ ابْنُ أَيُّوبَ حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، - أَخْبَرَنِي سَعْدُ بْنُ سَعِيدِ بْنِ قَيْسٍ، عَنْ عُمَرَ، بْنِ ثَابِتِ بْنِ الْحَارِثِ الْخَزْرَجِيِّ عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، - رضى الله عنه - أَنَّهُ حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ ‏\"‏ ‏.‏", "en": "Abu Ayyub al-Ansari (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying:He who observed the fast of Ramadan and then followed it with six (fasts) of Shawwal. it would be as if he fasted perpetually", "fr": "Rapporté par Abu Ayyub al-Ansari رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Celui qui jeûne le mois de Ramadan puis le suit de six jours de Chawwal, c’est comme s’il avait jeûné toute l’année. »", "id": "Telah menceritakan kepada kami [Yahya bin Ayyub] dan [Qutaibah bin Sa'id] dan [Ali bin Hujr] semuanya dari [Isma'il] - [Ibnu Ayyub] berkata- Telah menceritakan kepada kami [Isma'il bin Ja'far] telah mengabarkan kepadaku [Sa'd bin Sa'id bin Qais] dari [Umar bin Tsabit bin Harits Al Khazraji] dari [Abu Ayyub Al Anshari] radliallahu 'anhu, bahwa ia telah menceritakan kepadanya bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Siapa yang berpuasa Ramadlan kemudian diiringinya dengan puasa enam hari di bulan Syawwal, maka yang demikian itu seolah-olah berpuasa sepanjang masa.\" Dan Telah menceritakan kepada kami [Ibnu Numair] telah menceritakan kepada kami [bapakku] telah menceritakan kepada kami [Sa'd Sa'id] saudaranya Yahya bin Sa'id, telah mengabarkan kepada kami [Umar bin Tsabit] telah mengabarkan kepada kami [Ayyub Al Anshari] radliallahu 'anhu, ia berkata; Saya mendengar Rasulullah shallallahu 'alaihi wasallam bersabda. Yakni dengan hadits semisalnya. Dan Telah menceritakannya kepada kami [Abu Bakr bin Abu Syaibah] telah menceritakan kepada kami [Abdullah bin Mubarak] dari [Sa'd bin Sa'id] ia berkata, saya mendengar [Umar bin Tsabit] ia berkata, saya mendengar [Abu Ayyub] radliallahu 'anhu. Berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: yakni dengan hadits yang serupa", "tr": "Bize Yahya b. Eyyûb ile Kuteybetü'bnü Saîd ve Aliyyü'bnü Hucr toptan İsmail'den rivayet ettiler. İbni Eyyûb (Dediki) Bize İsmail b. Ca'fer rivayet etti. (Dediki) Bana Sa'd b. Saîd b. Kays, Ömer b. Sabit b. Haris El-Hazrecî'den, ona da Ebû Eyyûb El-Ensari (Radiyallahu anh) rivayet etmiş olmak Üzere haber verdiki, Resulullah (Sallallahu Aleyhi ve Sellem) : — «Her kim ramazan orucunu tutar da sonra Şevval'den altı günü eklerse bu bütün sene oruçlu gibi olur.» buyurmuşlar"}}, "afw": {"refs": [["tirmidhi", 3513]], "txt": {"ar": "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ الضُّبَعِيُّ، عَنْ كَهْمَسِ بْنِ الْحَسَنِ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ عَائِشَةَ، قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ عَلِمْتُ أَىُّ لَيْلَةٍ لَيْلَةُ الْقَدْرِ مَا أَقُولُ فِيهَا قَالَ ‏ \"‏ قُولِي اللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏\"‏ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏", "en": "Aishah narrated:“I said: ‘O Messenger of Allah, what is your view if I know when the Night of Al-Qadr is, then what should I say in it?” He said: ‘Say: “O Allah, indeed You are Pardoning, [Generous,] You love pardon, so pardon me (Allāhumma innaka `Afuwwun [Karīmun], tuḥibbul-`afwa fa`fu `annī).’”", "tr": "Âişe (r.anha)’dan rivâyete göre, şöyle demiştir: “Ey Allah’ın Rasûlü! Kadir gecesinin hangi gece olduğunu bilirsem hangi duâyı okumamı tavsiye edersin?” dedim. Rasûlullah (Sallallahu aleyhi ve Sellem) şöyle buyurdu: [ALLAHUMME İNNEKE AFUVVUN KERİM, TUHİBBUL AFVE, FA’FU ANNİ] Meali: “Allah’ım sen affedicisin, ikram sahibisin affetmeyi seversin beni de affet.” Diğer tahric: İbn Mâce, Dua Tirmizî: Bu hadis hasen sahihtir. İBN-İ MACE HADİSİ İÇİN TIKLA"}}, "ikhlas": {"refs": [["bukhari", 5013]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَجُلاً، سَمِعَ رَجُلاً، يَقْرَأُ ‏{‏قُلْ هُوَ اللَّهُ أَحَدٌ‏}‏ يُرَدِّدُهَا فَلَمَّا أَصْبَحَ جَاءَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَذَكَرَ ذَلِكَ لَهُ وَكَأَنَّ الرَّجُلَ يَتَقَالُّهَا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ ‏\"‏‏.‏", "en": "Narrated Abu Said Al-Khudri: A man heard another man reciting (Surat-Al-Ikhlas) 'Say He is Allah, (the) One.' (112. 1) repeatedly. The next morning he came to Allah's Messenger (ﷺ) and informed him about it as if he thought that it was not enough to recite. On that Allah's Messenger (ﷺ) said, \"By Him in Whose Hand my life is, this Surah is equal to one-third of the Qur'an", "fr": "Rapporté par Abu Saïd Al-Khudri : Un homme a entendu un autre homme réciter à plusieurs reprises la sourate Al-Ikhlas : « Dis : Il est Allah, l’Unique. » (112.1). Le lendemain matin, il est allé voir le Messager d’Allah (ﷺ) et lui a raconté cela, pensant que ce n’était pas suffisant de ne réciter que cette sourate. Le Messager d’Allah (ﷺ) a dit : « Par Celui qui tient ma vie dans Sa main, cette sourate équivaut au tiers du Coran. »", "id": "Telah menceritakan kepada kami [Abdullah bin Yusuf] Telah mengabarkan kepada kami [Malik] dari [Abdurrahman bin Abdullah bin Abdurrahman bin Abu Sha'shah] dari [bapaknya] dari [Abu Sa'id Al Khudri] bahwa seorang laki-laki mendengar seseorang yang membaca surat: \"QUL HUWALLAHU AHAD.\" dan orang itu selalu mengulang-ngulangnya. Di pagi harinya, maka laki-laki itu pun segera menemui Rasulullah shallallahu 'alaihi wasallam dan mengadukan mengenai seseorang yang ia dengar semalam membaca surat yang sepertinya ia menganggap sangat sedikit. Maka Rasulullah shallallahu 'alaihi wasallam pun bersabda: \"Demi Dzat yang jiwaku berada di tangan-Nya, sesungguhnya surat itu benar-benar menyamai sepertiga Al Qur`an.\" [Abu Ma'mar] menambahkan dan Telah menceritakan kepada kami [Isma'il bin Ja'far] dari [Malik] dari [Abdurrahman bin Abdullah bin Abdurrahman bin Sha'sha'ah] dari [bapaknya] dari [Abu S'aid Al Khudri] Telah mengabarkan kepadaku adikku [Qatadah bin An Nu'man] bahwasanya; Ada seorang laki-laki yang berdiri menunaikan shalat di waiktu sahur, dan ia membaca surat, \"QUL HUWALLAHU AHAD..\" lalu ia tidaklah menambahkan sesuatu pun pada surat itu.\" Maka ketika pagi, maka seseorang mendatangi Nabi shallallahu 'alaihi wasallam. Yakni dengan hadists semisalnya", "tr": "Ebu Said el-Hudrl'den rivayet edildiğine göre; Adam'ın biri, başka birinin İhlas suresini tekrarlayıp durduğunu işitmiş. Sabah olunca, Nebi Sallallahu Aleyhi ve Sellem'e gelip biraz da adamın yaptığını hafife alarak bu durumu haber vermiş. Bunun üzerine Allah Resülü Sallallahu Aleyhi ve Sellem şöyle buyurmuş: \"Canım elinde bulunan Allah'a yemin ederim ki, bu sure Kur'an'ın üçte birine denktir.\" Hadisin geçtiği diğer yerler:"}}, "kursi": {"refs": [["muslim", 810]], "txt": {"en": "Ubayy b. Ka'b said:Allah's Messenger (ﷺ) said: O Abu' al-Mundhir, do you know the verse from the Book of Allah which, according to you, is the greatest? I said: Allah and His Apostle (ﷺ) know best. He again said: Abu'l-Mundhir, do you know the verse from the Book of Allah which, according to you, is the greatest? I said: Allah, there is no god but He, the Living, the Eternal. Thereupon he struck me on my breast and said: May knowledge be pleasant for you, O Abu'l-Mundhir", "fr": "Rapporté par Ubayy b. Ka'b رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Ô Abu al-Mundhir, sais-tu quel verset du Livre d’Allah, selon toi, est le plus grand ? » J’ai répondu : « Allah et Son Messager ﷺ savent mieux. » Il a répété : « Ô Abu al-Mundhir, sais-tu quel verset du Livre d’Allah, selon toi, est le plus grand ? » J’ai répondu : « Allah, il n’y a pas d’autre divinité que Lui, le Vivant, l’Éternel. » Alors il m’a frappé la poitrine et a dit : « Que la connaissance te soit agréable, ô Abu al-Mundhir ! »", "id": "Telah menceritakan kepada kami [Abu Bakar bin Abu Syaibah] telah menceritakan kepada kami [Abdul A'la bin Abdul A'la] dari [Al Jurairi] dari [Abu As Salil] dari [Abdullah bin Rabah Al Anshari] dari [Ubay bin Ka'ab] ia berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Hai Abu Mundzir! tahukah kamu, ayat manakah di antara ayat-ayat Al Qur`an yang ada padamu yang paling utama?\" Abu Mundzir berkata; saya menjawab, \"Allah dan Rasul-Nya yang lebih mengetahui.\" Beliau bertanya lagi: \"Hai Abu Mundzir, tahukah kamu, ayat manakah di antara ayat-ayat Al Qur`an yang ada padamu yang paling utama?\" Abu Mundzir berkata; Saya menjawab, \"ALLAHU LAA ILAAHA ILLAA HUWAL HAYYUL QAYYUUM.\" Abu Mundzir berkata; lalu beliau menepuk dadaku seraya bersabda: \"Demi Allah, semoga dadamu dipenuhi dengan ilmu, wahai Abu Mundzir", "tr": "Bize Ebû Bekir b. Ebî Şeybe rivayet etti. (Dediki): Bize Abdül a'lâ, b. Abdil a'lâ, Cüreyrî'den, o da Ebu's-Selil'den o da Abdullah Rabah El-Ensârî'den o da Ubeyyü'bnü Kâ'b'dan naklen rivayet etti. Ubeyy şöyle demiş: Resûlullah (Sallallahu Aleyhi ve Sellem) : «Yâ Ebe'l-Münzir! Allah'ın kitabından ezberinde bulunan hangi âyet daha biiyükdür? bilirmisin?» dedi. Ben : — Allah ve Resûlü bilir...» cevâbını verdim. Efendimiz (tekrar): «Yâ Ebe'l-Münzir! Allah'ın kitabından ezberinde bulunan hangi âyet daha büyükdür? bilirmisin?» diye sordu. (Bu sefer ben) : — Âyetü'l-Kürsî'dir. dedim. Bunun üzerine Resûl-i Ekrem (Sallallahu Aleyhi ve Sellem) göğsüme vurdu ve : «Vallahi ilim sana afiyet olsun Ey Ebe'l-Münzir!» buyurdular. İzah için buraya tıklayın", "ar": "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدُ الأَعْلَى بْنُ عَبْدِ الأَعْلَى، عَنِ الْجُرَيْرِيِّ، عَنْ أَبِي السَّلِيلِ، عَنْ عَبْدِ اللَّهِ بْنِ رَبَاحٍ الأَنْصَارِيِّ، عَنْ أُبَىِّ بْنِ كَعْبٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَبَا الْمُنْذِرِ أَتَدْرِي أَىُّ آيَةٍ مِنْ كِتَابِ اللَّهِ مَعَكَ أَعْظَمُ ‏\"‏ ‏.‏ قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏.‏ قَالَ ‏\"‏ يَا أَبَا الْمُنْذِرِ أَتَدْرِي أَىُّ آيَةٍ مِنْ كِتَابِ اللَّهِ مَعَكَ أَعْظَمُ ‏\"‏ ‏.‏ قَالَ قُلْتُ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ ‏.‏ قَالَ فَضَرَبَ فِي صَدْرِي وَقَالَ ‏\"‏ وَاللَّهِ لِيَهْنِكَ الْعِلْمُ أَبَا الْمُنْذِرِ ‏\"‏ ‏.‏"}}, "wudu": {"refs": [["bukhari", 135], ["muslim", 225]], "txt": {"ar": "حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ، قَالَ أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، قَالَ أَخْبَرَنَا مَعْمَرٌ، عَنْ هَمَّامِ بْنِ مُنَبِّهٍ، أَنَّهُ سَمِعَ أَبَا هُرَيْرَةَ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ لاَ تُقْبَلُ صَلاَةُ مَنْ أَحْدَثَ حَتَّى يَتَوَضَّأَ ‏\"‏‏.‏ قَالَ رَجُلٌ مِنْ حَضْرَمَوْتَ مَا الْحَدَثُ يَا أَبَا هُرَيْرَةَ قَالَ فُسَاءٌ أَوْ ضُرَاطٌ‏.‏", "en": "Narrated Abu Huraira:Allah's Messenger (ﷺ) said, \"The prayer of a person who does Hadath (passes urine, stool or wind) is not accepted till he performs the ablution.\" A person from Hadaramout asked Abu Huraira, \"What is 'Hadath'?\" Abu Huraira replied, \" 'Hadath' means the passing of wind", "fr": "Rapporté par Abu Huraira : Le Messager d’Allah (ﷺ) a dit : « La prière de celui qui est en état d’impureté (après avoir uriné, déféqué ou émis un vent) n’est pas acceptée tant qu’il n’a pas fait les ablutions. » Un homme du Hadramout a demandé à Abu Huraira : « Qu’est-ce que ‘l’état d’impureté’ ? » Abu Huraira a répondu : « Cela signifie avoir émis un vent. »", "tr": "Ebu Hureyre r.a. şöyle demiştir: Resulullâh sallallahu aleyhi ve sellem: \"Kendisinde hades vâkı` olan kimsenin namazı (o kimse) abdest almadıkça kabul olunmaz.\" buyurdu. Hadramevt ahâlîsinden biri: \"Ya Eba Hureyre, hades nedir?\" diye sordu. \"Sessiz veya sesli yel.\" cevâbını verdi", "id": "Telah menceritakan kepada kami [Ishaq bin Ibrahim Al Hanzhali] berkata, telah mengabarkan kepada kami [Abdurrazaq] berkata, telah mengabarkan kepada kami [Ma'mar] dari [Hammam bin Munabbih] bahwa ia mendengar [Abu Hurairah] berkata, \"Rasulullah shallallahu 'alaihi wasallam bersabda: \"Tidak akan diterima shalat seseorang yang berhadats hingga dia berwudlu.\" Seorang laki-laki dari Hadlramaut berkata, \"Apa yang dimaksud dengan hadats wahai Abu Hurairah?\" Abu Hurairah menjawab, \"Kentut baik dengan suara atau tidak"}}, "hajj_une": {"refs": [["muslim", 1337]], "txt": {"ar": "وَحَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا الرَّبِيعُ بْنُ مُسْلِمٍ الْقُرَشِيُّ، عَنْ مُحَمَّدِ بْنِ زِيَادٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ خَطَبَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ أَيُّهَا النَّاسُ قَدْ فَرَضَ اللَّهُ عَلَيْكُمُ الْحَجَّ فَحُجُّوا ‏\"‏ ‏.‏ فَقَالَ رَجُلٌ أَكُلَّ عَامٍ يَا رَسُولَ اللَّهِ فَسَكَتَ حَتَّى قَالَهَا ثَلاَثًا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَوْ قُلْتُ نَعَمْ لَوَجَبَتْ وَلَمَا اسْتَطَعْتُمْ - ثُمَّ قَالَ - ذَرُونِي مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ وَاخْتِلاَفِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِشَىْءٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ شَىْءٍ فَدَعُوهُ ‏\"‏ ‏.‏", "en": "Abu Huraira (Allah be pleased with him) reported:Allah's Messenger (ﷺ) addressed us and said: O people, Allah has made Hajj obligatory for you; so perform Hajj. Thereupon a person said: Messenger of Allah, (is it to be performed) every year? He (the Holy Prophet) kept quiet, and he repeated (these words) thrice, whereupon Allah's Messenger (ﷺ) said: If I were to say\" Yes,\" it would become obligatory (for you to perform it every year) and you would not be able to do it. Then he said: Leave me with what I have left to you, for those who were before you were desroyed because of excessive questioning, and their opposition to their apostles. So when I command you to do anything, do it as much as it lies in your power and when I forbid you to do anything, then abandon it", "fr": "Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ nous a adressé un discours et a dit : « Ô gens, Allah a rendu le Hajj obligatoire pour vous ; accomplissez donc le Hajj. » Quelqu’un demanda : « Ô Messager d’Allah, est-ce chaque année ? » Il garda le silence, et la question fut répétée trois fois. Le Messager d’Allah ﷺ répondit : « Si j’avais dit “oui”, cela serait devenu obligatoire et vous n’auriez pas pu le supporter. Laissez-moi donc avec ce que je vous ai laissé. Ceux qui vous ont précédés ont été détruits à cause de leurs questions excessives et de leur opposition à leurs prophètes. Quand je vous ordonne quelque chose, faites-le autant que vous le pouvez, et quand je vous interdis quelque chose, abstenez-vous-en. »", "id": "Dan telah menceritakan kepadaku [Zuhair bin Harb] Telah menceritakan kepada kami [Yazid bin Harun] telah mengabarkan kepada kami [Ar Rabi' bin Muslim Al Qarasyi] dari [Muhammad bin Ziyad] dari [Abu Hurairah] ia berkata; Rasulullah shallallahu 'alaihi wasallam menyampaikan khutbah kepada kami seraya bersabda: \"Wahai sekalian manusia, Allah telah mewajibkan atas kalian untuk menunaikan ibadah haji. Karena itu, tunaikanlah ibadah haji.\" Kemudian seorang laki-laki bertanya, \"Apakah setiap tahun ya Rasulullah?\" beliau terdiam beberapa saat, hingga laki-laki itu mengulanginya hingga tiga kali. Maka beliau pun bersabda: \"Sekiranya aku menjawab, 'Ya' niscaya akan menjadi kewajiban setiap tahun dan kalian tidak akan sanggup melaksanakannya. Karena itu, biarkanlah apa adanya masalah yang kutinggalkan untuk kalian. Sesungguhnya orang-orang yang sebelum kamu mendapat celaka karena mereka banyak tanya dan suka mendebat para Nabi mereka. karena itu, bila kuperintahkan mengerjakan sesuatu, laksanakanlah sebisa-bisanya, dan apabila kularang kalian mengerjakan sesuatu, maka hentikanlah segera", "tr": "Bana Züheyr b. Harb rivayet etti. (Dediki): Bize Yezîd b. Hârûn rivayet etti. (Dediki): Bize Rabi' b. Müslim El-Kuraşî Muhammed b. Ziyâd'dan, o da Ebû Hureyre'den naklen haber verdi. Ebû Hureyre şöyle demiş: «Resulullah (Sallallahu Aleyhi ve Sellem) bize hutbe okuyarak: — Ey cemaat! Allah size haccı farz kılmıştır. Binâenaleyh hacc edin! buyurdular. Bunun üzerine bir adam ayağa kalkarak: — Her sene mi yâ Resûlallah? diye sordu. Resulullah (Sallallahu Aleyhi ve Sellem) sükût buyurdu. Hattâ o zât sözünü üç defa tekrarladı. Nihayet: — Evet desem (her sene) vâcib olur. Siz de buna güç yetiremezsiniz buyurdu ve şunu ilâve etti: — Ben sîzi bıraktığım müddetçe siz de beni bırakın. Sizden önce geçenler ancak çok sual sormaları ve Nebileri hakkında ihtilâfa düşmeleri sebebiyle helak olmuşlardır. Ben size bir şey emrettimmi ondan gücünüzün yettiği kadarını yapın! Bir şeyden sîzi men ettimmi onu derhal bırakın!»"}}, "hajj_pardon": {"refs": [["bukhari", 1521], ["muslim", 1350]], "txt": {"en": "Narrated Abu Huraira:The Prophet (ﷺ) said, \"Whoever performs Hajj for Allah's pleasure and does not have sexual relations with his wife, and does not do evil or sins then he will return (after Hajj free from all sins) as if he were born anew", "fr": "Rapporté par Abu Huraira : Le Prophète (ﷺ) a dit : « Celui qui accomplit le Hajj pour plaire à Allah, sans avoir de relations intimes avec sa femme, sans commettre de mauvaises actions ni de péchés, reviendra (du Hajj pur de tout péché) comme au jour où il est né. »", "id": "Telah menceritakan kepada kami [Adam] telah menceritakan kepada kami [Syu'bah] telah menceritakan kepada kami [Sayyar Abu Al Hakam] berkata; aku mendengar [Abu Hazim] berkata; aku mendengar [Abu Hurairah radliallahu 'anhu] berkata; Aku mendengar Nabi shallallahu 'alaihi wasallam bersabda: \"Barangsiapa melaksanakan hajji lalu dia tidak berkata, -kata kotor dn tidak berbuat fasik maka dia kembali seperti hari saat dilahirkan oleh ibunya", "tr": "(Ebû Hureyre r.a., \"Resûlullah Sallallahu aleyhi ve Sellem'i, \"Kim Allah için hacceder ve bu sırada) cinsel ilişkiye girmez ve fasıklık da yapmaz ise (hacdan) annesinden doğduğu günkü gibi (günahsız olarak) döner\" buyururken işittim\" demiştir. Tekrar:", "ar": "حَدَّثَنَا آدَمُ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا سَيَّارٌ أَبُو الْحَكَمِ، قَالَ سَمِعْتُ أَبَا حَازِمٍ، قَالَ سَمِعْتُ أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ مَنْ حَجَّ لِلَّهِ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ ‏\"‏‏.‏"}}, "arafa": {"refs": [["abudawud", 1949], ["tirmidhi", 889]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنِي بُكَيْرُ بْنُ عَطَاءٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي يَعْمَرَ الدِّيلِيِّ، قَالَ أَتَيْتُ النَّبِيَّ صلى الله عليه وسلم وَهُوَ بِعَرَفَةَ فَجَاءَ نَاسٌ - أَوْ نَفَرٌ - مِنْ أَهْلِ نَجْدٍ فَأَمَرُوا رَجُلاً فَنَادَى رَسُولَ اللَّهِ صلى الله عليه وسلم كَيْفَ الْحَجُّ فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم رَجُلاً فَنَادَى ‏\"‏ الْحَجُّ الْحَجُّ يَوْمُ عَرَفَةَ مَنْ جَاءَ قَبْلَ صَلاَةِ الصُّبْحِ مِنْ لَيْلَةِ جَمْعٍ فَتَمَّ حَجُّهُ أَيَّامُ مِنًى ثَلاَثَةٌ فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلاَ إِثْمَ عَلَيْهِ ‏\"‏ ‏.‏ قَالَ ثُمَّ أَرْدَفَ رَجُلاً خَلْفَهُ فَجَعَلَ يُنَادِي بِذَلِكَ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَلِكَ رَوَاهُ مِهْرَانُ عَنْ سُفْيَانَ قَالَ ‏\"‏ الْحَجُّ الْحَجُّ ‏\"‏ ‏.‏ مَرَّتَيْنِ وَرَوَاهُ يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ عَنْ سُفْيَانَ قَالَ ‏\"‏ الْحَجُّ ‏\"‏ ‏.‏ مَرَّةً ‏.‏", "en": "Narrated AbdurRahman Ya'mar ad-Dayli: I came to the Holy Prophet (ﷺ) when he was in Arafat. Some people or a group of people came from Najd. They commanded someone (to ask the Prophet about hajj). So he called the Messenger of Allah (ﷺ), saying: How is the hajj done? He (the Prophet) ordered a man (to reply). He shouted loudly: The hajj, the hajj is on the day of Arafah. If anyone comes over there before the dawn prayer on the night of al-Muzdalifah, his hajj will be complete. The period of halting at Mina is three days. Then whoever hastens (his departure) by two days, it is no sin for him, and whoever delays it there is no sin for him. The narrator said: He (the Prophet) then put a man behind him on the camel. He began to proclaim this loudly. Abu Dawud said: This tradition has been narrated by Mahran from Sufyan in a similar way. This version adds: The Hajj, the Hajj, twice. The version narrated by Yaya b. Sa'id al-Qattan has the words: The Hajj only once", "fr": "Rapporté par AbdurRahman Ya’mar ad-Dayli : Je suis venu voir le Saint Prophète ﷺ alors qu’il était à Arafat. Des gens ou un groupe de personnes sont venus du Najd. Ils ont demandé à quelqu’un d’interroger le Prophète sur le hajj. Il a alors appelé le Messager d’Allah ﷺ en disant : « Comment accomplit-on le hajj ? » Le Prophète a ordonné à un homme de répondre. Il a crié à haute voix : « Le hajj, le hajj, c’est le jour de ‘Arafah. Si quelqu’un arrive là-bas avant la prière de l’aube dans la nuit d’Al Muzdalifah, son hajj sera complet. Le temps de séjour à Mina est de trois jours. Celui qui part plus tôt en deux jours, il n’y a pas de faute pour lui, et celui qui reste plus longtemps, il n’y a pas de faute pour lui. » Le narrateur a dit : Le Prophète a ensuite fait monter un homme derrière lui sur le chameau. Il a commencé à proclamer cela à haute voix. Abu Dawud a dit : Ce récit a été rapporté par Mahran d’après Sufyan de façon similaire. Cette version ajoute : « Le Hajj, le Hajj », deux fois. La version rapportée par Yaya b. Sa’id al-Qattan dit : « Le Hajj n’a lieu qu’une seule fois. »", "tr": "Abdurrahman b.Ya'mur ed-Deyl(em)î'den; demiştir ki: Nebi (S.A.V.) Arafat'ta iken yanına varmıştım. Necid halkından da bazı kimseler ^Yahut bir grup- geldiler. (İçlerinden) birine (Hz. Nebi'e hacla ilgili sorular sormasını) emrettiler. (O da) Resûlullah (S.A.V.)'e, (Arafat'ta vakfeye yetişemeyen kimsenin) hacc(ı) nasıldır? diye sordu. Resûlullah (S.A.V.) de birisine emretti. (O adam da aldığı emre uyarak) \"Hac, hac, Arafe günü (vakfe yapmak) demektir, kim Müzdelife gecesi sabah olmadan (Arafat'a) gelirse haccı tamdır. Minâ günleri üçtür, kim acele eder de iki gün de (Mekke'ye dönerse) ona bir günah yoktur. (Minâ'da) geciken de günahkâr olmaz\" diye yüksek sesle bağırdı. Sonra (o bağıran adamın) arkasından bir başka adam gönderdi. O da aynı şeyleri yüksek sesle ilân etmeye başladı. Tirmizî, hac, tefsir sure; İbn Mace, menâsik; Nesai, menâsik, Ahmed b. Hanbel IV, 309-310, 335; Beyhakî, es-Sünenu'l-kübrâ, V, 116; Hâkim, el-Müstedrek, I, 464; İbn Hıbbân, Sahih, VI, 76. Ebû Dâvûd dedi ki: Bu hadisi Mihrân da Süfyân'dan (hac keli­mesini) -iki-defa tekrarlayarak- \"Hac, hac (Arafat'ta durmaktır)\" dedi, (şeklinde) rivayet etti. Yahya b. Safd el-Kattân ise Süfyân 'dan (hac kelimesini) bir kerre (söyleyerek) \"hac (Arafat'ta durmaktır) ded”, (şeklinde rivayet etti)", "id": "Telah menceritakan kepada Kami [Muhammad bin Katsir], telah menceritakan kepada Kami [Sufyan] telah menceritakan kepadaku [Bukair bin 'Atha`] dari [Abdurrahman bin Ya'mar Ad Dili], ia berkata; aku datang kepada Nabi shallallahu 'alaihi wasallam dan beliau sedang di Arafah. Kemudian datang beberapa orang dari penduduk Najed, kemudian mereka memerintahkan seorang laki-laki untuk bertanya kepada Rasulullah shallAllahu wa'alaihi wa sallam; bagaimana berhaji itu? Kemudian Rasulullah shallAllahu wa'alaihi wa sallam memerintahkan seseorang agar mengumumkan; haji adalah pada hari 'Arafah, barang siapa yang datang sebelum shalat Subuh semenjak malam di Muzdalifah maka Hajinya telah sempurna, hari-hari di Mina ada tiga, barang siapa yang menyegerakan dalam dua hari maka tidak ada dosa padanya dan barang siapa yang menunda maka tidak ada dosa baginya. Abdurrahman berkata; kemudian beliau memboncengkan seorang laki-laki di belakangnya dan menyerukan hal tersebut. Abu Daud berkata; dan demikianlah hadits yang diriwayatkan [Mihran] dari [Sufyan], ia berkata; haji, haji …… (ia menyebutkan dua kali). Dan telah diriwayatkan [Yahya Al Qaththan] dari [Sufyan], ia berkata; haji ….. (ia menyebutkan satu kali)"}}, "jibril": {"refs": [["muslim", 8]], "txt": {"ar": "حَدَّثَنِي أَبُو خَيْثَمَةَ، زُهَيْرُ بْنُ حَرْبٍ حَدَّثَنَا وَكِيعٌ، عَنْ كَهْمَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، ح وَحَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، - وَهَذَا حَدِيثُهُ - حَدَّثَنَا أَبِي، حَدَّثَنَا كَهْمَسٌ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، قَالَ كَانَ أَوَّلَ مَنْ قَالَ فِي الْقَدَرِ بِالْبَصْرَةِ مَعْبَدٌ الْجُهَنِيُّ فَانْطَلَقْتُ أَنَا وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ حَاجَّيْنِ أَوْ مُعْتَمِرَيْنِ فَقُلْنَا لَوْ لَقِينَا أَحَدًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَسَأَلْنَاهُ عَمَّا يَقُولُ هَؤُلاَءِ فِي الْقَدَرِ فَوُفِّقَ لَنَا عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ الْخَطَّابِ دَاخِلاً الْمَسْجِدَ فَاكْتَنَفْتُهُ أَنَا وَصَاحِبِي أَحَدُنَا عَنْ يَمِينِهِ وَالآخَرُ عَنْ شِمَالِهِ فَظَنَنْتُ أَنَّ صَاحِبِي سَيَكِلُ الْكَلاَمَ إِلَىَّ فَقُلْتُ أَبَا عَبْدِ الرَّحْمَنِ إِنَّهُ قَدْ ظَهَرَ قِبَلَنَا نَاسٌ يَقْرَءُونَ الْقُرْآنَ وَيَتَقَفَّرُونَ الْعِلْمَ - وَذَكَرَ مِنْ شَأْنِهِمْ - وَأَنَّهُمْ يَزْعُمُونَ أَنْ لاَ قَدَرَ وَأَنَّ الأَمْرَ أُنُفٌ ‏.‏ قَالَ فَإِذَا لَقِيتَ أُولَئِكَ فَأَخْبِرْهُمْ أَنِّي بَرِيءٌ مِنْهُمْ وَأَنَّهُمْ بُرَآءُ مِنِّي وَالَّذِي يَحْلِفُ بِهِ عَبْدُ اللَّهِ بْنُ عُمَرَ لَوْ أَنَّ لأَحَدِهِمْ مِثْلَ أُحُدٍ ذَهَبًا فَأَنْفَقَهُ مَا قَبِلَ اللَّهُ مِنْهُ حَتَّى يُؤْمِنَ بِالْقَدَرِ ثُمَّ قَالَ حَدَّثَنِي أَبِي عُمَرُ بْنُ الْخَطَّابِ قَالَ بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَاتَ يَوْمٍ إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ الشَّعَرِ لاَ يُرَى عَلَيْهِ أَثَرُ السَّفَرِ وَلاَ يَعْرِفُهُ مِنَّا أَحَدٌ حَتَّى جَلَسَ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ وَقَالَ يَا مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلاَمِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَتُقِيمَ الصَّلاَةَ وَتُؤْتِيَ الزَّكَاةَ وَتَصُومَ رَمَضَانَ وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلاً ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ الإِيمَانِ ‏.‏ قَالَ ‏\"‏ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ ‏\"‏ ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ الإِحْسَانِ ‏.‏ قَالَ ‏\"‏ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏\"‏ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ السَّاعَةِ ‏.‏ قَالَ ‏\"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ ‏\"‏ ‏.‏ قَالَ فَأَخْبِرْنِي عَنْ أَمَارَتِهَا ‏.‏ قَالَ ‏\"‏ أَنْ تَلِدَ الأَمَةُ رَبَّتَهَا وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ ‏\"‏ ‏.‏ قَالَ ثُمَّ انْطَلَقَ فَلَبِثْتُ مَلِيًّا ثُمَّ قَالَ لِي ‏\"‏ يَا عُمَرُ أَتَدْرِي مَنِ السَّائِلُ ‏\"‏ ‏.‏ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏.‏ قَالَ ‏\"‏ فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ ‏\"‏ ‏.‏", "en": "It is narrated on the authority of Yahya b. Ya'mur that the first man who discussed qadr (Divine Decree) in Basra was Ma'bad al-Juhani. I along with Humaid b. 'Abdur-Rahman Himyari set out for pilgrimage or for 'Umrah and said:Should it so happen that we come into contact with one of the Companions of the Messenger of Allah (peace be upon him) we shall ask him about what is talked about taqdir (Divine Decree). Accidentally we came across Abdullah ibn Umar ibn al-Khattab, while he was entering the mosque. My companion and I surrounded him. One of us (stood) on his right and the other stood on his left. I expected that my companion would authorize me to speak. I therefore said: Abu Abdur Rahman! There have appeared some people in our land who recite the Qur'an and pursue knowledge. And then after talking about their affairs, added: They (such people) claim that there is no such thing as Divine Decree and events are not predestined. He (Abdullah ibn Umar) said: When you happen to meet such people tell them that I have nothing to do with them and they have nothing to do with me. And verily they are in no way responsible for my (belief). Abdullah ibn Umar swore by Him (the Lord) (and said): If any one of them (who does not believe in the Divine Decree) had with him gold equal to the bulk of (the mountain) Uhud and spent it (in the way of Allah), Allah would not accept it unless he affirmed his faith in Divine Decree. He further said: My father, Umar ibn al-Khattab, told me: One day we were sitting in the company of Allah's Apostle (peace be upon him) when there appeared before us a man dressed in pure white clothes, his hair extraordinarily black. There were no signs of travel on him. None amongst us recognized him. At last he sat with the Apostle (peace be upon him) He knelt before him placed his palms on his thighs and said: Muhammad, inform me about al-Islam. The Messenger of Allah (peace be upon him) said: Al-Islam implies that you testify that there is no god but Allah and that Muhammad is the messenger of Allah, and you establish prayer, pay Zakat, observe the fast of Ramadan, and perform pilgrimage to the (House) if you are solvent enough (to bear the expense of) the journey. He (the inquirer) said: You have told the truth. He (Umar ibn al-Khattab) said: It amazed us that he would put the question and then he would himself verify the truth. He (the inquirer) said: Inform me about Iman (faith). He (the Holy Prophet) replied: That you affirm your faith in Allah, in His angels, in His Books, in His Apostles, in the Day of Judgment, and you affirm your faith in the Divine Decree about good and evil. He (the inquirer) said: You have told the truth. He (the inquirer) again said: Inform me about al-Ihsan (performance of good deeds). He (the Holy Prophet) said: That you worship Allah as if you are seeing Him, for though you don't see Him, He, verily, sees you. He (the enquirer) again said: Inform me about the hour (of the Doom). He (the Holy Prophet) remarked: One who is asked knows no more than the one who is inquiring (about it). He (the inquirer) said: Tell me some of its indications. He (the Holy Prophet) said: That the slave-girl will give birth to her mistress and master, that you will find barefooted, destitute goat-herds vying with one another in the construction of magnificent buildings. He (the narrator, Umar ibn al-Khattab) said: Then he (the inquirer) went on his way but I stayed with him (the Holy Prophet) for a long while. He then, said to me: Umar, do you know who this inquirer was? I replied: Allah and His Apostle knows best. He (the Holy Prophet) remarked: He was Gabriel (the angel). He came to you in order to instruct you in matters of religion", "fr": "Rapporté par Yahya b. Ya’mur : Le premier homme à avoir parlé du qadr (Décret divin) à Bassora fut Ma’bad al-Juhani. Avec Humaid b. ‘Abdur-Rahman Himyari, nous sommes partis en pèlerinage ou pour la ‘Umrah et nous nous sommes dit : « Si nous rencontrons un Compagnon du Messager d’Allah ﷺ, nous lui demanderons ce qu’il pense du taqdir (Décret divin). » Par hasard, nous avons croisé Abdullah ibn Umar ibn al-Khattab alors qu’il entrait dans la mosquée. Mon compagnon et moi l’avons entouré, l’un à sa droite, l’autre à sa gauche. J’espérais que mon compagnon me laisserait parler, alors j’ai dit : « Abū Abdur Rahman ! Il y a dans notre région des gens qui récitent le Coran et cherchent la connaissance. » Après avoir parlé de leur situation, j’ai ajouté : « Ils prétendent qu’il n’existe pas de Décret divin et que les événements ne sont pas prédestinés. » Il (Abdullah ibn Umar) a dit : « Lorsque vous rencontrez ces gens-là, dites-leur que je n’ai rien à voir avec eux et qu’ils n’ont rien à voir avec moi. En vérité, ils ne partagent en rien ma croyance. » Abdullah ibn Umar a juré par Allah et a dit : « Si l’un d’eux (qui ne croit pas au Décret divin) possédait de l’or équivalent à la montagne de Uhud et le dépensait (pour Allah), Allah ne l’accepterait pas tant qu’il ne croirait pas au Décret divin. » Il a ajouté : « Mon père, Umar ibn al-Khattab, m’a raconté : Un jour, nous étions assis avec le Messager d’Allah ﷺ lorsqu’un homme vêtu de vêtements d’un blanc éclatant, aux cheveux très noirs, est apparu devant nous. On ne voyait aucun signe de voyage sur lui et personne parmi nous ne le connaissait. Il s’est assis devant le Prophète ﷺ, a posé ses genoux contre les siens, a mis ses mains sur ses cuisses et a dit : “Muhammad, informe-moi sur l’islam.” Le Messager d’Allah ﷺ a dit : “L’islam, c’est que tu témoignes qu’il n’y a de dieu qu’Allah et que Muhammad est le Messager d’Allah, que tu accomplisses la prière, que tu verses la zakat, que tu jeûnes le Ramadan et que tu fasses le pèlerinage à la Maison si tu en as les moyens.” L’homme a dit : “Tu as dit vrai.” Umar ibn al-Khattab a dit : “Cela nous a étonnés qu’il pose la question puis confirme lui-même la réponse.” L’homme a dit : “Informe-moi sur la foi (iman).” Le Prophète ﷺ a répondu : “C’est que tu croies en Allah, en Ses anges, en Ses Livres, en Ses Messagers, au Jour du Jugement et que tu croies au Décret divin, qu’il soit bon ou mauvais.” L’homme a dit : “Tu as dit vrai.” Il a encore dit : “Informe-moi sur l’excellence (ihsan).” Le Prophète ﷺ a dit : “C’est que tu adores Allah comme si tu Le voyais, car même si tu ne Le vois pas, Lui te voit.” L’homme a encore dit : “Informe-moi sur l’Heure (du Jugement).” Le Prophète ﷺ a répondu : “Celui qui est interrogé n’en sait pas plus que celui qui interroge.” L’homme a dit : “Dis-moi quelques-uns de ses signes.” Le Prophète ﷺ a dit : “Quand la servante donnera naissance à sa maîtresse, et que tu verras les pieds-nus, pauvres bergers rivaliser dans la construction de hauts bâtiments.” Umar ibn al-Khattab a dit : “Puis l’homme est parti, mais je suis resté un moment avec le Prophète ﷺ. Il m’a alors dit : ‘Umar, sais-tu qui était cet homme ?’ J’ai répondu : ‘Allah et Son Messager le savent mieux.’ Le Prophète ﷺ a dit : ‘C’était Gabriel. Il est venu vous enseigner votre religion.’ »", "id": "Telah menceritakan kepadaku [Abu Khaitsamah Zuhair bin Harb] telah menceritakan kepada kami [Waki'] dari [Kahmas] dari [Abdullah bin Buraidah] dari [Yahya bin Ya'mar]. (dalam riwayat lain disebutkan) Dan telah menceritakan kepada kami [Ubaidullah bin Mu'adz al-'Anbari] dan ini haditsnya, telah menceritakan kepada kami [Bapakku] telah menceritakan kepada kami [Kahmas] dari [Ibnu Buraidah] dari [Yahya bin Ya'mar] dia berkata, \"Orang yang pertama kali membahas takdir di Bashrah adalah Ma'bad al-Juhani, maka aku dan Humaid bin Abdurrahman al-Himyari bertolak haji atau umrah, maka kami berkata, 'Seandainya kami bertemu dengan salah seorang sahabat Rasulullah shallallahu 'alaihi wasallam, maka kami akan bertanya kepadanya tentang sesuatu yang mereka katakan berkaitan dengan takdir.' Maka [Abdullah bin Umar] diberikan taufik (oleh Allah) untuk kami, sedangkan dia masuk masjid. Lalu aku dan temanku menghadangnya. Salah seorang dari kami di sebelah kanannya dan yang lain di sebelah kirinya. Lalu aku mengira bahwa temanku akan mewakilkan pembicaraan kepadaku, maka aku berkata, 'Wahai Abu Abdurrahman, sesungguhnya nampak di hadapan kami suatu kaum membaca al-Qur'an dan mencari ilmu lalu mengklaim bahwa tidak ada takdir, dan perkaranya adalah baru (tidak didahului oleh takdir dan ilmu Allah).' Maka [Abdullah bin Umar] menjawab, 'Apabila kamu bertemu orang-orang tersebut, maka kabarkanlah kepada mereka bahwa saya berlepas diri dari mereka, dan bahwa mereka berlepas diri dariku. Dan demi Dzat yang mana hamba Allah bersumpah dengan-Nya, kalau seandainya salah seorang dari kalian menafkahkan emas seperti gunung Uhud, niscaya sedekahnya tidak akan diterima hingga dia beriman kepada takdir baik dan buruk.' Dia berkata, 'Kemudian dia mulai menceritakan hadits seraya berkata, ['Umar bin al-Khaththab] berkata, 'Dahulu kami pernah berada di sisi Rasulullah shallallahu 'alaihi wasallam, lalu datanglah seorang laki-laki yang bajunya sangat putih, rambutnya sangat hitam, tidak tampak padanya bekas-bekas perjalanan. Tidak seorang pun dari kami mengenalnya, hingga dia mendatangi Nabi Shallallahu 'Alaihi Wasalam lalu menyandarkan lututnya pada lutut Nabi Shallallahu 'Alaihi Wasalam, kemudian ia berkata, 'Wahai Muhammad, kabarkanlah kepadaku tentang Islam? ' Rasulullah Shallallahu 'Alaihi Wasalam menjawab: \"Kesaksian bahwa tidak ada tuhan (yang berhak disembah) selain Allah dan bahwa Muhammad adalah hamba dan utusan-Nya, mendirikan shalat, menunaikan zakat, dan puasa Ramadlan, serta haji ke Baitullah jika kamu mampu bepergian kepadanya.' Dia berkata, 'Kamu benar.' Umar berkata, 'Maka kami kaget terhadapnya karena dia menanyakannya dan membenarkannya.' Dia bertanya lagi, 'Kabarkanlah kepadaku tentang iman itu? ' Beliau menjawab: \"Kamu beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, para Rasul-Nya, hari akhir, dan takdir baik dan buruk.\" Dia berkata, 'Kamu benar.' Dia bertanya, 'Kabarkanlah kepadaku tentang ihsan itu? ' Beliau menjawab: \"Kamu menyembah Allah seakan-akan kamu melihat-Nya, maka jika kamu tidak melihat-Nya, maka sesungguhnya Dia melihatmu.\" Dia bertanya lagi, 'Kapankah hari akhir itu? ' Beliau menjawab: \"Tidaklah orang yang ditanya itu lebih mengetahui daripada orang yang bertanya.\" Dia bertanya, 'Lalu kabarkanlah kepadaku tentang tanda-tandanya? ' Beliau menjawab: \"Apabila seorang budak melahirkan (anak) tuan-Nya, dan kamu melihat orang yang tidak beralas kaki, telanjang, miskin, penggembala kambing, namun bermegah-megahan dalam membangun bangunan.\" Kemudian dia bertolak pergi. Maka aku tetap saja heran kemudian beliau berkata; \"Wahai Umar, apakah kamu tahu siapa penanya tersebut?\" Aku menjawab, 'Allah dan Rasul-Nya lebih tahu.' Beliau bersabda: \"Itulah jibril, dia mendatangi kalian untuk mengajarkan kepada kalian tentang pengetahuan agama kalian'.\" Telah menceritakan kepada kami [Muhammad bin Ubaid al-Ghubari] dan [Abu Kamil al-Jahdari] serta [Ahmad bin Abdah] mereka berkata, telah menceritakan kepada kami [Hammad bin Yazid] dari [Mathar al Warraq] dari [Abdullah bin Buraidah] dari [Yahya bin Ya'mar] dia berkata, 'Ketika Ma'bad berkata dengan sesuatu yang dia bicarakan tentang masalah takdir, maka kami mengingkari hal tersebut.' Dia berkata lagi, 'Lalu aku melakukan haji bersama Humaid bin Abdurrahman al-Himyari.' Lalu mereka menyebutkan hadits dengan makna hadits Kahmas. Di dalamnya terdapat sebagian tambahan dan kekurangan huruf.\" Dan telah menceritakan kepada kami [Muhammad bin Hatim] telah menceritakan kepada kami [Yahya bin Sa'id al Qaththan] telah menceritakan kepada kami [Utsman bin Ghiyats] telah menceritakan kepada kami [Abdullah bin Buraidah] dari [Yahya bin Ya'mar] dan [Humaid bin Abdurrahman] keduanya berkata, \"Kami bertemu [Abdullah bin Umar], lalu kami menyebutkan tentang takdir dan pendapat mereka tentangnya, lalu dia mengisahkan hadits tersebut sebagaimana hadits mereka dari [Umar] radlialllahu 'anhuma dari Nabi shallallahu 'alaihi wasallam, dan di dalamnya terdapat suatu tambahan dan pengurangan.\" Dan telah menceritakan kepada kami [Hajjaj bin asy-Sya'ir] telah menceritakan kepada kami [Yunus bin Muhammad] telah menceritakan kepada kami [al-Mu'tamir] dari [Bapaknya] dari [Yahya bin Ya'mar] dari [Ibnu Umar] dari [Umar] dari Nabi shallallahu 'alaihi wasallam dengan semisal hadits mereka", "tr": "Bana Ebu Hayseme Zuheyr b. Harb tahdis etti, bize Veki', Kehmes'den tahdis etti. O Abdullah b. Bureyde'den, o Yahya b. Ya'mer'den (H) Bize Ubeydullah b. Muaz el-Anberi de tahdis etti -ki bu onun (naklettiği) hadisidir-, bize babam tahdis etti, bize Kehmes, İbn Bureyde'den tahdis etti. O Yahya b. Ya'mer'den şöyle dediğini nakletti: - Kader hakkında ilk konuşan kişi Basra'da Ma'bed el-Cuheni oldu. Ben ve Humeyd b. Abdurrahman el-Himyeri hac -ya da umre- yapmak üzere gitmiştik. Kendi kendimize: Rasulullah (Sallallahu aleyhi ve Sellem)'in ashabından birisi ile karşılaşsak da bunların kader hakkında söylediklerine dair ona (kanaatini) sorsak, dedik. Abdullah b. Ömer b. el-Hattab'a mescide girerken rastgeldik. Ben ve arkadaşım birimiz sağından, diğerimiz solundan olmak üzere etrafında durduk. Arkadaşımın sözü bana bırakacağını düşünerek: - Ey Ebu Abdurrahman, dedim. Bizim oralarda birtakım insanlar çıktı. Bunlar Kur'an'ı okuyorlar, ilmi araştırıyorlar -ve böyle diyerek onların durumlarını zikretti.- Bununla birlikte onlar kader diye bir şey olmadığını, olayların (Allah'ın ezeli ilmi söz konusu olmaksızın) kendiliğinden meydana geldiğini iddia ediyorlar. (İbn Ömer) dedi ki: Bunlarla karşılaşacak olursan benim onlardan uzak olduğumu, onların da benden uzak olduklarını onlara haber ver. Abdullah b. Ömer'in adına yemin ettiği zat hakkı için eğer onlardan (1/37a) birinin Uhud dağı gibi altını bulunsa ve onu (Allah yolunda) infak etse kadere iman etmedikçe Allah ondan (infakını) kabul etmez. Sonra şunları ekledi: -Babam Ömer b. el-Hattab bana tahdis edip dedi ki: Bir gün Rasulullah (Sallallahu aleyhi ve Sellem)'in huzurunda idik. Birden yanımıza elbiseleri oldukça beyaz, saçı oldukça siyah, üzerinde yolculuk izleri görülmeyen ve aramızdan kimsenin de tanımadığı bir adam çıkageldi. Nebi (Sallallahu aleyhi ve Sellem)'in yanına oturuverdi, dizlerini onun dizlerine dayadı. Ellerini uylukları üzerine koydu ve: - Ey Muhammed, bana İslam'dan haber ver, dedi. RasuluIlah (Sallallahu aleyhi ve Sellem): \"İslam Allah'tan başka hiçbir ilah olmadığına, Muhammed'in Allah'ın Rasulü olduğuna şahadet etmen, namazı dosdoğru kılman, zekatı vermen, Ramazan ayı orucunu tutman, oraya gitmek için yol bulabildiğin takdirde beyti haccetmendir\" buyurdu. Adam: Doğru söyledin, dedi. (Ömer): Biz onun bu yaptığına hayret ettik. Hem ona soru soruyor, hem ona doğru söylüyorsun diyordu, dedi. Sonra adam: Bana imandan haber ver, dedi. Allah Rasulü (Sallallahu aleyhi ve Sellem): ''Allah'a, meleklerine, kitaplarına, rasullerine, ahiret gününe iman etmen, bir de hayrıyla, şerriyle kadere iman etmendir\" buyurdu. (Adam): Doğru söyledin, dedi. Sonra: Bana ihsandan haber ver, dedi. Allah Rasulü (Sallallahu aleyhi ve Sellem): ''Allah'a onu görüyormuşsun gibi ibadet etmendir. Sen onu görmüyorsan da şüphesiz o seni görür\" buyurdu. Adam: Bana kıyamet'ten haber ver dedi. Allah Rasulü (Sallallahu aleyhi ve Sellem): \"Bu hususta kendisine soru sorulan sorandan daha bilgili değildir\" buyurdu. Adam: O halde bana onun alamet(ler)ini haber ver, dedi. Allah Rasulü (Sallallahu aleyhi ve Sellem): \"Cariyenin kendi hanımefendisini doğurması, yalınayak, çıplak, yoksul koyun çobanı kimselerin uzun (yüksek) bina yapmakta birbirleriyle yarıştıklarını görmendir\" buyurdu. (Ömer) dedi ki: Sonra adam gitti. Uzunca bir süre bekledim sonra (Allah Rasulü) bana: \"Ey Ömer, o soru soran kimdi biliyor musun\" buyurdu. Ben: Allah ve Rasulü en iyi bilendir, dedim. O: \"O (gelen) Cibril'di. Size dininizi öğretmek üzere gelmişti\" buyurdu. Diğer tahric: Ebu Davud, 4695; Tırmizi, 2610; Nesai, 5005; İbn Mace, 63; Tuhfetu'l-Eşraf"}}, "vie": {"refs": [["bukhari", 3902]], "txt": {"ar": "حَدَّثَنَا مَطَرُ بْنُ الْفَضْلِ، حَدَّثَنَا رَوْحٌ، حَدَّثَنَا هِشَامٌ، حَدَّثَنَا عِكْرِمَةُ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ بُعِثَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَرْبَعِينَ سَنَةً، فَمَكُثَ بِمَكَّةَ ثَلاَثَ عَشْرَةَ سَنَةً يُوحَى إِلَيْهِ، ثُمَّ أُمِرَ بِالْهِجْرَةِ فَهَاجَرَ عَشْرَ سِنِينَ، وَمَاتَ وَهُوَ ابْنُ ثَلاَثٍ وَسِتِّينَ‏.‏", "id": "Telah menceritakan kepada kami [Mathar bin Al Fadlal] telah menceritakan kepada kami [Rauh bin 'Ubadah] telah menceritakan kepada kami [Hisyam] telah menceritakan kepada kami ['Ikrimah] dari [Ibnu 'Abbas] radliallahu 'anhuma berkata; Rasulullah shallallahu 'alaihi wasallam diutus sebagai rasul saat beliau berusia empat puluh tahun, beliau tinggal di Makkah selama tiga belas tahun menerima wahyu, kemudian beliau diperintahkan untuk berhijrah, Maka beliau berhijrah dan (menetap di Madinah) selama sepuluh tahun hingga beliau wafat ketika berusia enam puluh tiga tahun", "tr": "İbn Abbas r.a. dedi ki: \"Resulullah Sallallahu Aleyhi ve Sellem'e kırk yaşında iken Nebilik verildi. (Bundan sonra) Mekke'de on üç yıl boyunca kaldı ve bu süre zarfında ona vahiy geliyordu. Sonra hicret etmekle emrolundu, o da hicret etti. (Hicret'ten sonra) on yıl muhacir kaldı ve altmış üç yaşında iken vefat etti", "en": "Narrated Ibn `Abbas:Allah's Messenger (ﷺ) started receiving the Divine Inspiration at the age of forty. Then he stayed in Mecca for thirteen years, receiving the Divine Revelation. Then he was ordered to migrate and he lived as an Emigrant for ten years and then died at the age of sixty-three (years)", "fr": "Rapporté par Ibn `Abbas : Le Messager d’Allah (ﷺ) a commencé à recevoir la Révélation divine à l’âge de quarante ans. Ensuite, il est resté treize ans à La Mecque à recevoir la Révélation. Puis il a reçu l’ordre d’émigrer et il a vécu en tant qu’émigré pendant dix ans, puis il est décédé à l’âge de soixante-trois ans"}}, "idoles": {"refs": [["bukhari", 4287], ["muslim", 1781]], "txt": {"ar": "حَدَّثَنَا صَدَقَةُ بْنُ الْفَضْلِ، أَخْبَرَنَا ابْنُ عُيَيْنَةَ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، عَنْ أَبِي مَعْمَرٍ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ قَالَ دَخَلَ النَّبِيُّ صلى الله عليه وسلم مَكَّةَ يَوْمَ الْفَتْحِ وَحَوْلَ الْبَيْتِ سِتُّونَ وَثَلاَثُمِائَةِ نُصُبٍ، فَجَعَلَ يَطْعُنُهَا بِعُودٍ فِي يَدِهِ وَيَقُولُ ‏ \"‏ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ، جَاءَ الْحَقُّ، وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ ‏\"‏‏.‏", "en": "Narrated `Abdullah:When the Prophet (ﷺ) entered Mecca on the day of the Conquest, there were 360 idols around the Ka`ba. The Prophet (ﷺ) started striking them with a stick he had in his hand and was saying, \"Truth has come and Falsehood will neither start nor will it reappear", "tr": "Abdullah r.a.'dan dedi ki: \"Nebi Sallallahu Aleyhi ve Sellem fetih günü Mekke'ye girdiğinde Beyt'in etrafında üçyüz altmış dikili put vardı. Elinde bulunan bir sopa ile o putları dürterken: Hak geldi, batıl da can çekişerek yok oldu. Hak geldi, batıl ise ne bir şeyi baştan var edebilir, ne de tekraren bir şeyi iade edebilir, diyordu", "fr": "Rapporté par ‘Abdullah : Le Prophète ﷺ entra à La Mecque le jour de la conquête, et autour de la Maison il y avait trois cent soixante statues. Il se mit à les frapper avec un bâton qu’il tenait à la main, en disant : « La vérité est venue et le faux a disparu. La vérité est venue, et le faux ne commence rien et ne ramène rien. »", "id": "Telah menceritakan kepada kami [Shadaqah bin Fadhl] Telah mengabarkan kepada kami [Ibnu 'Uyainah] dari [Ibnu Abu Najih] dari [Mujahid] dari [Abu Ma'mar] dari [Abdullah] radliallahu 'anhu, katanya, Nabi shallallahu 'alaihi wasallam memasuki Makkah pada penaklukan Makkah yang ketika itu di sekitar ka'bah ada tiga ratus enam puluh patung, lantas beliau porak-porandakan dengan sebongkah kayu di tangannya seraya beliau serukan \"Sekarang telah datang kebenaran dan kebatilan telah musnah.\" (QS. Isra'; 81), \"Sekarang kebenaran telah datang dan kebatilan tak akan terulang dan kembali lagi.\" (QS. Saba':)"}}, "compilation": {"refs": [["bukhari", 4986]], "txt": {"ar": "حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، عَنْ إِبْرَاهِيمَ بْنِ سَعْدٍ، حَدَّثَنَا ابْنُ شِهَابٍ، عَنْ عُبَيْدِ بْنِ السَّبَّاقِ، أَنَّ زَيْدَ بْنَ ثَابِتٍ ـ رضى الله عنه ـ قَالَ أَرْسَلَ إِلَىَّ أَبُو بَكْرٍ مَقْتَلَ أَهْلِ الْيَمَامَةِ فَإِذَا عُمَرُ بْنُ الْخَطَّابِ عِنْدَهُ قَالَ أَبُو بَكْرٍ ـ رضى الله عنه ـ إِنَّ عُمَرَ أَتَانِي فَقَالَ إِنَّ الْقَتْلَ قَدِ اسْتَحَرَّ يَوْمَ الْيَمَامَةِ بِقُرَّاءِ الْقُرْآنِ وَإِنِّي أَخْشَى أَنْ يَسْتَحِرَّ الْقَتْلُ بِالْقُرَّاءِ بِالْمَوَاطِنِ، فَيَذْهَبَ كَثِيرٌ مِنَ الْقُرْآنِ وَإِنِّي أَرَى أَنْ تَأْمُرَ بِجَمْعِ الْقُرْآنِ‏.‏ قُلْتُ لِعُمَرَ كَيْفَ تَفْعَلُ شَيْئًا لَمْ يَفْعَلْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَ عُمَرُ هَذَا وَاللَّهِ خَيْرٌ‏.‏ فَلَمْ يَزَلْ عُمَرُ يُرَاجِعُنِي حَتَّى شَرَحَ اللَّهُ صَدْرِي لِذَلِكَ، وَرَأَيْتُ فِي ذَلِكَ الَّذِي رَأَى عُمَرُ‏.‏ قَالَ زَيْدٌ قَالَ أَبُو بَكْرٍ إِنَّكَ رَجُلٌ شَابٌّ عَاقِلٌ لاَ نَتَّهِمُكَ، وَقَدْ كُنْتَ تَكْتُبُ الْوَحْىَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَتَتَبَّعِ الْقُرْآنَ فَاجْمَعْهُ فَوَاللَّهِ لَوْ كَلَّفُونِي نَقْلَ جَبَلٍ مِنَ الْجِبَالِ مَا كَانَ أَثْقَلَ عَلَىَّ مِمَّا أَمَرَنِي مِنْ جَمْعِ الْقُرْآنِ قُلْتُ كَيْفَ تَفْعَلُونَ شَيْئًا لَمْ يَفْعَلْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَ هُوَ وَاللَّهِ خَيْرٌ فَلَمْ يَزَلْ أَبُو بَكْرٍ يُرَاجِعُنِي حَتَّى شَرَحَ اللَّهُ صَدْرِي لِلَّذِي شَرَحَ لَهُ صَدْرَ أَبِي بَكْرٍ وَعُمَرَ ـ رضى الله عنهما ـ فَتَتَبَّعْتُ الْقُرْآنَ أَجْمَعُهُ مِنَ الْعُسُبِ وَاللِّخَافِ وَصُدُورِ الرِّجَالِ حَتَّى وَجَدْتُ آخِرَ سُورَةِ التَّوْبَةِ مَعَ أَبِي خُزَيْمَةَ الأَنْصَارِيِّ لَمْ أَجِدْهَا مَعَ أَحَدٍ غَيْرَهُ ‏{‏لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ‏}‏ حَتَّى خَاتِمَةِ بَرَاءَةَ، فَكَانَتِ الصُّحُفُ عِنْدَ أَبِي بَكْرٍ حَتَّى تَوَفَّاهُ اللَّهُ ثُمَّ عِنْدَ عُمَرَ حَيَاتَهُ ثُمَّ عِنْدَ حَفْصَةَ بِنْتِ عُمَرَ ـ رضى الله عنه ـ‏.‏", "en": "Narrated Zaid bin Thabit:Abu Bakr As-Siddiq sent for me when the people of Yamama had been killed (i.e., a number of the Prophet's Companions who fought against Musailima). (I went to him) and found `Umar bin Al- Khattab sitting with him. Abu Bakr then said (to me), \"`Umar has come to me and said: \"Casualties were heavy among the Qurra' of the Qur'an (i.e. those who knew the Qur'an by heart) on the day of the Battle of Yamama, and I am afraid that more heavy casualties may take place among the Qurra' on other battlefields, whereby a large part of the Qur'an may be lost. Therefore I suggest, you (Abu Bakr) order that the Qur'an be collected.\" I said to `Umar, \"How can you do something which Allah's Apostle did not do?\" `Umar said, \"By Allah, that is a good project.\" `Umar kept on urging me to accept his proposal till Allah opened my chest for it and I began to realize the good in the idea which `Umar had realized.\" Then Abu Bakr said (to me). 'You are a wise young man and we do not have any suspicion about you, and you used to write the Divine Inspiration for Allah's Messenger (ﷺ). So you should search for (the fragmentary scripts of) the Qur'an and collect it in one book.\" By Allah If they had ordered me to shift one of the mountains, it would not have been heavier for me than this ordering me to collect the Qur'an. Then I said to Abu Bakr, \"How will you do something which Allah's Messenger (ﷺ) did not do?\" Abu Bakr replied, \"By Allah, it is a good project.\" Abu Bakr kept on urging me to accept his idea until Allah opened my chest for what He had opened the chests of Abu Bakr and `Umar. So I started looking for the Qur'an and collecting it from (what was written on) palme stalks, thin white stones and also from the men who knew it by heart, till I found the last Verse of Surat at-Tauba (Repentance) with Abi Khuzaima Al-Ansari, and I did not find it with anybody other than him. The Verse is: 'Verily there has come unto you an Apostle (Muhammad) from amongst yourselves. It grieves him that you should receive any injury or difficulty..(till the end of Surat-Baraa' (at-Tauba) (9.128-129). Then the complete manuscripts (copy) of the Qur'an remained with Abu Bakr till he died, then with `Umar till the end of his life, and then with Hafsa, the daughter of `Umar", "id": "Telah menceritakan kepada kami [Musa bin Isa'il] dari [Ibrahim bin Sa'd] Telah menceritakan kepada kami [Ibnu Syihab] dari [Ubaid bin As Sabbaq] bahwa [Zaid bin Tsabit] radliallahu 'anhu, ia berkata; Abu Bakar mengirim para korban perang Yamamah kepadaku, dan ternyata Umar bin Al Khaththab ada di sisinya. Abu Bakar radliallahu 'anhu berkata, \"Sesungguhnya Umar mendatangiku dan berkata, 'Mayoritas korban perang Yamamah adalah para penghafal Al Qur`an. Dengan gugurnya mayoritas penghafal Al Qur`an, maka aku khawatir sebagian besar Al Qur`an juga akan hilang. Maka aku berpendapat, sebaiknya Anda segera memerintahkan guna melakukan dokumentasi alquran.' Maka aku pun bertanya kepada Umar, 'Bagaimana kamu akan melakukan sesuatu yang belum pernah dilakukan oleh Rasulullah shallallahu 'alaihi wasallam? ' Umar menjawab, 'Perkara ini, demi Allah adalah ide yang baik.' Umar selalu membujukku hingga Allah memberikan kelapangan dadaku, dan akhirnya aku sependapat dengan Umar.\" Zaid berkata; Abu Bakar berkata, \"Sesungguhnya kamu adalah seorang pemuda yang cerdas, kami sama sekali tidak curiga sedikit pun padamu. Dan sungguh, kamulah yang telah menulis wahyu untuk Rasulullah shallallahu 'alaihi wasallam. Karena itu, telusurilah Al Qur`an dan kumpulkanlah.\" Zaid berkata, \"Demi Allah, sekiranya mereka memerintahkanku untuk memindahkan gunung, niscaya hal itu tidaklah lebih berat daripada apa yang mereka perintahkan padaku, yakni dokumentasi alquran.\" Zaid bertanya, \"Bagaimana kalian melakukan sesuatu yang belum pernah dilakukan oleh Rasulullah shallallahu 'alaihi wasallam?\" Ia menjawab, \"Demi Allah, itu adalah kebaikan.\" Abu Bakar terus membujukku, hinnga Allah pun memberikan kelapangan dadaku, sebagaimana Abu Bakar dan Umar radliallahu 'anhuma. Maka aku pun mulai menelusuri Al Qur`an, mengumpulkannya dari tulang-tulang, kulit-kulit dan dari hafalan para Qari`. Dan akhirnya aku pun mendapatkan bagian akhir dari surat At Taubah bersama Abu Khuzaimah Al Anshari, yang aku tidak mendapatkannya pada seorang pun selainnya. Yakni ayat: 'Sungguh, telah datang pada kalian seorang Rasul dari kaum kalian sendiri, yang sangat berat olehnya kesulitan yang menimpa kalian..'\" hingga akhir surat Al Bara`ah. Lembaran-lembaran Al Qur`an itu pun tetap tersimpan pada Abu Bakar hingga Allah mewafatkannya. Kemudian beralih kepada Umar semasa hidupnya, lalu berpindah lagi ke tangan Hafshah binti Umar radliallahu 'anhu", "tr": "Zeyd İbn Sabit'ten şöyle söylediği nakledilmiştir: \"Hz. Ebu Bekir Yemame'de kurra' (Kur'an hafız) ların öldürülmesinin ardından haber yollayıp beni çağırttı. Yanına vardığım zaman, Ömer'in orada bulunduğunu fark ettim. Ebu Bekir dedi ki: Ömer bana gelip 'Yemame savaşında Kur'an hafızlarından önemli bir kısmı şehid oldu. Ben diğer savaşlarda da, hafızların ağır zayiat vermesinden ve Kur'an'ın bir çok kısmının kaybolmasından endişe ediyorum. Bu yüzden Kur'an'ın toplanmasını emretmen gerektiğini düşünüyorum' dedi. Ona 'Nebi Sallallahu Aleyhi ve Sellem'in yapmadığı bir şeyi nasıl yaparız?' diye itiraz ettim. Ömer, 'Allah'a yemin ederim ki, bu hayırlı bir iştir' dedi. Israrla benden böyle bir şey yapmamı istedi. Nihayet Allah Teala aklıma bu işi yatırdı. Ben de Ömer gibi düşünür oldum.\" Zeyd olayı anlatmaya şöyle devam etti: \"Ebu Bekir bana: 'Sen genç ve akıllı birisin. Bu güne kadar senin bir eksikliğini gören ve seni bir konuda itham eden olmadı. Nebi Sallallahu Aleyhi ve Sellem. için vahyi yazıyordun. O halde, Kur'an'ı araştırıp topla!' dedi. Allah'a yemin ederim ki, beni dağlardan birini taşımakla sorumlu tutsaydı, bu, bana emrettiği Kur'an'ı toplama görevinden daha ağır olmazdı. Ebu Bekir'e 'Allah Resulünün yapmadığı birşeyi sizler nasıl yaparsınız' diyerek itiraz ettim. O da 'Allah'a and olsun ki, bu hayırlı bir iştir' dedi. Ebu Bekir beni ikna etmek için ısrarlarını sürdürdü. Nihayet, Allah Teala Ebu Bekir ve Ömer'in aklına yatanı, benim de aklıma yatırdı. Sonunda Kur'an'ı bir araya getirmek için o güne kadar hurma dallarında, yassı taşlar üzerinde yazılı olanları ve hafızların hafızalarında bulunanları toplamaya başladım. \"Andalsun size kendinizden öyle bir Nebi gelmiştir ki, sizin sıkıntıya uğramanzz ona çok ağır gelir, \"(Tevbe 128) ayetinden itibaren Tevbe suresinin sonuna kadar olan (iki ayetlik) kısmı sadece Ebu Huzeyme el-Ensarı'nin yanında buldum. Onun dışında başka birinde bulamadım. Toplayıp yazdığım ve bir araya getirdiğim sahifeleri Halife Ebu Bekr'e teslim ettim. Bunlar, vefat edinceye kadar Ebu Bekir'in yanında kaldı. Sonra Ömer Halife olunca o teslim aldı ve hayatı boyunca onda kaldı. Daha sonra bu mushaf, Ömer'in kızı Hafsa'ya geçti", "fr": "Rapporté par Zaid bin Thabit : Abu Bakr As-Siddiq m’a fait venir après la bataille de Yamama, où de nombreux compagnons du Prophète avaient été tués en combattant Musailima. J’ai trouvé `Umar bin Al-Khattab avec lui. Abu Bakr m’a dit : « `Umar est venu me voir et m’a dit : ‘Beaucoup de ceux qui connaissaient le Coran par cœur sont morts à Yamama, et j’ai peur qu’il y ait encore plus de pertes dans d’autres batailles, ce qui risquerait de faire disparaître une grande partie du Coran. Je propose donc que tu ordonnes de rassembler le Coran.’ » J’ai dit à `Umar : « Comment peux-tu faire quelque chose que le Messager d’Allah n’a pas fait ? » `Umar répondit : « Par Allah, c’est une bonne initiative. » Il insista jusqu’à ce qu’Allah ouvre mon cœur à cette idée, comme Il l’avait fait pour `Umar. Abu Bakr me dit alors : « Tu es un jeune homme sage, nous n’avons aucun doute sur toi, et tu écrivais la révélation pour le Messager d’Allah (ﷺ). Cherche donc les fragments du Coran et rassemble-les dans un seul livre. » Par Allah, si on m’avait demandé de déplacer une montagne, cela n’aurait pas été plus difficile que de rassembler le Coran. J’ai alors demandé à Abu Bakr : « Comment vas-tu faire quelque chose que le Messager d’Allah (ﷺ) n’a pas fait ? » Il répondit : « Par Allah, c’est une bonne chose. » Il insista jusqu’à ce qu’Allah ouvre mon cœur comme Il l’avait fait pour Abu Bakr et `Umar. J’ai donc commencé à chercher le Coran, à le rassembler à partir de tiges de palmier, de pierres blanches fines et auprès des hommes qui le connaissaient par cœur, jusqu’à ce que je trouve le dernier verset de la sourate At-Tawba chez Abi Khuzaima Al-Ansari, et je ne l’ai trouvé chez personne d’autre. Ce verset est : « Un Messager issu de vous est venu à vous. Ce qui vous fait du mal lui pèse… » (jusqu’à la fin de la sourate At-Tawba, 9:128-129). Le manuscrit complet du Coran resta chez Abu Bakr jusqu’à sa mort, puis chez `Umar jusqu’à la fin de sa vie, puis chez Hafsa, la fille de `Umar"}}, "copies": {"refs": [["bukhari", 4987]], "txt": {"ar": "حَدَّثَنَا مُوسَى، حَدَّثَنَا إِبْرَاهِيمُ، حَدَّثَنَا ابْنُ شِهَابٍ، أَنَّ أَنَسَ بْنَ مَالِكٍ، حَدَّثَهُ أَنَّ حُذَيْفَةَ بْنَ الْيَمَانِ قَدِمَ عَلَى عُثْمَانَ وَكَانَ يُغَازِي أَهْلَ الشَّأْمِ فِي فَتْحِ إِرْمِينِيَةَ وَأَذْرَبِيجَانَ مَعَ أَهْلِ الْعِرَاقِ فَأَفْزَعَ حُذَيْفَةَ اخْتِلاَفُهُمْ فِي الْقِرَاءَةِ فَقَالَ حُذَيْفَةُ لِعُثْمَانَ يَا أَمِيرَ الْمُؤْمِنِينَ أَدْرِكْ هَذِهِ الأُمَّةَ قَبْلَ أَنْ يَخْتَلِفُوا فِي الْكِتَابِ اخْتِلاَفَ الْيَهُودِ وَالنَّصَارَى فَأَرْسَلَ عُثْمَانُ إِلَى حَفْصَةَ أَنْ أَرْسِلِي إِلَيْنَا بِالصُّحُفِ نَنْسَخُهَا فِي الْمَصَاحِفِ ثُمَّ نَرُدُّهَا إِلَيْكِ فَأَرْسَلَتْ بِهَا حَفْصَةُ إِلَى عُثْمَانَ فَأَمَرَ زَيْدَ بْنَ ثَابِتٍ وَعَبْدَ اللَّهِ بْنَ الزُّبَيْرِ وَسَعِيدَ بْنَ الْعَاصِ وَعَبْدَ الرَّحْمَنِ بْنَ الْحَارِثِ بْنِ هِشَامٍ فَنَسَخُوهَا فِي الْمَصَاحِفِ وَقَالَ عُثْمَانُ لِلرَّهْطِ الْقُرَشِيِّينَ الثَّلاَثَةِ إِذَا اخْتَلَفْتُمْ أَنْتُمْ وَزَيْدُ بْنُ ثَابِتٍ فِي شَىْءٍ مِنَ الْقُرْآنِ فَاكْتُبُوهُ بِلِسَانِ قُرَيْشٍ فَإِنَّمَا نَزَلَ بِلِسَانِهِمْ فَفَعَلُوا حَتَّى إِذَا نَسَخُوا الصُّحُفَ فِي الْمَصَاحِفِ رَدَّ عُثْمَانُ الصُّحُفَ إِلَى حَفْصَةَ وَأَرْسَلَ إِلَى كُلِّ أُفُقٍ بِمُصْحَفٍ مِمَّا نَسَخُوا وَأَمَرَ بِمَا سِوَاهُ مِنَ الْقُرْآنِ فِي كُلِّ صَحِيفَةٍ أَوْ مُصْحَفٍ أَنْ يُحْرَقَ‏.‏", "en": "Narrated Anas bin Malik:Hudhaifa bin Al-Yaman came to `Uthman at the time when the people of Sham and the people of Iraq were Waging war to conquer Arminya and Adharbijan. Hudhaifa was afraid of their (the people of Sham and Iraq) differences in the recitation of the Qur'an, so he said to `Uthman, \"O chief of the Believers! Save this nation before they differ about the Book (Qur'an) as Jews and the Christians did before.\" So `Uthman sent a message to Hafsa saying, \"Send us the manuscripts of the Qur'an so that we may compile the Qur'anic materials in perfect copies and return the manuscripts to you.\" Hafsa sent it to `Uthman. `Uthman then ordered Zaid bin Thabit, `Abdullah bin Az-Zubair, Sa`id bin Al-As and `AbdurRahman bin Harith bin Hisham to rewrite the manuscripts in perfect copies. `Uthman said to the three Quraishi men, \"In case you disagree with Zaid bin Thabit on any point in the Qur'an, then write it in the dialect of Quraish, the Qur'an was revealed in their tongue.\" They did so, and when they had written many copies, `Uthman returned the original manuscripts to Hafsa. `Uthman sent to every Muslim province one copy of what they had copied, and ordered that all the other Qur'anic materials, whether written in fragmentary manuscripts or whole copies, be burnt", "fr": "Rapporté par Anas bin Malik : Hudhaifa bin Al-Yaman est venu voir `Uthman alors que les gens du Sham et d’Irak combattaient pour conquérir l’Arménie et l’Azerbaïdjan. Hudhaifa craignait les différences dans la récitation du Coran entre ces deux groupes. Il dit à `Uthman : « Ô chef des croyants ! Sauve cette communauté avant qu’elle ne se divise à propos du Livre, comme l’ont fait les Juifs et les Chrétiens. » `Uthman envoya alors un message à Hafsa : « Envoie-nous les manuscrits du Coran pour que nous puissions en faire des copies parfaites, puis nous te les rendrons. » Hafsa les lui envoya. `Uthman ordonna alors à Zaid bin Thabit, `Abdullah bin Az-Zubair, Sa`id bin Al-As et `AbdurRahman bin Harith bin Hisham de recopier les manuscrits en copies parfaites. Il dit aux trois hommes de Quraysh : « Si vous n’êtes pas d’accord avec Zaid bin Thabit sur un point du Coran, écrivez-le dans le dialecte de Quraysh, car le Coran a été révélé dans leur langue. » Ils firent ainsi, et une fois les copies terminées, `Uthman rendit les manuscrits originaux à Hafsa. Il envoya une copie dans chaque province musulmane et ordonna de brûler tous les autres fragments ou copies du Coran", "id": "Telah menceritakan kepada kami [Musa] Telah menceritakan kepada kami [Ibrahim] Telah menceritakan kepada kami [Ibnu Syihab] bahwasanya [Anas bin Malik] telah menceritakan kepadanya, bahwasanya; Hudzaifah bin Al Yamani datang kepada Utsman setelah sebelumnya memerangi Ahlus Syam yakni pada saat penaklukan Armenia dan Azerbaijan bersama penduduk Irak. Dan ternyata perselisihan mereka dalam Qira`ah mengejutkan Hudzaifah. Maka Hudzaifah pun berkata kepada Utsman, \"Rangkullah ummat ini sebelum mereka berselisih tentang Al Qur`an sebagaimana perselisihan yang telah terjadi pada kaum Yahudi dan Nasrani.\" Akhirnya, Utsman mengirim surat kepada Hafshah yang berisikan, \"Tolong, kirimkanlah lembaran alquran kepada kami, agar kami dapat segera menyalinnya ke dalam lembaran yang lain, lalu kami akan segera mengembalikannya pada Anda.\" Maka Hafshah pun mengirimkannya kepada Utsman. Lalu Utsman memerintahkan kepada Zaid bin Tsabit, Abdullah bin Zubair, Sa'id bin Al Ash dan Abdurrahman bin Al Harits bin Hisyam, sehingga mereka pun menyalinnya ke dalam lembaran shuhuf yang lain. Utsman berkata kepada tiga orang Quraisy dari mereka, \"Jika kalian berselisih dengan Zaid bin Tsabit terkait dengan Al Qur`an, maka tulislah dengan bahasa Quraisy, sebab Al Qur`an turun dengan bahasa mereka.\" Kemudian mereka mengindahkan perintah itu hingga penyalinan selesai dan Utsman pun mengembalikannya ke Hafshah. Setelah itu, Utsman mengirimkan sejumlah Shuhuf yang telah disalin ke berbagai penjuru negeri kaum muslimin, dan memerintahkan untuk membakar Al Qur`an yang terdapat pada selain Shuhuf tersebut. Ibnu Syihab berkata; [Kharijah bin Zaid] telah mengabarkan kepadaku bahwa ia mendengar [Zaid bin Tsabit] berkata, \"Kami kehilangan satu ayat dari surat Al Ahzab saat kami menyalinnya, yang sungguh aku telah mendengarnya langsung dari Rasulullah shallallahu 'alaihi wasallam saat beliau membacanya. Lalu kami pun mencarinya, dan ternyata kami menemukannya pada Khuzaimah bin Tsabit Al Anshari. Yakni ayat, \"MINAL MUKMINIINA RIJAALUN SHADAQUU MAA 'AAHADUU ALLAAHA 'ALAIHI.\" Maka kami pun menggabungkannya di dalam mushhaf", "tr": "Enes İbn Malik'in rivayet ettiğine göre; \"Huzeyfe İbn Yeman Hz. Osman'ın huzuruna çıktı. Ermenistan ve Azerbaycan'ın fethi sırasında Iraklılarla birlikte Şamlılarla tartışmıştı. İki tarafın kıraatler konusunda ihtilafa düşmesi Huzeyfe'yi endişelendirmişti. Bu yüzden Hz. Osman'a: 'Ey mu'minlerin Emiri! Yahudi ve Hıristiyanların ihtilafı gibi, Kitap hakkında ihtilafa düşmeden önce ümmet için tedbir al!' dedi. Bunun üzerine Hz. Osman, Hafsa'ya haber gönderdi ve 'Mushafı bize gönder, onu çoğaltıp tekrar sana iade edelim' dedi. Hafsa, mushafı Hz. Osman'a gönderdi. O da, Zeyd İbn Sabit, Abdullah İbnu'z-ZUbeyr, Saıd İbnu'ı-As ve Abdurrahman İbnu'l-Haris İbn Hişam'a Kur'an' nüshalarının çoğaltılmasını emretti. Komisyonun üç Kureyşli üyesine şöyle tenbih etti: Siz, Zeyd İbn Sabit ile herhangi bir ayetin yazımı konusunda ayrılığa düşerseniz, onu Kureyş lehçesiyle yazın! Çünkü Kur'an onların diliyle indi. Üyeler de bu talimatı yerine getirdi. Sonunda Mushafı çoğalttılar. Hz. Osman da, ana mushafı Hafsa'ya geri verdi. Daha sonra çoğalttıkları Mushaflardan her tarafa birer tane gönderdi. Bunun dışında sahifelerde yazılı bulunan veya Mushaf şeklinde yazılmış olan Kur'anların yakılmasını emretti"}}, "arafa_achoura": {"refs": [["muslim", 1162]], "txt": {"ar": "وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، جَمِيعًا عَنْ حَمَّادٍ، - قَالَ يَحْيَى أَخْبَرَنَا حَمَّادُ بْنُ زَيْدٍ، - عَنْ غَيْلاَنَ، عَنْ عَبْدِ اللَّهِ بْنِ مَعْبَدٍ الزِّمَّانِيِّ، عَنْ أَبِي قَتَادَةَ، رَجُلٌ أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ كَيْفَ تَصُومُ فَغَضِبَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَلَمَّا رَأَى عُمَرُ - رضى الله عنه - غَضَبَهُ قَالَ رَضِينَا بِاللَّهِ رَبًّا وَبِالإِسْلاَمِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا نَعُوذُ بِاللَّهِ مِنْ غَضَبِ اللَّهِ وَغَضَبِ رَسُولِهِ ‏.‏ فَجَعَلَ عُمَرُ - رضى الله عنه - يُرَدِّدُ هَذَا الْكَلاَمَ حَتَّى سَكَنَ غَضَبُهُ فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ كَيْفَ بِمَنْ يَصُومُ الدَّهْرَ كُلَّهُ قَالَ ‏\"‏ لاَ صَامَ وَلاَ أَفْطَرَ - أَوْ قَالَ - لَمْ يَصُمْ وَلَمْ يُفْطِرْ ‏\"‏ ‏.‏ قَالَ كَيْفَ مَنْ يَصُومُ يَوْمَيْنِ وَيُفْطِرُ يَوْمًا قَالَ ‏\"‏ وَيُطِيقُ ذَلِكَ أَحَدٌ ‏\"‏ ‏.‏ قَالَ كَيْفَ مَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا قَالَ ‏\"‏ ذَاكَ صَوْمُ دَاوُدَ عَلَيْهِ السَّلاَمُ ‏\"‏ ‏.‏ قَالَ كَيْفَ مَنْ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمَيْنِ قَالَ ‏\"‏ وَدِدْتُ أَنِّي طُوِّقْتُ ذَلِكَ ‏\"‏ ‏.‏ ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ ثَلاَثٌ مِنْ كُلِّ شَهْرٍ وَرَمَضَانُ إِلَى رَمَضَانَ فَهَذَا صِيَامُ الدَّهْرِ كُلِّهِ صِيَامُ يَوْمِ عَرَفَةَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ وَصِيَامُ يَوْمِ عَاشُورَاءَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ ‏\"‏ ‏.‏", "en": "Abu Qatada reported that a person came to the Messenger of Allah (ﷺ) and said:How do you fast? The Messenger of Allah (ﷺ) felt annoyed. When 'Umar (Allah be pleased with him) noticed his annoyance, he said: We are well pleased with Allah as our Lord, with Islam as our code of life, and with Muhammad as our Prophet. We seek refuge with Allah from the anger of Allah and that of His Messenger. 'Umar kept on repeating these words till his (the Prophet's) anger calmed down. Then Umar said: Messenger of Allah, what is the position of one who fasts perpetually? He (ﷺ) said: He neither fasted nor broke it, or he said: He did not fast and he did not break it. 'Umar said: What about him who fasts for two days and does not fast one day? He (ﷺ) said: Is anyone capable of doing that? He ('Umar) said: What is the position of him who fasts for a day and doesn't fast on the other day? Thereupon he (the Holy Prophet) said: That is the fast of David (peace be upon him). He ('Umar) said: What about him who fasts one day and doesn't fast for two days. Thereupon he (the Messenger of Allah) said: I wish I were given the strength to do that. Thereafter he (ﷺ) said: Fasting three days every month and that of Ramadan every year is a perpetual fasting. I seek from Allah that fasting on the day of 'Arafa may atone for the sins of the preceding and the coming years, and I seek from Allah that fasting on the day of Ashura may atone for the sins of the preceding year", "fr": "Rapporté par Abu Qatada : Un homme est venu voir le Messager d’Allah ﷺ et a demandé : « Comment jeûnes-tu ? » Le Messager d’Allah ﷺ a montré de l’agacement. Quand Omar رضي الله عنه a remarqué cela, il a dit : « Nous sommes satisfaits qu’Allah soit notre Seigneur, que l’Islam soit notre mode de vie, et que Muhammad soit notre Prophète. Nous cherchons refuge auprès d’Allah contre la colère d’Allah et celle de Son Messager. » Omar a répété ces paroles jusqu’à ce que la colère du Prophète ﷺ s’apaise. Puis Omar a dit : « Messager d’Allah, que penses-tu de celui qui jeûne sans interruption ? » Il ﷺ a répondu : « Il n’a ni jeûné ni rompu son jeûne, ou il a dit : Il n’a ni jeûné ni arrêté. » Omar a demandé : « Et celui qui jeûne deux jours et ne jeûne pas un jour ? » Il ﷺ a dit : « Qui en est capable ? » Omar a demandé : « Et celui qui jeûne un jour et ne jeûne pas le lendemain ? » Le Prophète ﷺ a répondu : « C’est le jeûne de Dawud عليه السلام. » Omar a demandé : « Et celui qui jeûne un jour et ne jeûne pas pendant deux jours ? » Le Messager d’Allah ﷺ a dit : « J’aimerais avoir la force de le faire. » Ensuite, il ﷺ a dit : « Jeûner trois jours chaque mois et le Ramadan chaque année, c’est comme jeûner tout le temps. Je demande à Allah que le jeûne du jour de ‘Arafat efface les péchés de l’année précédente et de l’année suivante, et je demande à Allah que le jeûne du jour de ‘Achoura efface les péchés de l’année précédente. »", "id": "Dan Telah menceritakan kepada kami [Yahya bin Yahya At Tamimi] dan [Qutaibah bin Sa'id] semuanya dari [Hammad] - [Yahya] berkata- telah mengabarkan kepada kami [Hammad bin Zaid] dari [Ghailan] dari [Abdullah bin Ma'bad Az Zimani] dari [Abu Qatadah] bahwa seorang laki-laki datang kepada Nabi shallallahu 'alaihi wasallam dan bertanya, \"Bagaimanakah Anda berpuasa?\" Mendengar pertanyaan itu, Rasulullah shallallahu 'alaihi wasallam marah. Dan ketika Umar menyaksikan Rasulullah shallallahu 'alaihi wasallam marah, ia berkata, \"Kami rela Allah sebagai Tuhan, Islam sebagai agama dan Muhammad sebagai Rasul. Kami berlindung kepada Allah, dari murka Allah dan Rasul-Nya.\" Umar mengulang ucapan tersebut hingga kemarahan Rasulullah shallallahu 'alaihi wasallam reda. Kemudian ia bertanya, \"Wahai Rasulullah, bagaimana dengan orang yang berpuasa sepanjang tahun?\" Beliau menjawab: \"Dia tidak berpuasa dan tidak juga berbuka.\" -atau beliau katakan dengan redaksi 'Selamanya ia tak dianggap berpuasa dan tidak pula dianggap berbuka-- Umar bertanya lagi, \"Bagaimana dengan orang yang berpuasa sehari dan berbuka sehari?\" beliau menjawab: \"Itu adalah puasa Dawud 'Alaihis Salam.\" Umar bertanya lagi, \"Bagaimana dengan orang yang berpuasa sehari dan berbuka dua hari?\" beliau menjawab: \"Aku senang, jika diberi kekuatan untuk itu.\" kemudian Rasulullah shallallahu 'alaihi wasallam bersabda: \"Puasa tiga hari setiap bulan, puasa dari Ramadlan ke Ramadlan sama dengan puasa setahun penuh. Sedangkan puasa pada hari Arafah, aku memohon pula kepada Allah, agar puasa itu bisa menghapus dosa setahun setahun penuh sebelumnya dan setahun sesudahnya. Adapun puasa pada hari 'Asyura`, aku memohon kepada Allah agar puasa tersebut bisa menghapus dosa setahun sebelumnya", "tr": "Bize Yahya b .Yahya et-Temîmî ile Kuteybetübnü Saîd hep birden Hammad'dan rivayet ettiler. Yahya dedi ki: Bize Hammâd b. Zeyd, Gaylan'dan, o da Abdullah b. Mabed-i Zimmâni'den, o da Ebû Katâde'den, naklen haber verdi. (Ebû Katâde şöyle demiş): «Bir adam Nebi (Sallallahu Aleyhi ve Sellem)'e gelerek: — Nasıl oruç tutarsın? diye sordu. Bunun üzerine Resulullah (Sallallahu Aleyhi ve Sellem) gabadlandı. Ömer (Radiyallahû anh) onun kızdığını görünce: — Biz, Rabb olarak Allah'a, din olarak İslâm'a, Nebi olarak da Muhammed'e razı olduk. Allah'ın gadabi ile Resulünün gadabından Allah'a sığınırız, dedi. Ömer (Radiyallahû anh) bu sözü Nebi (Sallallahu Aleyhi ve Sellem)'in gadabı yatışıncaya kadar tekrarladı, durdu. Nihayet Ömer : — Yâ Resûlallah! Bütün sene oruç tutan kimsenin hali ne olacak? dedi. Resulullah (Sallallahu Aleyhi ve Sellem): — «(Böylesi) ne oruç tutmuştur, ne tutmamıştır —yahut oruç da tutmamıştır, iftar da etmemiştir—» buyurdu. Ömer (tekrar) : — İki gün oruç tutup bir gün tutmayanın hâli ne olacak? diye sordu. Resulullah (Sallallahu Aleyhi ve Sellem) : — Buna kimse takat getirebilir mi? buyurdu. Ömer (yine): — Bir gün oruç tutup bir gün tutmayanın hâli nice olacak? diye sordu. Nebi (Sallallahu Aleyhi ve Sellem): — Bu, Dâvud Aleyhisselâm'ın orucudur, buyurdu. Ömer: — Bir gün oruç tutup iki gün tutmayanın hali nasıldır? diye sordu. Resulullah (Sallallahu Aleyhi ve Sellem) : — Bunun için bana takat verilmesini dilerim; cevâbını verdi. Bundan sonra Resulullah (Sallallahu Aleyhi ve Sellem) ; — Her aydan üç gün, bir de ramazandan ramazana oruç tutmak yok mu? İşte bu bütün senenin orucu demektir. Arafe günün orucunu Allah'ın o günden önceki sene ile o günden sonraki senelerin günahlarına keffâret yapacağını umarım. Aşûra günün orucunu ise Allah'ın o günden önceki senenin günahlarına keffâret kılacağını ümîd ederim, buyurdular"}}, "tasua": {"refs": [["muslim", 1134]], "txt": {"en": "Ibn 'Abbas reported that when the Messenger of Allah (ﷺ) fasted on the day of 'Ashura and commanded that it should he observed as a fast, they (his Companions) said to him:Messenger of Allah, it is a day which the Jews and Christians hold in high esteem. Thereupon the Messenger of Allah (ﷺ) said: When the next year comes, God willing, we would observe fast on the 9th But the Messenger of Allah (ﷺ) died before the advent of the next year", "fr": "Rapporté par Ibn Abbas رضي الله عنهما : Quand le Messager d’Allah ﷺ jeûna le jour de ‘Ashura et recommanda de jeûner ce jour-là, ses Compagnons lui dirent : « Messager d’Allah, c’est un jour que les Juifs et les Chrétiens respectent beaucoup. » Le Messager d’Allah ﷺ répondit : « L’an prochain, si Allah le veut, nous jeûnerons aussi le neuvième jour. » Mais le Messager d’Allah ﷺ mourut avant l’année suivante", "id": "Dan Telah menceritakan kepada kami [Al Hasan bin Ali Al Hulwani] telah menceritakan kepada kami [Ibnu Abu Maryam] telah menceritakan kepada kami [Yahya bin Ayyub] telah menceritakan kepadaku [Isma'il bin Umayyah] bahwa ia mendengar [Abu Ghathafan bin Tharif Al Murri] berkata, saya mendengar [Abdullah bin Abbas] radliallahu 'anhuma berkata saat Rasulullah shallallahu 'alaihi wasallam berpuasa pada hari 'Asyura`dan juga memerintahkan para sahabatnya untuk berpuasa; Para sahabat berkata, \"Wahai Rasulullah, itu adalah hari yang sangat diagungkan oleh kaum Yahudi dan Nashrani.\" Maka Rasulullah shallallahu 'alaihi wasallam bersabda: \"Pada tahun depan insya Allah, kita akan berpuasa pada hari ke sembilan (Muharram).\" Tahun depan itu pun tak kunjung tiba, hingga Rasulullah shallallahu 'alaihi wasallam wafat", "tr": "Bize Hasen b. Aliy El-Hulvâni rivayet etti. (Dediki) Bize Îbni Ebî Meryem rivayet etti. (Dediki) Bize Yahya b. Eyyub rivayet eyledi (Dediki) Bana İsmail b. Ümmeyye rivayet etti ki Ebû Gatafan b. Tarif El-Mürri'yi şöyle derken işitmiş: Ben, Abdullah b. Abbâs (Radiyallahû anhûma)'yi şunları söylerken dinledim : «Resulullah (Sallallahu Aleyhi ve Sellem) Aşûra günü oruç tuttuğu ve tu tutmasını emir buyurduğu zaman eshab — Yâ Resûlullan, şüphesiz ki bu gün Yahudilerle Hristiyanların ta'-zim ettikleri bir gündür, dediler. Bunun üzerine Resulullah (Sallallahu Aleyhi ve Sellem): — «Gelecek seneye inşaattan 9. gön oruç tutarız,» buyurdular, İbni Abbâs: — «Fakat gelecek sene gelmeden Resulullah (Sallallahu Aleyhi ve Sellem) vefat etti.» dedi", "ar": "وَحَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، حَدَّثَنِي إِسْمَاعِيلُ بْنُ أُمَيَّةَ، أَنَّهُ سَمِعَ أَبَا غَطَفَانَ بْنَ طَرِيفٍ الْمُرِّيَّ، يَقُولُ سَمِعْتُ عَبْدَ اللَّهِ، بْنَ عَبَّاسٍ - رضى الله عنهما - يَقُولُ حِينَ صَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمَ عَاشُورَاءَ وَأَمَرَ بِصِيَامِهِ قَالُوا يَا رَسُولَ اللَّهِ إِنَّهُ يَوْمٌ تُعَظِّمُهُ الْيَهُودُ وَالنَّصَارَى ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ فَإِذَا كَانَ الْعَامُ الْمُقْبِلُ - إِنْ شَاءَ اللَّهُ - صُمْنَا الْيَوْمَ التَّاسِعَ ‏\"‏ ‏.‏ قَالَ فَلَمْ يَأْتِ الْعَامُ الْمُقْبِلُ حَتَّى تُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم"}}, "tachriq": {"refs": [["muslim", 1141]], "txt": {"ar": "وَحَدَّثَنَا سُرَيْجُ بْنُ يُونُسَ، حَدَّثَنَا هُشَيْمٌ، أَخْبَرَنَا خَالِدٌ، عَنْ أَبِي الْمَلِيحِ، عَنْ نُبَيْشَةَ، الْهُذَلِيِّ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ أَيَّامُ التَّشْرِيقِ أَيَّامُ أَكْلٍ وَشُرْبٍ ‏\"‏ ‏.‏", "fr": "Rapporté par Nubaisha al-Hudhali : Le Messager d’Allah ﷺ a dit : « Les jours de Tashriq sont des jours de nourriture et de boisson. »", "tr": "Bize, Süreye b. Yûnus rivayet etti.. (Dediki): Bize Hüşeym rivayet etti. (Dediki): Bize Hâlid, Ebu'l-Melih'den, o da Nubeyşetül-Hüzeli'den naklen haber verdi. Nübeyşe şöyle demiş: Resûlullah (Sallallahu Aleyhi ve Sellem) : «Teşrik günleri yeyip içme günleridir, buyurdular", "en": "Nubaisha al-Hudhali reported Allah's Messenger (ﷺ) as saying:The days of Tashriq are the days of eating and drinking"}}, "dix_dhulhijja": {"refs": [["bukhari", 969]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ عَرْعَرَةَ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ سُلَيْمَانَ، عَنْ مُسْلِمٍ الْبَطِينِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ قَالَ ‏\"‏ مَا الْعَمَلُ فِي أَيَّامِ الْعَشْرِ أَفْضَلَ مِنَ الْعَمَلِ فِي هَذِهِ ‏\"‏‏.‏ قَالُوا وَلاَ الْجِهَادُ قَالَ ‏\"‏ وَلاَ الْجِهَادُ، إِلاَّ رَجُلٌ خَرَجَ يُخَاطِرُ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ بِشَىْءٍ ‏\"‏‏.‏", "en": "Narrated Ibn `Abbas:The Prophet (ﷺ) said, \"No good deeds done on other days are superior to those done on these (first ten days of Dhul Hijja).\" Then some companions of the Prophet (ﷺ) said, \"Not even Jihad?\" He replied, \"Not even Jihad, except that of a man who does it by putting himself and his property in danger (for Allah's sake) and does not return with any of those things", "fr": "Rapporté par Ibn `Abbas : Le Prophète (ﷺ) a dit : « Aucun acte accompli pendant d’autres jours n’est meilleur que ceux faits pendant ces dix premiers jours de Dhul Hijja. » Certains compagnons du Prophète (ﷺ) ont demandé : « Même pas le Jihad ? » Il a répondu : « Même pas le Jihad, sauf pour celui qui part en risquant sa vie et ses biens pour Allah et ne revient avec rien. »", "id": "Telah menceritakan kepada kami [Muhammad bin 'Ar'arah] berkata, telah menceritakan kepada kami [Syu'bah] dari [Sulaiman] dari [Muslim Al Bathin] dari [Sa'id bin Jubair] dari [Ibnu 'Abbas] dari Nabi shallallahu 'alaihi wasallam, beliau bersabda: \"Tidak ada amal yang lebih utama pada hari-hari (tasyriq) ini selian berkurban.\" Para sahabat berkata, \"Tidak juga jihad?\" Beliau menjawab: \"Tidak juga jihad. Kecuali seseorang yang keluar dari rumahnya dengan mengorbankan diri dan hartanya (di jalan Allah), lalu dia tidak kembali lagi", "tr": "Saîd İbn Cübeyr'in İbn Abbas (Radiyallahu Anh)'dan naklettiğine göre Resuİullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Zilhicce'nin on günü içinde işte şu vakitteki amel kadar faziletli hiçbir amel yoktur.\" Sahâbîler: \"Cihad damı bu günlerdeki amellerden daha faziletli değil!?\" deyince Resul-i Ekrem Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Cihad da... Sadece canını ve malını hiç gözünü kırpmadan feda edebilecek şekilde savaşa tutuşan ve geriye hiçbir şey getiremeyen kişinin ameli bunun dışındadır"}}, "aid_interdit": {"refs": [["bukhari", 1990]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي عُبَيْدٍ، مَوْلَى ابْنِ أَزْهَرَ قَالَ شَهِدْتُ الْعِيدَ مَعَ عُمَرَ بْنِ الْخَطَّابِ ـ رضى الله عنه ـ فَقَالَ هَذَانِ يَوْمَانِ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ صِيَامِهِمَا يَوْمُ فِطْرِكُمْ مِنْ صِيَامِكُمْ، وَالْيَوْمُ الآخَرُ تَأْكُلُونَ فِيهِ مِنْ نُسُكِكُمْ‏.‏ قَالَ أَبُو عَبْد اللَّهِ قَالَ ابْنُ عُيَيْنَةَ مَنْ قَالَ مَوْلَى ابْنِ أَزْهَرَ فَقَدْ أَصَابَ وَمَنْ قَالَ مَوْلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ فَقَدْ أَصَابَ", "en": "Narrated Abu `Ubaid:(the slave of Ibn Azhar) I witnessed the `Id with `Umar bin Al-Khattab who said, Allah's Messenger (ﷺ) has forbidden people to fast on the day on which you break fasting (the fasts of Ramadan) and the day on which you eat the meat of your sacrifices (the first day of `Id ul Fitr and `Id ul-Adha)", "fr": "Rapporté par Abu `Ubaid (l'esclave d'Ibn Azhar) : J'ai assisté à la fête avec `Umar bin Al-Khattab qui a dit : Le Messager d'Allah (ﷺ) a interdit aux gens de jeûner le jour où vous rompez le jeûne (de Ramadan) et le jour où vous mangez la viande de vos sacrifices (le premier jour de l'Aïd al-Fitr et de l'Aïd al-Adha)", "id": "Telah menceritakan kepada kami ['Abdullah bin Yusuf] telah mengabarkan kepada kami [Malik] dari [Ibnu Syihab] dari [Abu 'Ubaid, maula Ibnu Azhar] berkata; Aku mengikuti shalat 'Ied bersama ['Umar bin Al Khaththob radliallahu 'anhu] lalu dia berkata: \"Inilah dua hari yang Rasulullah shallallahu 'alaihi wasallam melarang puasa padanya, yaitu pada hari saat kalian berbuka dari puasa kalian ('Iedul Fithri) dan hari lainnya adalah hari ketika kalian memakan hewan qurban kalian ('Iedul Adhha) \". Dan Abu 'Abdullah Al Bukhariy berkata; Ibnu 'Uyainah berkata; Siapa yang berkata bahwa Abu 'Ubaid adalah maula Ibnu Azhar berarti dia telah berkata benar dan juga siapa yang berkata bahwa dia adalah maula 'Abdurrahman bin 'Auf, dia juga telah berkata benar", "tr": "İbn Ezher'in azatlısı Ebu Ubeyd şöyle demiştir: Ömer İbn Hattab r.a. ile bir bayrama şahit oldum. O şöyle dedi: \"Şu İki gün Resulullah Sallallahu Aleyhi ve Sellem'in oruç tutmayı yasakladığı günlerdir: Birisi orucunuzdan iftar ettiğiniz bayram günü, diğeri de kurbanınızdan yediğiniz gün\". Tekrar:"}}, "blancs": {"refs": [["tirmidhi", 761]], "txt": {"ar": "حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا أَبُو دَاوُدَ، قَالَ أَنْبَأَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، قَالَ سَمِعْتُ يَحْيَى بْنَ سَامٍ، يُحَدِّثُ عَنْ مُوسَى بْنِ طَلْحَةَ، قَالَ سَمِعْتُ أَبَا ذَرٍّ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَبَا ذَرٍّ إِذَا صُمْتَ مِنَ الشَّهْرِ ثَلاَثَةَ أَيَّامٍ فَصُمْ ثَلاَثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ ‏\"‏ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي قَتَادَةَ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو وَقُرَّةَ بْنِ إِيَاسٍ الْمُزَنِيِّ وَعَبْدِ اللَّهِ بْنِ مَسْعُودٍ وَأَبِي عَقْرَبٍ وَابْنِ عَبَّاسٍ وَعَائِشَةَ وَقَتَادَةَ بْنِ مِلْحَانَ وَعُثْمَانَ بْنِ أَبِي الْعَاصِي وَجَرِيرٍ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي ذَرٍّ حَدِيثٌ حَسَنٌ ‏.‏ وَقَدْ رُوِيَ فِي بَعْضِ الْحَدِيثِ أَنَّ ‏\"‏ مَنْ صَامَ ثَلاَثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ كَانَ كَمَنْ صَامَ الدَّهْرَ ‏\"‏ ‏.‏", "en": "Abu Dharr narrated that :the Messenger of Allah said: \"O Abu Dharr! When you fast three days out of a month, then fast the thirteenth, fourteenth, and fifteenth", "id": "Telah menceritakan kepada kami [Mahmud bin Ghailan] telah menceritakan kepada kami [Abu Daud] dia berkata, telah memberitakan kepada kami [Syu'bah] dari [Al A'masy] dia berkata, saya mendengar [Yahya bin Saam] telah menceritakan dari [Musa bin Thalhah] dia berkata, saya mendengar [Abu Dzar] berkata, Rasulullah Shallallaahu 'alaihi wasallam bersabda kepadaku: \"Wahai Abu Dzar, jika kamu ingin berpuasa tiga hari pada tiap bulan, maka berpuasalah pada tanggal ke tiga belas, empat belas dan lima belas\". Dalam bab ini (ada juga riwayat -pent) dari Abu Qatadah, Abdullah bin Amru, Qurrah bin Iyas Al Muzani, Abdullah bin Mas'ud, Abu 'Aqrab, Ibnu Abbas, 'Aisyah, Qatadah bin Milhan, 'Utsman bin Abil 'Ash, Serta Jarir. Abu 'Isa berkata, hadits Abu Dzar merupakan hadits hasan. Telah diriwayatkan di sebagian hadits: \"Barang siapa yang berpuasa tiga hari dari tiap bulan sama dengan berpuasa setahun penuh", "tr": "Mûsâ b. Talha (radıyallahü anh)’den rivâyete göre, şöyle demiştir: Ebû Zerr’den işittim diyordu ki: Rasûlüllah (sallallahü aleyhi ve sellem) şöyle buyurdu: “Ey Ebû Zerr! Her aydan tutacağın üç gün oruç, o ayın onüç, ondört ve onbeşinci günleri olsun.” (Müslim, Sıyam: 36; Ebû Dâvûd, Sıyam: 68) konuda Ebû Katâde, Abdullah b. Amr, Kurrete b. İyas el Müzenî, Abdullah b. Mes’ûd, Ebû Akreb, İbn Abbâs, Âişe, Katâde, İbn Milhan, Osman b. ebil Âs ve Cerir’den de hadis rivâyet edilmiştir. Ebû Zerr hadisi hasendir. Bazı hadislerde şöyle rivâyet edilmiştir: “Her aydan üç gün, oruç tutmak tüm yılı oruç tutmuş gibidir.”"}}, "lundi_jeudi": {"refs": [["tirmidhi", 747]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا أَبُو عَاصِمٍ، عَنْ مُحَمَّدِ بْنِ رِفَاعَةَ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ تُعْرَضُ الأَعْمَالُ يَوْمَ الاِثْنَيْنِ وَالْخَمِيسِ فَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي هُرَيْرَةَ فِي هَذَا الْبَابِ حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏", "en": "Abu Hurairah narrated that:the Messenger of Allah said: \"Deeds are presented on Monday and Thursday, and I love that my deeds be presented while I am fasting", "id": "Telah menceritakan kepada kami [Muhammad bin Yahya] telah menceritakan kepada kami [Abu 'Ashim] dari [Muhammad bin Rifa'ah] dari [Suhail bin Abu Shalih] dari [ayahnya] dari [Abu Hurairah] bahwasanya Rasulullah Shallallaahu 'alaihi wa sallam bersabda: \" Pada hari senin dan kamis semua amalan dinaikkan kepada Allah ta'ala, maka saya lebih suka amalanku dinaikkan kepada-Nya ketika saya sedang berpuasa\". Abu 'Isa berkata, dalam hal ini hadits Abu Hurairah merupakan hadits hasan gharib", "tr": "Ebû Hureyre (r.a.)’den rivâyete göre, Rasûlullah (Sallallahu aleyhi ve Sellem) şöyle buyurdu: “İnsanların amelleri Pazartesi ve Perşembe günleri Allah’a arz olunur. Bu yüzden ben amelimin oruçlu olarak Allah’a arz olunmasını severim.” Tirmîzî rivâyet etmiştir. Tirmîzî: Bu konuda Ebû Hureyre hadisi hasen garibtir"}}, "inv_manger": {"refs": [["bukhari", 5376]], "txt": {"ar": "حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، أَخْبَرَنَا سُفْيَانُ، قَالَ الْوَلِيدُ بْنُ كَثِيرٍ أَخْبَرَنِي أَنَّهُ، سَمِعَ وَهْبَ بْنَ كَيْسَانَ، أَنَّهُ سَمِعَ عُمَرَ بْنَ أَبِي سَلَمَةَ، يَقُولُ كُنْتُ غُلاَمًا فِي حَجْرِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ فَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ يَا غُلاَمُ سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏\"‏‏.‏ فَمَا زَالَتْ تِلْكَ طِعْمَتِي بَعْدُ‏.‏", "en": "Narrated `Umar bin Abi Salama:I was a boy under the care of Allah's Messenger (ﷺ) and my hand used to go around the dish while I was eating. So Allah's Messenger (ﷺ) said to me, 'O boy! Mention the Name of Allah and eat with your right hand, and eat of the dish what is nearer to you.\" Since then I have applied those instructions when eating", "fr": "Rapporté par ‘Umar ibn Abi Salama : J’étais un garçon sous la garde du Messager d’Allah (ﷺ) et ma main allait dans tous les sens dans le plat pendant que je mangeais. Alors le Messager d’Allah (ﷺ) m’a dit : « Ô garçon ! Dis le nom d’Allah, mange avec ta main droite et mange ce qui est devant toi dans le plat. » Depuis ce jour-là, j’ai toujours suivi ces conseils en mangeant", "id": "Telah menceritakan kepada kami [Ali bin Abdullah] Telah mengabarkan kepada kami [Sufyan] ia berkata; [Al Walid bin Katsir] Telah mengabarkan kepadaku, bahwa ia mendengar [Wahb bin Kaisan] bahwa ia mendengar [Umar bin Abu Salamah] berkata; Waktu aku masih kecil dan berada di bawah asuhan Rasulullah shallallahu 'alaihi wasallam, tanganku bersileweran di nampan saat makan. Maka Rasulullah shallallahu 'alaihi wasallam bersabda: \"Wahai Ghulam, bacalah Bismilillah, makanlah dengan tangan kananmu dan makanlah makanan yang ada di hadapanmu.\" Maka seperti itulah gaya makanku setelah itu", "tr": "(Ömer b. Ebi Seleme'den, dedi ki: \"Ben Resulullah Sallallahu Aleyhi ve Sellem'in himayesinde büyüyen küçük bir çocuk idim. Elim de yemek kabında rastgele dolaşır dururdu. Resulullah Sallallahu Aleyhi ve Sellem bana: Ey oğul, Allah'ın adını an, sağ elinle ye ve önünden ye, buyurdu. Bundan sonra da hep bu şekilde yemek yedim.' Hadis'in geçtiği diğer yerler: 5377 ve 5328 Fethu'l-Bari Açıklaması: \"Yemeğe bc.şlamadan besmele çekmek ve sağ el ile yemek.\" Yemeğe başlamadan önce besmele çekmekten kasıt, yemeğin başında \"bismiilah\" demektir. Besmele çekmenin nasılolacağı ile ilgili olarak varid olmuş en sari h rivayet Ebu Davud ile Tirmizi'nin Ümmü Kulsum yoluyla Aişe radıyallahu anha'dan Nebie merfu olarak nakledilmiş şU: hadistir: \"Sizden bir kimse yemek yiyecek olursa bismillah desin. Eğer başlangıcında unutursa o takdirde: \"Bismillahi fi ewelihl ve ahirihl: Başında da, sonunda da bismillah\" desin.\" \"Küçük bir çocuk,\" yani büluğa ermemiş idim.\" \"Rasulullah Sallallahu Aleyhi ve Sellem'in himayesinde\", onun terbiyesi ve gözetimi altında. Rasulullah Sallallahu Aleyhi ve Sellem'ın himayesinde, kendi çocuğunu terbiye eder gibi terbiyesinde ... demektir. \"Elim yemek kabının içerisinde\" yani yemek yerken \"rastgele dolaşır dururdu.\" Elin rastgele dolaşması kabın etrafına, çeşitli yerlerine dalması ve bir tek yere uzanmakla kalmaması demektir. \"Eyoğul! Allah'ın adını an.\" Nevevi dedi ki: Yemeğin başında besmele çekmenin müstehap oluşu üzerinde ilim adamları icma' etmişlerdir. Ancak m\\)stehap oluşu üzerinde icma'ın nakledildiği su götürür. Şu kadar var ki müstehaplıkla tercih edilen fiil olduğu kastedilirse müstesna. Yoksa bir topluluk bunun vacip olduğu kanaatindedir. Bu da sağ elle yemenin vacip olduğu görüşünü kabul etmenin bir gereğidir. Çünkü her ikisi hakkındaki emir kipi aynıdır. \"Sağ elinle ye ve önünden ye.\" Hocamız \"Tirmizi Şerhi\" adlı eserinde şöyle demektedir: Şafii alimlerinin çoğunluğu bunu mendub olarak kabul etmişlerdir. Once el-Gazzali, daha sonra en-Nevevl de bunu bu şekilde ifade etmişlerdir. Ancak Şafı1, er-Risale adlı eserinde ve el-Umm'un başka bir yerinde bunun vacip olduğunu belirtmiş bulunmaktadır. Derim ki: Sağ elle.yemek yemenin vacip oluşuna, sol elle yemek yemeğe dair tehdidin varid oluşu delil teşkil etmektedir. Müslim'in Sahih'inde Seleme b. el-Ekva yoluyla gelen hadiste şöyle denilmektedir: \"Nebi Sallallahu Aleyhi ve Sellem sol eliyle yemek yiyen bir adam gördü. Allah Rasulü: Sağ elinle ye, diye buyurdu. Adam: Yiyemiyorum deyince, Allah Rasulü: Yiyemez olasın diye buyurdu. Ondan sonra elini ağzına kaldıramad!.\" Sol elle yemek yemeyi yasaklayan ve onunşeytanın işi olduğunu belirten hadis, İbn Ömer ve Cabir yoluyla Müslim'de, ayrıca Ahmed'in Müsned'inde hasen bir sened ile Aişe'den diye sabit olmuştur. Aişe radıyallahu anha hadisiNebi efendimize ref ederek şöylece zikretmiştir: \"Sol eliyle yemek yiyen kişi ile birlikte şeytan da yer.\" Nevevi der ki: Bu hadislerden anlaşıldığına göre sağ elle yemek yemek ve içmek müstehap, aynı işi sol el ile yapmak mekruhtur. İbn Ömer yoluyla gelen hadisin bazı rivayet yollarında görüldüğü gibi bütün alıp vermeler de böyledir. EI verir ki (sağ elde) herhangi bir hastalık ya da yara gibi bir mazeret bulunmasın. Eğer böyle bir mazeret varsa mekruhluk yoktur. Nevevi böyle demiştir. Rasu.lullah Sallallahu Aleyhi ve Sellem'in sol eliyle yemek yiyip de mazeret beyan eden ve onun mazeretini kabul etmediğini gösteren bedduasındaki problem ile ilgili olarak da şöyle cevap vermektedir: Iyad bu zatın münafık olduğunu iddia etmiştir. \"Artık bundan sonra hep bu şekilde yemek yedim.\" Yani yemek yiyişim hep böyle oldu. Böyle yemeye davet ettim ve bu benim adetim oldu. Hadisten Çıkarılan Sonuçlar 1- Hadisten anlaşıldığına göre şeytanların ve kafirlerin amellerine benzeyen amellerden sakınmak gerekir. 2- Şeytanın iki eli vardır. Şeytan yer, içer, alır ve verir. 3- Şer'! hükme aykırı hareket eden kimselere beddua etmek caizdir. 4- İyiliği emretmek, münkerden alıkoymak yemek esnasında bile yerine getirilmelidir. 5- Yemek ve içmek adabını öğretmek müstehaptır. 6- EbU. Seleme'nin oğlu Ömer'e ait güzel bir menkıbe söz konusudur. Çünkü Nebiin emrine uymuş ve gereğini hep yerine getirmiştir"}}, "inv_oubli_manger": {"refs": [["abudawud", 3767]], "txt": {"ar": "حَدَّثَنَا مُؤَمَّلُ بْنُ هِشَامٍ، حَدَّثَنَا إِسْمَاعِيلُ، عَنْ هِشَامٍ، - يَعْنِي ابْنَ أَبِي عَبْدِ اللَّهِ الدَّسْتَوَائِيَّ - عَنْ بُدَيْلٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُبَيْدٍ، عَنِ امْرَأَةٍ، مِنْهُمْ يُقَالُ لَهَا أُمُّ كُلْثُومٍ عَنْ عَائِشَةَ، - رضى الله عنها - أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا أَكَلَ أَحَدُكُمْ فَلْيَذْكُرِ اسْمَ اللَّهِ تَعَالَى فَإِنْ نَسِيَ أَنْ يَذْكُرَ اسْمَ اللَّهِ تَعَالَى فِي أَوَّلِهِ فَلْيَقُلْ بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ ‏\"‏ ‏.‏", "en": "Narrated Aisha, Ummul Mu'minin: The Messenger of Allah (ﷺ) said: When one of you eats, he should mention Allah's name; if he forgets to mention Allah's name at the beginning, he should say: \"In the name of Allah at the beginning and at the end of it", "fr": "Rapporté par Aisha (la mère des croyants) رضي الله عنها : Le Messager d’Allah ﷺ a dit : « Quand l’un de vous mange, qu’il mentionne le nom d’Allah ; s’il l’oublie au début, qu’il dise : “Au nom d’Allah au début et à la fin.” »", "id": "Telah menceritakan kepada kami [Muammal bin Hisyam] telah menceritakan kepada kami [Isma'il] dari [Hisyam bin Abu Abdullah Ad Dastuwai] dari [Budail] dari [Abdullah bin 'Ubaid] dari seorang wanita di antara mereka yang dipanggil [Ummu Kultsum] dari [Aisyah] radliallahu 'anhuma, bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Apabila salah seorang di antara kalian makan, maka hendaknya ia menyebutkan nama Allah Ta'ala. Jika ia lupa untuk menyebut nama Allah Ta'ala di awal, hendaklah ia mengucapkan: BISMILLAAHI AWWALAHU WA AAKHIRAHU (dengan nama Allah pada awal dan akhirnya)", "tr": "Âişe (r. anha)'dan rivayet olunduğuna göre; Rasûlullah (s.a.v.) şöyle buyurmuştur: “Biriniz ye(mek yemek iste)diği zaman (yemeğe başlarken) yüce Allah'ın ismini ansın. Eğer (yemeğin) başında yüce Allah'ın ismini anmayı unutursa 'Bismillâhi evvelehü ve âhirehu: Başında da sonunda Allah'ın ismiyle başlarım' desin.\" Ayrıca bu hadis'i Tirmizî, et'ime; İbn Mâce, et'ime; Dârimî, et'ime; Ahmed b. Hanbel, VI, 143 208, 246, 265. te tahric ettiler"}}, "inv_apres_repas": {"refs": [["abudawud", 4023]], "txt": {"ar": "حَدَّثَنَا نُصَيْرُ بْنُ الْفَرَجِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَزِيدَ، حَدَّثَنَا سَعِيدٌ، - يَعْنِي ابْنَ أَبِي أَيُّوبَ - عَنْ أَبِي مَرْحُومٍ، عَنْ سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ أَكَلَ طَعَامًا ثُمَّ قَالَ الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا الطَّعَامَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ وَمَنْ لَبِسَ ثَوْبًا فَقَالَ الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ ‏\"‏ ‏.‏", "id": "Telah menceritakan kepada kami [Nushair Ibnul Faraj] berkata, telah menceritakan kepada kami [Abdullah bin Yazid] berkata, telah menceritakan kepada kami [Sa'id] -yaitu Ibnu Abu Ayyub- dari [Abu Marhum] dari [Sahl bin Mu'adz bin Anas] dari [Bapaknya] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Barangsiapa memakan makanan kemudian membaca doa; 'ALHAMDULILLAHIL LADZII ATH'AMANII HADZA ATH THA'AAMA WA RAZAQANIIHI MIN GHAIRI HAULIN MINNI WA LAA QUWWATIN (Segala puji bagi Allah yang telah memberikan makanan ini kepadaku sebagai rizki, tanpa daya dan kekuatan dariku). ' Maka akan diampuni dosanya yang lalu dan yang akan datang. Dan barangsiapa memakai baju lalu membaca doa; 'ALHAMDULILLAHIL LADZII KASAANII HADZA ATS TSAUBA WA RAZAQANIIHI MIN GHAIRI HAULIN MINNI WA LAA QUWWATIN (Segala puji bagi Allah yang telah memberikan pakaian ini kepadaku sebagai rizki, tanpa daya dan kekuatan dariku). ' Maka akan diampuni dosanya yang lalu dan yang akan datang", "tr": "(Sehl b, Muaz b. Enes'in) babasından rivayet edildiğine göre; ResuluIIah (Sallallahu Aleyhi ve Sellem) şöyle buyurmuştur: \"Kim bir yemek yer ve sonra; \" Benim hiç güç ve kuvvetim olmaksızın bu yemeği bana yediren ve onu bana rızk olarak veren Allah'a hamd olsun derse onun geçmiş ve gelecek günahları bağışlanır.\" Kim de bir elbise giyer ve; \"Bu elbiseyi ben hiç bir güç ve kuvvetim olmadan bana giydiren ve onu bana rızık olarak veren Allah'a hamdolsun\" derse (onun da) geçmiş ve gelecek günahları bağışlanır", "en": "Narrated Mu'adh ibn Anas: The Prophet (ﷺ) said: If anyone eats food and then says: \"Praise be to Allah Who has fed me with this food and provided me with it through no might and power on my part,\" he will be forgiven his former and later sins. If anyone puts on a garment and says: \"Praise be to Allah Who has clothed me with this and provided me with it through no might and power on my part,\" he will be forgiven his former and later sins", "fr": "Rapporté par Mu’adh ibn Anas رضي الله عنه : Le Prophète ﷺ a dit : « Si quelqu’un mange de la nourriture puis dit : “Louange à Allah qui m’a nourri de cette nourriture et me l’a donnée sans force ni puissance de ma part”, ses péchés passés et futurs lui seront pardonnés. Si quelqu’un met un vêtement et dit : “Louange à Allah qui m’a habillé de cela et me l’a donné sans force ni puissance de ma part”, ses péchés passés et futurs lui seront pardonnés. »"}}, "inv_sommeil": {"refs": [["bukhari", 6324]], "txt": {"ar": "حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا سُفْيَانُ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنْ رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ حُذَيْفَةَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَرَادَ أَنْ يَنَامَ قَالَ ‏\"‏ بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا ‏\"‏‏.‏ وَإِذَا اسْتَيْقَظَ مِنْ مَنَامِهِ قَالَ ‏\"‏ الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ ‏\"‏‏.‏", "en": "Narrated Hudhaifa:Whenever the Prophet (ﷺ) intended to go to bed, he would recite: \"Bismika Allahumma amutu wa ahya (With Your name, O Allah, I die and I live).\" And when he woke up from his sleep, he would say: \"Al-hamdu lil-lahil-ladhi ahyana ba'da ma amatana; wa ilaihi an-nushur (All the Praises are for Allah Who has made us alive after He made us die (sleep) and unto Him is the Resurrection", "id": "Telah menceritakan kepada kami [Abu Nu'aim] telah menceritakan kepada kami [Sufyan] dari [Abdul Malik bin Umair] dari [Rib'i bin Hirasy] dari [Hudzaifah] dia berkata; \"Apabila Nabi shallallahu 'alaihi wasallam hendak tidur, beliau membaca: 'Bismika allahumma amuutu wa ahya (Dengan nama-Mu Ya Allah, aku mati dan aku hidup).' Dan apabila bangun tidur, beliau mengucapkan: 'Al Hamdulillahilladzii ahyaana ba'da maa amatana wailaihi nusyur (Segala puji bagi Allah yang telah menghidupkan kami setelah mematikan kami, dan kepada-Nya lah tempat kembali)", "tr": "Huzeyfe r.a.'den rivayet edildiğine göre Nebi Sallallahu Aleyhi ve Sellem yatmaya gittiğinde \"Senin adınla ölür ve dirilirim\" uyandığında da \"Bizi öldürdükten sonra tekrar dirilten ve en sonunda mezarlarımızdan bizi çıkaracak olan Allah'a hamdolsun\" dermiş", "fr": "Rapporté par Hudhaifa : Chaque fois que le Prophète ﷺ voulait aller se coucher, il récitait : « Bismika Allahumma amutu wa ahya » (C’est en Ton nom, ô Allah, que je meurs et que je vis). Et quand il se réveillait, il disait : « Al-hamdu lil-lahil-ladhi ahyana ba'da ma amatana ; wa ilaihi an-nushur » (Louange à Allah qui nous a redonné la vie après nous avoir fait mourir [le sommeil], et c’est vers Lui que sera la résurrection"}}, "inv_toilettes": {"refs": [["bukhari", 142], ["muslim", 375]], "txt": {"ar": "حَدَّثَنَا آدَمُ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، قَالَ سَمِعْتُ أَنَسًا، يَقُولُ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ قَالَ ‏ \"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ ‏\"‏‏.‏ تَابَعَهُ ابْنُ عَرْعَرَةَ عَنْ شُعْبَةَ‏.‏ وَقَالَ غُنْدَرٌ عَنْ شُعْبَةَ إِذَا أَتَى الْخَلاَءَ‏.‏ وَقَالَ مُوسَى عَنْ حَمَّادٍ إِذَا دَخَلَ‏.‏ وَقَالَ سَعِيدُ بْنُ زَيْدٍ حَدَّثَنَا عَبْدُ الْعَزِيزِ إِذَا أَرَادَ أَنْ يَدْخُلَ‏.‏", "en": "Narrated Anas:Whenever the Prophet (ﷺ) went to answer the call of nature, he used to say, \"Allah-umma inni a`udhu bika minal khubuthi wal khaba'ith i.e. O Allah, I seek Refuge with You from all offensive and wicked things (evil deeds and evil spirits)", "fr": "Rapporté par Anas : Chaque fois que le Prophète (ﷺ) allait aux toilettes, il disait : « Allahumma inni a`udhu bika minal khubuthi wal khaba’ith », c’est-à-dire : « Ô Allah, je cherche refuge auprès de Toi contre tout ce qui est mauvais et impur (mauvaises actions et mauvais esprits). »", "id": "Telah menceritakan kepada kami [Adam] berkata, telah menceritakan kepada kami [Syu'bah] dari [Abdul 'Aziz bin Shuhaib] berkata, aku mendengar [Anas] berkata, \"Jika Nabi shallallahu 'alaihi wasallam masuk ke dalam WC, maka beliau berdo'a: ALLAHUMMA INNI A'UUDZU BIKA MINAL KHUBUTSI WAL KHBA`ITS (Ya Allah aku berlindung kepada-Mu dari setan laki-laki dan setan perempuan) '. Dan hadits ini dikuatkan oleh [Ibnu 'Ar'arah] dari [Syu'bah], dan [Ghundar] berkata dari [Syu'bah] ia berkata, \"Jika mendatangi WC.\" Dan [Musa] dari [Hammad], \"Jika masuk.\" Dan [Sa'id bin Zaid] berkata, telah menceritakan kepada kami [Abdul 'Aziz], \"Jika mau masuk", "tr": "Enes r.a. şöyle demiştir: Nebiyy-i Muhterem sallallahu aleyhi ve sellem, helaya girdiği zaman Allahumme inni auzu bike minel hubsi vel hebaisi diye duâ buyurdu. Tekrar: 6322 Diğer tahric edenler: Tirmizi Tahare; Müslim, Hayz Duanın Meali: Allah'ım, gözle görülmeyen kötülüklerden, erkek ve dişi şeytanlardan Sana sığı­nırım"}}, "inv_sortir": {"refs": [["abudawud", 5095]], "txt": {"ar": "حَدَّثَنَا إِبْرَاهِيمُ بْنُ الْحَسَنِ الْخَثْعَمِيُّ، حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ ‏\"‏ ‏.‏ قَالَ ‏\"‏ يُقَالُ حِينَئِذٍ هُدِيتَ وَكُفِيتَ وَوُقِيتَ فَتَتَنَحَّى لَهُ الشَّيَاطِينُ فَيَقُولُ لَهُ شَيْطَانٌ آخَرُ كَيْفَ لَكَ بِرَجُلٍ قَدْ هُدِيَ وَكُفِيَ وَوُقِيَ ‏\"‏ ‏.‏", "en": "Narrated Anas ibn Malik: The Prophet (ﷺ) said: When a man goes out of his house and says: \"In the name of Allah, I trust in Allah; there is no might and no power but in Allah,\" the following will be said to him at that time: \"You are guided, defended and protected.\" The devils will go far from him and another devil will say: How can you deal with a man who has been guided, defended and protected?", "id": "Telah menceritakan kepada kami [Ibrahim bin Al Hasan Al Khats'ami] berkata, telah menceritakan kepada kami [Hajjaj bin Muhammad] dari [Ibnu Juraij] dari [Ishaq bin Abdullah bin Abu Thalhah] dari [Anas bin Malik] bahwa Nabi shallallahu 'alaihi wasallam bersabda: \"Jika seorang laki-laki keluar dari rumahnya lalu mengucapkan: 'BISMILLAHI TAWAKKALTU 'ALAALLAHI LAA HAULA WA LAA QUWWATA ILLA BILLAH (Dengan nama Allah aku bertawakal kepada Allah, tidak ada daya dan kekuatan kecuali dengan izin Allah). ' Beliau bersabda: \"Maka pada saat itu akan dikatakan kepadanya, 'Kamu telah mendapat petunjuk, telah diberi kecukupan dan mendapat penjagaan', hingga setan-setan menjauh darinya. Lalu setan yang lainnya berkata, \"Bagaimana (engkau akan mengoda) seorang laki-laki yang telah mendapat petunjuk, kecukupan dan penjagaan", "tr": "Enes b. Mâlik'den (rivayet edildiğine göre) Nebi (s.a.v.) şöyle buyurmuştur; \"Bir adam evinden çıkınca \"Bismillah tevekkeltu al-allah, lâ havle velâ kuvvete illa billah: Allah'ın ismiyle (daşırı çıktım) Allah'a tevekkkül ettim, güç ve kuvvet sadece Allah'dandır\" derse, o zaman kendisine (bir melek tarafından o adam'a: \"Sen bu duanın bereketiyle) doğru yol'a iletildin, şerlere karşı koymakta yeterli hale getirildin (ve onlardan) korundun\" diye karşılık verilir. Bunun üzerine şeytanlar ondan uzaklaşır. Diğer bir şeytan da ona: Senin için doğru yola iletilen, yeterli hale getirilen ve korunulan bir kimseyi (yoldan çıkarmak) nasıl (mümkün olur)? der", "fr": "Rapporté par Anas ibn Malik رضي الله عنه : Le Prophète ﷺ a dit : « Quand un homme sort de chez lui et dit : “Au nom d’Allah, je place ma confiance en Allah ; il n’y a de force ni de puissance qu’en Allah”, il lui sera dit à ce moment-là : “Tu es guidé, protégé et préservé.” Les diables s’éloigneront de lui et un autre diable dira : “Que peux-tu faire contre un homme qui a été guidé, protégé et préservé ?” »"}}, "inv_mosquee": {"refs": [["muslim", 713]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ يَحْيَى، أَخْبَرَنَا سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، عَنْ عَبْدِ الْمَلِكِ بْنِ سَعِيدٍ، عَنْ أَبِي حُمَيْدٍ، - أَوْ عَنْ أَبِي أُسَيْدٍ، - قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَقُلِ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ ‏.‏ وَإِذَا خَرَجَ فَلْيَقُلِ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ ‏\"‏ ‏.‏ قَالَ مُسْلِمٌ سَمِعْتُ يَحْيَى بْنَ يَحْيَى يَقُولُ كَتَبْتُ هَذَا الْحَدِيثَ مِنْ كِتَابِ سُلَيْمَانَ بْنِ بِلاَلٍ ‏.‏ قَالَ بَلَغَنِي أَنَّ يَحْيَى الْحِمَّانِيَّ يَقُولُ وَأَبِي أُسَيْدٍ ‏.‏", "en": "Abu Usaid reported that the Messenger of Allah (ﷺ) said:When any one of you enters the mosque, he should say:\" O Allah! open for me the doors of Thy mercy\" ; and when he steps out he should say: 'O Allah! I beg of Thee Thy Grace.\" (Imam Muslim said: I heard Yahya saying: I transcribed this hadith from the compilation of Sulaiman b. Bilal)", "fr": "Rapporté par Abu Usaid : Le Messager d’Allah ﷺ a dit : « Quand l’un d’entre vous entre dans la mosquée, qu’il dise : “Ô Allah ! ouvre-moi les portes de Ta miséricorde.” Et quand il en sort, qu’il dise : “Ô Allah ! je Te demande Ta grâce.” » (Imam Muslim a dit : J’ai entendu Yahya dire : J’ai copié ce hadith de la compilation de Sulaiman b. Bilal)", "id": "Telah menceritakan kepada kami [Yahya bin Yahya] telah mengabarkan kepada kami [Sulaiman bin Bilal] dari [Rabi'ah bin Abdurrahman] dari [Abdul Malik bin Sa'id] dari [Abu Humaid] atau dari [Abu Usaid] katanya; Rasulullah shallallahu 'alaihi wasallam bersabda: \"jika salah seorang diantara kalin masuk masjid, bacalah doa ALLAAHUMMAFTAH LII ABWAABA RAHMATIKA (Ya Allah, bukalah pintu-pintu rahmat-Mu).\" Dan apabila keluar, hendaknya ia membaca doa ALLAAHUMMA INNII AS`ALUKA MIN FADHLIKA (Ya Allah, aku meminta kurnia-Mu).\" Muslim berkata; Aku mendengar [Yahya bin Yahya] mengatakan; \"Aku menulis hadis ini dari kitab Sulaiman bin Bilal, katanya; telah sampai berita kepadaku bahwa [Yahya Al Himmani] mengatakan; dan [Abu Usaid], telah menceritakan kepada kami [Hamid bin Umar Al Bakrawi] telah menceritakan kepada kami [Bisyr bin Al Mufadlal] telah menceritakan kepada kami ['Umarah bin Ghaziyyah] dari [Rabi'ah bin Abdurrahman] dari [Abdul Malik bin Sa'id bin Suwaid Al Anshari] dari [Abu Humaid] atau [Abu Usaid] dari Nabi shallallahu 'alaihi wasallam seperti hadits ini", "tr": "Bize Yahya b. Yahya rivayet etti. (Dediki): Bize Süleyman b. Bilâl, Rabîatü'bnü Ebî Abdirrahmân'dan, o da Abdülmelik b. Saîd'den, o da Ebû Humeyd'den (yahut Ebû Useyd'den) naklen haber verdi. Şöyle demiş: Resûlullah (Sallallahu Aleyhi ve Sellem) : «Biriniz mescide girdiği vakit : Yâ Rabbî! Bana, rahmet kapılarını aç! desin, Çıktığı vakit de Yâ Rabbî! Ben, senden fadlını dilerim, desin!» buyurdular. Müslim der ki: Ben, Yahya b. Yahya'yı şöyle derken işittim: Ben, bu hadîsi Süleyman b. Bilâl'in kitabından yazdım. O: Duydum ki Yahye'l -Hımmânî (ve Ebû Useyd) diyormuş; demişdir"}}, "inv_wudu": {"refs": [["muslim", 234]], "txt": {"ar": "حَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا مُعَاوِيَةُ بْنُ صَالِحٍ، عَنْ رَبِيعَةَ، - يَعْنِي ابْنَ يَزِيدَ - عَنْ أَبِي إِدْرِيسَ الْخَوْلاَنِيِّ، عَنْ عُقْبَةَ بْنِ عَامِرٍ، ح وَحَدَّثَنِي أَبُو عُثْمَانَ، عَنْ جُبَيْرِ بْنِ نُفَيْرٍ، عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ كَانَتْ عَلَيْنَا رِعَايَةُ الإِبِلِ فَجَاءَتْ نَوْبَتِي فَرَوَّحْتُهَا بِعَشِيٍّ فَأَدْرَكْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم قَائِمًا يُحَدِّثُ النَّاسَ فَأَدْرَكْتُ مِنْ قَوْلِهِ ‏\"‏ مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلاَّ وَجَبَتْ لَهُ الْجَنَّةُ ‏\"‏ ‏.‏ قَالَ فَقُلْتُ مَا أَجْوَدَ هَذِهِ ‏.‏ فَإِذَا قَائِلٌ بَيْنَ يَدَىَّ يَقُولُ الَّتِي قَبْلَهَا أَجْوَدُ ‏.‏ فَنَظَرْتُ فَإِذَا عُمَرُ قَالَ إِنِّي قَدْ رَأَيْتُكَ جِئْتَ آنِفًا قَالَ ‏\"‏ مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُبْلِغُ - أَوْ فَيُسْبِغُ - الْوُضُوءَ ثُمَّ يَقُولُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ إِلاَّ فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏\"‏ ‏.‏", "en": "Uqba b. 'Amir reported:We were entrusted with the task of tending the camels. On my turn when I came back in the evening after grazing them in the pastures, I found Allah's Messenger (ﷺ) stand and address the people. I heard these words of his: If any Muslim performs ablution well, then stands and prays two rak'ahs setting about them with his heart as well as his face, Paradise would be guaranteed to him. I said: What a fine thing is this! And a narrator who was before me said: The first was better than even this. When I cast a glance, I saw that it was 'Umar who said: I see that you have just come and observed: If anyone amongst you performs the ablution, and then completes the ablution well and then says: I testify that there is no god but Allah and that Muhammad is the servant of Allah and His Messenger, the eight gates of Paradise would be opened for him and he may enter by whichever of them he wishes", "fr": "Rapporté par ‘Uqba b. ‘Amir رضي الله عنه : Nous avions la charge de garder les chameaux. Un soir, quand c’était mon tour, je suis revenu après les avoir fait paître et j’ai trouvé le Messager d’Allah ﷺ debout, s’adressant aux gens. J’ai entendu ces paroles : « Si un musulman fait bien ses ablutions, puis se lève et prie deux unités de prière avec son cœur et son visage tournés vers Allah, le Paradis lui sera garanti. » J’ai dit : « Quelle belle chose ! » Un narrateur avant moi a dit : « La première chose était encore meilleure. » J’ai regardé, c’était ‘Umar qui a dit : « Je vois que tu viens d’arriver. » Puis il a dit : « Si l’un d’entre vous fait ses ablutions, les complète bien, puis dit : “J’atteste qu’il n’y a pas d’autre divinité qu’Allah et que Muhammad est le serviteur d’Allah et Son Messager”, les huit portes du Paradis lui seront ouvertes et il pourra entrer par celle qu’il voudra. »", "id": "Telah menceritakan kepadaku [Muhammad bin Hatim bin Maimun] telah menceritakan kepada kami [Abdurrahman bin Mahdi] telah menceritakan kepada kami [Muawiyah bin Shalih] dari [Rabi'ah] -yaitu Ibnu Yazid- dari [Abu Idris al-Khaulani] dari [Uqbah bin Amir]. (dalam riwayat lain disebutkan) Dan telah menceritakan kepadaku [Abu Utsman] dari [Jubair bin Nufair] dari [Uqbah bin Amir] dia berkata, \"Dahulu kami menggembala unta, lalu datanglah malam, maka aku mengistirahatkannya dengan memberikan makan malam. Lalu aku mendapati Rasulullah shallallahu 'alaihi wasallam berdiri berbicara kepada manusia. Dan dari sebagian sabdanya yang aku dengar adalah: 'Tidaklah seorang muslim berwudlu lalu menyempurnakan wudlunya, kemudian mendirikan shalat dua rakaat dengan menghadapkan hati dan wajahnya, kecuali surga wajib diberikan kepadanya.\" Uqbah berkata, 'Maka aku berkata, 'Alangkah baiknya ini, ' tiba-tiba seorang pembicara di depanku berkata, 'Yang sebelumnya adalah lebih bagus'. Saat aku lihat, ternyata dia adalah [Umar].' Uqbah lalu berkata, 'Sesungguhnya aku telah melihatmu datang barusan.\" Umar lalu menyebutkan, \"Tidaklah salah seorang di antara kalian berwudlu, lalu menyampaikan wudlunya atau menyempurnakan wudlunya kemudian dia bersaksi bahwa tidak ada tuhan yang berhak disembah selain Allah, dan bahwa Muhammad adalah hamba dan utusan-Nya melainkan pintu surga yang delapan akan dibukakan untuknya. Dia masuk dari pintu manapun yang dia kehendaki'.\" Dan telah menceritakannya kepada kami [Abu Bakar bin Abu Syaibah] telah menceritakan kepada kami [Zaid bin al-Hubab] telah menceritakan kepada kami [Muawiyah bin Shalih] dari [Rabi'ah bin Yazid] dari [Abu Idris al-Khaulani] dan [Abu Utsman] dari [Jubair bin Nufair bin Malik al-Hadlrami] dari [Uqbah bin Amir al-Juhani] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda…Lalu dia menyebutkan hadits semisalnya, hanya saja dia menyebutkan, \"Barangsiapa bersaksi bahwa tidak ada tuhan yang berhak disembah selain Allah semata, tidak ada sekutu bagi-Nya, dan saya bersaksi bahwa Muhammad adalah hamba dan utusan-Nya", "tr": "Bana Muhammed b. Hatim b. Meymun tahdis etti. Bize Abdurrahman b. Mehdi tahdis etti. Bize Muaviye b. Salih, Rabia -yani b. Yezid'den tahdis etti. O Ebu İdris el-Havlanl'den, o Ukbe b. Amir'den (H). Bana Ebu Osman da Cubeyr b. Nufeyr'den tahdis etti. O Ukbe b. Amir'den şöyle dediğini nakletti: Deve çobanlığı (sırası) bizde idi. Benim sıram geldi, akşam vakti onları götürdüm. Resulullah (Sallallahu aleyhi ve Sellem)'e ayakta insanlara konuşma yaparken yetiştim. Onun sözlerinden: \"Herhangi bir Müslüman güzel bir şekilde abdest aldıktan sonra kalbiyle ve yüzüyle kendisini onlara vererek iki rekat namaz kılacak olursa, mutlaka ona cennet vacip olur\" sözlerini söylerken yetiştim. Ben: Bu ne güzel bir şey, dedim. Bir de baktım ki önümdeki birisi: Bundan önceki daha da güzeldi, dedi. (Kim olduğuna) bakınca Ömer olduğunu gördüm. Şöyle dedi: Ben senin az önce geldiğini gördüm. (Allah Resulü) şöyle buyurdu: \"Sizden biriniz abdest alıp da abdestini eksiksiz alır -yahut abdest organlarını tamamen yıkar- sonra da eşhedu en Ia iahe illallah ve enne Muhammeden Abdullahi ve Resuluh: Allah'tan bClşka bir ilah olmadığına ve Muhammed'in Allah'ın kulu ve Resulü olduğuna şahitlik ederim, diyecek olursa, mutlaka ona cennetin sekiz kapısı açılır, hangisinden dilerse ondan girer. \" Diğer tahric: Ebu Davud, 169 -uzunca-, 906; Nesai, 148, 151; İbn Mace, 470; Tuhfetu'l-Eşraf, 9914 ve"}}, "inv_eternuement": {"refs": [["bukhari", 6224]], "txt": {"ar": "حَدَّثَنَا مَالِكُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ دِينَارٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلِ الْحَمْدُ لِلَّهِ‏.‏ وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ يَرْحَمُكَ اللَّهُ‏.‏ فَإِذَا قَالَ لَهُ يَرْحَمُكَ اللَّهُ‏.‏ فَلْيَقُلْ يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏\"‏‏.‏", "fr": "Rapporté par Abu Huraira : Le Prophète (ﷺ) a dit : « Si l’un d’entre vous éternue, il doit dire : “Al-Hamduli l-lah” (Louange à Allah), et son frère musulman ou son compagnon doit lui répondre : “Yar-hamuka-l-lah” (Qu’Allah te fasse miséricorde). Quand ce dernier dit : “Yar-hamuka-l-lah”, le premier doit répondre : “Yahdikumul-lah wa Yuslih balakum” (Qu’Allah vous guide et améliore votre situation). »", "id": "Telah menceritakan kepada kami [Malik bin Isma'il] telah menceritakan kepada kami [Abdul Aziz bin Abu Salamah] telah mengabarkan kepada kami [Abdullah bin Dinar] dari [Abu Shalih] dari [Abu Hurairah] radliallahu 'anhu dari Nabi shallallahu 'alaihi wasallam beliau bersabda: \"Ababila salah seorang dari kalian bersin, hendaknya ia mengucapkan \"Al Hamdulillah\" sedangkan saudaranya atau temannya hendaklah mengucapkan \"Yarhamukallah (semoga Allah merahmatimu), dan hendaknya ia membalas; \"Yahdikumullah wa yushlih baalakum (semoga Allah memberimu petunjuk dan memperbaiki hatimu)", "tr": "Ebu Hureyre r.a.'dan rivayete göre Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Sizden biriniz aksıracak olursa elhamdulillah desin, kardeşi -yahut arkadaşı- da ona: Yerhamukellah desin. Ona yerhamukellah dediği takdirde aksıran da: Yehdikumullahu ve yuslihu balekum: (Allah size hidayet versin ve halinizi de düzeltsin), desin.\" Fethu'l-Bari Açıklaması: Aksıran kimseye elhamdulillah demesinin emredilmiş olması, bunun namaz kılan kimse için dahi meşru olduğuna delil gösterilmiştir. Daha önceden \"Aksıran kimsenin hamdetmesi\" başlığında Rifaa İbn Rafi'in hadisine işaret edilmiş idi. Ashabın cumhuru ve onlardan sonraki imamlar da bu görüşü ifade etmişlerdir. Malik, Şafil ve Ahmed de böyle demiştir. Tirmizi bazı tabiınden bunun farz namazda değil, nafile namazda meşru olduğunu söylediklerini nakletmiştir. Bununla birlikte (farz namazda) kendi kendisine elhamdulillah, der. Hocamız da Tirmizi Şerhi'nde bu sözleri ile bunu gizlice söyler, açıkça söylemez demek istemiş olabileceğini belirtmiştir. Fakat buna rağmen ona Rifaa İbn Rafi'in rivayet ettiği hadis ileri sürülerek itiraz edilir. Çünkü o, elhamdulillahı açıktan söylemiş, Nebi Sallallahu Aleyhi ve Sellem de onun bu yaptığını reddetmemişti. Evet, aksıranın Fatiha'yı okumakta olması ile başkasını okuyar olması arasında fark gözetilir. Çünkü Fatiha'nın kıraatinin kesintisiz olması gerekmektedir. Malikilerden İbnu'l-Arabi de kesin bir dille namazda iken aksıran kimsenin kendi kendisine elhamdulillah diyeceğini ifade etmiştir. Suhnun'dan ise namazı bitirinceye kadar elhamdulillah demeyeceğini söylediğini nakletmekte, ama daha sonra bunun bir aşırılık olduğunu söyleyerek ona itiraz etmektedir. \"Kardeşi yahut onun arkadaşı da ona yerhamukellah desin.\" Burada kardeşlikten kasıt, İslam kardeşliğidir. Buhari e!-Edebu'l-Müfred'de sahih bir sened ile Ebu Cemra'dan şunu rivayet etmektedir: \"Ben İbn Abbas') aksırıp da ona yerhamukellah denildiği takdirde: Afanallahu ve iyyakum mine'n-nari yerhamukumullah: Allah bizi de, sizi de ateşten kurtarıp afiyet versin, Allah size de rahmet ihsan etsin, derken işitmişimdir.\" Muvatta'da Rafi'den, onun İbn Ömer'den rivayetine göre \"İbn Ömer aksırır da ona yerhamukellah denilirse, o da: yerhamunallahu ve iyyakum ve yağfirullahu lena ve lekum: Allah bize de size de rahmet ihsan etsin, Allah bize de size de mağfiret buyursun, derdi.\" \"Ona: Yerhamukellah diyecek olursa, aksıran: Yehdikumullahu ve yuslihu balekum: Allah size hidayet versin ve halinizi de düzeltsin, desin.\" Bu ifadenin gereği, ancak kendisine yerhamukellah diyen kimse için böyle demenin meşru olmasıdır. Bu da açıktır. Bu lafız da aksırıp elhamdulillah diyen kimsenin vereceği cevaptır. Bu, hakkında görüş ayrılığı bulunan bir husustur. İbn Battal dedi ki: Cumhurun görüşü bu doğrultudadır ama KD.fe bilginlerinin görüşüne göre yağfirullahu lena ve lekum: Allah bize ve size mağfiret buyursun, der. Bunu Taberi, İbn Mesud'dan, İbn Ömer'den ve başkalarından diye rivayet etmiştir. İbn Battal dedi ki: Malik ve Şafii' de bu iki lafızdan istediğini seçebileceği görüşündedirler. İbn Ebi Cemra dedi ki: Hadiste yüce Allah'ın aksırana nimetinin pek büyük olduğuna bir delil vardır. Bu da aksırmaya bağlı olarak sözkonusu olan hayırlardan anlaşılır. Yine bu hadiste Allah'ın kulu üzerindeki pek büyük lütfuna da işaret vardır. O, aksırma nimetiyle kuluna gelecek zararı gidermiştir. Arkasından dolayısıyla kendisine sevap verilen hamd etmek de ona meşru kılınmış, ayrıca hayır ile dua ettikten sonra yine hayır ile dua meşru kılınmıştır. Şanı yüce Allah'ın, kısacık bir zamanda ardı arkasına bu nimetleri teşri buyurmuş olması, onun bir lütfu ve ihsanıdır. Bu da kalbi ve basireti olan bir kimsenin imanını artıran bir husustur. Öyle ki, bundan dolayı pek çok gün ibadet ile elde edemeyeceği şeyleri elde edebilir. Bu vesile ile hatırına getirmediği Allah'ın kendisine ihsan etmiş olduğu Allah sevgisi nimeti de bunun kapsamındadır. Aynı şekilde kendisi vasıtası ile bu hayrı bilip öğrendiğimiz ve değeri ölçülüp biçilemeyecek kadar büyük sünnetinin getirdiği ilim de bunun içerisindedir. Bu kabilden, bir zerrenin artışında bile bunun dışında pek çok amelden daha bir üstünlük sözkonusu olur. Allah'a pek çok hamd olsun", "en": "Narrated Abu Huraira:The Prophet (ﷺ) said, \" If anyone of you sneezes, he should say 'Al-Hamduli l-lah' (Praise be to Allah), and his (Muslim) brother or companion should say to him, 'Yar-hamuka-l-lah' (May Allah bestow his Mercy on you). When the latter says 'Yar-hamuka-llah\", the former should say, 'Yahdikumul-lah wa Yuslih balakum' (May Allah give you guidance and improve your condition)"}}, "inv_pluie": {"refs": [["bukhari", 1032]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدٌ ـ هُوَ ابْنُ مُقَاتِلٍ أَبُو الْحَسَنِ الْمَرْوَزِيُّ ـ قَالَ أَخْبَرَنَا عَبْدُ اللَّهِ، قَالَ أَخْبَرَنَا عُبَيْدُ اللَّهِ، عَنْ نَافِعٍ، عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ إِذَا رَأَى الْمَطَرَ قَالَ ‏ \"‏ صَيِّبًا نَافِعًا ‏\"‏‏.‏ تَابَعَهُ الْقَاسِمُ بْنُ يَحْيَى عَنْ عُبَيْدِ اللَّهِ‏.‏ وَرَوَاهُ الأَوْزَاعِيُّ وَعُقَيْلٌ عَنْ نَافِعٍ‏.‏", "en": "Narrated Aisha:Whenever Allah's Messenger (ﷺ) saw the rain, he used to say, \"O Allah! Let it be a strong fruitful rain", "fr": "Rapporté par Aisha : Chaque fois que le Messager d’Allah (ﷺ) voyait la pluie, il disait : « Ô Allah ! Fais que ce soit une pluie abondante et bénéfique. »", "id": "Telah menceritakan kepada kami [Muhammad] -yaitu Ibnu Muqatil Abu Al Hasan Al Marwazi- berkata, telah mengabarkan kepada kami ['Abdullah] berkata, telah mengabarkan kepada kami ['Ubaidullah] dari [Nafi'] dari [Al Qasim bin Muhammad] dari ['Aisyah], bahwa jika Rasulullah shallallahu 'alaihi wasallam melihat hujan, maka beliau berdoa: 'ALLAHUMMA SHAYYIBAA NAAFI'AA (Ya Allah, jadikanlah hujan ini bermanfaat) '.\" Hadits ini juga dikuatkan oleh [Al Qasim bin Yahya] dari ['Ubaidullah], dan diriwayatkan pula oleh [Al Auza'i] dan ['Uqail] dari [Nafi]", "tr": "Aişe (r.anha)'dan nakledilmiştir: \"Resulullah Sallallahu Aleyhi ve Sellem yağmur yağdığı zaman: صيبا نافع = Allah'ım, faydalı bir yağmur olsun! derdi"}}, "inv_rupture": {"refs": [["abudawud", 2357]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ يَحْيَى أَبُو مُحَمَّدٍ، حَدَّثَنَا عَلِيُّ بْنُ الْحَسَنِ، أَخْبَرَنِي الْحُسَيْنُ بْنُ وَاقِدٍ، حَدَّثَنَا مَرْوَانُ، - يَعْنِي ابْنَ سَالِمٍ - الْمُقَفَّعُ - قَالَ رَأَيْتُ ابْنَ عُمَرَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ وَقَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا أَفْطَرَ قَالَ ‏ \"‏ ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللَّهُ ‏\"‏ ‏.‏", "en": "Marwan ibn Salim al-Muqaffa' said: I saw Ibn Umar holding his beard with his hand and cutting what exceeded the handful of it. He (Ibn Umar) said that the Prophet (ﷺ) said when he broke his fast: Thirst has gone, the arteries are moist, and the reward is sure, if Allah wills", "fr": "Marwan ibn Salim al-Muqaffa' a dit : J’ai vu Ibn Umar رضي الله عنه prendre sa barbe dans sa main et couper ce qui dépassait une poignée. Il (Ibn Umar) a dit que le Prophète ﷺ disait lorsqu’il rompait son jeûne : « La soif est partie, les veines sont humidifiées, et la récompense est assurée, si Allah le veut. »", "id": "Telah menceritakan kepada kami [Abdullah bin Muhammad bin Yahya Abu Muhammad], telah menceritakan kepada kami [Ali bin Al Hasan], telah mengabarkan kepadaku [Al Husain bin Waqid], telah menceritakan kepada kami [Marwan bin Salim Al Muqaffa'], ia berkata; saya melihat [Ibnu Umar] menggenggam jenggotnya dan memotong jenggot yang melebihi telapak tangan. Dan ia berkata; dahulu Rasulullah shallallahu 'alaihi wasallam apabila berbuka beliau mengucapkan: DZAHABAZH ZHAMAA`U WABTALLATIL 'URUUQU WA TSABATIL AJRU IN SYAA-ALLAAH (Telah hilang dahaga, dan telah basah tenggorokan, dan telah tetap pahala insya Allah)", "tr": "Mervân b. Salim el-Mukaffa'dan demiştirki; İbn Ömer (r.a.) sakalını avuçlar, avucundan artan kısmı keserdi; O şöyle dedi; \"Rasûlullah (s.a.v.) iftar ettiği zaman, \"susuzluk gitti, damarlar nemlendi ve inşallah ecir hâsıl oldu\" buyurdu"}}, "inv_istighfar": {"refs": [["bukhari", 6306]], "txt": {"ar": "حَدَّثَنَا أَبُو مَعْمَرٍ، حَدَّثَنَا عَبْدُ الْوَارِثِ، حَدَّثَنَا الْحُسَيْنُ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ، عَنْ بُشَيْرِ بْنِ كَعْبٍ الْعَدَوِيِّ، قَالَ حَدَّثَنِي شَدَّادُ بْنُ أَوْسٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏\"‏ سَيِّدُ الاِسْتِغْفَارِ أَنْ تَقُولَ اللَّهُمَّ أَنْتَ رَبِّي، لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَىَّ وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ ‏\"‏‏.‏ قَالَ ‏\"‏ وَمَنْ قَالَهَا مِنَ النَّهَارِ مُوقِنًا بِهَا، فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ، فَهُوَ مِنْ أَهْلِ الْجَنَّةِ، وَمَنْ قَالَهَا مِنَ اللَّيْلِ وَهْوَ مُوقِنٌ بِهَا، فَمَاتَ قَبْلَ أَنْ يُصْبِحَ، فَهْوَ مِنْ أَهْلِ الْجَنَّةِ ‏\"‏‏.‏", "en": "Narrated Shaddad bin Aus:The Prophet (ﷺ) said \"The most superior way of asking for forgiveness from Allah is: 'Allahumma anta Rabbi la ilaha illa anta, Khalaqtani wa ana `Abduka, wa ana `ala `ahdika wa wa`dika mastata`tu, A`udhu bika min Sharri ma sana`tu, abu'u Laka bini`matika `alaiya, wa abu'u laka bidhanbi faghfir lee fa innahu la yaghfiru adhdhunuba illa anta.\" The Prophet (ﷺ) added. \"If somebody recites it during the day with firm faith in it, and dies on the same day before the evening, he will be from the people of Paradise; and if somebody recites it at night with firm faith in it, and dies before the morning, he will be from the people of Paradise", "fr": "Rapporté par Shaddad bin Aus : Le Prophète (ﷺ) a dit : « La meilleure façon de demander pardon à Allah est : ‘Allahumma anta Rabbi la ilaha illa anta, Khalaqtani wa ana `Abduka, wa ana `ala `ahdika wa wa`dika mastata`tu, A`udhu bika min Sharri ma sana`tu, abu'u Laka bini`matika `alaiya, wa abu'u laka bidhanbi faghfir lee fa innahu la yaghfiru adhdhunuba illa anta.’ » Le Prophète (ﷺ) a ajouté : « Si quelqu’un récite cette invocation dans la journée avec une foi sincère et meurt le même jour avant le soir, il fera partie des gens du Paradis ; et si quelqu’un la récite la nuit avec une foi sincère et meurt avant le matin, il fera aussi partie des gens du Paradis. »", "id": "Telah menceritakan kepada kami [Abu Ma'mar] telah menceritakan kepada kami [Abdul Warits] telah menceritakan kepada kami [Al Husain] telah menceritakan kepada kami [Abdullah bin Buraidah] dia berkata; telah menceritakan kepadaku [Busyair bin Ka'b Al 'Adawi] dia berkata; telah menceritakan kepadaku [Syaddad bin Aus] radliallahu 'anhu dari Nabi shallallahu 'alaihi wasallam; \"Sesungguhnya istighfar yang paling baik adalah; kamu mengucapkan: 'ALLAHUMMA ANTA RABBI LAA ILAAHA ILLA ANTA KHALAQTANI WA ANA 'ABDUKA WA ANA 'ALA 'AHDIKA WA WA'DIKA MASTATHA'TU A'UUDZU BIKA MIN SYARRI MAA SHANA'TU ABUU`U LAKA BIDZANBI WA ABUU`U LAKA BINI'MATIKA 'ALAYYA FAGHFIRLI FA INNAHU LAA YAGHFIRU ADZ DZUNUUBA ILLA ANTA (Ya Allah, Engkau adalah Tuhanku, tidak ada Tuhan yang berhak diibadahi selain Engkau. Engkau telah menciptakanku dan aku adalah hamba-Mu. Aku menetapi perjanjian-Mu dan janji-Mu sesuai dengan kemampuanku. Aku berlindung kepada-Mu dari keburukan perbuatanku, aku mengakui dosaku kepada-Mu dan aku akui nikmat-Mu kepadaku, maka ampunilah aku. Sebab tidak ada yang dapat mengampuni dosa selain-Mu) '.\" Beliau bersabda: 'Jika ia mengucapkan di waktu siang dengan penuh keyakinan lalu meninggal pada hari itu sebelum waktu sore, maka ia termasuk dari penghuni surga. Dan jika ia membacanya di waktu malam dengan penuh keyakinan lalu meninggal sebelum masuk waktu pagi, maka ia termasuk dari penghuni surga", "tr": "Şeddad İbn Evs'ten nakledildiğine göre Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Seyyidu'l-istiğfar = İstiğfarların efendisi şöyledir:"}}, "inv_detresse": {"refs": [["bukhari", 6346]], "txt": {"ar": "حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ هِشَامِ بْنِ أَبِي عَبْدِ اللَّهِ، عَنْ قَتَادَةَ، عَنْ أَبِي الْعَالِيَةِ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَقُولُ عِنْدَ الْكَرْبِ ‏ \"‏ لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ، وَرَبُّ الأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيمِ ‏\"‏‏.‏ وَقَالَ وَهْبٌ حَدَّثَنَا شُعْبَةُ عَنْ قَتَادَةَ مِثْلَهُ‏.‏", "en": "Narrated Ibn `Abbas:Allah's Messenger (ﷺ) used to say at a time of distress, \"La ilaha illal-lahu Rabbul-l-'arsh il-'azim, La ilaha illallahu Rabbu-s-samawati wa Rabbu-l-ard, Rabbu-l-'arsh-il-Karim", "fr": "Rapporté par Ibn `Abbas : Le Messager d'Allah ﷺ disait lors d’un moment de détresse : « La ilaha illal-lahu Rabbul-l-'arsh il-'azim, La ilaha illallahu Rabbu-s-samawati wa Rabbu-l-ard, Rabbu-l-'arsh-il-Karim. »", "tr": "İbn Abbas'tan nakledildiğine göre Resulullah Sallallahu Aleyhi ve Sellem sıkıntı halinde şöyle dua ederdi: La İlahe illallahu’l-Azimu’l-Halim, La İlahe illlahu Rabbi’l-Arşi’l-Azim, La İlahe İllallahu Rabbi’s-semavati ve Rabbi’l-Ardi ve Rabbi’l-Arşi’l-Kerim Meali: \"Azim ve halim olan Allah'tan başka ilah yoktur, Yüce arşın rabbi olan Allah'tan başka ilah yoktur. Göklerin, yerin ve yüce arşın rabbi olan Allah'tan başka ilah yoktur\". Fethu'l-Bari Açıklaması: Alimler hadiste zikri geçen \"Halim\" kelimesini cezalandırmaya gücü olduğu halde bunu erteleyen diye anlamışlardır. \"Azim\" ise üstünde kimsenin olmadığı demektir. \"Kerim\"e gelince fazlıyla veren anlamındadır. Esma-i hüsna şerhedilirken bunlar daha fazla izah edilecektir. Tibi bu zikirde \"Rab\" kelimesinin özellikle kullanıldığını; zira bunun sıkıntıyı gidermek için daha uygun düştüğünü söylemiştir. Çünkü sıkıntı (ya da sıkıntının giderilmesi) de terbiyenin bir parçasıdır. Bu zikirde tevhid’i de içeren tehlil söz konusudur. Bu en yüce tenzihtir. Allah'ın kudretini tam olarak gösteren bir yüceltmedir. İlmi de gösteren bir merhamettir. Zira cahilden merhamet ve cömertlik beklenmez. Azamet ve hilim cömertlik vasıflarının en önemlileridir. Taberi'nin belirttiğine göre İbn Abbas'ın \"dua ediyor\" sözüne rağmen rivayette tehlil ve tazimin yer alması iki şekilde yorumlanabilir: İlk olarak dua öncesinde Resulullah s.a.v.'in Allah'ı tehlil ve tazim ettiği düşünülebilir. Yusuf İbn Abdillah İbn Haris'ten nakledilen rivayette \"sonra dua etti\" ifadesi açıkça yer almaktadır. Yine Taberi'nin A'meş vasıtasıyla İbrahim'den aktardığına göre kişi dua öncesinde Allah'ı överse icabet edileceğinin, övgü öncesinde dua ederse icabetin umulacağının söylenmesi de yukarıdaki kanaati teyid etmektedir. İkinci yorum ise İbn Uyeyne'ye aittir. İbn Uyeyne'ye \"Resulullah s.a.v. Arafat'ta genelde \"Ortağı bulunmayan Allah'tan başka ilah yoktur\" diye dua ederdi\" hadisi sorulunca, burada duanın değil zikrin söz konusu olduğunu; ancak kudsi bir hadiste \"Beni zikrettiği için dua edemeyene dua edenlere verdiğimden daha güzelini veririm\" buyurulduğunu söylemiştir. Bana göre Sa'd İbn Ebi Vakkas'ın merfu olarak naklettiği şu hadis ikinci ihtimali desteklemektedir: \"Zü'n-nun (Hz. Yunus) balığın karnındayken şöyle dua etmiştir: Senden başka ilah yoktur. \"Seni her türlü noksanlıklardan tenzih ederim. Bende zalimlerden biriyim\". Bir müslüman böyle dua ederse duası mutlaka kabul edilir\". Bu hadis Tirmizı, Nesaıve Hakim tarafından naklediimiştir. Hakim'in rivayetinde \"Ordakilerden biri: \"Bu Yunus'a mı özeldir yoksa tüm müslümanlar için de geçerli midir?\" diye sorunca Resulullah s.a.v.: \"İşte Biz mu'minleri böyle kurtarırız\"(Enbiya 88) ayetini işitmediniz mi?\" diye cevap vermiştir\" lafzı yer almaktadır. İbn Ebi'd-Dünya el-Ferec ba'de'ş-şidde adlı eserinde şu rivayet i kaydetmektedir: \"Velid İbn Abdilmelik Osman İbn Hibban'a Hasan İbn Hasan'ı yakalayıp halkın önünde yüz celde vurmasını emretmiştir. Hasan yakalanıp huzura getirilince Ali İbn Hüseyn ayağa kalkıp \"Allah'ın seni kurtaracağı bir şeyler söyle\" demiştir. O da bu sözleri söylemiştir. Bunun üzerine Osman kafasını kaldırıp Hasan'a iftira atıldığını serbest bırakılmasını istemiştir. Emirü'l-mü'minıne durumu kendisinin arzedeceğini açıklamıştır\". Nesai ve Taberi'nin naklettiğine göre Abdullah İbn Ca'fer kızını evlendirdiği zaman başına bir iş geldiğinde \"Halim ve kerim olan Allah'tan başka ilah yoktur. Yüce arşın rabbi olan Allah'ı noksan sıfatlardan tenzih ederim. Alemlerin rabbi' olan Allah'a hamdolsun\" demesini öğütlemiştir. Hasan yukarıdaki sözleri söylediği zaman Haccac \"Ben seni öldürmek amacındaydım. Şimdi ise şundan şundan daha sevimli geliyorsun\" demiştir. Hatta bir rivayette \"ihtiyacın varsa söyle\" ilavesi yer almaktadır. Ebu Davud ve İbn Hibban'ın naklettiğine göre sıkıntı halinde \"Allahım! Rahmetini diliyorum. Bir bile beni kendime bırakma. Benim sıkıntımı gider. Senden başka ilah yoktur\" diye dua edilmesi gerektiği ifade edilmiştir", "id": "Telah menceritakan kepada kami [Musaddad] telah menceritakan kepada kami [Yahya] dari [Hisyam bin Abu Abdullah] dari [Qatadah] dari [Abu 'Aliyah] dari [Ibnu Abbas] bahwa Rasulullah shallallahu 'alaihi wasallam biasa berdo'a ketika dalam kesulitan, beliau mengucapkan: \"LAA ILAAHA ILLALLAHUL 'ADZIIM AL HALIIM LAA ILAAHA ILLALLAH RABBUL 'ARSYIL 'AZHIIM, LAA ILAAHA ILLALLAH RABBUS SAMAAWATI WA RABBUL ARDLI WA RABBUL ASRSYL KARIIM (Tiada Tuhan selain Allah Yang Maha Agung dan Maha Penyantun. Tiada Tuhan selain Allah, Tuhan Penguasa arasy yang agung. Tiada Tuhan selain Allah, Tuhan langit dan bumi serta Tuhan arasy yang mulia).\" Dan berkata [Wahb] telah menceritakan kepada kami [Syu'bah] dari [Qatadah] seperti itu"}}, "inv_tasbih": {"refs": [["bukhari", 6405]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ سُمَىٍّ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ‏.‏ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:Allah's Messenger (ﷺ) said, \"Whoever says, 'Subhan Allah wa bihamdihi,' one hundred times a day, will be forgiven all his sins even if they were as much as the foam of the sea", "fr": "Rapporté par Abu Huraira : Le Messager d’Allah ﷺ a dit : « Celui qui dit ‘Subhan Allah wa bihamdihi’ cent fois par jour verra tous ses péchés pardonnés, même s’ils étaient aussi nombreux que l’écume de la mer. »", "id": "Telah menceritakan kepada kami [Abdullah bin Maslamah] dari [Malik] dari [Sumay] dari [Abu Shalih] dari [Abu Hurairah] radliallahu 'anhu bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Barangsiapa mengucapkan 'Subhanallah wabihamdihi Maha suci Allah dan segala pujian hanya untuk-Nya' sehari seratus kali, maka kesalahan-kesalahannya akan terampuni walaupun sebanyak buih di lautan", "tr": "Ebu Hureyre'den nakledildiğine göre Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Günde yüz defa tesbih edenlerin deniz köpüğü kadar bile olsa günahları bağışlanır"}}, "inv_yunus": {"refs": [["tirmidhi", 3505]], "txt": {"en": "Ibrahim bin Muhammad bin Sa`d narrated from his father, from Sa`d that the Messenger of Allah (ﷺ) said:“The supplication of Dhun-Nun (Prophet Yunus) when he supplicated, while in the belly of the whale was: ‘There is none worthy of worship except You, Glory to You, Indeed, I have been of the transgressors. (Lā ilāha illā anta subḥānaka innī kuntu minaẓ-ẓālimīn)’ So indeed, no Muslim man supplicates with it for anything, ever, except Allah responds to him.”", "tr": "Sa’d b. ebî Vakkâs (r.a.)’den rivâyete göre, Rasûlullah (Sallallahu aleyhi ve Sellem) şöyle buyurdu: “Yunus’un balığın karnında iken yaptığı duâ olan: ‘’La ilahe illa ente sübhaneke inni kuntu mine’z-zalimin’’ (Enbiya: 87) Bu duâyı herhangi konuda yaparsa Allah onun duâsını mutlaka kabul eder.” Diğer tahric: Müsned: 1383; Beyhaki, şuab Muhammed b. Yahya diyor ki: Muhammed b. Yusuf b. Mürre b. İbrahim b. Muhammed b. Sa’d bu hadisi Sa’d b. ebî Vakkâs’tan rivâyet etmiş olup “Âişe’den” dememiştir. Tirmizî: Başkaları bu hadisi Yunus b. ebî İshâk’tan, İbrahim b. Muhammed b. Sa’d’den ve Sa’d b. ebî Vakkâs’tan rivâyet etmişler ve senedinde “babasından” dememişlerdir. Bazıları ise Yunus b. İshâk’tan rivâyet ederek şöyle demişlerdir: “İbrahim b. Muhammed b. Sa’d, babasından ve Sa’d b. ebî Vakkâs’tan rivâyet etmişlerdir.” Yunus b. ebî İshâk ise bazen hadisin senedinden “babasından” demekte bazen da dememektedir", "ar": "حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا يُونُسُ بْنُ أَبِي إِسْحَاقَ، عَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، عَنْ سَعْدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ ‏.‏ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلاَّ اسْتَجَابَ اللَّهُ لَهُ ‏\"‏ ‏.‏ قَالَ مُحَمَّدُ بْنُ يَحْيَى قَالَ مُحَمَّدُ بْنُ يُوسُفَ مَرَّةً عَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ سَعْدٍ، ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى غَيْرُ، وَاحِدٍ، هَذَا الْحَدِيثَ عَنْ يُونُسَ بْنِ أَبِي إِسْحَاقَ، عَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ سَعْدٍ، وَلَمْ يَذْكُرُوا فِيهِ عَنْ أَبِيهِ، ‏.‏ وَرَوَى بَعْضُهُمْ، عَنْ يُونُسَ بْنِ أَبِي إِسْحَاقَ، فَقَالُوا عَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، عَنْ سَعْدٍ، وَكَانَ، يُونُسُ بْنُ أَبِي إِسْحَاقَ رُبَّمَا ذَكَرَ فِي هَذَا الْحَدِيثِ عَنْ أَبِيهِ، وَرُبَّمَا، لَمْ يَذْكُرْهُ ‏.‏"}}, "sav_chemin": {"refs": [["muslim", 2699]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ، وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ وَمُحَمَّدُ بْنُ الْعَلاَءِ الْهَمْدَانِيُّ - وَاللَّفْظُ لِيَحْيَى - قَالَ يَحْيَى أَخْبَرَنَا وَقَالَ الآخَرَانِ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلاَّ نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ وَغَشِيَتْهُمُ الرَّحْمَةُ وَحَفَّتْهُمُ الْمَلاَئِكَةُ وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ ‏\"‏ ‏.‏", "en": "Abu Huraira reported Allah's Messenger (ﷺ) as saying:He who alleviates the suffering of a brother out of the sufferings of the world, Allah would alleviate his suffering from the sufferings of the Day of Resurrection, and he who finds relief for one who is hard-pressed, Allah would make things easy for him in the Hereafter, and he who conceals (the faults) of a Muslim, Allah would conceal his faults in the world and in the Hereafter. Allah is at the back of a servant so long as the servant is at the back of his brother, and he who treads the path in search of knowledge, Allah would make that path easy, leading to Paradise for him and those persons who assemble in the house among the houses of Allah (mosques) and recite the Book of Allah and they learn and teach the Qur'an (among themselves) there would descend upon them tranquility and mercy would cover them and the angels would surround them and Allah mentions them in the presence of those near Him, and he who is slow-paced in doing good deeds, his (high) lineage does not make him go ahead", "id": "Telah menceritakan kepada kami [Yahya bin Yahya At Tamimi] dan [Abu Bakr bin Abu Syaibah] dan [Muhammad bin Al 'Ala Al Hamdani] -dan lafadh ini milik Yahya- dia berkata; telah mengabarkan kepada kami, dan berkata yang lainnya, telah menceritakan kepada kami [Abu Mu'awiyah] dari [Al A'masy] dari [Abu Shalih] dari [Abu Hurairah] dia berkata; Rasulullah shallallahu 'alaihi wasallam telah bersabda: 'Barang siapa membebaskan seorang mukmin dari suatu kesulitan dunia, maka Allah akan membebaskannya dari suatu kesulitan pada hari kiamat. Barang siapa memberi kemudahan kepada orang yang berada dalam kesulitan, maka Allah akan memberikan kemudahan di dunia dan akhirat. Barang siapa menutupi aib seorang muslim, maka Allah akan menutup aibnya di dunia dan akhirat. Allah akan selalu menolong hamba-Nya selama hamba tersebut menolong saudaranya sesama muslim. Barang siapa menempuh jalan untuk mencari ilmu, maka Allah akan memudahkan jalan ke surga baginya. Tidaklah sekelompok orang berkumpul di suatu masjid (rumah Allah) untuk membaca Al Qur'an, melainkan mereka akan diliputi ketenangan, rahmat, dan dikelilingi para malaikat, serta Allah akan menyebut-nyebut mereka pada malaikat-malaikat yang berada di sisi-Nya. Barang siapa yang ketinggalan amalnya, maka nasabnya tidak juga meninggikannya.' Telah menceritakan kepada kami [Muhammad bin 'Abdullah bin Numair] telah menceritakan kepada kami [Bapakku] Demikian juga diriwayatkan dari jalur lainnya, dan telah menceritakannya kepada kami [Nashr bin 'Ali Al Jahdhami] telah menceritakan kepada kami [Abu Usamah] mereka berkata; telah menceritakan kepada kami [Al A'masy] -telah menceritakan kepada kami Ibnu Numair- dari [Abu Shalih]. Sebagaimana di dalam hadits Abu Usamah Telah menceritakan kepada kami Abu Shalih dari [Abu Hurairah] dia berkata; Rasulullah shallallahu 'alaihi wasallam berkata dengan lantang, -sebagaimana Hadits Abu Mu'awiyah, hanya saja di dalam Hadits Abu Usamah tidak disebutkan; memberi kemudahan kepada orang yang kesusahan", "tr": "Bize Yahya b. Yahya Et-Temîmî ile Ebû Bekr b. Ebî Şeybe ve Muhammed b. Ala' El-Hemdani rivayet ettiler. Lafız Yahya'nındir. (Yahya: Ahberana; ötekilerse: Haddesena tabirlerim kullandılar. Dedilerki): Bize Ebû Muaviyc, A'meş'den, o da Ebu Salih'den, o da Ebu Hureyre'den naklen rivayet elti. (Şöyle demiş): Resulullah (Sallalluhu Aleyhi ve Sellem): «Bir kimse bir mu'minden dünya sıkıntılarından bir sıkıntı giderirse; Allah ondan ahiret stkınrilanndan bir sıkıntı giderir. Bir kimse başı sıkılana kolaylık gösterirse, Allah ona dünya ve ahirette kolaylık verir. Ve bir kimse bir müslümanı (n günahını) örtbas ederse, Allah da onu dünya ve ahirette örtbas eder. Kul din kardeşinin yardımında oldukça, Allah da kulun yardımındadır. Ve her kim bir yol tutarak, o yolda ilim ararsa, bu sebeple Allah ona cennete götüren bir yol müyesser kılar. Bir kavim Allah'ın evlerinden bir evde toplanarak kitabullahı okurlar ve onu aralarında müzakere ederlerse; üzerlerine sekinet iner. Allah'ın rahmeti onları kaplar. Melekler de etraflarını kuşatırlar. Allah onları kendi nezdindekilere anar. Bir kimseyi ameli yavaşlatırsa, nesebi hızlandıramaz.» buyurdular", "fr": "Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Celui qui soulage un frère d’une difficulté de ce monde, Allah le soulagera d’une difficulté du Jour de la Résurrection. Celui qui vient en aide à une personne en difficulté, Allah lui facilitera les choses dans l’au-delà. Celui qui couvre les défauts d’un musulman, Allah couvrira ses défauts dans ce monde et dans l’au-delà. Allah aide le serviteur tant que celui-ci aide son frère. Celui qui emprunte un chemin pour rechercher la connaissance, Allah lui facilitera un chemin vers le Paradis. Quand des gens se réunissent dans une des maisons d’Allah (les mosquées) pour réciter le Livre d’Allah, l’étudier et l’enseigner entre eux, la tranquillité descend sur eux, la miséricorde les couvre, les anges les entourent et Allah les mentionne auprès de ceux qui sont auprès de Lui. Et celui qui tarde à faire de bonnes actions, sa noble lignée ne le fera pas avancer. »"}}, "sav_trois": {"refs": [["muslim", 1631]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ، - يَعْنِي ابْنَ سَعِيدٍ - وَابْنُ حُجْرٍ قَالُوا حَدَّثَنَا إِسْمَاعِيلُ، - هُوَ ابْنُ جَعْفَرٍ - عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ إِلاَّ مِنْ صَدَقَةٍ جَارِيَةٍ أَوْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ ‏\"‏ ‏.‏", "en": "Abu Huraira (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying:When a man dies, his acts come to an end, but three, recurring charity, or knowledge (by which people) benefit, or a pious son, who prays for him (for the deceased)", "fr": "Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Quand une personne meurt, ses actions s’arrêtent, sauf pour trois choses : une aumône continue, un savoir dont les gens profitent, ou un enfant pieux qui prie pour lui (le défunt). »", "id": "Telah menceritakan kepada kami [Yahya bin Ayyub] dan [Qutaibah] -yaitu Ibnu Sa'id- dan [Ibnu Hujr] mereka berkata; telah menceritakan kepada kami [Isma'il] -yaitu Ibnu Ja'far- dari [Al 'Ala'] dari [Ayahnya] dari [Abu Hurairah], bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Apabila salah seorang manusia meninggal dunia, maka terputuslah segala amalannya kecuali tiga perkara; sedekah jariyah, ilmu yang bermanfa'at baginya dan anak shalih yang selalu mendoakannya", "tr": "Bize Yahya b. Eyyub ile Kuteybe yani İbni Saîd ve İbni Hucr rivayet ettiler. (Dedilerki): Bize İsmail —ki İbni Ca'fer'dir— Ala'dan, o da babasından, o da Ebu Hureyre'den naklen rivayet ettiki, Reulullah (Sallallahu Aleyhi ve Sellem): «İnsan öldüğü vakit bütün amelleri ondan kesilir. Yalnız üç şeyden: sadaka-i cariyeden, faydalanılan ilimden ve kendisine dua eden salih evladdan kesilmez.» buyurmuşlar"}}, "sav_fiqh": {"refs": [["bukhari", 71], ["muslim", 1037]], "txt": {"ar": "حَدَّثَنَا سَعِيدُ بْنُ عُفَيْرٍ، قَالَ حَدَّثَنَا ابْنُ وَهْبٍ، عَنْ يُونُسَ، عَنِ ابْنِ شِهَابٍ، قَالَ قَالَ حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ سَمِعْتُ مُعَاوِيَةَ، خَطِيبًا يَقُولُ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ، وَإِنَّمَا أَنَا قَاسِمٌ وَاللَّهُ يُعْطِي، وَلَنْ تَزَالَ هَذِهِ الأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللَّهِ لاَ يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ ‏\"‏‏.‏", "en": "Narrated Muawiya:I heard Allah's Messenger (ﷺ) saying, \"If Allah wants to do good to a person, He makes him comprehend the religion. I am just a distributor, but the grant is from Allah. (And remember) that this nation (true Muslims) will keep on following Allah's teachings strictly and they will not be harmed by any one going on a different path till Allah's order (Day of Judgment) is established", "id": "Telah menceritakan kepada kami [Sa'id bin 'Ufair] Telah menceritakan kepada kami [Ibnu Wahab] dari [Yunus] dari [Ibnu Syihab] berkata, [Humaid bin Abdurrahman] berkata; aku mendengar [Mu'awiyyah] memberi khutbah untuk kami, dia berkata; Aku mendengar Nabi shallallahu 'alaihi wasallam bersabda: \"Barangsiapa yang Allah kehendaki menjadi baik maka Allah faqihkan dia terhadap agama. Aku hanyalah yang membagi-bagikan sedang Allah yang memberi. Dan senantiasa ummat ini akan tegak diatas perintah Allah, mereka tidak akan celaka karena adanya orang-orang yang menyelisihi mereka hingga datang keputusan Allah", "tr": "Muaviye r.a. şöyle demiştir: Nebi Sallallahu Aleyhi ve Sellem’in şöyle dediğini işittim: \"Allah kimin için hayır dilerse onu dinde fakih (anlayış sahibi) kılar. Ben yalnızca taksim eden bir kişiyim, veren Allah'tır. Allah'ın emri gelinceye (kıyamet kopuncaya) kadar bu ümmet Allah'ın emri üzere kalacak, muhalefet edenler onlara zarar veremeyeceklerdir. Tekrar: 3116, 3641, 7312, 7460 Diğer tahric: Muhtelif raviler ve az farklarla Buhari, ilim; Müslim, zekat; İbn-i Mace, mukaddime; Dârimî, Mukaddime", "fr": "Rapporté par Muawiya : J’ai entendu le Messager d’Allah (ﷺ) dire : « Si Allah veut du bien à une personne, Il lui fait comprendre la religion. Je ne fais que distribuer, mais le don vient d’Allah. (Et souvenez-vous) que cette communauté (les vrais musulmans) continuera à suivre strictement les enseignements d’Allah et ils ne seront pas blessés par ceux qui prennent un autre chemin jusqu’à ce que l’ordre d’Allah (le Jour du Jugement) soit établi. »"}}, "sav_coran": {"refs": [["bukhari", 5027]], "txt": {"en": "Narrated `Uthman:The Prophet (ﷺ) said, \"The best among you (Muslims) are those who learn the Qur'an and teach it", "fr": "Rapporté par `Uthman : Le Prophète (ﷺ) a dit : « Les meilleurs parmi vous sont ceux qui apprennent le Coran et l’enseignent. »", "id": "Telah menceritakan kepada kami [Hajjaj bin Minhal] Telah menceritakan kepada kami [Syu'bah] ia berkata, Telah mengabarkan kepadaku ['Alqamah bin Martsad] Aku mendengar [Sa'd bin Ubaidah] dari [Abu Abdurrahman As Sulami] dari [Utsman] radliallahu 'anhu, dari Nabi shallallahu 'alaihi wasallam, beliau bersabda: \"Orang yang paling baik di antara kalian adalah seorang yang belajar Al Qur`an dan mengajarkannya.\" Abu Abdirrahman membacakan (Al Qur`an) pada masa Utsman hingga Hajjaj pun berkata, \"Dan hal itulah yang menjadikanku duduk di tempat dudukku ini", "tr": "Osman radiyallahu anh'dan Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu rivayet edilmiştir: \"Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.\" Sa 'd İbn Ubeyde şöyle dedi: Hz. Osman döneminde Ebu Abdurrahman Müslümanlara Kur'an öğretti. Haccac dönemine kadar da bu faaliyetini sürdürdü. Bu konuda şöyle demiştir: \"Kur'an'ın faziletine ilişkin nakledilen hadis, benim buraya oturup Kur'an öğretmeme vesile oldu.\" Diğer tahric edenler: Tirmizî, Fedail-ül Kur’ân; İbn Mâce,i Mukaddime", "ar": "حَدَّثَنَا حَجَّاجُ بْنُ مِنْهَالٍ، حَدَّثَنَا شُعْبَةُ، قَالَ أَخْبَرَنِي عَلْقَمَةُ بْنُ مَرْثَدٍ، سَمِعْتُ سَعْدَ بْنَ عُبَيْدَةَ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ عُثْمَانَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ ‏\"‏‏.‏ قَالَ وَأَقْرَأَ أَبُو عَبْدِ الرَّحْمَنِ فِي إِمْرَةِ عُثْمَانَ حَتَّى كَانَ الْحَجَّاجُ، قَالَ وَذَاكَ الَّذِي أَقْعَدَنِي مَقْعَدِي هَذَا‏.‏"}}, "sav_indiquer": {"refs": [["muslim", 1893]], "txt": {"ar": "وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ وَابْنُ أَبِي عُمَرَ - وَاللَّفْظُ لأَبِي كُرَيْبٍ - قَالُوا حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي عَمْرٍو الشَّيْبَانِيِّ، عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنِّي أُبْدِعَ بِي فَاحْمِلْنِي فَقَالَ ‏\"‏ مَا عِنْدِي ‏\"‏ ‏.‏ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏\"‏ ‏.‏", "en": "It has been narrated on the authority of Abu Mas'ud al-Ansari who said:A man came to the Messenger of Allah (ﷺ) and said: My riding beast has been killed, so give me some animal to ride upon. He (the Holy Prophet) said: I have none with me. A man said: Messenger of Allah, I can guide him to one who will provide him with a riding beast. The Messenger of Allah (ﷺ) said: One who guides to something good has a reward similar to that of its doer", "fr": "Rapporté par Abu Mas'ud al-Ansari رضي الله عنه : Un homme est venu voir le Messager d’Allah ﷺ et a dit : « Ma monture a été tuée, donne-moi un animal pour me déplacer. » Le Prophète ﷺ répondit : « Je n’en ai pas. » Un autre homme dit : « Messager d’Allah, je peux l’orienter vers quelqu’un qui pourra lui fournir une monture. » Le Messager d’Allah ﷺ dit : « Celui qui guide vers une bonne action aura une récompense semblable à celle de celui qui l’accomplit. »", "id": "Telah menceritakan kepada kami [Abu Bakar bin Abu Syaibah] dan [Abu Kuraib] dan [Ibnu Abu Umar] dan ini adalah lafadz Abu Kuraib, mereka berkata; telah menceritakan kepada kami [Abu Mu'awiyah] dari [Al A'masy] dari [Abu 'Amru As Syaibani] dari [Abu Mas'ud Al Anshari] dia berkata, \"Seorang laki-laki datang kepada Nabi shallallahu 'alaihi wasallam seraya berkata, \"Wahai Rasulullah, jalan kami telah terputus karena hewan tungganganku telah mati, oleh karena itu bawalah saya dengan hewan tunggangan yang lain.\" Maka beliau bersabda: \"Saya tidak memiliki (hewan tunggangan yang lain).\" Tiba-tiba ada seorang laki-laki yang berkata, \"Wahai Rasulullah, saya dapat menunjukkan seseorang yang dapat membawanya (memperoleh penggantinya).\" Maka beliau bersabda: \"Barangsiapa dapat menunjukkan suatu kebaikan, maka dia akan mendapatkan pahala seperti orang yang melakukannya.\" Dan telah menceritakan kepada kami [Ishaq bin Ibrahim] telah mengabarkan kepada kami [Isa bin Yunus]. (dalam jalur lain disebutkan) Telah menceritakan kepadaku [Bisyr bin Khalid] telah mengabarkan kepada kami [Muhammad bin Ja'far] dari [Syu'bah]. (dalam jalur lain disebutkan) Telah menceritakan kepadaku [Muhammad bin Rafi'] telah menceritakan kepada kami [Abdurrazaq] telah mengabarkan kepada kami [Sufyan] semuanya dari [Al A'masy] dengan sanad ini", "tr": "Bize Ebû Bekir b. Ebî Şeybe ile Ebû Kureyb ve İbnİ Ebî Ömer rivayet ettiler. Lâfız Ebû Kureyb'indir. (Dedilerki): Bize Ebû Muâviye, A'meş'den, o da Ebû Amr Eş-Şeybânî'den, o da Ebû Mes'ûd El-Ensârî'den naklen rivayet etti. Şöyle demiş: Bir adam Nebi (Sallalldhu Aleyhi ve Sellem)'e gelerek: Benim hayvanım helak oldu; bana bir binek hayvanı ver! Dedi. Efendimiz: «Bende yok!» buyurdu. Bunun üzerine bir adam : — Yâ Resûlâllah! Ben ona binek hayvanı verecek kimseyi gösteririm! Dedi. Resûlullah (Sallalldhu Aleyhi ve Sellem) «Her kim bir hayra delâlet ederse ona da hayrı yapanın ecri kadar ecir verilir.» buyurdular"}}, "sav_appeler": {"refs": [["muslim", 2674]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، وَابْنُ، حُجْرٍ قَالُوا حَدَّثَنَا إِسْمَاعِيلُ، - يَعْنُونَ ابْنَ جَعْفَرٍ - عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لاَ يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا وَمَنْ دَعَا إِلَى ضَلاَلَةٍ كَانَ عَلَيْهِ مِنَ الإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لاَ يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا ‏\"‏ ‏.‏", "en": "Abu Huraira reported Allah's Messenger (ﷺ) as saying:He who called (people) to righteousness, there would be reward (assured) for him like the rewards of those who adhered to it, without their rewards being diminished in any respect. And he who called (people) to error, he shall have to carry (the burden) of its sin, like those who committed it, without their sins being diminished in any respect", "fr": "Rapporté par Abu Huraira : Le Messager d’Allah ﷺ a dit : « Celui qui appelle les gens à la droiture aura une récompense égale à celle de ceux qui la suivent, sans que cela ne diminue leur récompense. Et celui qui appelle à l’égarement portera le fardeau de son péché et de celui de ceux qui le suivent, sans que cela ne diminue leur fardeau. »", "id": "Telah menceritakan kepada kami [Yahya bin Ayyub] dan [Qutaibah bin Sa'id] dan [Ibnu Hujr], mereka berkata; telah menceritakan kepada kami [Isma'il] yaitu Ibnu Ja'far dari [Al 'Ala] dari [bapaknya] dari [Abu Hurairah] bahwasanya Rasulullah shallallahu 'alaihi wasallam telah bersabda: \"Barang siapa mengajak kepada kebaikan, maka ia akan mendapat pahala sebanyak pahala yang diperoleh orang-orang yang mengikutinya tanpa mengurangi pahala mereka sedikitpun. Sebaliknya, barang siapa mengajak kepada kesesatan, maka ia akan mendapat dosa sebanyak yang diperoleh orang-orang yang mengikutinya tanpa mengurangi dosa mereka sedikitpun", "tr": "Bize Yahya b. Eyyûb ile Kuteybe b. Saîd ve İbni Hucr rivayet ettiler. (Dedilerki): Bize İsmail yâni İbni Ca'fer Alâ'dan, o da babasından, o da Ebû Hureyre'den naklen rivayet ettiki: Resûlullah (Sallallahu Aleyhi ve Sellem): «Bir kimse doğru bîr yola da'vet ederse, ona tâbi olanların ecirleri kadar kendisi için ecir olur. Bu, tâbi olanların ecrinden bir şey eksiltmez. Ve her kim bir dalâlete davel ederse, ona tâbi olanların günahları kadar kendine günah olur. Bu, tâbi olanların günahlarından hiç bir şey eksiltmez.» buyurdular"}}, "noms99": {"refs": [["bukhari", 2736], ["muslim", 2677]], "txt": {"ar": "حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمَا مِائَةً إِلاَّ وَاحِدًا مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:Allah's Messenger (ﷺ) said, \"Allah has ninety-nine names, i.e. one-hundred minus one, and whoever knows them will go to Paradise.\" (Please see Hadith No. 419 Vol)", "fr": "Rapporté par Abu Huraira : Le Messager d’Allah (ﷺ) a dit : « Allah a quatre-vingt-dix-neuf noms, soit cent moins un, et celui qui les connaît entrera au Paradis. » (Voir aussi le hadith n°419, volume)", "id": "Telah bercerita kepada kami [Abu Al Yaman] telah mengabarkan kepada kami [Syu'aib] telah bercerita kepada kami [Abu Az Zanad] dari [Al A'raj] dari [Abu Hurairah radliallahu 'anhu] bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Sesungguhnya Allah memiliki sembilan puluh sembilan nama, seratus kurang satu. Siapa yang menghitungnya (menjaganya) maka dia akan masuk surga", "tr": "Bize Ebu'z-Zinâd, el-A'rac'dan; o da Ebû Hureyre (radıyallahü anh)'den tahdîs etti ki, Rasûlüllah (sallallahü aleyhi ve sellem): \"Allah'ın yüzden bir eksik olarak doksan dokuz ismi vardır. Bu isimleri kim (tamamen) sayarsa cennete girer\" buyurmuştur"}}, "anges_lumiere": {"refs": [["muslim", 2996]], "txt": {"ar": "حَدَّثَنَا مُحَمَّدُ بْنُ رَافِعٍ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالَ عَبْدٌ أَخْبَرَنَا وَقَالَ ابْنُ رَافِعٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ خُلِقَتِ الْمَلاَئِكَةُ مِنْ نُورٍ وَخُلِقَ الْجَانُّ مِنْ مَارِجٍ مِنْ نَارٍ وَخُلِقَ آدَمُ مِمَّا وُصِفَ لَكُمْ ‏\"‏ ‏.‏", "en": "A'isha reported that Allah's Messenger (ﷺ) said:The Angels were born out of light and the Jinns were born out of the spark of fire and Adam was born as he has been defined (in the Qur'an) for you (i. e. he is fashioned out of clay)", "id": "Telah menceritakan kepada kami [Muhammad bin Rafi'] dan [Abdu bin Humaid], berkata Abdu: Telah mengkhabarkan kepada kami, sedangkan Ibnu Rafi' berkata: Telah menceritakan kepada kami [Abdurrazzaq] telah mengkhabarkan kepada kami [Ma'mar] dari [Az Zuhri] dari [Urwah] dari [Aisyah] berkata: Rasulullah Shallallahu 'alaihi wa Salam bersabda: \"Malaikat diciptakan dari cahaya, jin diciptakan dari api yang menyala-nyala dan Adam diciptakan dari sesuatu yang telah disebutkan (ciri-cirinya) untuk kalian", "tr": "Bize Muhammed b. Râfi' ile Abd b. Humeyd rivayet ettiler. Abd Ahberanâ dedi, ibni Râfi' ise Haddesenâ tâbirini kullandı. (Dediki): Bize Abdûrrezzâk rivayet etti. (Dediki): Bize Ma'mer Zührî'den, o da Urve'den, o da Âişe'den naklen haber verdi. (Şöyle demiş): Resulullah {Sallallahu Aleyhi ve Sellem) : «Melekler nurdan yaratıldı. Cinler dumanlı alevden, ateşden yaratıldılar. Âdem ise size anlatılandan yaratıldı.» buyurdular. izah: Mâric: Ateşin siyahiyle karışmış alev demektir. Müslim şarihlerinden Übbî bunu dumanla karışık alev diye ta'rif etmiştir. Meleklerle cinlerin birbirlerinden farkları tâ hilkatlerinden başlar. Görülüyor ki, biri nurdan, diğeri dumanlı alevden yaratılmıştır. Bunlar insana görünmemek hususunda birleşirlerse de, meleklerin masum cinlerin mükellef olması meleklerde yiyip içmek, evlenmek ve doğup ölmek gibi şeyler olmadığı halde, cinlerde bunların bulunması, cinlerin yerde yaşamaları gibi, birçok hususatta aralarında büyük farklar vardır. Resûlullah (Sallallahu Aleyhi ve Sellem) : «Adem de size anlatılan şeyden yaratılmıştır.» buyurmakla, onun topraktan halkedildiğine işaret etmiştir", "fr": "Rapporté par Aïsha رضي الله عنها : Le Messager d’Allah ﷺ a dit : « Les Anges ont été créés de lumière, les djinns ont été créés d’une flamme de feu, et Adam a été créé comme cela a été décrit pour vous (c’est-à-dire à partir d’argile). »"}}, "mere": {"refs": [["bukhari", 5971], ["muslim", 2548]], "txt": {"ar": "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا جَرِيرٌ، عَنْ عُمَارَةَ بْنِ الْقَعْقَاعِ بْنِ شُبْرُمَةَ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ مَنْ أَحَقُّ بِحُسْنِ صَحَابَتِي قَالَ ‏\"‏ أُمُّكَ ‏\"‏‏.‏ قَالَ ثُمَّ مَنْ قَالَ ‏\"‏ أُمُّكَ ‏\"‏‏.‏ قَالَ ثُمَّ مَنْ قَالَ ‏\"‏ أُمُّكَ ‏\"‏‏.‏ قَالَ ثُمَّ مَنْ قَالَ ‏\"‏ ثُمَّ أَبُوكَ ‏\"‏‏.‏ وَقَالَ ابْنُ شُبْرُمَةَ وَيَحْيَى بْنُ أَيُّوبَ حَدَّثَنَا أَبُو زُرْعَةَ مِثْلَهُ‏.‏", "en": "Narrated Abu Huraira:A man came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! Who is more entitled to be treated with the best companionship by me?\" The Prophet (ﷺ) said, \"Your mother.\" The man said. \"Who is next?\" The Prophet said, \"Your mother.\" The man further said, \"Who is next?\" The Prophet (ﷺ) said, \"Your mother.\" The man asked for the fourth time, \"Who is next?\" The Prophet (ﷺ) said, \"Your father", "fr": "Rapporté par Abu Huraira : Un homme est venu voir le Messager d’Allah (ﷺ) et a dit : « Ô Messager d’Allah (ﷺ) ! Qui mérite le plus que je lui tienne la meilleure compagnie ? » Le Prophète (ﷺ) a répondu : « Ta mère. » L’homme a demandé : « Et ensuite ? » Le Prophète a dit : « Ta mère. » L’homme a insisté : « Et ensuite ? » Le Prophète (ﷺ) a dit : « Ta mère. » L’homme a demandé une quatrième fois : « Et ensuite ? » Le Prophète (ﷺ) a dit : « Ton père. »", "id": "Telah menceritakan kepada kami [Qutaibah bin Sa'id] telah menceritakan kepada kami [Jarir] dari ['Umarah bin Al Qa'qa' bin Syubrumah] dari [Abu Zur'ah] dari [Abu Hurairah] radliallahu 'anhu dia berkata; \"Seorang laki-laki datang kepada Rasulullah shallallahu 'alaihi wasallam sambil berkata; \"Wahai Rasulullah, siapakah orang yang paling berhak aku berbakti kepadanya?\" beliau menjawab: \"Ibumu.\" Dia bertanya lagi; \"Kemudian siapa?\" beliau menjawab: \"Ibumu.\" Dia bertanya lagi; \"kemudian siapa lagi?\" beliau menjawab: \"Ibumu.\" Dia bertanya lagi; \"Kemudian siapa?\" dia menjawab: \"Kemudian ayahmu.\" [Ibnu Syubrumah] dan [Yahya bin Ayyub] berkata; telah menceritakan kepada kami [Abu Zur'ah] hadits seperti di atas", "tr": "Ebu Hureyre r.a.'dan, dedi ki: \"Bir adam Resulullah Sallallahu Aleyhi ve Sellem'e gelerek: Ey Allah'ın Rasulü' Benim güzel sohbetime (arkadaşlığıma, dostluğuma) en fazla hak sahibi olan kimdir, diye sordu. Allah Rasulü: Annendir, buyurdu. Adam: Sonra kimdir, diye sordu. Allah Rasulü: Annendir, buyurdu. Adam: Sonra kimdir, diye sordu. Allah Rasulü: Annendir, buyurdu. Adam: Sonra kimdir, diye sordu. Allah Rasulü: Sonra babandır, buyurdu.\" Fethu'l-Bari Açıklaması: İbn Battal dedi ki: Bu hadisin gereğine göre annenin görmeyi hak ettiği iyilik, babanın üç mislidir. Bu ise hamileliğin, sonra doğumun, sonra da süt emzirmenin zorluğundan dolayıdır. Bütün bunları yalnız başına anne yapar ve onlardan dolayı oldukça zorlanır. Bundan sonra da çocuğun terbiyesinde baba ile ortak hareket eder. İşte yüce Allah'ın: \"Biz insana ana-babasına iyilikte bulunmasını tavsiye ettik. Annesi onu zorlukla taşımış, zorlukla bırakmıştır. Onun taşınması ve sütten kesilmesi de iki yılda olur. \"(Lukman, 14) buyruğunda da buna işaret edilmektedir. Bu buyrukta her ikisine iyi davranmanın tavsiye edilmesi bakımından aralarında eşitlik sözkonusu iken, diğer üç husus sadece anne hakkında sözkonusu edilmiştir. Kurtubi der ki: Maksat annenin çocuğu üzerindeki kendisine iyi davranma hakkının daha üstün bir derecede olduğunu ve bu hususta haklar arasında bir çatışma bulunacak olursa, annenin hakkının babanın hakkına önceleneceğini anlatmaktır. İyad dedi ki: Cumhurun kanaatine göreanne iyi muamele konusunda babadan daha üstün bir hakka sahiptir. Her ikisine de eşit bir şekilde iyi davranılacağı da söylenmiştir. Bazıları bu görüşü Malik'ten diye nakletmiştir ama doğru olanı birincisidir. Derim ki: Bazı Şafii alimleri ikinci görüşü benimsemiştir, ama el-Haris elMuhasibi iyilikte annenin üstün tutulacağı hususunda icma' bulunduğunu nakletmiştir, ama böyle bir nakil tartışılır. Malik'ten yapılan nakil de bu hususta açık değildir. Bunu İbn Battal zikrederek şöyle demiştir: Malik'e: Babam benden istedi, annem de benden aksini yapmamı istedi, diye soruldu. Malik: Babana itaat et, annene de karşı çıkma, diye cevap verdi. İbn Battal dedi ki: Bu onun her ikisine de iyi davranmanın eşit düzeyde olduğunu göstermektedir, demiştir. Evet, o böyle demiştir, ama buna delaleti pek açık değildir. İbn Battal dedi ki: el-leys'e de aynı mesele sorulmuş, kendisi: Annene itaat et. Çünkü iyiliğin üçte iki payı onundur, diye cevap vermiştir. İyad dedi ki: Bazı ilim adamları dede ve kardeş hususunda tereddüde düşmüşlerdir. Çoğunluk dedenin önceleneceği kanaatindedir. Derim ki: Şafiiler de bunu kesin bir ifade olarak zikretmiş ve: Önce dede, sonra kardeş gelir. Daha sonra aynı anne-baba ile akrabalığı olan kimse onlardan birisi vasıtası ile akrabalığı olanın önüne geçirilir. Sonra da zevi'l-erham olan akrabalar öncelenir. Bunlar arasında mahrem olanlar, mahrem olmayanlardan önce gelir, daha sonra diğer asabeler, sonra sıhri akrabalar, sonra vela bağı ile yakınlığı olanlar, sonra da komşular gelir, demişlerdir. ileride iyilik yapmanın hükmünedair açıklamalar gelecektir. İbn Battal bu sıralamanın, iyiliğin bir defada hepsine ulaştırılmasının imkansız olması halinde sözkonusu olacağına işaret etmiştir. Bu da açıkça anlaşılan bir konudur"}}, "parler_bien": {"refs": [["muslim", 47], ["bukhari", 6018]], "txt": {"ar": "حَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى، أَنْبَأَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ ‏\"‏ ‏.‏", "en": "It is reported on the authority of Abu Huraira that the Messenger of Allah (ﷺ) observed:He who believes in Allah and the Last Day should either utter good words or better keep silence; and he who believes in Allah and the Last Day should treat his neighbour with kindness and he who believes in Allah and the Last Day should show hospitality to his guest", "fr": "Rapporté par Abu Huraira رضي الله عنه : Le Messager d’Allah ﷺ a dit : « Celui qui croit en Allah et au Jour dernier, qu’il dise du bien ou qu’il se taise ; celui qui croit en Allah et au Jour dernier, qu’il soit bon envers son voisin ; et celui qui croit en Allah et au Jour dernier, qu’il soit hospitalier envers son invité. »", "id": "Telah menceritakan kepada kami [Harmalah bin Yahya] telah memberitakan kepada kami [Ibnu Wahab] dia berkata, telah mengabarkan kepadaku [Yunus] dari [Ibnu Syihab] dari [Abu Salamah bin Abdurrahman] dari [Abu Hurairah] dari Rasulullah shallallahu 'alaihi wasallam, beliau bersabda: \"Barangsiapa beriman kepada Allah dan hari akhir, maka hendaklah dia mengucapkan perkataan yang baik atau diam. Dan barangsiapa yang beriman kepada Allah dan hari akhir maka hendaklah dia memuliakan tetangganya. Dan barangsiapa beriman kepada Allah dan hari akhir maka hendaklah dia memuliakan tamunya", "tr": "Bana Harmeletü'bnü Yahya rivayet etti. (Dediki): Bize İbni Vehb anlattı. Dediki: Bana Yunus, İbni Şihab'dan, o da Ebu Selemete'bni Abdirrahman'dan, o da Ebu Hureyre'den, o da Resulullah (Sallallahu Aleyhi ve Sellem'den naklen haber verdi. ''Allah'a ve ahiret gününe iman eden bir kimse ya hayır söylesin yahut sussun. Allah'a ve ahiret gününe iman eden bir kimse komşusuna ikram etsin. Allah'a ve ahiret gününe iman eden bir kimse misafirine ikram etsin. \" Yalnız Müslim rivayet etmiştir; Tuhfetu'l-Eşraf, 15339 A.DAVUDOĞLU AÇIKLAMASI İÇİN bBURAYA TIKLA)"}}, "verite": {"refs": [["bukhari", 6094], ["muslim", 2607]], "txt": {"ar": "حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يَكُونَ صِدِّيقًا، وَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الرَّجُلَ لَيَكْذِبُ، حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا ‏\"‏‏.‏", "en": "Narrated `Abdullah:The Prophet (ﷺ) said, \"Truthfulness leads to righteousness, and righteousness leads to Paradise. And a man keeps on telling the truth until he becomes a truthful person. Falsehood leads to Al-Fajur (i.e. wickedness, evil-doing), and Al-Fajur (wickedness) leads to the (Hell) Fire, and a man may keep on telling lies till he is written before Allah, a liar", "fr": "Rapporté par `Abdullah : Le Prophète (ﷺ) a dit : « La véracité mène à la droiture, et la droiture mène au Paradis. Un homme continue à dire la vérité jusqu’à devenir quelqu’un de véridique. Le mensonge mène à la perversité, et la perversité mène au Feu (de l’Enfer). Un homme continue à mentir jusqu’à être inscrit auprès d’Allah comme menteur. »", "id": "Telah menceritakan kepada kami [Utsman bin Abu Syaibah] telah menceritakan kepada kami [Jarir] dari [Manshur] dari [Abu Wa`il] dari [Abdullah] radliallahu 'anhu dari Nabi shallallahu 'alaihi wasallam beliau bersabda: \"Sesungguhnya kejujuran akan membimbing pada kebaikan, dan kebaikan itu akan membimbing ke surga, sesungguhnya jika seseorang yang senantiasa berlaku jujur hingga ia akan dicatat sebagai orang yang jujur. Dan sesungguhnya kedustaan itu akan mengantarkan pada kejahatan, dan sesungguhnya kejahatan itu akan menggiring ke neraka. Dan sesungguhnya jika seseorang yang selalu berdusta sehingga akan dicatat baginya sebagai seorang pendusta", "tr": "Abdullah r.a.'dan rivayete göre; \"Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: Şüphesiz sıdk (doğruluk) birr (iyiliğ)e götürür. Şüphesiz birr de cennet'e götürür. Gerçek şu ki, kişi doğru söyleyip durdukça sonunda sıddik olur. Muhakkak yalan da fucur (günah)a götürür. fucur da ateşe götürür. Şüphe yok ki kişi yalan söyleyip durdukça sonunda Allah'ın yanında da kezzab (çok yalancı) diye yazılır.\" Diğer tahric edenler: Tirmizi Birr; Müslim, Birr"}}, "ghiba": {"refs": [["muslim", 2589]], "txt": {"ar": "حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ، وَابْنُ، حُجْرٍ قَالُوا حَدَّثَنَا إِسْمَاعِيلُ، عَنِ الْعَلاَءِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ أَتَدْرُونَ مَا الْغِيبَةُ ‏\"‏ ‏.‏ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏.‏ قَالَ ‏\"‏ ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ ‏\"‏ ‏.‏ قِيلَ أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ قَالَ ‏\"‏ إِنْ كَانَ فِيهِ مَا تَقُولُ فَقَدِ اغْتَبْتَهُ وَإِنْ لَمْ يَكُنْ فِيهِ فَقَدْ بَهَتَّهُ ‏\"‏ ‏.‏", "en": "Abu Huraira reported Allah's Messenger (ﷺ) as saying:Do you know what is backbiting? They (the Companions) said: Allah and His Messenger know best. Thereupon he (the Holy Prophet) said: Backbiting implies your talking about your brother in a manner which he does not like. It was said to him: What is your opinion about this that if I actually find (that failing) in my brother which I made a mention of? He said: If (that failing) is actually found (in him) what you assert, you in fact backbited him, and if that is not in him it is a slander", "id": "Telah menceritakan kepada kami [Yahya bin Ayyub] dan [Qutaibah] dan [Ibnu Hujr] mereka berkata; Telah menceritakan kepada kami [Isma'il] dari [Al A'laa] dari [Bapaknya] dari [Abu Hurairah] bahwa Rasulullah shallallahu 'alaihi wasallam pernah bertanya: \"Tahukah kamu, apakah ghibah itu?\" Para sahabat menjawab; 'Allah dan Rasul-Nya lebih tahu.' Kemudian Rasulullah shallallahu 'alaihi wasallam bersabda: 'Ghibah adalah kamu membicarakan saudaramu mengenai sesuatu yang tidak ia sukai.' Seseorang bertanya; 'Ya Rasulullah, bagaimanakah menurut engkau apabila orang yang saya bicarakan itu memang sesuai dengan yang saya ucapkan? ' Rasulullah shallallahu 'alaihi wasallam berkata: 'Apabila benar apa yang kamu bicarakan itu ada padanya, maka berarti kamu telah menggunjingnya. Dan apabila yang kamu bicarakan itu tidak ada padanya, maka berarti kamu telah membuat-buat kebohongan terhadapnya", "tr": "Bize Yahya b. Eyyûb ile Kuteybe ve İbni Hucr rivayet ettiler. (Dedilerki): Bize İsmail, Alâ'dan, o da babasından, o da Ebû Hureyre'den naklen rivayet etti ki, Resûlullah (Sallallahu Aleyhi ve Sellem): «Gıybet nedir bilir misiniz?» buyurmuş. Ashâb : — Allah ve Resulü bilir demişler. «Kardeşini hoşlanmadığı bir şeyle anmanehr.» buyurmuş, — Yâ kardeşimde benim söylediğim bulunursa, ne buyurursun? denilmiş. «Söylediğin onda varsa, onu gıybet ettin demektir. Eğar onda yoksa, ona bühtan etmiş olursun.» buyurmuşlar", "fr": "Rapporté par Abu Huraira : Le Messager d’Allah ﷺ a dit : « Savez-vous ce qu’est la médisance ? » Les Compagnons ont répondu : « Allah et Son Messager savent mieux. » Il a dit : « La médisance, c’est de parler de ton frère d’une manière qu’il n’aime pas. » On lui demanda : « Et si ce que je dis est vrai ? » Il répondit : « Si ce défaut est vraiment en lui, tu as médit de lui ; et s’il n’y est pas, tu l’as calomnié. »"}}, "voisin": {"refs": [["muslim", 2624], ["bukhari", 6014]], "txt": {"ar": "حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، عَنْ مَالِكِ بْنِ أَنَسٍ، ح وَحَدَّثَنَا قُتَيْبَةُ، وَمُحَمَّدُ بْنُ رُمْحٍ، عَنِ اللَّيْثِ بْنِ سَعْدٍ، ح وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَبْدَةُ، وَيَزِيدُ بْنُ هَارُونَ، كُلُّهُمْ عَنْ يَحْيَى بْنِ سَعِيدٍ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، - وَاللَّفْظُ لَهُ - حَدَّثَنَا عَبْدُ الْوَهَّابِ، - يَعْنِي الثَّقَفِيَّ - سَمِعْتُ يَحْيَى بْنَ سَعِيدٍ، أَخْبَرَنِي أَبُو بَكْرٍ، - وَهُوَ ابْنُ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ - أَنَّ عَمْرَةَ، حَدَّثَتْهُ أَنَّهَا، سَمِعَتْ عَائِشَةَ، تَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏ \"‏ مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ لَيُوَرِّثَنَّهُ ‏\"‏ ‏.‏", "en": "A'isha reported Allah's Messenger (ﷺ) as saying:Gabriel impressed upon me (kind treatment) towards the neighbour (so much) that I thought as if he would confer upon him the (right) of inheritance", "fr": "Rapporté par Aïcha رضي الله عنها : Le Messager d’Allah ﷺ a dit : « Gabriel m’a tellement recommandé de bien traiter le voisin que j’ai cru qu’il allait lui donner un droit d’héritage. »", "id": "Telah menceritakan kepada kami [Qutaibah bin Sa'id] dari [Malik bin Anas]; Demikian juga diriwayatkan dari jalur lainnya, Dan telah menceritakan kepada kami [Qutaibah] dan [Muhammad bin Rumh] dari [Al Laits bin Sa'ad]; Demikian juga diriwayatkan dari jalur lainnya, Dan telah menceritakan kepada kami [Abu Bakr bin Abu Syaibah]; Telah menceritakan kepada kami ['Abdah] dan [Yazid bin Harun] seluruhnya dari [Yahya bin Sa'id]; Demikian juga diriwayatkan dari jalur lainnya, Dan telah menceritakan kepada kami [Muhammad bin Al Mutsanna] lafazh ini miliknya; Telah menceritakan kepada kami ['Abdul Wahhab] yaitu Ats Tsaqafi; Aku mendengar [Yahya bin Sa'id]; Telah mengabarkan kepadaku [Abu Bakr] yaitu Ibnu Muhammad bin 'Amru bin Hazm bahwa ['Amrah] Telah menceritakan kepadanya, dia mendengar [Aisyah] berkata; \"Saya pernah mendengar RasuIullah shallallahu 'alaihi wasallam bersabda: 'Sesungguhnya Jibril terus-menerus berpesan kepadaku tentang tetangga, hingga aku menduga bahwasanya ia akan memberikan hak waris kepada tetangga.'\" Telah menceritakan kepadaku ['Amru An Naqid]; Telah menceritakan kepada kami ['Abdul 'Aziz bin Abu Hazim]; Telah menceritakan kepadaku [Hisyam bin 'Urwah] dari [Bapaknya] dari ['Aisyah] dari Nabi shallallahu 'alaihi wasallam dengan Hadits yang serupa", "tr": "Bize Kuteybe b. Saîd, Mâlik b, Enes'den rivayet etti. H. Bize Kuteybe ile Muhammed b. Rumh dahi Leys b. Sa'd'dan rivayet ettiler. H. Bize Ebû Bekr b. Ebî Şeybe de rivayet etti. (Dediki): Bize Abde İle Yezid b. Harun rivayet ettiler. Bu râvilerin hepsi Yahya b. Saîd'den rivayet etmişlerdir, H. Bize Muhammed b. Müsennâ da rivayet etti: Lâfız onundur. (Dediki): Bize Abdü'l-Vahhab (yâni Sekâfî) rivayet etti. (Dediki): Ben Yahya b. Saîd'den dinledim. (Dediki): Bana Ebû Bekr (bu zât İbni Muhammed b. Amr b. Hazm'dır) haber verdi. Ona da Amra rivayet etmiş ki: Kendisi Âişe'yi şöyle derken işitmiş: Ben Resûlullah (Sallallahu Aleyhi ve Sellem)'i: «Cibril bana komşuyu o derece tavsiyede bulundu ki, onu mutlaka bana mirasçı yapacak sandım.» buyururken işittim"}}, "frere_aime": {"refs": [["bukhari", 13], ["muslim", 45]], "txt": {"ar": "حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا يَحْيَى، عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم‏.‏ وَعَنْ حُسَيْنٍ الْمُعَلِّمِ، قَالَ حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ ‏\"‏‏.‏", "en": "Narrated Anas: The Prophet (ﷺ) said, \"None of you will have faith till he wishes for his (Muslim) brother what he likes for himself", "fr": "Rapporté par Anas : Le Prophète (ﷺ) a dit : Aucun de vous n'aura vraiment la foi tant qu'il n'aimera pas pour son frère (musulman) ce qu'il aime pour lui-même", "id": "Telah menceritakan kepada kami [Musaddad] berkata, telah menceritakan kepada kami [Yahya] dari [Syu'bah] dari [Qotadah] dari [Anas] dari Nabi shallallahu 'alaihi wasallam Dan dari [Husain Al Mu'alim] berkata, telah menceritakan kepada kami [Qotadah] dari [Anas] dari Nabi shallallahu 'alaihi wasallam, beliau bersabda: \"Tidaklah beriman seseorang dari kalian sehingga dia mencintai untuk saudaranya sebagaimana dia mencintai untuk dirinya sendiri", "tr": "Enes'ten rivayet edilmiştir: Nebi (Sallallahu aleyhi ve Sellem) şöyle buyurmuştur: Hiçbiriniz kendisi için sevdiğini (istediğini) (Müslüman) kardeşi için de sevmedikçe iman etmiş olamaz"}}, "sourire": {"refs": [["tirmidhi", 1956]], "txt": {"ar": "حَدَّثَنَا عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ، حَدَّثَنَا النَّضْرُ بْنُ مُحَمَّدٍ الْجُرَشِيُّ الْيَمَامِيُّ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ، حَدَّثَنَا أَبُو زُمَيْلٍ، عَنْ مَالِكِ بْنِ مَرْثَدٍ، عَنْ أَبِيهِ، عَنْ أَبِي ذَرٍّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ وَأَمْرُكَ بِالْمَعْرُوفِ وَنَهْيُكَ عَنِ الْمُنْكَرِ صَدَقَةٌ وَإِرْشَادُكَ الرَّجُلَ فِي أَرْضِ الضَّلاَلِ لَكَ صَدَقَةٌ وَبَصَرُكَ لِلرَّجُلِ الرَّدِيءِ الْبَصَرِ لَكَ صَدَقَةٌ وَإِمَاطَتُكَ الْحَجَرَ وَالشَّوْكَةَ وَالْعَظْمَ عَنِ الطَّرِيقِ لَكَ صَدَقَةٌ وَإِفْرَاغُكَ مِنْ دَلْوِكَ فِي دَلْوِ أَخِيكَ لَكَ صَدَقَةٌ ‏\"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنِ ابْنِ مَسْعُودٍ وَجَابِرٍ وَحُذَيْفَةَ وَعَائِشَةَ وَأَبِي هُرَيْرَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ وَأَبُو زُمَيْلٍ اسْمُهُ سِمَاكُ بْنُ الْوَلِيدِ الْحَنَفِيُّ ‏.‏", "en": "Abu Dharr narrated that the Messenger of Allah said :\"Your smiling in the face of your brother is charity, commanding good and forbidding evil is charity, your giving directions to a man lost in the land is charity for you. Your seeing for a man with bad sight is a charity for you, your removal of a rock, a thorn or a bone from the road is charity for you. Your pouring what remains from your bucket into the bucket of your brother is charity for you", "id": "Telah menceritakan kepada kami [Abbas bin Abdul Azhim Al Anbari], telah menceritakan kepada kami [An Nadlr bin Muhammad Al Jurasyi Al Yamami], telah menceritakan kepada kami [Ikrimah bin Ammar], telah menceritakan kepada kami [Abu Zuamail] dari [Malik bin Martsad] dari [bapaknya] dari [Abu Dzarr] ia berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Senyummu kepada saudaramu merupakan sedekah, engkau berbuat ma'ruf dan melarang dari kemungkaran juga sedekah, engkau menunjukkan jalan kepada orang yang tersesat juga sedekah, engkau menuntun orang yang berpenglihatan kabur juga sedekah, menyingkirkan batu, duri dan tulang dari jalan merupakan sedekah, dan engkau menuangkan air dari embermu ke ember saudaramu juga sedekah.\" Hadits semakna diriwayatkan dari Ibnu Mas'ud, Jabir, Hudzaifah, 'Aisyah dan Abu Hurairah. Berkata Abu 'Isa: Ini merupakan hadits hasan gharib dan Abu Zumail bernama Simak bin Walid Al Hanafi", "tr": "Ebû Zerr (r.a.)’den rivâyete göre, şöyle demiştir: Rasûlullah (s.a.v.) şöyle buyurdu: “Kardeşinizin yüzüne gülmeniz size sadaka sevâbı kazandırır. İyi şeyleri emredip kötülüklerden sakındırmak sadaka sevabı kazandırır. Yabancısı bulunduğu bir bölgedeki kimseye yol gösterip yardımcı olmak sadaka sevâbı kazandırır. Gözünden rahatsız olan bir kimseye yardımcı olmanız sizin için yine sadaka sevâbı kazandırır. Yollardan insanların gelip geçmesine engel olabilecek taş, kemik, diken gibi şeyleri kaldırmak ta yine sadaka sevâbı kazandırır. Kendi kabından ihtiyacı olan bir kimsenin kabına bir şeyler boşaltıvermekte yine sadaka sevâbı kazandırır.” Tirmizî rivâyet etmiştir. Tirmizî: Bu Konuda İbn Mes’ûd, Câbir, Huzeyfe, Âişe ve Ebû Hüreyre’den de hadis rivâyet edilmiştir. Tirmizî: Bu hadis hasen garibtir. Ebû Zümeyl’in ismi Simâk b. Velîd el Hanefî’dir"}}, "misericorde": {"refs": [["abudawud", 4941], ["tirmidhi", 1924]], "txt": {"ar": "حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَمُسَدَّدٌ، - الْمَعْنَى - قَالاَ حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنْ أَبِي قَابُوسَ، مَوْلًى لِعَبْدِ اللَّهِ بْنِ عَمْرٍو عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، يَبْلُغُ بِهِ النَّبِيَّ صلى الله عليه وسلم ‏ \"‏ الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ ارْحَمُوا أَهْلَ الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ ‏\"‏ ‏.‏ لَمْ يَقُلْ مُسَدَّدٌ مَوْلَى عَبْدِ اللَّهِ بْنِ عَمْرٍو وَقَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏.‏", "en": "Narrated Abdullah ibn Amr ibn al-'As: The Prophet (ﷺ) said: The Compassionate One has mercy on those who are merciful. If you show mercy to those who are on the earth, He Who is in the heaven will show mercy to you. Musaddad did not say: The client of 'Adb Allah b. 'Amr. He said: The Prophet (ﷺ) said", "fr": "Rapporté par Abdullah ibn Amr ibn al-‘As رضي الله عنه : Le Prophète ﷺ a dit : « Le Miséricordieux fait miséricorde à ceux qui sont miséricordieux. Si vous faites miséricorde à ceux qui sont sur la terre, Celui qui est au ciel vous fera miséricorde. » Musaddad n’a pas dit : Le client de ‘Abd Allah b. ‘Amr. Il a dit : Le Prophète ﷺ a dit", "id": "Telah menceritakan kepada kami [Abu Bakar bin Abu Syaibah] dan [Musaddad] secara makna, keduanya berkata; telah menceritakan kepada kami [Sufyan] dari [Amru] dari [Abu Qabus] -mantan budak (yang telah dimerdekakan oleh) Abdullah bin Amru- dari [Abdullah bin Amru] dan sanadnya sampai kepada Nabi shallallahu 'alaihi wasallam, (beliau bersabda): \"Para penyayang akan disayangi oleh Ar Rahman. Sayangilah penduduk bumi maka kalian akan disayangi oleh siapa saja yang di langit.\" Musaddad tidak mengatakan 'mantan budak Abdullah bin Amru, dan ia juga berkata, \"Nabi shallallahu 'alaihi wasallam bersabda", "tr": "Abdullah İbn Amr'den (rivayet edildiğine göre); Nebi (s.a.v.) (şöyle) buyurmuştur: \"Merhametli olanlara, Rahman (olan Allah) merhamet eder. (Öyleyse siz) yerde bulunanlara merhametti davranınız da gökteki de size merhamet etsin.\" Müsedded (bu hadisi rivayet ederken) Abdullah ibn Amr’in \"kölesi\" (kelimesi) ile \"bu hadisi Hz. Neb s.a.v.’e ulaştırdı\" ... cümlesini hiç zikretmedi. (Hadisi doğrudan doğruya): \"Nebi (s.a.v.) buyurdu ki\" (diye­rek) rivayet etti"}}, "caractere": {"refs": [["tirmidhi", 1162], ["abudawud", 4682]], "txt": {"ar": "حَدَّثَنَا أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، حَدَّثَنَا أَبُو سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ خُلُقًا ‏\"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عَائِشَةَ وَابْنِ عَبَّاسٍ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي هُرَيْرَةَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏", "en": "Abu Hurairah narrated that The Messenger of Allah said:“The most complete of the believers in faith, is the one with the best character among them. And the best of you are those who are best to your women.”", "id": "Telah menceritakan kepada kami [Abu Kuraib], telah menceritakan kepada kami ['Abdah bin Sulaiman] dari [Muhammad bin 'Amr], telah menceritakan kepada kami [Abu Salamah] dari [Abu Hurairah] berkata; Rasulullah shallallahu 'alaihi wasallam bersabda: \"Orang mukmin yang paling sempurna imannya adalah yang paling baik akhlaknya. Sebaik-baik kalian adalah yang paling baik terhadap para istrinya.\" Abu Isa berkata; \"Hadits semakna diriwayatkan dari Aisyah dan Ibnu Abbas.\" Dia menambahkan; \"Hadits Abu Hurairah merupakan hadits hasan sahih", "tr": "Ebû Hureyre (r.a.)’den rivâyete göre, şöyle demiştir: Rasûlullah (s.a.v.) şöyle buyurmuştur: “Müminlerin iman bakımından en olgun olanları ahlak yönünden de en güzel olanlarıdır. Sizin iyileriniz kadınlarına iyi davrananlardır.” Diğer tahric: Ebû Dâvûd, Sünnet Tirmîzî: Bu konuda Âişe ve İbn Abbâs’tan da hadis rivâyet edilmiştir. Tirmîzî: Ebû Hureyre hadisi hasen sahihtir"}}, "colere": {"refs": [["bukhari", 6116]], "txt": {"ar": "حَدَّثَنِي يَحْيَى بْنُ يُوسُفَ، أَخْبَرَنَا أَبُو بَكْرٍ ـ هُوَ ابْنُ عَيَّاشٍ ـ عَنْ أَبِي حَصِينٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَجُلاً، قَالَ لِلنَّبِيِّ صلى الله عليه وسلم أَوْصِنِي‏.‏ قَالَ ‏\"‏ لاَ تَغْضَبْ ‏\"‏‏.‏ فَرَدَّدَ مِرَارًا، قَالَ ‏\"‏ لاَ تَغْضَبْ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:A man said to the Prophet (ﷺ) , \"Advise me! \"The Prophet (ﷺ) said, \"Do not become angry and furious.\" The man asked (the same) again and again, and the Prophet (ﷺ) said in each case, \"Do not become angry and furious", "fr": "Rapporté par Abu Huraira : Un homme a dit au Prophète (ﷺ) : « Donne-moi un conseil ! » Le Prophète (ﷺ) a dit : « Ne te mets pas en colère. » L’homme a répété sa demande plusieurs fois, et à chaque fois, le Prophète (ﷺ) a répondu : « Ne te mets pas en colère. »", "id": "Telah menceritakan kepadaku [Yahya bin Yusuf] telah mengabarkan kepada kami [Abu Bakr yaitu Ibnu Ayyasy] dari [Abu Hashin] dari [Abu Shalih] dari [Abu Hurairah] radliallahu 'anhu bahwa seorang laki-laki berkata kepada Nabi shallallahu 'alaihi wasallam; \"Berilah aku wasiat?\" beliau bersabda: \"Janganlah kamu marah.\" Laki-laki itu mengulangi kata-katanya, beliau tetap bersabda: \"Janganlah kamu marah", "tr": "Ebu Hureyre r.a.'dan rivayete göre; \"Bir adam Nebi Sallallahu Aleyhi ve Sellem'e: \"Bana tavsiyede bulun, dedi. Allah Rasulü: Kızma, buyurdu. Adam istediğini defalarca tekrarladığı halde yine: Kızma, buyurdu.\" Diğer tahric eden: Tirmizi Birr Fethu'l-Bari Açıklaması: \"Güçlü kuwetli kişi rakiplerinin sırtını yere getiren değildir.\" Yani gücüyle insanların sırtını çokça yere getiren kişi değildir. \"Asıl güçlü kuwetli kişi, kızdığı zaman kendisine hakim olandır.\" Hadise dair açıklamalar daha önce \"Sövüp saymak ve lanetlemek\" başlığında geçmiş bulunmaktadır. el-Hattabi dedi ki: Nebi efendimizin: \"Kızma\" buyruğu, kızgınlığa götüren sebeplerden uzak dur, kızgınlığı getirecek hallerle kendi kendini karşı karşıya bırakma, demektir. Bizatihi kızmanın kendisinin yasaklanması zaten sözkonusu olamaz. Çünkü kızgınlık tabii bir durum olup insanın tabiatından gitmesi düşünülemez. Anlamının şöyle olduğu da söylenmiştir: Kızma, çünkü kızgınlığın çıkardığı en büyük şey, kibirdir. Kızmak, genelde kişinin istediği bir işe aykırılık halinde ortaya çıkar. Bunun sonucunda da kibir kişiyi kızmaya götürür. Ama nefsin kibri gidene kadar alçak gönüllü davranan kimse, kızgınlığın şerrinden kurtulur. Kızmanın sana emrettiği işi yapma, anlamında olduğu da söylenmiştir. İbn Battal dedi ki: Birinci hadiste nefse karşı mücahedenin düşmana karşı mücahededen daha zor olduğu anlatılmaktadır. Çünkü Nebi Sallallahu Aleyhi ve Sellem kızgınlık halinde kendisine hakim olan kimseyi, insanların en güçlüsü olarak değerlEmdirmiştir. Başkası da şöyle demektedir: Muhtemelen (başlıktaki 6116 nolu hadiste) sözü geçen soruyu soran kişi, çokça kızan birisi idi. Nebi Sallallahu Aleyhi ve Sellem de soru soran herbir kimseye en uygun olan emri verirdi. Bundan dolayı Allah Rasulü, bu kişiye de kızmayı terk etmeyi tavsiyeyle yetindi. Kimi ilim adamı da şöyle demiştir: Allah kızgınlığı ateşten yarattı ve bunu insanın bir tabiatı kıldı. Kızgınlık ateşinin yanıp parlamasına sebep olan herbir hususta insana karşı çıkılıp yahut onunla tartışıldığı takdirde, onun da yüzü ve gözleri kandan dolayı kızarır. Çünkü insanın teni, arka tarafında gizlenen rengi anlatır. Böyle bir kimse, kendisinden daha alt mertebede bulunana gücünün yettiğini anlarsa bu hali alır. Eğer kendisinden daha yukarı bir mertebede ise, bundan dolayı derinin görünen tarafından kalbin iç tarafına doğru kan çekilmeye başlar ve üzüntüden dolayı rengi sararır. Eğer kendisine denk bir kimseye karşı bu halortaya çıkarsa, kan çekilmek ile yayılmak arasında gider gelir. Bundan dolayı kızarır ve sararır. Öfkenin sonucu olarak dış ve içte değişiklikler meydana gelir. Renk değişmesi, organların titremesi, gelişigüzel davranışların gösterilmesi, hilkatin farklı bir hal alması gibi. Hatta kızgın bir kimse, kendisini kızgın haliyle görecek olursa, suretinin çirkinliğinden ve hilkatinin değişime uğramasından utanarak öfkesi diner. Bütün bunlar zahiren görülen şeylerdir. İç dünyadaki çirkinliği ise, zahiren görünenden daha da ileridir. Çünkü kızgınlık, kalpte kini ve kıskançlığı doğurur, farklı türleriyle kötülükleri kalpte saklamaya neden olur. Hatta kızgınlık ilk olarak insanın iç dünyasını çirkinleştirir. Dışının değişikliğe uğraması ise, iç dünyasındaki değişikliğin bir neticesidir. Bütün bunlar, kızgınlığın bedendeki etkileridir. Dildeki etkilerine gelince, gelişigüzel sövüp sayar ve aklı başında kimsenin utanacağı, öfkesinin dinmesi esnasında söyleyenin pişman olacağı çirkin sözler söyler. Kızgınlık, dövmek yahut öldürmek gibi fiili davranışlarda da etkisini gösterir. Bütün bunlar ise, daha önce -bir önceki başlıkta- açıklandığı üzere dini anlamıyla gazapta değil, dünyevı gazapta sözkonusudur. Kızıp öfkelenmeyi terk etmeye yardımcı olan husus, öfkeyi yenmenin faziletine dair varid olmuş buyrukları hatırlamak, kızgınlığın semeresi olan şeylerin ortaya çıkması sonucundaki tehditleri hatıra getirmek, ayrıca Süleyman İbn Surad'ın rivayet ettiği hadiste geçtiği gibi, şeytandan Allah'a sığınmak, daha önce Atiyye hadisinde işaret edildiği gibi de abdest almak ile olur. Doğrusunu en iyi bilen Allah'tır"}}, "fort": {"refs": [["bukhari", 6114], ["muslim", 2609]], "txt": {"ar": "حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ ‏\"‏‏.‏", "en": "Narrated Abu Huraira:Allah's Messenger (ﷺ) said, \"The strong is not the one who overcomes the people by his strength, but the strong is the one who controls himself while in anger", "fr": "Rapporté par Abu Huraira : Le Messager d'Allah (ﷺ) a dit : « Le fort n’est pas celui qui l’emporte sur les autres par sa force, mais celui qui sait se maîtriser lorsqu’il est en colère. »", "id": "Telah menceritakan kepada kami [Abdullah bin Yusuf] telah mengabarkan kepada kami [Malik] dari [Ibnu Syihab] dari [Sa'id bin Musayyib] dari [Abu Hurairah] radliallahu 'anhu bahwa Rasulullah shallallahu 'alaihi wasallam bersabda: \"Tidaklah orang yang kuat adalah orang yang pandai bergulat, tapi orang yang kuat adalah orang yang dapat menahan nafsunya ketika ia marah", "tr": "Ebu Hureyre r.a.'dan rivayete göre; \"Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Güçlü, kuvvetli kişi rakiplerinin sırtını yerine getiren kişi değildir. Asıl güçlü kuvvetli kişi, öfkelendiği vakit nefsine hakim olabilendir"}}, "intention": {"refs": [["bukhari", 1], ["muslim", 1907]], "txt": {"ar": "حَدَّثَنَا الْحُمَيْدِيُّ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ، قَالَ : حَدَّثَنَا سُفْيَانُ ، قَالَ : حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ ، قَالَ : أَخْبَرَنِي مُحَمَّدُ بْنُ إِبْرَاهِيمَ التَّيْمِيُّ ، أَنَّهُ سَمِعَ عَلْقَمَةَ بْنَ وَقَّاصٍ اللَّيْثِيَّ ، يَقُولُ : سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ عَلَى الْمِنْبَرِ، قَالَ : سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ : \" إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ", "en": "Narrated 'Umar bin Al-Khattab: I heard Allah's Messenger (ﷺ) saying, \"The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended. So whoever emigrated for worldly benefits or for a woman to marry, his emigration was for what he emigrated for", "fr": "Rapporté par 'Umar ibn Al-Khattab : J'ai entendu le Messager d'Allah (ﷺ) dire : « La récompense des actions dépend des intentions, et chacun sera récompensé selon son intention. Donc, celui qui a émigré pour obtenir des biens matériels ou pour épouser une femme, son émigration sera pour ce pour quoi il a émigré. »", "id": "Telah menceritakan kepada kami [Al Humaidi Abdullah bin Az Zubair] dia berkata, Telah menceritakan kepada kami [Sufyan] yang berkata, bahwa Telah menceritakan kepada kami [Yahya bin Sa'id Al Anshari] berkata, telah mengabarkan kepada kami [Muhammad bin Ibrahim At Taimi], bahwa dia pernah mendengar [Alqamah bin Waqash Al Laitsi] berkata; saya pernah mendengar [Umar bin Al Khaththab] diatas mimbar berkata; saya mendengar Rasulullah shallallahu 'alaihi wasallam bersabda: \"Semua perbuatan tergantung niatnya, dan (balasan) bagi tiap-tiap orang (tergantung) apa yang diniatkan; Barangsiapa niat hijrahnya karena dunia yang ingin digapainya atau karena seorang perempuan yang ingin dinikahinya, maka hijrahnya adalah kepada apa dia diniatkan", "tr": "Alkame b. Vakkâs el-Leysî'den: O şöyle demiştir: Ömer İbnu'l-Hattâb'ın minberde şöyle dediğini duydum: Allah Resulü (Sallallahu Aleyhi ve Sellem)’in şunları söylediğini duydum: \"Ameller niyetlere göredir ve herkes için niyet ettiğinin karşılığı vardır. Kimin hicreti elde edeceği dünyalığa veya evleneceği bir kadına ise hicreti, hicret ettiği şeyedir. Tekrar: 54, 2529, 3898, 5070, 6689, 6953. Diğer Tahric:: Müslim, imare; Ebu Davud Talak; Tirmizî, cihad; Nesâî, tahare, talak, eymân; İbn Mace, zühd; Ahmed b. Hanbel, I"}}};
